#include "bubble.hpp"
#include "swap.hpp"
void bubble(int *data, const int size_of_data)
{
    if(size_of_data <= 0) return;
    for(int i = 0; i + 1 < size_of_data; ++i)
        if(data[i] > data[i + 1]) swap(data[i], data[i + 1]);
    return bubble(data, size_of_data - 1);
}

