void
vaapi_gotcha::shutdown()
{
    vaapi_gotcha_t::disable();
}
void
vaapi_gotcha::start()
{
    if(!get_vaapi_gotcha().get<vaapi_gotcha_t>()->get_is_running())
    {
        configure();
        get_vaapi_gotcha().start();
    }
}
void
