#include <iostream>
#include "Interpreter.h"
#include "TuiLog.h"
int main(int argc, const char* argv[])
{
    std::vector<std::string> args;
    for(int i = 1; i < argc; i++)
    {
        args.push_back(argv[i]);
    }
    if(args.empty())
    {
        TuiLog("Please supply a script to run, eg. ./tui examples/example.tui");
        return 0;
    }
    Interpreter* interpreter = new Interpreter(args);
    delete interpreter;
    return 0;
}

#include <iterator>
#include <string>

#include "utf8/checked.h"
#include "utils/string/convert.hpp"

namespace conv {
auto ToBytes(const std::wstring& wstr) -> std::string {
  std::string str;
  utf8::utf16to8(wstr.begin(), wstr.end(), std::back_inserter(str));
  return str;
}

auto ToBytes(std::wstring&& wstr) -> std::string {
  std::string str;
  utf8::utf16to8(wstr.begin(), wstr.end(), std::back_inserter(str));
  return str;
}

auto FromBytes(const std::string& str) -> std::wstring {
  std::wstring wstr;
  utf8::utf8to16(str.begin(), str.end(), std::back_inserter(wstr));
  return wstr;
}

auto FromBytes(std::string&& str) -> std::wstring {
  std::wstring wstr;
  utf8::utf8to16(str.begin(), str.end(), std::back_inserter(wstr));
  return wstr;
}
