  char* c_ptr{nullptr};
  size_t size{1};
  strat_.alloc(&c_ptr, size);
  ASSERT_NE(c_ptr, nullptr);
}
TEST_F(DLMallocTestFixture, alloc_128_bytes) {
  char* c_ptr{nullptr};
  size_t size{128};
  strat_.alloc(&c_ptr, size);
  ASSERT_NE(c_ptr, nullptr);
}
TEST_F(DLMallocTestFixture, alloc_256_bytes) {
  char* c_ptr{nullptr};
  size_t size{256};
  strat_.alloc(&c_ptr, size);
  ASSERT_NE(c_ptr, nullptr);
}
TEST_F(DLMallocTestFixture, alloc_512_bytes) {
