#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
static safety_check_abort_hook_t safety_check_abort;
void safety_check_fail_sized_dealloc(bool current_dealloc, const void *ptr,
    size_t true_size, size_t input_size) {
	char *src = current_dealloc ? "the current pointer being freed" :
	    "in thread cache, possibly from previous deallocations";
	safety_check_fail("<jemalloc>: size mismatch detected (true size %zu "
	    "vs input size %zu), likely caused by application sized "
	    "deallocation bugs (source address: %p, %s). Suggest building with "
	    "--enable-debug or address sanitizer for debugging. Abort.\n",
	    true_size, input_size, ptr, src);
}
void safety_check_set_abort(safety_check_abort_hook_t abort_fn) {
	safety_check_abort = abort_fn;
}
void safety_check_fail(const char *format, ...) {
	char buf[MALLOC_PRINTF_BUFSIZE];
	va_list ap;
	va_start(ap, format);
	malloc_vsnprintf(buf, MALLOC_PRINTF_BUFSIZE, format, ap);
	va_end(ap);
	if (safety_check_abort == NULL) {
		malloc_write(buf);
		abort();
	} else {
		safety_check_abort(buf);
	}
}

#include "autolink/transport/common/identity.hpp"
#include "gtest/gtest.h"
namespace autolink {
namespace transport {
TEST(IdentityTest, testConstructFalse) {
  Identity it(false);
  EXPECT_EQ(it.HashValue(), static_cast<uint64_t>(0));
  EXPECT_EQ(it.ToString(), "0");
}
TEST(IdentityTest, testConstructTrue) {
  Identity it(true);
  EXPECT_NE(it.HashValue(), static_cast<uint64_t>(0));
  EXPECT_NE(it.ToString(), "0");
}
TEST(IdentityTest, testIdentityEqual) {
  Identity id1;
  Identity id2;
  Identity id3;
  EXPECT_NE(id1, id2);
  EXPECT_NE(id2, id3);
  EXPECT_NE(id1, id3);
  EXPECT_NE(id1.HashValue(), id3.HashValue());
  id2 = id2;
  EXPECT_NE(id2, id3);
  id2 = id3;
  EXPECT_EQ(id2, id3);
  Identity id4(id1);
  EXPECT_EQ(id1, id4);
  EXPECT_EQ(id1.ToString(), id4.ToString());
  EXPECT_EQ(id1.HashValue(), id4.HashValue());
}
TEST(IdentityTest, testOperatorEqual) {
  Identity it(true);
  Identity it1(false);
  it1 = it;
  EXPECT_EQ(it.HashValue(), it1.HashValue());
  EXPECT_EQ(it.ToString(), it1.ToString());
  EXPECT_EQ(it1.Length(), it.Length());
  it.set_data(nullptr);
  Identity it2;
  it2.set_data(it.data());
  EXPECT_EQ(it2.HashValue(), it1.HashValue());
  EXPECT_EQ(it2.ToString(), it1.ToString());
  EXPECT_EQ(it1.Length(), it2.Length());
}
}  // namespace transport
}  // namespace autolink

