TEST_F(ApiTest, ReadOnlyDBTest) {
    if (inMemMode) {
        GTEST_SKIP();
    }
    createDBAndConn();
#ifndef __STATIC_LINK_EXTENSION_TEST__
    ASSERT_TRUE(conn->query(std::format("LOAD EXTENSION '{}'",
                                TestHelper::appendLbugRootPath(
                                    "extension/fts/build/libfts.lbug_extension")))
                    ->isSuccess());
#endif
    ASSERT_TRUE(conn->query("CREATE NODE TABLE doc (NAME STRING, PRIMARY KEY(NAME))")->isSuccess());
