  EXPECT_EQ(eprosima::fastrtps::VOLATILE_DURABILITY_QOS, attrs.qos.m_durability.kind);
  EXPECT_EQ(eprosima::fastrtps::RELIABLE_RELIABILITY_QOS, attrs.qos.m_reliability.kind);
