// program hh from Scozzari SAS'13
int main(void) {
  int i,j;

  i=0;
  while (i<4) {
    j=0;
    while (j < 4) {
      __CRAB_assert(i <= j+3);
      i++;
      j++;
    }
    i = i-j+1;
  }

  return 0;
}

