#include <herbs/intformat/intformat.h>
#include <herbs/exceptionmissing/exceptionmissing.h>

// Expands the macro with comment processing
Herbs::String Doxymax::Item::expand(const Macro& macro, CommentProcessor& processor)
{
    // Check if at least one argument is provided
    if(macro.args.length() < 1)
    {
        throw Herbs::ExceptionMissing(___FILE__, __LINE__);
    }

    // Initialize output string with capacity
    Herbs::String str_out(64);

    // Append opening li tag with class
    str_out.append(STR("<li class=\"itemdoxmax\""));

    // Add special styling for top-level expansion
    if(processor.macroExpansionDepth() == 1)
    {
        str_out.append(STR(" style=\"position:relative\""));
    }

    // Complete opening tag and add header
    str_out.append(STR("><div class=\"itemhead\">"))
        .append(macro.args[0])
        .append(STR("</div>"));

    // Process optional comment if present
    if(macro.args.length() > 2)
    {
        str_out.append(STR("<div class=\"itemcomment\">"))
            .append(macro.args[2])
            .append(STR("</div>"));
    }

    // Process optional body content if present
    if(macro.args.length() > 1)
    {
        str_out.append(macro.args[1]);
    }

    // Close the list item
    str_out.append(STR("</li>"));

    return std::move(str_out);
}

