// Class definition with typestate annotations
class [[clang::consumable(unconsumed)]] Object {
public:
    // Default constructor
    Object() {}

    // Move constructor
    Object(Object&& other) { 
        other.invalidate(); 
    }

    // Method callable only when unconsumed
    [[clang::callable_when(unconsumed)]]
    void do_something() { 
        assert(m_valid); 
    }

private:
    // Marks object as consumed
    [[clang::set_typestate(consumed)]]
    void invalidate() { 
        m_valid = false; 
    }

    bool m_valid { true };
};

