// Adds octree layers recursively
void SceneGroup::addOctreeLayers(unsigned int levels)
{
    if(levels != 0)
    {
        childGroups.reset(new std::array<SceneGroup,8>);
        std::for_each(childGroups->begin(), childGroups->end(),
        [&levels](SceneGroup& child) {
            child.addOctreeLayers(--levels);
        });
    }
}

// Updates all scene items and child groups
void SceneGroup::updateScene()
{
    std::for_each(childItems.begin(), childItems.end(), [](std::unique_ptr<SceneItem>& child) {
        child->update();
    });

    if(childGroups != nullptr)
    {
        std::for_each(childGroups->begin(), childGroups->end(),
        [](SceneGroup& child) {
            child.updateScene();
        });
    }
}

// Renders all scene items and child groups
void SceneGroup::renderScene()
{
    std::for_each(childItems.begin(), childItems.end(), [](std::unique_ptr<SceneItem>& child) {
        child->draw();
    });

    if(childGroups != nullptr)
    {
        std::for_each(childGroups->begin(), childGroups->end(),
        [](SceneGroup& child) {
            child.renderScene();
        });
    }
}

#include "threadpool.h"

// ThreadPool constructor
ThreadPool::ThreadPool(size_t size)
{
    for (size_t i = 0; i < size; ++i)
    {
        workers.emplace_back([this] {
            for (;;)
            {
                std::unique_lock<std::mutex> lock(this->queue_mutex);
                while (!this->m_stop && this->tasks.empty())
                    this->condition.wait(lock);
                if (this->m_stop && this->tasks.empty())
                    return;
                std::function<void()> task(this->tasks.front());
                this->tasks.pop();
                lock.unlock();
                task();
            }
        });
    }
}

// ThreadPool destructor
ThreadPool::~ThreadPool()
{
    {
        std::unique_lock<std::mutex> lock(queue_mutex);
        m_stop = true;
    }
    condition.notify_all();
    for (auto i = 0; i < workers.size(); ++i)
        workers[i].join();
}

