// Constructor
HtmlSnap::HtmlSnap()
{
    connect(&page, SIGNAL(loadFinished(bool)), this, SLOT(render()));
}

// Load HTML content
void HtmlSnap::loadHtml(char* html)
{
    page.mainFrame()->setHtml(QString(html), QUrl());
}

// Render the HTML to image and output base64
void HtmlSnap::render()
{
    // Set viewport size to match content
    page.setViewportSize(page.mainFrame()->contentsSize());

    // Create image with appropriate format
    QImage image(page.viewportSize(), QImage::Format_ARGB32);

    // Paint the frame onto the image
    QPainter painter(&image);
    page.mainFrame()->render(&painter);
    painter.end();

    // Convert image to base64 for output
    QByteArray data;
    QBuffer buffer(&data);
    buffer.open(QBuffer::WriteOnly);

    if(!image.save(&buffer, "PNG"))
        std::cerr << "could not save data to buffer" << std::endl;
    else
        std::cout << data.toBase64().data() << std::endl;

    // Emit finished signal asynchronously
    QTimer::singleShot(0, this, SIGNAL(finished()));
}

