        switch (ev) {
        case UI::kEnter: {
            // Transition to start game state
            std::shared_ptr<IState> start_game_state(new StartGameState(ui));
            stm->change_state(std::shared_ptr<IState>(start_game_state));
            }
            break;
        case UI::kEsc:
            // Stop the application
            stm->stop();
            break;
        default:
            // Ignore other events
            break;
        }
    }
}

