namespace base {

// Constructor initializes helper with target thread
ThreadTestHelper::ThreadTestHelper(MessageLoopProxy* target_thread)
    : test_result_(false),
      target_thread_(target_thread),
      done_event_(false, false) {
}

// Runs the test on the target thread and waits for completion
bool ThreadTestHelper::Run() {
  if (!target_thread_->PostTask(
          FROM_HERE, base::Bind(&ThreadTestHelper::RunInThread, this))) {
    return false;
  }
  done_event_.Wait();
  return test_result_;
}

// Sets the test result to true
void ThreadTestHelper::RunTest() { set_test_result(true); }

// Destructor
ThreadTestHelper::~ThreadTestHelper() {}

// Executes test on target thread and signals completion
void ThreadTestHelper::RunInThread() {
  RunTest();
  done_event_.Signal();
}

