{
  // Initialize UART with policy for carriage return character
  uart::init_instance<uart::PolicyNotifyOnChar<'\r'>>(CURRENT_UART, callback);

  unsigned char Idx = 0;

  // Infinite loop for periodic output
  while(1)
  {
    printf ("Index : %d\r\n", Idx);
    clock::msleep(500);
    Idx++;
  }
}
