using namespace std;

// Template function for general types
template <typename T>
string debug_rep(const T &t) {
    ostringstream ret;
    ret << t;
    return ret.str();
}

// Template function for pointer types
template <typename T>
string debug_rep(T *p) {
    ostringstream ret;
    ret << "pointer: " << p;
    if(p) {
        ret << " content: " << debug_rep(*p);
    } else {
        ret << " null pointer";
    }
    return ret.str();
}

// Specialization for string type
string debug_rep(const string &s) {
    return '"' + s + '"' + "no template";
}

int main() {
    string s("hi");
    // Calls debug_rep(const T&), T is string, when the third function is commented
    cout << debug_rep(s) << endl;
    // Calls debug_rep(T*p), T is string
    cout << debug_rep(&s) << endl;

    const string *sp = &s;
    // Calls debug_rep(T* p), T is const string, this one is more specialized
    cout << debug_rep(sp) << endl;

    // const char*
    cout << debug_rep("hi world!") << endl;
}

