// Loads all game objects in the level
void Level::load()
{
    for(auto game_object : objects)
    {
        std::cout << "Loading " << game_object->name << std::endl;
        game_object->load();
        for(auto hit : game_object->get_hitboxes())
        {
            hit->initialize();
        }
    }
}

// Frees all game objects and clears event listeners
void Level::free()
{
    for(auto game_object : objects)
    {
        std::cout << "Freeing" << game_object->name << std::endl;
        game_object->free();
    }
    EventHandler::listeners.clear();
}

