                                                   std::istream_iterator<chip8::byte_t>{} };
            in.close();
            m_mmu.load( data, chip8::init_rom_load_address );
            return true;
        }
        return false;
    }

    // Execute one CPU cycle
    void VM::cycle()
    {
        m_cpu.cycle();
    }
