#include <mutex>

// Structure definition
struct Complex
{
    std::mutex mutex;
    int i;

    // Constructor
    Complex() : i(0) {}

    // Multiplication method
    void mul(int x)
    {
        std::lock_guard<std::mutex> lock(mutex);
        i *= x;
    }

    // Division method
    void div(int x)
    {
        std::lock_guard<std::mutex> lock(mutex);
        i /= x;
    }

    // Combined operation
    void both(int x, int y)
    {
        std::lock_guard<std::mutex> lock(mutex);
        mul(x);
        div(y);
    }
};

// Main function
int main()
{
    Complex complex;
    complex.both(32, 23);
    return 0;

}

