using namespace llvm;

namespace {

// Test for timer additivity
TEST(Timer, Additivity) 
{
    Timer T1("T1");
    EXPECT_TRUE(T1.isInitialized());

    // First timing interval
    T1.startTimer();
    T1.stopTimer();
    auto TR1 = T1.getTotalTime();

    // Second timing interval (should be longer)
    T1.startTimer();
    std::this_thread::sleep_for(std::chrono::milliseconds(1));
    T1.stopTimer();
    auto TR2 = T1.getTotalTime();

    EXPECT_TRUE(TR1 < TR2);
}

// Test for trigger state tracking
TEST(Timer, CheckIfTriggered) 
{
    Timer T1("T1");

    // Initially not triggered
    EXPECT_FALSE(T1.hasTriggered());

    // After starting, should be triggered
    T1.startTimer();
    EXPECT_TRUE(T1.hasTriggered());

    // Still triggered after stopping
    T1.stopTimer();
    EXPECT_TRUE(T1.hasTriggered());

    // After clearing, should no longer be triggered
    T1.clear();
    EXPECT_FALSE(T1.hasTriggered());
}

