namespace base {

// Sets the cancellation flag
void CancellationFlag::Set()
{
#if !defined(NDEBUG)
    // Ensure the flag is set from the same thread that owns it
    DCHECK_EQ(set_on_, PlatformThread::CurrentId());
#endif
    // Atomically store 1 to the flag with release semantics
    base::subtle::Release_Store(&flag_, 1);
}

// Checks if the cancellation flag has been set
bool CancellationFlag::IsSet() const
{
    // Atomically load the flag with acquire semantics
    return base::subtle::Acquire_Load(&flag_) != 0;
}

