#define TEST_CLASS BaseCPUTest

// Custom test CPU implementation for testing purposes
class BaseTestCPU : public BaseCPU {
public:
    // Constructor initializes member variables and base class
    BaseTestCPU(int maxTicks, const System &sys) 
        : maxTicks(maxTicks), ticks(0), resets(0), BaseCPU(sys) { }

    // Reset method increments reset counter
    void reset() { 
        resets++; 
    }

    // Tick method simulates CPU execution
    void tick() {
        assert(isRunning());
        ticks++;
        if(ticks >= maxTicks) {
            stop();
        }
    }

    int ticks;
    int resets;
    int maxTicks;
};

const int TEST_TICK_COUNT = 3;

// Test fixture class
class TEST_CLASS : public testing::Test {
protected:
    // Constructor initializes the CPU with test parameters
    TEST_CLASS() : cpu(TEST_TICK_COUNT, dummySystem) { }

    BaseTestCPU cpu;
    System dummySystem;
};

// Test case: verify run loop behavior
TEST_F(TEST_CLASS, TestRunLoop) {
    // Check initial state
    ASSERT_FALSE(cpu.isRunning()) << "Incorrect initial CPU running state";
    ASSERT_EQ(cpu.ticks, 0) << "Incorrect initial CPU tick count";
    ASSERT_EQ(cpu.resets, 0) << "Incorrect initial CPU reset count";

    // Start the CPU
    cpu.startup();

    // Verify final state after execution
    ASSERT_FALSE(cpu.isRunning()) << "Incorrect final CPU running state";
    ASSERT_EQ(cpu.ticks, TEST_TICK_COUNT) << "Incorrect final CPU tick count";
    ASSERT_EQ(cpu.resets, 1) << "Incorrect initial CPU reset count";
}

