// Callback function for sqlite3_exec to process query results
int callback(void *res, int columns, char **data, char **)
{
    vector<vector<string>> &results =
        *(static_cast<vector<vector<string>> *>(res));
    vector<string> row;
    for (int i = 0; i < columns; i++)
    {
        row.push_back(data[i] ? data[i] : "NULL");
        cout << data[i] << ", ";
    }
    results.push_back(row);
    return 0;
}

// Executes an SQL command and returns the result set
vector<vector<string>> Database::execute(string command) const
{
    cout << "Executing SQL: " << command << endl;
    cout << "Data: ";
    vector<vector<string>> results;
    char *err;
    int status = sqlite3_exec(db,              /* An open database */
                              command.c_str(), /* SQL to be evaluated */
                              callback,        /* Callback function */
                              &results,        /* 1st argument to callback */
                              &err             /* Error msg written here */
                             );
    cout << endl;
    cout << "DB status: " << status;
    if (err)
    {
        cout << ", Error: " << err;
        sqlite3_free(err);
    }
    cout << endl;
    return results;
}

#include <iostream>
using namespace std;

// Shell sort implementation
int shellSort(int a[], int n)
{
    for (int shell = n / 2; shell > 0; shell /= 2)
    {
        for (int i = shell; i < n; i++)
        {
            int tmp = a[i];
            int j;
            for (j = i; (j >= shell) && (a[j - shell] > tmp); j -= shell)
                a[j] = a[j - shell];
            a[j] = tmp;
        }
    }
    return 0;
}

int main()
{
    int n, arr[10000];
    cin >> n;
    for (int i = 0; i < n; i++)
        cin >> arr[i];

    // Perform shell sort
    shellSort(arr, n);

    cout << "Array after sorting: \n";
    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";
    cout << endl;

    return 0;
}

