// Constructs a Status object from printf-style arguments
Status ToStatusF(Code code, const char* format, ...)
{
    va_list ap;
    va_start(ap, format);
    char* p;
    if(vasprintf(&p, format, ap) < 0)
    {
        abort();
    }
    va_end(ap);
    Status status(code, p);
    free(p);
    return status;
}

