// Base class definition
struct Base {
    void bar(int i) {
        cout << "Base::bar(int)" << endl;
    }
protected:
    int ival = 0;
};

// Derived1 inherits virtually from Base
struct Derived1 : virtual public Base {
    void bar(char c) {
        cout << "Derived1::bar(char)" << endl;
    }
    void foo(char c) {
        cout << "Derived1::foo(char)" << endl;
    }
protected:
    char cval = 'c';
};

// Derived2 inherits virtually from Base
struct Derived2 : virtual public Base {
    void foo(int i) {
        cout << "Derived2::foo(int)" << endl;
    }
protected:
    int ival = 1;
    char cval = 'd';
};

// VMI class inherits from both Derived1 and Derived2
class VMI : public Derived1, public Derived2 {
public:
    // Access the ival from Base (ambiguous without scope resolution)
    void access_ival() {
        cout << Base::ival << endl; // without Base::, it will be Derived2::ival
    }

    // Access cval from Derived1 (ambiguous without scope resolution)
    void access_cval() {
        cout << Derived1::cval << endl; // both cval need ::
    }
};

int main() {
    VMI vmi;

    // Call methods to demonstrate member access
    vmi.access_ival();
    vmi.access_cval();

    // Explicitly call foo from Derived1
    vmi.Derived1::foo('c'); // both need ::

    // Calls Derived1::bar(int) due to inheritance
    vmi.bar(1); // call Derived1::bar()

    // Calls Derived1::bar(char)
    vmi.bar('c'); // call Derived1::bar()

    // Explicitly call Base::bar(int)
    vmi.Base::bar(1);

    return 0;
}

