#include <stdio.h>
#include <string.h>

// External function declaration
extern void UNSAFE_BUFACCESS(void *buffer, int size);

int main()
{
    // Initialize buffer with a short string
    char buffer[10] = "Hi";
    char input[20];

    // Prompt user for input
    printf("Enter a string: ");
    scanf("%19s", input);

    // Concatenate input to buffer (unsafe operation)
    strcat(buffer, input);

    // Call unsafe function with buffer and its length
    UNSAFE_BUFACCESS(buffer, strlen(buffer));

    // Output the resulting buffer content
    printf("Buffer: %s\n", buffer);

    return 0;
}

