namespace llarp
{
    // Initialize crypto types for Python bindings
    void CryptoTypes_Init(py::module& mod)
    {
        // PubKey class binding
        py::class_<PubKey>(mod, "PubKey")
            .def(py::init<>())
            .def("FromHex", &PubKey::FromString)
            .def("__repr__", &PubKey::ToString);

        // SecretKey class binding
        py::class_<SecretKey>(mod, "SecretKey")
            .def(py::init<>())
            .def("LoadFile", &SecretKey::LoadFromFile)
            .def("SaveFile", &SecretKey::SaveToFile)
            .def("ToPublic", &SecretKey::toPublic);

        // Signature class binding
        py::class_<Signature>(mod, "Signature")
            .def(py::init<>())
            .def("__repr__", [](const Signature& sig) {
                return sig.ToHex();
            });
    }
}  // namespace llarp

