// Main entry point for the application
int main(int argc, const char** argv)
{
    anm2ed::Loader loader(argc, argv);

    // Check if loader encountered an error
    if (loader.isError) 
        return EXIT_FAILURE;

    // Initialize state with loader-provided resources
    anm2ed::State state(loader.window, loader.settings, loader.arguments);

    // Main loop
    while (!state.isQuit)
        state.loop(loader.window, loader.settings);

    return EXIT_SUCCESS;
}

