        } else {
            fprintf(stderr, "\033[33mWARNING: Python not found (min version required is 3.8), skipping Python JSON schema -> grammar tests.\n\033[0m");
        }

        if (getenv("LLAMA_NODE_AVAILABLE") || (std::system("node --version") == 0)) {
