// Seed48 function implementation
unsigned short *seed48(unsigned short *s)
{
    static unsigned short p[3];

    // Copy current seed to temporary array
    memcpy(p, __seed48, sizeof p);

    // Update global seed with new values
    memcpy(__seed48, s, sizeof p);

    // Return previous seed values
    return p;
}

