    // Force colored output
    ctx.setOption("force-colors", true);

    // Process command line arguments
    ctx.applyCommandLine(argc, argv);

    // Run tests and capture result
    int test_result = ctx.run();

    // Finalize MPI
    doctest::mpi_finalize();

    return test_result;
}

#include <stdio.h>
