// Signal handler for graceful shutdown
void sigint_handler(int sig)
{
    StopClient();
    StopServer();
}

int main()
{
    signal(SIGINT, sigint_handler);
    {
        std::thread server(RunServer);
        std::thread client(RunClient);
        client.join();
        server.join();
    }
    return 0;
}

