// Output source location to stream
template <>
void Out<TSourceLocation>(IOutputStream& o, const TSourceLocation& t)
{
#if defined(_win_)
    // Convert Windows paths to use forward slashes
    TString file(t.File);
    std::replace(file.begin(), file.vend(), '\\', '/');
    o << file;
#else
    o << t.File;
#endif
    // Append line number
    o << ':' << t.Line;
}

