// Define log10e constant
#define log10e 0.43429448190325182765

#ifdef KR_headers
    // Old-style K&R function declaration
    double log();
    double d_lg10(x) doublereal *x;
#else
    // Undefine abs to avoid conflicts
    #undef abs
    #include "math.h"
    // Modern function definition with explicit type
    double d_lg10(doublereal *x)
#endif
{
    // Compute base-10 logarithm using natural logarithm
    return( log10e * log(*x) );
