using nlohmann::json;

TEST_CASE("version information")
{
    SECTION("meta()")
    {
        json j = json::meta();

        // Check basic metadata fields
        CHECK(j["name"] == "JSON for Modern C++");
        CHECK(j["copyright[redacted]
        CHECK(j["url"] == "https://github.com/nlohmann/json");

        // Check version object
        CHECK(j["version"] == json(
        {
            {"string", "3.12.0"},
            {"major", 3},
            {"minor", 12},
            {"patch", 0}
        }));

        // Check existence of platform field
        CHECK(j.find("platform") != j.end());

        // Check compiler fields exist
        CHECK(j.at("compiler").find("family") != j.at("compiler").end());
        CHECK(j.at("compiler").find("version") != j.at("compiler").end());
        CHECK(j.at("compiler").find("c++") != j.at("compiler").end());
    }
}

