// Fatalf handles fatal errors with formatted output
void fatalf(const char* format, ...)
{
    va_list ap;
    fprintf(stderr, "runtime/cgo: ");
    va_start(ap, format);
    vfprintf(stderr, format, ap);
    va_end(ap);
    fprintf(stderr, "\n");
    abort();
}

