// Test for ring buffer avoiding underflow on popBack
test$("ring-avoid-pop-back-underflow")
{
    Ring<int> ring(5);
    ring.pushBack(0);
    ring.pushBack(1);
    ring.pushBack(2);
    ring.pushBack(3);
    ring.pushBack(4);

    // Head should be at 0 initially
    expectEq$(ring._head, 0u);

    // Pop one element from back
    ring.popBack();

    // Head should wrap around to 4 (size - 1)
    expectEq$(ring._head, 4u);

    return Ok();
}

