    switch(g_app.currentTab)
    {
        case Tab::TAB_SLEEP:
            uiSleepMenuHandle(in);
            return;
        case Tab::TAB_INV:
            uiInventoryHandle(in);
            return;
        case Tab::TAB_SHOP:
            uiShopHandle(in);
            return;
        case Tab::TAB_PET:
        case Tab::TAB_FEED:
        case Tab::TAB_PLAY:
        default:
            uiPetScreenHandle(in);
            return;
    }
}

