// Register archive types for E1.31 protocol packets
REGISTER_DMX_ARCHIVE(FDMXProtocolE131RootLayerPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolE131FramingLayerPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolE131DMPLayerPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolUDPE131FramingLayerPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolUDPE131DiscoveryLayerPacket);

// Pack root layer packet into buffer
TSharedPtr<FBufferArchive> FDMXProtocolE131RootLayerPacket::Pack()
{
    TSharedPtr<FBufferArchive> Writer = MakeShared<FBufferArchive>();
    *Writer << *this;
    return Writer;
}

// Serialize root layer packet
void FDMXProtocolE131RootLayerPacket::Serialize(FArchive & Ar)
{
    Ar.SetByteSwapping(true);
    Ar << PreambleSize;
    Ar << PostambleSize;
    Ar.SetByteSwapping(false);
    Ar.Serialize((void*)ACNPacketIdentifier, ACN_IDENTIFIER_SIZE);
    Ar.SetByteSwapping(true);
    Ar << FlagsAndLength;
    Ar << Vector;
    Ar.SetByteSwapping(false);
    Ar.Serialize((void*)CID, ACN_CIDBYTES);
}

// Pack framing layer packet into buffer
TSharedPtr<FBufferArchive> FDMXProtocolE131FramingLayerPacket::Pack()
{
    TSharedPtr<FBufferArchive> Writer = MakeShared<FBufferArchive>();
    *Writer << *this;
    return Writer;
}

// Serialize framing layer packet
void FDMXProtocolE131FramingLayerPacket::Serialize(FArchive & Ar)
{
    Ar.SetByteSwapping(true);
    Ar << FlagsAndLength;
    Ar << Vector;
    Ar.SetByteSwapping(false);
    Ar.Serialize((void*)SourceName, ACN_SOURCE_NAME_SIZE);
    Ar.SetByteSwapping(true);
    Ar << Priority;
    Ar << SynchronizationAddress;
    Ar << SequenceNumber;
    Ar << Options;
    Ar << Universe;
}

// Pack DMP layer packet into buffer
TSharedPtr<FBufferArchive> FDMXProtocolE131DMPLayerPacket::Pack()
{
    TSharedPtr<FBufferArchive> Writer = MakeShared<FBufferArchive>();
    *Writer << *this;
    return Writer;
}

// Serialize DMP layer packet
void FDMXProtocolE131DMPLayerPacket::Serialize(FArchive & Ar)
{
    Ar.SetByteSwapping(true);
    Ar << FlagsAndLength;
    Ar << Vector;
    Ar << AddressTypeAndDataType;
    Ar << FirstPropertyAddress;
    Ar << AddressIncrement;
    Ar << PropertyValueCount;
    Ar << STARTCode;
    Ar.SetByteSwapping(false);
    Ar.Serialize((void*)DMX, ACN_DMX_SIZE);
}

// Pack UDP E1.31 framing layer packet into buffer
TSharedPtr<FBufferArchive> FDMXProtocolUDPE131FramingLayerPacket::Pack()
{
    TSharedPtr<FBufferArchive> Writer = MakeShared<FBufferArchive>();
    *Writer << *this;
    return Writer;
}

// Serialize UDP E1.31 framing layer packet
void FDMXProtocolUDPE131FramingLayerPacket::Serialize(FArchive & Ar)
{
    Ar.SetByteSwapping(true);
    Ar << FlagsAndLength;
    Ar << Vector;
    Ar.SetByteSwapping(false);
    Ar.Serialize((void*)SourceName, ACN_SOURCE_NAME_SIZE);
    Ar.Serialize((void*)Reserved, sizeof(Reserved));
}

// Pack UDP E1.31 discovery layer packet into buffer
TSharedPtr<FBufferArchive> FDMXProtocolUDPE131DiscoveryLayerPacket::Pack()
{
    TSharedPtr<FBufferArchive> Writer = MakeShared<FBufferArchive>();
    *Writer << *this;
    return Writer;
}

// Serialize UDP E1.31 discovery layer packet
void FDMXProtocolUDPE131DiscoveryLayerPacket::Serialize(FArchive & Ar)
{
    Ar.SetByteSwapping(true);
    Ar << FlagsAndLength;
    Ar << Vector;
    Ar << Page;
    Ar << Last;
    Ar.SetByteSwapping(false);
    Ar.Serialize((void*)Universes, sizeof(Universes));
}

#include "Misc/AutomationTest.h"

// Spec definition for System Automation
BEGIN_DEFINE_SPEC(AutomationSpec, "System.Automation.Spec", EAutomationTestFlags::EngineFilter | EAutomationTestFlags::ApplicationContextMask)
	bool Foo;
	FString RunOrder; 
END_DEFINE_SPEC(AutomationSpec)

void AutomationSpec::Define()
{
	// First describe block
	Describe("A Describe 1", [this]()
	{
		It("contains a spec with an expectation", [this]()
		{
			Foo = true;
			TestEqual("Foo", Foo, true);
		});
	});

	// Second describe block with disabled specs
	Describe("A Describe 2", [this]()
	{
		BeforeEach([&]()
		{
			Foo = false;
		});

		xIt("will not run disabled specs", [this]()
		{
			TestEqual("Foo", Foo, true);
		});

		xDescribe("with disabled nested Describes", [this]()
		{
			It("will not run specs within those Describes", [this]()
			{
				TestEqual("Foo", Foo, true);
			});
		});
	});

	// Third describe block - BeforeEach and AfterEach example 1
	Describe("A spec using BeforeEach and AfterEach", [this]()
	{
		BeforeEach([this]()
		{
			RunOrder = TEXT("A");
		});

		It("will run code before each spec in the Describe and after each spec in the Describe", [this]()
		{
			TestEqual("RunOrder", RunOrder, TEXT("A"));
		});

		AfterEach([this]()
		{
			RunOrder += TEXT("Z");
			TestEqual("RunOrder", RunOrder, TEXT("AZ"));
		});
	});

	// Fourth describe block - nested BeforeEach/AfterEach example
	Describe("A spec using BeforeEach and AfterEach", [this]()
	{
		AfterEach([this]()
		{
			RunOrder += TEXT("Z");
			TestEqual("RunOrder", RunOrder, TEXT("ABYZ"));
		});

		Describe("while nested inside another Describe", [this]()
		{
			It("will run all BeforeEach blocks and all AfterEach blocks", [this]()
			{
				TestEqual("RunOrder", RunOrder, TEXT("AB"));
			});

			AfterEach([this]()
			{
				RunOrder += TEXT("Y");
			});

			BeforeEach([this]()
			{
				RunOrder += TEXT("B");
			});
		});

		BeforeEach([this]()
		{
			RunOrder = TEXT("A");
		});
	});

	// Fifth describe block - deeply nested BeforeEach/AfterEach example
	Describe("A spec using BeforeEach and AfterEach", [this]()
	{
		BeforeEach([this]()
		{
			RunOrder = TEXT("A");
		});

		AfterEach([this]()
		{
			RunOrder += TEXT("Z");
			TestEqual("RunOrder", RunOrder, TEXT("ABCDXYZ"));
		});

		BeforeEach([this]()
		{
			RunOrder += TEXT("B");
		});

		Describe("while nested inside another Describe", [this]()
		{
			AfterEach([this]()
			{
				RunOrder += TEXT("Y");
			});

			BeforeEach([this]()
			{
				RunOrder += TEXT("C");
			});

			Describe("while nested inside yet another Describe", [this]()
			{
				It("will run all BeforeEach blocks and all AfterEach blocks", [this]()
				{
					TestEqual("RunOrder", RunOrder, TEXT("ABCD"));
				});

				AfterEach([this]()
				{
					RunOrder += TEXT("X");
				});

				BeforeEach([this]()
				{
					RunOrder += TEXT("D");
				});
			});
		});
	});
}

