    ASSERT_EQ(engine.m_lockup_enabled, true);
    ASSERT_NEAR(engine.m_wheelbase_max_nm, 18.0f, 0.01);
    ASSERT_EQ(Config::m_always_on_top, true);

    double saved_load;
    ASSERT_TRUE(Config::GetSavedStaticLoad("Ferrari 488 GTE", saved_load));
