// Test case for load_factor
TEST_CASE_MAP("load_factor", int, int)
{
    auto m = map_t();

    // Check initial load factor is 0.0
    REQUIRE(static_cast<double>(m.load_factor()) == doctest::Approx(0.0));

    // Insert elements and check load factor constraints
    for(int i=0; i<10000; ++i)
    {
        m.emplace(i, i);

        // Load factor should be positive after insertions
        REQUIRE(m.load_factor() > 0.0F);

        // Load factor should not exceed 0.8
        REQUIRE(m.load_factor() <= 0.8F);
    }
}

