    // load custom methods/properties
    registerHybrids(this, [](Prototype& prototype)
    {
      prototype.registerHybridMethod("getDeviceModel", &HybridRunAnywhereDeviceInfoSpec::getDeviceModel);
      prototype.registerHybridMethod("getOSVersion", &HybridRunAnywhereDeviceInfoSpec::getOSVersion);
      prototype.registerHybridMethod("getPlatform", &HybridRunAnywhereDeviceInfoSpec::getPlatform);
      prototype.registerHybridMethod("getTotalRAM", &HybridRunAnywhereDeviceInfoSpec::getTotalRAM);
      prototype.registerHybridMethod("getAvailableRAM", &HybridRunAnywhereDeviceInfoSpec::getAvailableRAM);
      prototype.registerHybridMethod("getCPUCores", &HybridRunAnywhereDeviceInfoSpec::getCPUCores);
      prototype.registerHybridMethod("hasGPU", &HybridRunAnywhereDeviceInfoSpec::hasGPU);
      prototype.registerHybridMethod("hasNPU", &HybridRunAnywhereDeviceInfoSpec::hasNPU);
      prototype.registerHybridMethod("getChipName", &HybridRunAnywhereDeviceInfoSpec::getChipName);
      prototype.registerHybridMethod("getThermalState", &HybridRunAnywhereDeviceInfoSpec::getThermalState);
      prototype.registerHybridMethod("getBatteryLevel", &HybridRunAnywhereDeviceInfoSpec::getBatteryLevel);
      prototype.registerHybridMethod("isCharging", &HybridRunAnywhereDeviceInfoSpec::isCharging);
      prototype.registerHybridMethod("isLowPowerMode", &HybridRunAnywhereDeviceInfoSpec::isLowPowerMode);
    });
  }

