// Process the websocket request
void StaticResponseProcessorWS::Process(SpectreWebsocketRequest& packet, SpectreWebsocket& sock)
{
    // Get base JSON response
    std::shared_ptr<json> res = packet.GetBaseJsonResponse();

    // Set payload
    (*res)["payload"] = *m_res;

    // Send packet
    sock.SendPacket(res);
}

