// Initialize display with default settings
void DspCore::initDisplay()
{
    begin();             /* SPI_DEFAULT_FREQ 40000000 */
    invert();
    cp437(true);
    flip();
    setTextWrap(false);
}

// Clear the display screen
void DspCore::clearDsp(bool black)
{
    fillScreen(black?0:config.theme.background);
}

// Set screen rotation based on config
void DspCore::flip()
{
    setRotation(config.store.flipscreen?1:3);
}

// Invert display colors based on config
void DspCore::invert()
{
    invertDisplay(config.store.invertdisplay);
}

// Put display into sleep mode
void DspCore::sleep(void)
{
    sendCommand(ILI9341_SLPIN);
    delay(150);
    sendCommand(ILI9341_DISPOFF);
    delay(150);
}

// Wake up display from sleep mode
void DspCore::wake(void)
{
    sendCommand(ILI9341_DISPON);
    delay(150);
    sendCommand(ILI9341_SLPOUT);
    delay(150);
}

