namespace {
class AndroidFileHandle
{
public:
    AndroidFileHandle(const std::string& filePath):
        m_filePath(filePath),
        m_asset(nullptr)
    {
        m_asset = AAssetManager_open(yarrar::android::getAssetManager(), m_filePath.c_str(), AASSET_MODE_BUFFER);
        if(!m_asset)
        {            
            throw std::runtime_error(std::string("unable to open resource: ") + m_filePath);
        }
    }

    ~AndroidFileHandle()
    {
        AAsset_close(m_asset);
    }

    void loadIntoBuffer(std::string& output)
    {
        if(!m_asset)
        {
            throw std::runtime_error(std::string("resource not available: ") + m_filePath);
        }

        size_t fileSize = AAsset_getLength(m_asset);
        output.clear();
        output.resize(fileSize);

        int bytesRead = AAsset_read(m_asset, &output[0], fileSize);
        if(bytesRead <= 0)
        {
            throw std::runtime_error(std::string("error reading from file: ") + m_filePath);
        }
    }

private:
    std::string m_filePath;
    AAsset* m_asset;
};
}

