	NeovimQt::InputConv converter;
};

void TestInputConversion::testSpecialKeyHandling()
{
	foreach(int key, converter.specialKeys.keys()) {
		QCOMPARE(converter.convertKey("", key, Qt::NoModifier),
			QString("<%1>").arg(converter.specialKeys.value(key)));
		QCOMPARE(converter.convertKey("", key, Qt::ControlModifier),
#ifdef Q_OS_MAC
			// On macOS, Control maps to the Cmd key, which is not yet supported
			QString("<D-%1>").arg(converter.specialKeys.value(key)));
#else
			QString("<C-%1>").arg(converter.specialKeys.value(key)));
#endif
		QCOMPARE(converter.convertKey("", key, Qt::AltModifier),
			QString("<A-%1>").arg(converter.specialKeys.value(key)));
		QCOMPARE(converter.convertKey("", key, Qt::MetaModifier),
#ifdef Q_OS_MAC
			// On macOS, Meta corresponds to the Control key
			QString("<C-%1>").arg(converter.specialKeys.value(key)));
#else
			// Meta key support is currently not implemented
			QString("<%1>").arg(converter.specialKeys.value(key)));
#endif
	}
}

