// Add message to queue if space permits, otherwise log drop
void addToQueueIfSpace(QUEUE_TYPE(uint8_t)* buffer, uint8_t* data,
        int length) {
    if(queue_free_space(buffer) < length + 2) {
            debug("Message discarded due to full output buffer\r\n");
            return;
    }
    for(int idx = 0; idx < length; idx++) {
        QUEUE_PUSH(uint8_t, buffer, (uint8_t)data[idx]);
    }
    QUEUE_PUSH(uint8_t, buffer, (uint8_t)'\r');
    QUEUE_PUSH(uint8_t, buffer, (uint8_t)'\n');
}

// Route message to appropriate output based on connection status
void transmitMessage(Listener* handler, uint8_t* payload, int payloadLength) {
    // Note: Multiple queued messages reduce throughput significantly—
    // performance drops nearly in half with dual queues. Potential solutions:
    // optimize the enqueue mechanism or enable queue sharing.
    if(handler->usbConnection->isConfigured) {
        addToQueueIfSpace(&handler->usbConnection->outputBuffer, payload, payloadLength);
    } else {
        addToQueueIfSpace(&handler->serialConnection->outputBuffer, payload, payloadLength);
    }
}

// Handle input processing for active communication channels
void handleInputProcessing(Listener* handler) {
    // USB processing is mandatory to support enumeration and control transfers
    processInputQueue(handler->usbConnection);
    if(!handler->usbConnection->isConfigured) {
        processInputQueue(handler->serialConnection);
    }
}

