#include "cmbf.h"
#include <unordered_map>
using namespace sketch::cmbf;

int main(int argc, char *argv[]) {
    // Initialize two CMBF structures: one approximate, one exact
    cmbf_exp_t approx_cmbf(4, 16, 1);
    cmbf_t exact_cmbf(4, 16, 5);

    // Report memory usage
    auto [stack_bytes, heap_bytes] = approx_cmbf.est_memory_usage();
    std::fprintf(stderr, "Memory - stack: %zu bytes, heap: %zu bytes\n", stack_bytes, heap_bytes);

    // Determine number of items to process
    size_t num_items = (argc > 1) ? std::strtoull(argv[1], nullptr, 10) : 100000;

    // Generate random 64-bit items
    std::vector<uint64_t> data_items;
    std::mt19937_64 rng_engine;
    while (data_items.size() < num_items) {
        data_items.push_back(rng_engine());
    }

    // Verify initial state is zero
    for (const auto val : approx_cmbf.ref()) {
        assert(unsigned(val) == 0);
    }

    // Add all items conservatively to both structures
    auto &approx_ref = approx_cmbf.ref();
    for (const auto item : data_items) {
        approx_cmbf.add_conservative(item);
        exact_cmbf.add_conservative(item);
    }

    // Build histograms of estimated counts
    std::unordered_map<uint64_t, uint64_t> exact_histogram, approx_histogram;
    for (const auto j : data_items) {
        ++approx_histogram[approx_cmbf.est_count(j)];
        ++exact_histogram[exact_cmbf.est_count(j)];
    }

    // Output exact histogram
    for (const auto &entry : exact_histogram) {
        std::fprintf(stderr, "Exact\t%" PRIu64 "\t%" PRIu64 "\n", entry.first, entry.second);
    }

    // Output approximate histogram
    for (const auto &entry : approx_histogram) {
        std::fprintf(stderr, "Approx\t%" PRIu64 "\t%" PRIu64 "\n", entry.first, entry.second);
    }

    return 0;
}

