using namespace scene;

// Constructor: initializes octree structure with specified depth
SceneGroup::SceneGroup(unsigned int treeDepth) {
    addOctreeLayers(treeDepth);
}

// Recursively adds octree layers up to the given level count
void SceneGroup::addOctreeLayers(unsigned int remainingLevels) {
    if(remainingLevels != 0) {
        childGroups.reset(new std::array<SceneGroup,8>);
        std::for_each(childGroups->begin(), childGroups->end(),
        [&remainingLevels](SceneGroup& subtree) {
            subtree.addOctreeLayers(--remainingLevels);
        });
    }
}

// Updates all scene items and recursively updates child groups
void SceneGroup::updateScene() {
    std::for_each(childItems.begin(), childItems.end(), [](std::unique_ptr<SceneItem>& node) {
        node->update();
    });
    if(childGroups != nullptr) {
        std::for_each(childGroups->begin(), childGroups->end(),
        [](SceneGroup& branch) {
            branch.updateScene();
        });
    }
}

// Renders all scene items and recursively renders child groups
void SceneGroup::renderScene() {
    std::for_each(childItems.begin(), childItems.end(), [](std::unique_ptr<SceneItem>& node) {
        node->draw();
    });
    if(childGroups != nullptr) {
        std::for_each(childGroups->begin(), childGroups->end(),
        [](SceneGroup& branch) {
            branch.renderScene();
        });
    }
}

#include "threadpool.h"

// Constructor: initializes a pool of worker threads
ThreadPool::ThreadPool(size_t num_threads)
{
    for (size_t index = 0; index < num_threads; ++index) {
        workers.emplace_back([this] {
            for (;;) {
                std::unique_lock<std::mutex> mtx_lock(this->queue_mutex);
                // Wait until there's a task or the pool is stopping
                while (!this->m_stop && this->tasks.empty())
                    this->condition.wait(mtx_lock);
                // Exit if stopped and no tasks remain
                if (this->m_stop && this->tasks.empty())
                    return;
                // Retrieve and remove the next task
                std::function<void()> work_item(this->tasks.front());
                this->tasks.pop();
                mtx_lock.unlock();
                // Execute the task outside the lock
                work_item();
            }
        });
    }
}

// Destructor: stops all workers and joins them
ThreadPool::~ThreadPool()
{
    {
        std::unique_lock<std::mutex> mtx_lock(queue_mutex);
        m_stop = true;
    }
    condition.notify_all();
    for (size_t idx = 0; idx < workers.size(); ++idx)
        workers[idx].join();
}

