namespace py = pybind11;

void InitializeDeviceModule(pybind11::module& module) {
    py::class_<Device>(module, "Device")
        .def(py::init(&MakeDevice))
        .def("__eq__", py::overload_cast<const Device&, const Device&>(&operator==))
        .def("__ne__", py::overload_cast<const Device&, const Device&>(&operator!=))
        .def("__repr__",
             [](Device dev) {
                 std::ostringstream stream;
                 stream << "<Device " << dev.name << ">";
                 return stream.str();
             });

    module.def("get_current_device", []() { return GetCurrentDevice(); });
    module.def("set_current_device", [](const Device& device) { SetCurrentDevice(device); });
    module.def("set_current_device", [](const std::string& device_name) { SetCurrentDevice(device_name); });
}
