namespace RosettaStone
{
Enchant Enchants::GetEnchantFromText(const std::string& cardId)
{
    std::vector<Effect> effectList;
    static std::regex attackHealthPattern("\\+([[:digit:]]+)/\\+([[:digit:]]+)");
    static std::regex attackPattern("\\+([[:digit:]]+) Attack");

    const std::string description = Cards::FindCardByID(cardId).text;
    std::smatch matchResults;

    if (std::regex_search(description, matchResults, attackHealthPattern))
    {
        effectList.emplace_back(Effects::AttackN(std::stoi(matchResults[1].str())));
        effectList.emplace_back(Effects::HealthN(std::stoi(matchResults[2].str())));
    }
    else if (std::regex_search(description, matchResults, attackPattern))
    {
        effectList.emplace_back(Effects::AttackN(std::stoi(matchResults[1].str())));
    }

    return Enchant(effectList);
}
}  // namespace RosettaStone

