// Main entry point for the Humbug Desktop application
int main(int argumentCount, char *arguments[])
{
    // Initialize the application instance
    HumbugApplication app(argumentCount, arguments);

    // Configure application metadata
    app.setApplicationName("Humbug");
    app.setApplicationVersion(HUMBUG_VERSION_STRING);

    // Set organization and application identifiers
    QCoreApplication::setOrganizationName("Humbug");
    QCoreApplication::setOrganizationDomain("humbug.com");
    QCoreApplication::setApplicationName("Humbug Desktop");

    // Create the main window
    HumbugWindow window;

    // Handle command-line URL specification
    if (argumentCount == 3 && QString(arguments[1]) == QString("--site")) {
        window.setUrl(QUrl(arguments[2]));
    }

#ifdef Q_OS_MAC
    // macOS-specific initialization
    macMain();
#endif

    // Assign main window to application and display
    app.setMainWindow(&window);
    window.show();

    // Start the application event loop
    return app.exec();
}

