#include "buffers.h"
#include "strutil.h"
#include "log.h"

// Process incoming data queue with user-provided handler
void handleIncomingData(ByteQueue* inputQueue, bool (*handler)(uint8_t*)) {
    uint8_t buffer[QUEUE_MAX_LENGTH(uint8_t)];
    queue_snapshot(inputQueue, buffer);

    if(handler == NULL) {
        debug("Handler function is NULL (%p) -- cannot process queue at %p\r\n",
                handler, inputQueue);
        return;
    }

    if(handler(buffer)) {
        queue_init(inputQueue);
    } else if(queue_full(inputQueue)) {
        debug("Received data packet exceeds buffer capacity\r\n");
        queue_init(inputQueue);
    } else if(strnchr((char*)buffer, queue_length(inputQueue), '\0') != NULL) {
        debug("Buffered data stream appears corrupted -- flushing buffer\r\n");
        queue_init(inputQueue);
    }
}

