void HtmlSnap::loadHtml(char* html)
{
    page.mainFrame()->setHtml(QString(html), QUrl());
}

void HtmlSnap::process()
{
    page.setViewportSize(page.mainFrame()->contentsSize());
    QImage snapshot(page.viewportSize(), QImage::Format_ARGB32);
    QPainter renderer(&snapshot);
    page.mainFrame()->render(&renderer);
    renderer.end();

    QByteArray bufferData;
    QBuffer ioBuffer(&bufferData);
    ioBuffer.open(QBuffer::WriteOnly);

    if (!snapshot.save(&ioBuffer, "PNG"))
        std::cerr << "failed to write image data" << std::endl;
    else
        std::cout << bufferData.toBase64().constData() << std::endl;

    QTimer::singleShot(0, this, SIGNAL(completed()));
}

