TEST(mha_parser, duplicate_entry_registration_throws_error)
{
  // Initialize a parser instance
  MHAParser::parser_t mha_parser;

  // Define two parser variables with distinct descriptions
  MHAParser::int_t var1("var1 description", "0", "[,]");
  MHAParser::int_t var2("var2 description", "0", "[,]");

  // Register first variable under name "entry"
  mha_parser.insert_item("entry", &var1);

  // Attempt to register second variable under same name - should fail
  EXPECT_THROW(mha_parser.insert_item("entry", &var2), MHA_Error);

  // Verify exception message content through try-catch block
  try {
    mha_parser.insert_item("entry", &var2);
    FAIL() << "insert_item operation should have triggered an exception";
  } catch(MHA_Error & exception) {
    ASSERT_STREQ("(mha_parser) The entry \"entry\" already exists.", exception.get_msg());
  }
}

