#include "bubble.hpp"
#include "swap.hpp"

void bubble(int *array, const int length)
{
    if(length <= 0) return;

    for(int index = 0; index + 1 < length; ++index)
        if(array[index] > array[index + 1]) swap(array[index], array[index + 1]);

    return bubble(array, length - 1);
}

