// Helper macros for encoder string literal handling
#define FUZZ_ENCODER_STRING_LITERAL_X(name) FUZZ_ENCODER_STRING_LITERAL(name)
#define FUZZ_ENCODER_STRING_LITERAL(name) #name

#ifndef FUZZ_ENCODER
#define FUZZ_ENCODER FUZZ_ENCODER_STRING_LITERAL_X(FUZZ_IMAGEMAGICK_ENCODER)
#endif

// Fuzzer entry point: processes input data as image blob
extern "C" int LLVMFuzzerTestOneInput(const uint8_t *inputData, size_t dataSize) {
  // Initialize blob with raw input data
  const Magick::Blob inputBlob(inputData, dataSize);

  // Create and configure image object
  Magick::Image processedImage;
  processedImage.magick(FUZZ_ENCODER);
  processedImage.fileName(std::string(FUZZ_ENCODER) + ":");

  try {
    // Attempt to read the image from blob
    processedImage.read(inputBlob);
  }
  catch (Magick::Exception &error) {
    return 0;  // Gracefully handle read errors
  }

  // Prepare output blob for encoded result
  Magick::Blob resultBlob;
  try {
    // Write processed image back to blob using same format
    processedImage.write(&resultBlob, FUZZ_ENCODER);
  }
  catch (Magick::Exception &error) {
    // Silently ignore write errors during fuzzing
  }

  return 0;  // Always return success for fuzzer
}

