// Define an aligned type for testing alignment requirements
struct __attribute__((aligned)) TestAlignedType {};

// Verify alignment matches _Unwind_Exception expectations
static_assert(alignof(TestAlignedType) == alignof(_Unwind_Exception),
  "_Unwind_Exception has incorrect alignment. This test should fail as expected");

// Minimal aligned structure with size and alignment of 1 byte
struct SmallAligned { };

// Ensure minimal alignment and size constraints
static_assert(alignof(SmallAligned) == 1 && sizeof(SmallAligned) == 1, "");

int main() {
  // Run multiple iterations to test exception handling alignment
  for (int iteration = 0; iteration < 10; ++iteration) {
    try {
      throw SmallAligned{};
    } catch (SmallAligned const& exceptionRef) {
      // Verify the thrown object is properly aligned
      assert(reinterpret_cast<uintptr_t>(&exceptionRef) % alignof(TestAlignedType) == 0);
    }
  }
  return 0;
}

