namespace
{
class Repl
{
  std::istream& input_stream_;
  std::ostream& output_stream_;
  std::string prompt_text_ = "mclisp> ";
  mclisp::Reader reader_instance_;

public:
  explicit Repl(std::istream& in = std::cin, std::ostream& out = std::cout):
    input_stream_(in), output_stream_(out), reader_instance_(in) {};

  int run();
};

int Repl::run()
{
  std::ostringstream buffer;
  while (buffer.str() != "EXIT" && buffer.str() != "(EXIT . NIL)")
  {
    output_stream_ << prompt_text_;
    buffer.str("");
    buffer.clear();
    const mclisp::ConsCell *expression = reader_instance_.Read();
    buffer << *expression;
    output_stream_ << *expression << std::endl;
  }
  return 0;
}
}; // end namespace

int main()
{
  Repl repl_instance;
  return repl_instance.run();
}

