    ::memset(m_fileName, 0, sizeof(m_fileName));
    ::memset(m_functionName, 0, sizeof(m_functionName));
}
//==============================================================================
Log::Log(const LoggerConfigPtr &spConfig, const std::string &message) :
    m_level(NUM_LEVELS),
    m_timestamp(-1.0),
    m_gameId(-1),
    m_lineNumber(-1),
    m_text(message, 0, spConfig->MaxMessageSize())
{
    ::memset(m_fileName, 0, sizeof(m_fileName));
    ::memset(m_functionName, 0, sizeof(m_functionName));
}
//==============================================================================
std::ostream &operator << (std::ostream &stream, const Log &log)
{
    stream << log.m_level << "\t";
    stream << log.m_timestamp << "\t";
    stream << log.m_gameId << "\t";
    stream << log.m_fileName << "\t";
    stream << log.m_functionName << "\t";
    stream << log.m_lineNumber << "\t";
    stream << log.m_text << "\n";
    return stream;
}
}

