// Add a message to the queue if there's enough space, otherwise log and drop
void enqueueIfSpace(QUEUE_TYPE(uint8_t)* buffer, uint8_t* data,
        int length) {
    if(queue_available(buffer) < length + 2) {
        debug("Dropped incoming CAN message -- send buffer (at %p) full\r\n",
                buffer);
        return;
    }
    for(int index = 0; index < length; index++) {
        QUEUE_PUSH(uint8_t, buffer, (uint8_t)data[index]);
    }
    QUEUE_PUSH(uint8_t, buffer, (uint8_t)'\r');
    QUEUE_PUSH(uint8_t, buffer, (uint8_t)'\n');
}

// Send message via USB if configured, otherwise use serial
void transmitMessage(Listener* handler, uint8_t* payload, int payloadLength) {
    if(handler->usb->configured) {
        enqueueIfSpace(&handler->usb->sendQueue, payload, payloadLength);
    } else {
        enqueueIfSpace(&handler->serial->sendQueue, payload, payloadLength);
    }
}

// Process input queues, prioritizing USB processing
void handleListenerBuffers(Listener* handler) {
    // Always process USB first as it runs the MCU's USB task for enumeration
    processInputQueue(handler->usb);
    if(!handler->usb->configured) {
        processInputQueue(handler->serial);
    }
}

