#include <boost/asio/io_service.hpp>
using boost::asio::ip::tcp;

BoostTransport::BoostTransport()
    : io_service_(),
      socket_(io_service_)
{
}

BoostTransport::~BoostTransport()
{
    if (socket_.is_open()) {
        socket_.close();
    }
}

void
BoostTransport::Connect(std::string host, short port_number)
{
    tcp::resolver resolver(io_service_);
    auto endpoints = resolver.resolve({host, std::to_string(port_number)});
    try
    {
        boost::asio::connect(socket_, endpoints);
    }
    catch (const boost::system::system_error& e)
    {
        LOG(LogLevel::Warning) << "Connection failed to " << host << ":" << port_number;
    }
}

void
BoostTransport::Send(std::string message)
{
    try
    {
        boost::asio::write(socket_, boost::asio::buffer(message.c_str(), message.length()));
    }
    catch (const boost::system::system_error& e)
    {
        LOG(LogLevel::Warning) << "Failed to send data over transport";
    }
}

