#include "math_container.h"
using std::complex;

/******************************************************/
/*solve the equation cosh(x)=exp(y), input y, return x*/
/******************************************************/
complex<double> solve_coshx_eq_expy(double inputY)
{
    complex<double> expYVal{exp(inputY), 0.0};
    complex<double> resultGamma = log(expYVal - sqrt(expYVal * expYVal - 1.0));

    // Since resultGamma is pure real or pure imaginary, normalize it:
    if (abs(resultGamma.real()) < abs(resultGamma.imag())) {
        resultGamma = complex<double>(0.0, resultGamma.imag());
    } else {
        resultGamma = complex<double>(resultGamma.real(), 0.0);
    }

    return resultGamma;
}

