#include "rapidcheck/detail/FrequencyMap.h"
#include <algorithm>

namespace rc {
namespace detail {

// Constructor: builds cumulative frequency table from input frequencies
FrequencyMap::FrequencyMap(const std::vector<std::size_t> &freqs)
    : total(0) {
  cumulative_table.reserve(freqs.size());

  // Build cumulative sum table
  for (auto value : freqs) {
    total += value;
    cumulative_table.push_back(total);
  }
}

// Find index corresponding to given cumulative value using binary search
std::size_t FrequencyMap::lookup(std::size_t value) const {
  return std::upper_bound(cumulative_table.begin(), cumulative_table.end(), value) - 
         cumulative_table.begin();
}

// Return the total sum of all frequencies
std::size_t FrequencyMap::sum() const { 
  return total; 
}

