#include "photoeffects.hpp"
using namespace cv;

// Test for sepia effect with single-channel input (should fail)
TEST(photoeffects, SepiaFakeTest) {
    Mat input(10, 10, CV_8UC1), output;
    EXPECT_EQ(0, sepia(input, output));
}

// Test for sepia effect with three-channel input (should succeed)
TEST(photoeffects, SepiaFailTest) {
    Mat input(10, 10, CV_8UC3), output;
    EXPECT_EQ(1, sepia(input, output));
}

// Comprehensive test for sepia effect on valid input
TEST(photoeffects, SepiaTest) {
    Mat input(10, 10, CV_8UC1), result, hsvResult;
    vector<Mat> splitChannels(3);

    // Apply sepia filter
    EXPECT_EQ(0, sepia(input, result));

    // Convert to HSV color space for analysis
    cvtColor(result, hsvResult, CV_BGR2HSV);
    split(hsvResult, splitChannels);

    // Check hue value around 19 degrees (±1 tolerance)
    EXPECT_LE(19 - 1, splitChannels[0].at<uchar>(0, 0));
    EXPECT_GE(19 + 1, splitChannels[0].at<uchar>(0, 0));

    // Check saturation value around 78 (±1 tolerance)
    EXPECT_LE(78 - 1, splitChannels[1].at<uchar>(0, 0));
    EXPECT_GE(78 + 1, splitChannels[1].at<uchar>(0, 0));

    // Check brightness/value component with offset of 20 from original (±1 tolerance)
    EXPECT_LE(input.at<uchar>(0, 0) + 20 - 1, splitChannels[2].at<uchar>(0, 0));
    EXPECT_GE(input.at<uchar>(0, 0) + 20 + 1, splitChannels[2].at<uchar>(0, 0));
}

