    = GridTools::find_active_cell_around_point (mesh, query_point);
  deallog << found_cell << std::endl;
  for (unsigned int vertex_index=0; vertex_index<GeometryInfo<2>::vertices_per_cell; ++vertex_index)
    deallog << "<" << found_cell->vertex(vertex_index) << "> ";
  deallog << std::endl;
  Assert (query_point.distance (found_cell->center()) < found_cell->diameter()/2,
	  ExcInternalError());
}

