namespace ql {

configured_limits_t
from_optargs(rdb_context_t *context, signal_t *interruptor, global_optargs_t *opts)
{
    if (opts->has_optarg("array_limit")) {
        // Create a minimal environment with no arguments to avoid circular dependencies.
        // This is safe because we only need it for parsing the limit value.
        env_t env(context, interruptor, std::map<std::string, wire_func_t>(), nullptr);
        int64_t limit_value = opts->get_optarg(&env, "array_limit")->as_int();

        rcheck_datum(limit_value > 1, base_exc_t::GENERIC,
                     strprintf("Invalid array size limit `%" PRIi64 "`.", limit_value));
        return configured_limits_t(limit_value);
    } else {
        return configured_limits_t();
    }
}

RDB_IMPL_ME_SERIALIZABLE_1(configured_limits_t, array_size_limit_);
INSTANTIATE_SERIALIZABLE_SELF_FOR_CLUSTER(configured_limits_t);

