// Process incoming message and dispatch based on payload type
bool traffic::MessageWorker::handle(std::string &output, void *buffer, size_t length)
{
	(void) output;
	request::Request msg;
	msg.ParseFromArray(buffer, length);
	switch (msg.Payload_case()) {
		case request::Request::kStatistic:
			return handle_statistics();
		case request::Request::kSummary:
			return handle_summary();
		case request::Request::PAYLOAD_NOT_SET:
			return false;
	}
	BOOST_ASSERT(false && "Message parsing failed!");
	return false;
}

