#include <test/unit/math/test_ad.hpp>
#include <limits>

// Test derivatives for normal lccdf computation
TEST(mathMixScalFun, lccdf_derivatives) {
  // Define the function to test: normal_lccdf with parameters mu and sigma
  auto test_func = [](const double mean, const double stddev) {
    return [=](const auto& value) { 
      return stan::math::normal_lccdf(value, mean, stddev); 
    };
  };

  // Test cases with different y values and parameters
  stan::test::expect_ad(test_func(0.0, 1.0), -50.0);
  stan::test::expect_ad(test_func(0.0, 1.0), -20.0 * stan::math::SQRT_TWO);
  stan::test::expect_ad(test_func(0.0, 1.0), -5.5);
  stan::test::expect_ad(test_func(0.0, 1.0), 0.0);
  stan::test::expect_ad(test_func(0.0, 1.0), 0.15);
  stan::test::expect_ad(test_func(0.0, 1.0), 1.14);
  stan::test::expect_ad(test_func(0.0, 1.0), 3.00);
  stan::test::expect_ad(test_func(0.0, 1.0), 10.00);
  stan::test::expect_ad(test_func(-1.0, 2.0), 1.50);
  stan::test::expect_ad(test_func(2.0, 1.0), 0.50);

  // Third-order autodiff tests may fail at piecewise function boundaries
  stan::test::ad_tolerances tolerances;
  tolerances.grad_hessian_grad_hessian_ = 1e1;
  stan::test::expect_ad(tolerances, test_func(0.0, 1.0), 0.1 * stan::math::SQRT_TWO);
}

