#include <cstdlib>
#include <iostream>
#include "caf/all.hpp"

using namespace caf;
using std::endl;

int main() {
  // Seed random number generator with current time
  std::srand(static_cast<unsigned>(std::time(nullptr)));

  // Spawn 50 actors
  for (int idx = 1; idx <= 50; ++idx) {
    spawn<blocking_api>([idx](blocking_actor* actor_ptr) {
      // Print greeting message
      aout(actor_ptr) << "Hi there! This is actor nr. "
                      << idx << "!" << endl;

      // Generate random delay
      std::random_device device;
      std::default_random_engine engine(device());
      std::chrono::milliseconds timeout{engine() % 10};

      // Send delayed message to self
      actor_ptr->delayed_send(actor_ptr, timeout, atom("done"));

      // Wait for the message and print goodbye
      actor_ptr->receive(others() >> [idx, actor_ptr] {
        aout(actor_ptr) << "Actor nr. "
                        << idx << " says goodbye!" << endl;
      });
    });
  }

  // Wait for all spawned actors to complete
  await_all_actors_done();

  // Shutdown the system
  shutdown();
  return 0;
}

