// Add message to queue if space is available, otherwise log drop
void addToQueueIfSpace(QUEUE_TYPE(uint8_t)* queue, uint8_t* data,
        int length) {
    if(queue_available(queue) < length + 1) {
            debug("Dropped incoming CAN message -- send queue full\r\n");
            return;
    }
    for(int idx = 0; idx < length; idx++) {
        QUEUE_PUSH(uint8_t, queue, (uint8_t)data[idx]);
    }
    QUEUE_PUSH(uint8_t, queue, (uint8_t)'\n');
}

// Send message to all configured output queues
void transmitMessage(Listener* listener, uint8_t* data, int length) {
    // TODO the more we enqueue here, the slower it gets - cuts the rate by
    // almost half to do it with 2 queues. we could either figure out how to
    // share a queue or make the enqueue function faster. right now I believe it
    // enqueues byte by byte, which could obviously be improved.
    addToQueueIfSpace(&listener->usb->sendQueue, data, length);
#ifdef SERIAL
    addToQueueIfSpace(&listener->serial->sendQueue, data, length);
#endif
}

// Process all active input queues
void handleListenerQueues(Listener* listener) {
    processInputQueue(listener->usb);
#ifdef SERIAL
    processInputQueue(listener->serial);
#endif
}

