TEST(keystore_tests, store_and_retrieve_spending_key) {
    CBasicKeyStore store;
    libzcash::SpendingKey retrievedKey;
    std::set<libzcash::PaymentAddress> addresses;

    store.GetPaymentAddresses(addresses);
    ASSERT_EQ(0, addresses.size());

    auto spendingKey = libzcash::SpendingKey::random();
    auto paymentAddr = spendingKey.address();

    // Verify we cannot retrieve a key before adding it
    ASSERT_FALSE(store.HaveSpendingKey(paymentAddr));
    ASSERT_FALSE(store.GetSpendingKey(paymentAddr, retrievedKey));

    store.AddSpendingKey(spendingKey);

    ASSERT_TRUE(store.HaveSpendingKey(paymentAddr));
    ASSERT_TRUE(store.GetSpendingKey(paymentAddr, retrievedKey));
    ASSERT_EQ(spendingKey, retrievedKey);

    store.GetPaymentAddresses(addresses);
    ASSERT_EQ(1, addresses.size());
    ASSERT_EQ(1, addresses.count(paymentAddr));
}

