TEST(Value, ToString) {
  Value string_val(NULL, "hi\" $me\\you\\$\\\"");
  EXPECT_EQ("hi\" $me\\you\\$\\\"", string_val.ToString(false));
  EXPECT_EQ("\"hi\\\" \\$me\\you\\\\\\$\\\\\\\"\"", string_val.ToString(true));

  // Test lists, bools, and ints.
  Value array_val(NULL, Value::LIST);
  array_val.list_value().push_back(Value(NULL, "hi\"me"));
  array_val.list_value().push_back(Value(NULL, true));
