#include "mainwindow.hpp"
#include <QApplication>
#include <QCommandLineParser>
#include <QDebug>
#include <cstdio>

bool debugMode = false;

void customMessageHandler(QtMsgType type, const QMessageLogContext &context, const QString &message)
{
    QByteArray localizedMsg = message.toLocal8Bit();
    switch (type)
    {
    case QtDebugMsg:
        if (debugMode)
            fprintf(stdout, "DEBUG %s:%s(%d): %s\n", context.file, context.function, context.line, localizedMsg.constData());
        break;
    case QtInfoMsg:
        fprintf(stdout, "INFO %s:%s(%d): %s\n", context.file, context.function, context.line, localizedMsg.constData());
        break;
    case QtWarningMsg:
        fprintf(stderr, "WARN %s:%s(%d): %s\n", context.file, context.function, context.line, localizedMsg.constData());
        break;
    case QtCriticalMsg:
        fprintf(stderr, "CRIT %s:%s(%d): %s\n", context.file, context.function, context.line, localizedMsg.constData());
        break;
    case QtFatalMsg:
        fprintf(stderr, "FATAL %s:%s(%d): %s\n", context.file, context.function, context.line, localizedMsg.constData());
        break;
    }
}

int main(int argc, char *argv[])
{
    qInstallMessageHandler(customMessageHandler);
    QApplication app(argc, argv);
    app.setApplicationName("KShare");
    app.setOrganizationName("ArsenArsen");
    app.setApplicationVersion("1.0");

    QCommandLineParser cmdParser;
    cmdParser.addHelpOption();

    QCommandLineOption bg({ "b", "background" }, "Starts the application in background mode without showing the main window.");
    QCommandLineOption verboseOpt({ "v", "verbose" }, "Enables detailed debug output for QtDebugMsg messages.");

    cmdParser.addOption(bg);
    cmdParser.addOption(verboseOpt);
    cmdParser.process(app);

    debugMode = cmdParser.isSet(verboseOpt);

    MainWindow window;
    if (!cmdParser.isSet(bg)) {
        window.show();
    }

    return app.exec();
}

