// Convert error code to human-readable string using system APIs
std::string errno_string(int error_code)
{
    char temp_buffer[2048];
#ifdef _WIN32
    if (strerror_s(temp_buffer, sizeof(temp_buffer), error_code)) 
        throw std::runtime_error("strerror_s operation failed");
    return temp_buffer;
#else
    strerror_r(error_code, temp_buffer, sizeof(temp_buffer));
    return temp_buffer;
#endif
}

#ifdef _WIN32
// Retrieve Windows-specific error message as UTF-8 string
std::string win_error_string(int error_code)
{
    std::unique_ptr<wchar_t[], LocalFreeDeleter> message_buffer;
    FormatMessageW(
        FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
        nullptr, error_code, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
        (LPWSTR)(wchar_t**)unique_out_ptr(message_buffer), 0, nullptr);
    return utf16_to_utf8(message_buffer.get());
}
