public:

    ExamResult() = default;
    ExamResult(unsigned long long u) : result(u) { }
    ExamResult(const string &s) : result(s) { }
    ExamResult(const char* cp) : result(cp) { }

    //required by test 17.12
    void set_response(size_t index, bool value = true) {
        result.set(index, value);
    }

    bool get_response(size_t index) {
        return result[index];
    }

    size_t length() const {
        return result.size();
    }

private:
