#define SUPPRESS_REPORTING

extern "C" void ReportMissingAlias(unsigned varIdA, unsigned varIdB, void *valuePtr) {
#ifdef SUPPRESS_REPORTING
#else
  fprintf(stderr, "alias detected: value(%u) == value(%u) == %p\n", varIdA, varIdB, valuePtr);
#endif
}

extern "C" void AbortIfMissed(void *ptrA, unsigned varIdA,
                              void *ptrB, unsigned varIdB) {
  if (ptrA && ptrA == ptrB) {
    ReportMissingAlias(varIdA, varIdB, ptrA);
    abort();
  }
}

extern "C" void ReportIfMissed(void *ptrA, unsigned varIdA,
                               void *ptrB, unsigned varIdB) {
  if (ptrA && ptrA == ptrB) {
    ReportMissingAlias(varIdA, varIdB, ptrA);
  }
}

