#include <mutex>

// Calculator class for thread-safe arithmetic operations
struct Calculator {
    std::mutex mtx;
    int value;
    Calculator() : value(100) {}

    void multiply(int factor){
        std::lock_guard<std::mutex> guard(mtx);
        value = value * factor;
    }

    void divide(int divisor){
        std::lock_guard<std::mutex> guard(mtx);
        value = value / divisor;
    }

    void process(int a, int b){
        std::lock_guard<std::mutex> guard(mtx);
        multiply(a);
        divide(b);
    }
};

int main(){
    Calculator calc;
    calc.process(15, 5);
    return 0;
}

