using namespace ofp;

void MPTableStatsBuilder::write(Writable *stream) {
  UInt8 ver = stream->version();
  if (ver >= OFP_VERSION_4) {
    stream->write(&msg_, 4);
    stream->write(&msg_.activeCount_, 20);
    stream->flush();
  } else if (ver == OFP_VERSION_1) {
    stream->write(&msg_, sizeof(msg_));
    stream->flush();
  } else {
    log::debug("MPTableStatsBuilder not supported for version:", ver);
  }
}

