void SpriteSheetImporter::import(const ImportingAsset& asset, IAssetCollector& collector)
{
    SpriteSheet spriteSheet;
    spriteSheet.load(YAMLConvert::parseConfig(asset.inputFiles.front().data).getRoot());

    Metadata metadata = asset.inputFiles.front().metadata;
    metadata.set("asset_compression", "deflate");

    collector.output(Path(asset.assetId).replaceExtension("").string(), AssetType::SpriteSheet, Serializer::toBytes(spriteSheet), metadata);
}

