class FinancialAccount {
  char ownerName[23];
  char accountNumber[15];
  double balance;
public:
  FinancialAccount(const char _ownerName[], const char _accountNumber[], double _balance) {
    strcpy(ownerName, _ownerName);
    strcpy(accountNumber, _accountNumber);
    balance = _balance;
  }
  void display() {
    cout << "Owner: " << ownerName << '\n' <<
            "Account Number: " << accountNumber << '\n' <<
            "Balance: " << balance << '\n';
  }
  void deposit(double amount) {
    balance += amount;
  }
  void withdraw(double amount) {
    if (balance >= amount) {
      balance -= amount;
    }
  }
};

int main() {
  FinancialAccount account("Petar", "A12345", 2000);
  account.display();
  account.deposit(300);
  account.display();
  account.withdraw(500);
  account.display();
  return 0;
}

