template<typename IteratorT>
void display(const range<IteratorT>& r)
{
    for (auto element : r)
        std::cout << element << " ";
    std::cout << std::endl;
}

template<typename IteratorT>
size_t count_elements(const range<IteratorT>& r)
{
    return std::distance(r.begin(), r.end());
}

int main()
{
    std::list<int> data{ 3, 1, 4, 22, 31 };
    auto view = make_range(data.begin(), data.end());
    display(view);
    std::cout << "Count: " << count_elements(view) << std::endl;

    std::vector<int> buffer;
    std::copy(data.begin(), data.end(), std::back_inserter(buffer));

    auto partial_view = make_range(buffer.begin(), std::next(buffer.begin(), 4));
    display(partial_view);
    std::cout << "Count: " << count_elements(partial_view) << std::endl;

    randomize();
    std::shuffle(partial_view.begin(), partial_view.end(), global_urng());

    std::copy(partial_view.begin(), partial_view.end(), std::ostream_iterator<int>(std::cout, " "));
    std::cout << std::endl;

    std::copy(view.begin(), view.end(), std::ostream_iterator<int>(std::cout, " "));
    std::cout << std::endl;

    return 0;
}

