#include <iostream>
using namespace std;

int main() {
    string str1, str2;
    cout << "Input two words: ";
    cin >> str1 >> str2;

    int len1 = str1.size();
    int len2 = str2.size();

    int dp[len1 + 1][len2 + 1];

    // Initialize base cases
    for (int row = 0; row <= len1; row++) {
        for (int col = 0; col <= len2; col++) {
            if (row == 0) {
                dp[row][col] = col;
            } else if (col == 0) {
                dp[row][col] = row;
            } else if (str1[row - 1] == str2[col - 1]) {
                dp[row][col] = dp[row - 1][col - 1];
            } else {
                dp[row][col] = 1 + min(dp[row - 1][col], 
                                      min(dp[row][col - 1], 
                                          dp[row - 1][col - 1]));
            }
        }
    }

    cout << "Minimum edit distance: " << dp[len1][len2] << endl;
    return 0;
}

