#include <iostream>
#include "CmdMessenger.h"
using namespace std;

enum {
  ksetled
};

int main(int argc, char *argv[]) {
    if (argc == 2) {
        char command;
        cmd::CmdMessenger device(argv[1], 115200);
        cmd::Cmd ledCommand(ksetled);
        cmd::Timeout timeout = cmd::Timeout::simpleTimeout(1000);
        device.setTimeout(timeout);

        while (true) {
            cout << "'1' turns on, '0' turns off, 'q' quits: ";
            cin >> command;
            cout << endl;

            switch (command) {
                case '1':
                    ledCommand << true << CmdEnd();
                    device.send(ledCommand);
                    cout << ledCommand.getNumArgs() << endl;
                    ledCommand.clear();
                    break;
                case '0':
                    ledCommand << false << CmdEnd();
                    device.send(ledCommand);
                    ledCommand.clear();
                    break;
                case 'q':
                    break;
            }

            if (command == 'q') break;
            cout << "feeding in serial data\n";
            device.feedInSerialData();
        }
    } else {
        cout << "Usage: led 'port_name'\n";
    }

    return 0;
}

