// Define peer nodes for the Raft cluster
std::vector<raft_node_endpoint_t> cluster_peers{
        {1ul, "localhost", 12345, 13001},
        {2ul, "localhost", 12346, 13002},
        {3ul, "localhost", 12347, 13003}
};

int main(int argc, char* argv[]) {
    try {
        // Launch worker threads for each Raft node
        std::vector<std::thread> node_threads;
        for (auto &peer : cluster_peers) {
            node_threads.emplace_back([&peer]() {
                auto node_instance = raft_node(peer.uuid, std::make_shared<raft::config>(cluster_peers));
                node_instance.start();
            });
        }

        // Join all worker threads to ensure proper cleanup
        std::for_each(node_threads.begin(), node_threads.end(), [](std::thread &worker){
            worker.join();
        });
    }
    catch(std::exception& e) {
        std::cerr << "Exception occurred" << std::endl;
        std::cerr << e.what() << std::endl;
    }
    return 0;
}

