#define TEST_CLASS ModifiedBaseCPUTest

class TestCPUForVerification : public BaseCPU {
public:
    TestCPUForVerification(int limitTicks, const System &sys) 
        : limitTicks(limitTicks), tickCount(0), resetCount(0), BaseCPU(sys) { }

    void reset() { resetCount++; }

    void tick() {
        assert(isRunning());
        tickCount++;
        if (tickCount >= limitTicks) {
            stop();
        }
    }

    int tickCount;
    int resetCount;
    int limitTicks;
};

const int MAX_TICKS_FOR_TEST = 3;

class TEST_CLASS : public testing::Test {
protected:
    TEST_CLASS() : cpu(MAX_TICKS_FOR_TEST, dummySystem) { }
    TestCPUForVerification cpu;
    System dummySystem;
};

TEST_F(TEST_CLASS, VerifyExecutionBehavior) {
    ASSERT_FALSE(cpu.isRunning()) << "Wrong initial running state";
    ASSERT_EQ(cpu.tickCount, 0) << "Wrong initial tick count";
    ASSERT_EQ(cpu.resetCount, 0) << "Wrong initial reset count";

    cpu.startup();

    ASSERT_FALSE(cpu.isRunning()) << "Wrong final running state";
    ASSERT_EQ(cpu.tickCount, MAX_TICKS_FOR_TEST) << "Wrong final tick count";
    ASSERT_EQ(cpu.resetCount, 1) << "Wrong final reset count";
}

