// Constructor: opens the database file
Database::Database(string dbPath) {
    char pathBuffer[100];
    strcpy(pathBuffer, dbPath.c_str());
    sqlite3_open(pathBuffer, &connection);
}

// Destructor: closes the database connection
Database::~Database() { 
    sqlite3_close(connection); 
}

// Callback function for sqlite3_exec to process query results
int resultHandler(void *output, int fieldCount, char **fieldValues, char **) {
    vector<vector<string>> &queryResults =
        *(static_cast<vector<vector<string>> *>(output));

    vector<string> currentRow;
    for (int index = 0; index < fieldCount; index++) {
        string value = fieldValues[index] ? fieldValues[index] : "NULL";
        currentRow.push_back(value);
        cout << fieldValues[index] << ", ";
    }
    queryResults.push_back(currentRow);
    return 0;
}

// Execute SQL command and return results as a 2D vector of strings
vector<vector<string>> Database::runQuery(string sqlStatement) const {
    cout << "Executing SQL: " << sqlStatement << endl;
    cout << "Data: ";

    vector<vector<string>> outputData;
    char *errorMessage;

    int executionResult = sqlite3_exec(
        connection,              // Open database handle
        sqlStatement.c_str(),   // SQL statement to execute
        resultHandler,          // Function to call for each result row
        &outputData,            // First argument passed to callback
        &errorMessage           // Pointer to store error message
    );

    cout << endl;
    cout << "DB status: " << executionResult;

    if (errorMessage) {
        cout << ", Error: " << errorMessage;
        sqlite3_free(errorMessage);
    }

    cout << endl;
    return outputData;
}

#include <iostream>
using namespace std;

// Perform shell sort on the given array
int shellSort(int data[], int size)
{
    for (int gap = size / 2; gap > 0; gap /= 2)
    {
        for (int index = gap; index < size; index++)
        {
            int temp = data[index];
            int position;
            for (position = index; (position >= gap) && (data[position - gap] > temp); position -= gap)
                data[position] = data[position - gap];
            data[position] = temp;
        }
    }
    return 0;
}

int main()
{
    int length, list[10000];
    cin >> length;
    for (int k = 0; k < length; k++)
        cin >> list[k];
    shellSort(list, length);
    cout << "Array after sorting: \n";
    for (int k = 0; k < length; k++)
        cout << list[k] << " ";
    cout << endl;
    return 0;
}

