#include "gtest/gtest.h"
#include "../include/rainy.h"

using namespace rainy;

// Test for Sphere instance creation and basic properties
TEST(SphereTest, InstanceTest) {
    Sphere sphere(2.0, Vector3(0.0, 0.0, 0.0), Color(), Color(0.75, 0.75, 0.75), REFLECTION_DIFFUSE);

    // Verify center coordinates
    EXPECT_EQ(0.0, sphere.center().x());
    EXPECT_EQ(0.0, sphere.center().y());
    EXPECT_EQ(0.0, sphere.center().z());

    // Verify emission color is zero
    EXPECT_EQ(0.0, sphere.emission().x());
    EXPECT_EQ(0.0, sphere.emission().y());
    EXPECT_EQ(0.0, sphere.emission().z());

    // Verify diffuse reflection color
    EXPECT_EQ(0.75, sphere.color().x());
    EXPECT_EQ(0.75, sphere.color().y());
    EXPECT_EQ(0.75, sphere.color().z());

    // Verify reflection type
    EXPECT_EQ(REFLECTION_DIFFUSE, sphere.reftype());

    // Test ray intersection
    HitPoint hit;
    EXPECT_TRUE(sphere.intersect(Ray(Vector3(10.0, 0.0, 0.0), Vector3(-1.0, 0.0, 0.0)), hit));

    // Verify hit point position
    EXPECT_EQ(2.0, hit.position().x());
    EXPECT_EQ(0.0, hit.position().y());
    EXPECT_EQ(0.0, hit.position().z());

    // Verify normal vector at hit point
    EXPECT_EQ(1.0, hit.normal().x());
    EXPECT_EQ(0.0, hit.normal().y());
    EXPECT_EQ(0.0, hit.normal().z());

    // Verify no intersection when ray misses the sphere
    EXPECT_FALSE(sphere.intersect(Ray(Vector3(10.0, 0.0, 0.0), Vector3(0.0, 1.0, 0.0)), hit));
}

int main(int argc, char **argv) {
    ::testing::InitGoogleTest(&argc, argv);
    return RUN_ALL_TESTS();
}

