// Template class for returning types
template <typename T> class ResultHolder {};
template <typename T> class SubClass;
template <typename T>
class Parent
{
  static SubClass<T>* instantiate();
};
template <typename T>
class SubClass : public Parent<T> {
public:
  static void execute();
};
