// Public methods.
void TextFormatter::afterEachHookFailed(exception_ptr error) const {
    output_ << "An error occurred in an `after(:example)` hook" << endl;
    outputException(error);
}

void TextFormatter::afterAllHookFailed(exception_ptr error) const {
    output_ << "An error occurred in an `after(:context)` hook" << endl;
    outputException(error);
}

void TextFormatter::aroundHookFailed(exception_ptr error) const {
    output_ << "An error occurred in an `around(:example)` hook" << endl;
    outputException(error);
}

void TextFormatter::dumpFailures(const list<exception_ptr>& errors) const {
    if (errors.empty())
        return;
    output_ << endl << "Failures:" << endl;
    for (auto error : errors)
        outputException(error);
}

// Protected methods.
TextFormatter::TextFormatter(ostream& stream) : Formatter(stream) {}

// Private methods.
void TextFormatter::outputException(exception_ptr error) const {
    try {
        rethrow_exception(error);
    } catch (const exception& e) {
        output_ << e.what() << endl;
    }
}

} // namespace formatters
} // namespace core
