// Converts a Bish AST to bash script and outputs to stream
void translate_to_bash(std::ostream &stream, Bish::AST *abstract_syntax_tree) {
    stream << "#!/bin/bash\n";
    Bish::CompileToBash translator(stream);
    abstract_syntax_tree->accept(&translator);
}

int main(int argument_count, char **argument_vector) {
    if (argument_count < 2) {
        std::cerr << "USAGE: " << argument_vector[0] << " <SOURCE_FILE>\n";
