  SmallString<128> path = sys::path::parent_path(TestMainArgv0);
  sys::fs::make_absolute(path);
  sys::path::append(path, "llvm.srcdir.txt");

  EXPECT_TRUE(sys::fs::is_regular_file(path))
      << "Unit test source directory file does not exist.";

  auto buffer = MemoryBuffer::getFile(path);
  EXPECT_TRUE(static_cast<bool>(buffer))
      << "Could not open unit test source directory file.";

