#include <common/buffer.h>
#include <common/endian.h>
#include <ssh/ssh_algorithm_negotiation.h>
#include <ssh/ssh_protocol.h>

namespace {
    static uint8_t fixed_cookie[16] = {
        0x01, 0x11, 0x21, 0x31,
        0x41, 0x51, 0x61, 0x71,
        0x81, 0x91, 0xa1, 0xb1,
        0xc1, 0xd1, 0xe1, 0xf1
    };

    template<typename Container>
    Buffer format_name_list(const Container& names_container)
    {
        typename Container::const_iterator iter;
        std::vector<Buffer> name_buffers;
        Buffer combined;
        uint32_t size;
        Buffer result;

        for (iter = names_container.begin(); iter != names_container.end(); ++iter) {
            name_buffers.push_back(iter->first);
        }

        combined = Buffer::join(name_buffers, ",");
        size = combined.length();
        size = BigEndian::encode(size);
        result.append(&size);
        result.append(combined);
        return (result);
    }
}

bool
SSHAlgorithmNegotiation::input(Buffer *data)
{
    switch (data->peek()) {
    case SSH::Message::KeyExchangeInitializationMessage:
        DEBUG(log_) << "Ignoring incoming initialization message.";
        return (true);
    default:
        DEBUG(log_) << "Unsupported negotiation message received:" << std::endl << data->hexdump();
        return (false);
    }
}

bool
SSHAlgorithmNegotiation::output(Buffer *destination)
{
    ASSERT(destination->empty());
    destination->append(SSH::Message::KeyExchangeInitializationMessage);
    destination->append(fixed_cookie, sizeof fixed_cookie); /* XXX Synchronous random byte generation?  */
    destination->append(format_name_list(key_exchange_map_));
    destination->append(format_name_list(server_host_key_map_));
    destination->append(format_name_list(encryption_client_to_server_map_));
    destination->append(format_name_list(encryption_server_to_client_map_));
    destination->append(format_name_list(mac_client_to_server_map_));
    destination->append(format_name_list(mac_server_to_client_map_));
    destination->append(format_name_list(compression_client_to_server_map_));
    destination->append(format_name_list(compression_server_to_client_map_));
    destination->append(format_name_list(language_client_to_server_map_));
    destination->append(format_name_list(language_server_to_client_map_));
    destination->append(SSH::Boolean::False);
    uint32_t padding_value(0);
    destination->append(&padding_value);
    return (true);
}

