// Create a Status instance from a printf-style format and variable arguments
Status ToStatusF(Code error_code, const char* fmt, ...) {
  va_list args;
  va_start(args, fmt);
  char* buffer;
  if (vasprintf(&buffer, fmt, args) < 0) {
    abort();
  }
  va_end(args);

  Status result(error_code, buffer);
  free(buffer);
  return result;
}

}  // namespace tink
}  // namespace crypto

