// Test wrapDirection behavior with positive and negative offsets
TEST(TestVec2i, DirectionWrappingWithOffset) {
    // Negative offset tests (counter-clockwise rotation)
    EXPECT_EQ(Knights::EDirection::kWest,  Knights::wrapDirection(Knights::EDirection::kNorth, -1));
    EXPECT_EQ(Knights::EDirection::kNorth, Knights::wrapDirection(Knights::EDirection::kEast, -1));
    EXPECT_EQ(Knights::EDirection::kEast,  Knights::wrapDirection(Knights::EDirection::kSouth, -1));
    EXPECT_EQ(Knights::EDirection::kSouth, Knights::wrapDirection(Knights::EDirection::kWest, -1));

    // Large negative offset tests (full cycles)
    EXPECT_EQ(Knights::EDirection::kNorth, Knights::wrapDirection(Knights::EDirection::kNorth, -4));
    EXPECT_EQ(Knights::EDirection::kEast,  Knights::wrapDirection(Knights::EDirection::kEast,  -4));
    EXPECT_EQ(Knights::EDirection::kSouth, Knights::wrapDirection(Knights::EDirection::kSouth, -4));
    EXPECT_EQ(Knights::EDirection::kWest,  Knights::wrapDirection(Knights::EDirection::kWest,  -4));

    // Positive offset tests (clockwise rotation)
    EXPECT_EQ(Knights::EDirection::kEast,  Knights::wrapDirection(Knights::EDirection::kNorth, +1));
    EXPECT_EQ(Knights::EDirection::kSouth, Knights::wrapDirection(Knights::EDirection::kEast,  +1));
    EXPECT_EQ(Knights::EDirection::kWest,  Knights::wrapDirection(Knights::EDirection::kSouth, +1));
    EXPECT_EQ(Knights::EDirection::kNorth, Knights::wrapDirection(Knights::EDirection::kWest,  +1));

    // Large positive offset tests (full cycles)
    EXPECT_EQ(Knights::EDirection::kNorth, Knights::wrapDirection(Knights::EDirection::kNorth, +4));
    EXPECT_EQ(Knights::EDirection::kEast,  Knights::wrapDirection(Knights::EDirection::kEast,  +4));
    EXPECT_EQ(Knights::EDirection::kSouth, Knights::wrapDirection(Knights::EDirection::kSouth, +4));
    EXPECT_EQ(Knights::EDirection::kWest,  Knights::wrapDirection(Knights::EDirection::kWest,  +4));
}

