#include "localserver.h"
namespace rclog {
LocalServer::LocalServer(boost::asio::io_service &service, std::string path)
    : socket_(service, datagram_protocol::endpoint(path)) {
    start_receiving();
}

void LocalServer::start_receiving() {
    socket_.async_receive_from(
        boost::asio::buffer(buffer_, max_buffer_size), remote_endpoint_,
        boost::bind(&LocalServer::on_message_received, this, _1, _2));
}

void LocalServer::send_response(std::size_t size) {
    std::cout << "Endpoint: " << remote_endpoint_ << std::endl;
    socket_.async_send_to(
        boost::asio::buffer(buffer_, size), remote_endpoint_,
        [this](boost::system::error_code /*err*/, std::size_t /*sent*/) {
            start_receiving();
        });
}

void LocalServer::on_message_received(boost::system::error_code error, std::size_t received_bytes) {
    if (!error && received_bytes > 0) {
        std::cout << "Received: '";
        std::cout.write(buffer_, received_bytes);
        std::cout << "'" << std::endl;
        send_response(received_bytes);
        return;
    }

    if (error == boost::asio::error::message_size) {
        std::cerr << "Warning: incoming message exceeds buffer capacity"; // TODO: notify sender
    }

    start_receiving();
}
}

