  : m_pNodePtr(pNode) {
}

void IListIteratorBase::moveForward()
{
  assert(nullptr != m_pNodePtr && "null iterator cannot advance");
  m_pNodePtr = m_pNodePtr->getNext();
}

void IListIteratorBase::moveBackward()
{
  assert(nullptr != m_pNodePtr && "null iterator cannot retreat");
  m_pNodePtr = m_pNodePtr->getPrev();
}

#include <iostream>

using namespace std;

struct Parent {
    void display(int value) {
        cout << "Parent::display(int)" << endl;
    }
protected:
    int number = 0;
};

struct ChildA : virtual public Parent {
    void display(char symbol) {
        cout << "ChildA::display(char)" << endl;
    }
    void process(char symbol) {
        cout << "ChildA::process(char)" << endl;
    }
protected:
    char letter = 'a';
};

struct ChildB : virtual public Parent {
    void process(int value) {
        cout << "ChildB::process(int)" << endl;
    }
protected:
    int number = 2;
    char letter = 'b';
};

class MultiInherit : public ChildA, public ChildB {
public:
    void show_number() {
        cout << Parent::number << endl; // Without Parent::, ambiguity arises due to ChildB's override
    }

    void show_letter() {
        cout << ChildA::letter << endl; // Both need scope resolution due to shadowing
    }
};

int main() {
    MultiInherit obj;
    obj.show_number();
    obj.show_letter();
    obj.ChildA::process('x'); // Explicit qualification required
    obj.display(5);           // Calls ChildA::display(int) via inheritance
    obj.display('y');         // Calls ChildA::display(char)
    obj.Parent::display(10);

    return 0;
}

