#include <ros/ros.h>
#include <rviz_visual_tools/rviz_visual_tools.h>
#include <tf2_eigen/tf2_eigen.h>
#include <tf2_ros/transform_listener.h>
#include <Eigen/Geometry>

int main(int argc, char** argv)
{
  ros::init(argc, argv, "body_angle_visualizer");
  ros::NodeHandle nh {};
  ros::Rate loop_rate {5};
  tf2_ros::Buffer transform_buffer {};
  tf2_ros::TransformListener transform_listener {transform_buffer};
  rviz_visual_tools::RvizVisualTools visual_markers {"openni_depth_frame", "rviz_visual_markers"};

  while (ros::ok()) {
    try {
      const auto head_transform {tf2::transformToEigen(transform_buffer.lookupTransform("openni_depth_frame", "head_1", ros::Time {0}))};
      const auto torso_transform {tf2::transformToEigen(transform_buffer.lookupTransform("openni_depth_frame", "torso_1", ros::Time {0}))};

      const auto direction_vector {head_transform.translation() - torso_transform.translation()};
      const auto orientation_quaternion {Eigen::Quaterniond::FromTwoVectors(Eigen::Vector3d::UnitX(), direction_vector)};

      visual_markers.deleteAllMarkers();
      Eigen::Affine3d arrow_pose {orientation_quaternion};
      visual_markers.publishArrow(arrow_pose);
      visual_markers.trigger();

    } catch (tf2::TransformException &error) {
      ROS_WARN("%s", error.what());
    }

    loop_rate.sleep();
  }
}

