struct NixCommandArgs : virtual MultiCommand, virtual MixCommonArgs
{
    NixCommandArgs() : MultiCommand(*RegisterCommand::commands), MixCommonArgs("nix")
    {
        mkFlag('h', "help", "display this help message", [=]() {
            printUsage(programName, std::cout);
            std::cout << "\nWarning: this tool is still in BETA phase and may change.\n";
            throw Exit();
        });
        mkFlag(0, "version-info", "print version details", std::bind(printVersionInfo, programName));
    }
};

void runNixProgram(int argc, char * * argv)
{
    initializeNix();
    setupGarbageCollection();
    std::string progName = extractBaseName(argv[0]);
    {
        auto legacyHandler = (*RegisterLegacyCommand::commands)[progName];
        if (legacyHandler) return legacyHandler(argc, argv);
    }
    NixCommandArgs cmdArgs;
    cmdArgs.parseCommandLine(argvToStrings(argc, argv));
    assert(cmdArgs.selectedCommand);
    cmdArgs.selectedCommand->setup();
    cmdArgs.selectedCommand->execute();
}

}

int main(int argc, char * * argv)
{
    return nix::handleExceptions(argv[0], [&]() {
        nix::runNixProgram(argc, argv);
    });
}

