#include "ics3/eepparam.hpp"
#include <stdexcept>

constexpr int byteWidth {4};
constexpr uint16_t bitMask {0xF};

void ics::EepParam::write(std::array<uint8_t, 64>& target) const noexcept {
    uint16_t currentData {data};
    for (size_t idx {offset + length - 1}; idx >= offset; --idx) {
        target[idx] = currentData & bitMask;
        currentData >>= byteWidth;
    }
}

void ics::EepParam::read(const std::array<uint8_t, 64>& source) {
    uint16_t accum {0};
    const size_t limit = offset + length;
    for (size_t pos {offset}; pos < limit; ++pos) {
        accum <<= byteWidth;
        accum |= source[pos] & bitMask;
    }
    set(accum); // throw std::invalid_argument
}

