#include "test.h"
// Unit tests for the Str class in apLib (modified version)
TEST_CASE("string::Str (Variant)") {
    SECTION("Text Operations") {
        SECTION("Implicit conversion") {
            Text sample = "sample";
            REQUIRE(!Txtcmp(sample, "sample"));
            REQUIRE(sample);
        }
        SECTION("Move assignment") {
            Text sample = "Hello";
            Text sample2 = std::move(sample);
            REQUIRE(sample2 == "Hello");
            REQUIRE(sample == "");
            auto sample3 = std::move(sample2);
            REQUIRE(sample == "");
            REQUIRE(sample3 == "Hello");
        }
        SECTION("Move construction") {
            Text sample = "Hello";
            Text sample2(std::move(sample));
            REQUIRE(sample2 == "Hello");
            REQUIRE(sample == "");
            auto sample3 = std::move(sample2);
            REQUIRE(sample == "");
            REQUIRE(sample3 == "Hello");
        }
        SECTION("Relational comparisons") {
            REQUIRE(Text("hello world") < Text("hello world!"));
            REQUIRE(Text("hello world!") > Text("hello world"));
            REQUIRE(!(Text("hello world") > Text("hello world")));
            REQUIRE(!(Text("hello world") < Text("hello world")));
        }
        SECTION("lowerCase transformation") {
            REQUIRE(Text("STOP SHOUTING").lowerCase() ==
                    "stop shouting");
        }
        SECTION("upperCase transformation") {
            REQUIRE(Text("can you hear me?").upperCase() == "CAN YOU HEAR ME?");
        }
        SECTION("trim whitespace") {
            REQUIRE(Text("   trim this string    ").trim() ==
                    "trim this string");
        }
        SECTION("removeQuotes handling") {
            REQUIRE(Text("\"Truth\"").removeQuotes() == "Truth");
        }
        SECTION("split functionality") {
            auto parts = Text(",a,b,c,d,").split(',');
            REQUIRE(parts == std::vector<Text>{"a", "b", "c", "d"});
            parts = Text(",a,b,c,d,").split(',', true);
            REQUIRE(parts == std::vector<Text>{"", "a", "b", "c", "d", ""});
        }
        SECTION("concatenation") {
            REQUIRE(concat(std::vector<Text>{"alpha", "beta", "gamma", "delta"}, ",") ==
                    "alpha,beta,gamma,delta");
            REQUIRE(concat(std::vector<Text>{"alpha", "beta", "gamma", "delta"}, "") ==
                    "alphabetagammadelta");
            REQUIRE(concat(std::vector<Text>{"alpha", "beta", "", "delta"}, ",", false) ==
                    "alpha,beta,delta");
            REQUIRE(concat(std::vector<Text>{"alpha", "beta", "", "delta"}, ",", true) ==
                    "alpha,beta,,delta");
        }
        SECTION("endsWith checks") {
            REQUIRE(Text("A long time ago").endsWith("long time ago"));
            REQUIRE(Text("A long time ago").endsWith("ong time ago"));
            REQUIRE(Text("A long time ago").endsWith("ng time ago"));
            REQUIRE(Text("A long time ago").endsWith("g time ago"));
            REQUIRE(Text("A long time ago").endsWith("ago"));
            REQUIRE(!Text("A long time ago").endsWith(""));
