extern void UNSAFE_BUFACCESS(void *buf, int len);
int main() {
    char dest[15] = "Go";
    char src[25];
    printf("Type a word: ");
    scanf("%24s", src);
    strcat(dest, src);
    UNSAFE_BUFACCESS(dest, strlen(dest));
    printf("Result: %s\n", dest);
    return 0;
}

