void
vaapi_gotcha::audit(const gotcha_data& info, audit::incoming, VADisplay display,
                    VAContextID ctx)
{
    if(info.tool_id == "vaDestroyBuffer")
        category_region<category::vaapi>::start(std::string_view{ info.tool_id }, "dpy",
                                                display, "buffer_id", ctx);
    else if(info.tool_id == "vaDestroyConfig")
        category_region<category::vaapi>::start(std::string_view{ info.tool_id }, "dpy",
                                                display, "config_id", ctx);
    else if(info.tool_id == "vaDestroyContext")
        category_region<category::vaapi>::start(std::string_view{ info.tool_id }, "dpy",
                                                display, "context", ctx);
    else if(info.tool_id == "vaEndPicture")
        category_region<category::vaapi>::start(std::string_view{ info.tool_id }, "dpy",
                                                display, "context", ctx);
    else if(info.tool_id == "vaSyncSurface")
        category_region<category::vaapi>::start(std::string_view{ info.tool_id }, "dpy",
                                                display, "render_target", ctx);
    else if(info.tool_id == "vaDestroyImage")
        category_region<category::vaapi>::start(std::string_view{ info.tool_id }, "dpy",
                                                display, "image_id", ctx);
    else if(info.tool_id == "vaUnmapBuffer" || info.tool_id == "vaReleaseBufferHandle")
        category_region<category::vaapi>::start(std::string_view{ info.tool_id }, "dpy",
                                                display, "buffer_id", ctx);
    else
        category_region<category::vaapi>::start(std::string_view{ info.tool_id }, "dpy",
                                                display, "id", ctx);
}

