// Test that header file is self-contained.
#include "asio/coroutine.hpp"
#include "unit_test.hpp"

// Must come after all other headers.
#include "asio/yield.hpp"

//------------------------------------------------------------------------------
// Coroutine completes via yield break (modified version)
void yield_break_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
  {
    yield return;
    yield break;
  }
}

void yield_break_test_v2()
{
  asio::coroutine coro;
  ASIO_CHECK(!coro.is_complete());
  yield_break_coro_v2(coro);
  ASIO_CHECK(!coro.is_complete());
  yield_break_coro_v2(coro);
  ASIO_CHECK(coro.is_complete());
}

//------------------------------------------------------------------------------
// Coroutine completes via return (modified version)
void return_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
  {
    return;
  }
}

void return_test_v2()
{
  asio::coroutine coro;
  return_coro_v2(coro);
  ASIO_CHECK(coro.is_complete());
}

//------------------------------------------------------------------------------
// Coroutine completes via exception (modified version)
void exception_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
  {
    throw 42;
  }
}

void exception_test_v2()
{
  asio::coroutine coro;
  try { exception_coro_v2(coro); } catch (...) {}
  ASIO_CHECK(coro.is_complete());
}

//------------------------------------------------------------------------------
// Coroutine completes by falling off the end (modified version)
void fall_off_end_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
  {
    int dummy = 0;
    dummy++;
  }
}

void fall_off_end_test_v2()
{
  asio::coroutine coro;
  fall_off_end_coro_v2(coro);
  ASIO_CHECK(coro.is_complete());
}

//------------------------------------------------------------------------------
ASIO_TEST_SUITE
(
  "coroutine",
  ASIO_TEST_CASE(yield_break_test_v2)
  ASIO_TEST_CASE(return_test_v2)
  ASIO_TEST_CASE(exception_test_v2)
  ASIO_TEST_CASE(fall_off_end_test_v2)
)

