    void CryptoTypes_Init(py::module& module)
    {
        py::class_<PubKey>(module, "PubKey")
            .def(py::init<>())
            .def("FromHex", &PubKey::FromString)
            .def("__repr__", &PubKey::ToString);

        py::class_<SecretKey>(module, "SecretKey")
            .def(py::init<>())
            .def("LoadFile", &SecretKey::LoadFromFile)
            .def("SaveFile", &SecretKey::SaveToFile)
            .def("ToPublic", &SecretKey::toPublic);

        py::class_<Signature>(module, "Signature")
            .def(py::init<>())
            .def("__repr__", [](const Signature& signature) {
                return signature.ToHex();
            });
    }
