// Display received data in hexadecimal format
void showHexStream(const std::string &buffer) {
  if (!buffer.empty()) {
    std::cout << "hex dump: ";
    for (size_t idx = 0; idx < buffer.size(); ++idx) {
      std::cout << std::hex << std::setfill('0') << std::setw(2)
                << static_cast<int>(static_cast<uint8_t>(buffer[idx])) << " ";
    }
    std::cout << std::endl;
  }
}

int main(int argc, char **argv) {
  ros::init(argc, argv, "linktrack_parser_node");
  ros::NodeHandle private_nh;
  serial::Serial device_serial;
  configureSerial(&device_serial);
  NProtocolExtracter parser;
  linktrack::Init initializer(&parser, &device_serial);
  ros::Rate update_rate(500);

  while (ros::ok()) {
    size_t pending_bytes = device_serial.available();
    std::string incoming_data;

    if (pending_bytes > 0) {
      device_serial.read(incoming_data, pending_bytes);
      // showHexStream(incoming_data);
      parser.InjectData(incoming_data);
    }

    ros::spinOnce();
    update_rate.sleep();
  }

  return EXIT_SUCCESS;
}

