#include <serialization/associative_archive.h>
#include <serialization/binary_archive.h>

namespace unravel
{
    REFLECT(camera_component)
    {
        // Predicate to check if camera uses orthographic projection
        auto ortho_check = entt::property_predicate<bool>(
            [](const entt::meta_any& val)
            {
                return val.try_cast<camera_component>()->get_projection_mode() == projection_mode::orthographic;
            });

        // Predicate to check if camera uses perspective projection
        auto persp_check = entt::property_predicate<bool>(
            [](const entt::meta_any& val)
            {
                return val.try_cast<camera_component>()->get_projection_mode() == projection_mode::perspective;
            });

        entt::meta_factory<camera_component>{}
            .type("camera_component"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "camera_component"},
                entt::attribute{"category", "RENDERING"},
                entt::attribute{"pretty_name", "Camera"},
            })
            .func<&component_meta<camera_component>::exists>("component_exists"_hs)
            .func<&component_meta<camera_component>::add>("component_add"_hs)
            .func<&component_meta<camera_component>::save>("component_save"_hs)
            .func<&component_meta<camera_component>::load>("component_load"_hs)
            .func<&component_meta<camera_component>::remove>("component_remove"_hs)

            // Projection mode property
            .data<&camera_component::set_projection_mode, &camera_component::get_projection_mode>("projection_mode"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "projection_mode"},
                entt::attribute{"pretty_name", "Projection Mode"},
            })

            // Field of view (only relevant in perspective mode)
            .data<&camera_component::set_fov, &camera_component::get_fov>("field_of_view"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "field_of_view"},
                entt::attribute{"pretty_name", "Field Of View"},
                entt::attribute{"min", 10.0f},
                entt::attribute{"max", 140.0f},
                entt::attribute{"predicate", persp_check},
            })

            // Orthographic size (only relevant in orthographic mode)
            .data<&camera_component::set_ortho_size, &camera_component::get_ortho_size>("orthographic_size"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "orthographic_size"},
                entt::attribute{"pretty_name", "Orthographic Size"},
                entt::attribute{"min", 0.2f},
                entt::attribute{"tooltip", "Half of the vertical viewing volume height.\nHorizontal size depends on viewport aspect ratio.\nIgnored when not in orthographic mode."},
                entt::attribute{"predicate", ortho_check},
            })

            // Pixels per unit (read-only, orthographic only)
            .data<nullptr, &camera_component::get_ppu>("pixels_per_unit"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "pixels_per_unit"},
                entt::attribute{"pretty_name", "Pixels Per Unit"},
                entt::attribute{"tooltip", "Only meaningful in orthographic projection mode."},
            })

            // Viewport dimensions (read-only)
            .data<nullptr, &camera_component::get_viewport_size>("viewport_size"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "viewport_size"},
                entt::attribute{"pretty_name", "Viewport Size"},
            })

            // Near clip plane
            .data<&camera_component::set_near_clip, &camera_component::get_near_clip>("near_clip_distance"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "near_clip_distance"},
                entt::attribute{"pretty_name", "Near Clip"},
                entt::attribute{"min", 0.05f},
            })

            // Far clip plane
            .data<&camera_component::set_far_clip, &camera_component::get_far_clip>("far_clip_distance"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "far_clip_distance"},
                entt::attribute{"pretty_name", "Far Clip"},
            })

            // Include layers mask
            .data<&camera_component::set_render_include_mask, &camera_component::get_render_include_mask>("include_layers"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "include_layers"},
                entt::attribute{"pretty_name", "Include Layers"},
                entt::attribute{"tooltip", "Layers included during rendering."},
            })

            // Exclude layers mask
            .data<&camera_component::set_render_exclude_mask, &camera_component::get_render_exclude_mask>("exclude_layers"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "exclude_layers"},
                entt::attribute{"pretty_name", "Exclude Layers"},
                entt::attribute{"tooltip", "Layers excluded during rendering."},
            })

            // Effective render mask (computed from include/exclude)
            .data<nullptr, &camera_component::get_render_mask>("render_layers"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "render_layers"},
                entt::attribute{"pretty_name", "Render Layers"},
                entt::attribute{"tooltip", "Effective layer mask used for rendering (Include - Exclude)."},
            });
    }

    // Serialization: Save
    SAVE(camera_component)
    {
        try_save(ar, ser20::make_nvp("camera", obj.get_camera()));
        try_save(ar, ser20::make_nvp("render_include_layers", obj.get_render_include_mask()));
        try_save(ar, ser20::make_nvp("render_exclude_layers", obj.get_render_exclude_mask()));
    }

    SAVE_INSTANTIATE(camera_component, ser20::oarchive_associative_t);
    SAVE_INSTANTIATE(camera_component, ser20::oarchive_binary_t);

    // Serialization: Load
    LOAD(camera_component)
    {
        try_load(ar, ser20::make_nvp("camera", obj.get_camera()));

        layer_mask incl_mask{layer_reserved::everything_layer};
        if (try_load(ar, ser20::make_nvp("render_include_layers", incl_mask)))
        {
            obj.set_render_include_mask(incl_mask);
        }

        layer_mask excl_mask{layer_reserved::nothing_layer};
        if (try_load(ar, ser20::make_nvp("render_exclude_layers", excl_mask)))
        {
            obj.set_render_exclude_mask(excl_mask);
        }
    }

    LOAD_INSTANTIATE(camera_component, ser20::iarchive_associative_t);
    LOAD_INSTANTIATE(camera_component, ser20::iarchive_binary_t);
} // namespace unravel

#include "TuyaDatapoints.h"
/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandBool(
  ZigbeeGateway *hub, zbg_device_params_t *target, uint8_t dp_identifier, 
  bool dp_state, bool request_synchronous, uint8_t tuya_command) {
  Tuya_dp_zcl_payload_t tuya_payload;

  makeTuyaDPBool(tuya_payload, dp_identifier, dp_state ? 1 : 0);

  return hub->sendCustomClusterCmd(
    target, TUYA_PRIVATE_CLUSTER_EF00, tuya_command, ESP_ZB_ZCL_ATTR_TYPE_SET, 
    TUYA_DP_ZCL_PAYLOAD_8, (uint8_t*)&tuya_payload, request_synchronous);
}
/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandEnum8(
  ZigbeeGateway *hub, zbg_device_params_t *target, uint8_t dp_identifier, 
  uint8_t dp_state, bool request_synchronous, uint8_t tuya_command) {
  Tuya_dp_zcl_payload_t tuya_payload;

  makeTuyaDPEnum8(tuya_payload, dp_identifier, dp_state);

  return hub->sendCustomClusterCmd(
    target, TUYA_PRIVATE_CLUSTER_EF00, tuya_command, ESP_ZB_ZCL_ATTR_TYPE_SET, 
    TUYA_DP_ZCL_PAYLOAD_8, (uint8_t*)&tuya_payload, request_synchronous);
}
/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandValue32(
  ZigbeeGateway *hub, zbg_device_params_t *target, uint8_t dp_identifier, 
  uint32_t dp_state, bool request_synchronous, uint8_t tuya_command) {
  Tuya_dp_zcl_payload_t tuya_payload;

  makeTuyaDPValue32(tuya_payload, dp_identifier, dp_state);

  return hub->sendCustomClusterCmd(
    target, TUYA_PRIVATE_CLUSTER_EF00, tuya_command, ESP_ZB_ZCL_ATTR_TYPE_SET, 
    TUYA_DP_ZCL_PAYLOAD_32, (uint8_t*)&tuya_payload, request_synchronous);
}
/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandData(
  ZigbeeGateway *hub, zbg_device_params_t *target, uint8_t dp_identifier,
  uint8_t dp_format, uint32_t dp_state, bool request_synchronous, uint8_t tuya_command) {
  switch (dp_format) {
    case TUYA_DP_TYPE_BOOL:
      return
        transmitTuyaCommandBool(
          hub, target, dp_identifier, dp_state, request_synchronous, tuya_command);
    break;
    case TUYA_DP_TYPE_VALUE:
      return
        transmitTuyaCommandValue32(
          hub, target, dp_identifier, dp_state, request_synchronous, tuya_command); 
    break;
    case TUYA_DP_TYPE_ENUM:
      return
        transmitTuyaCommandEnum8(
          hub, target, dp_identifier, dp_state, request_synchronous, tuya_command); 
    break;
    default:
      log_e("unsupported Tuya datapoint %02x format %02x", dp_identifier, dp_format); 
    break;
  }
  return false;
}
bool transmitTuyaQueryCommand(
  ZigbeeGateway *hub, zbg_device_params_t *target, bool request_synchronous) {
  return hub->sendCustomClusterCmd(
    target, TUYA_PRIVATE_CLUSTER_EF00, TUYA_QUERY_CMD, 
    ESP_ZB_ZCL_ATTR_TYPE_NULL, TUYA_DP_ZCL_PAYLOAD_0, nullptr, request_synchronous);
}

#include <basics/math_utils.hpp>
#include "tests_shared.hpp"
namespace math = irs::math;

TEST(math_utils_test, IsPower2) {
  using namespace irs::math;
  // static_assert(!IsPower2(0), "Incorrect result"); // 0 yields false negative
  static_assert(IsPower2(1), "Incorrect result");
  static_assert(IsPower2(4), "Incorrect result");
  static_assert(!IsPower2(5), "Incorrect result");
  static_assert(IsPower2(8), "Incorrect result");
  static_assert(!IsPower2(997), "Incorrect result");
  static_assert(IsPower2(2048), "Incorrect result");
  static_assert(IsPower2(UINT64_C(1) << 62), "Incorrect result");
  static_assert(!IsPower2(std::numeric_limits<size_t>::max() - 1),
                "Incorrect result");
}

TEST(math_utils_test, roundup_power2) {
  ASSERT_EQ(0, math::RoundupPower2(0));
  ASSERT_EQ(1, math::RoundupPower2(1));
  ASSERT_EQ(2, math::RoundupPower2(2));
  ASSERT_EQ(4, math::RoundupPower2(3));
  ASSERT_EQ(8, math::RoundupPower2(7));
  ASSERT_EQ(16, math::RoundupPower2(13));
  ASSERT_EQ(32, math::RoundupPower2(25));
  ASSERT_EQ(2048, math::RoundupPower2(1500));
  ASSERT_EQ(std::numeric_limits<size_t>::max(),
            math::RoundupPower2(std::numeric_limits<size_t>::max() - 1));
  ASSERT_EQ(0, math::RoundupPower2(std::numeric_limits<size_t>::max()));
}

TEST(math_utils_test, Log2Floor32) {
  ASSERT_EQ(0, math::Log2Floor32(1));
  ASSERT_EQ(2, math::Log2Floor32(4));
  ASSERT_EQ(2, math::Log2Floor32(5));
  ASSERT_EQ(3, math::Log2Floor32(8));
  ASSERT_EQ(3, math::Log2Floor32(10));
  ASSERT_EQ(4, math::Log2Floor32(16));
  ASSERT_EQ(9, math::Log2Floor32(512));
  ASSERT_EQ(10, math::Log2Floor32(1024));
  ASSERT_EQ(30, math::Log2Floor32(std::numeric_limits<uint32_t>::max() >> 1));
}

TEST(math_utils_test, Log2Floor64) {
  ASSERT_EQ(0, math::Log2Floor64(UINT64_C(1)));
  ASSERT_EQ(1, math::Log2Floor64(UINT64_C(2)));
  ASSERT_EQ(2, math::Log2Floor64(UINT64_C(5)));
  ASSERT_EQ(3, math::Log2Floor64(UINT64_C(9)));
  ASSERT_EQ(9, math::Log2Floor64(UINT64_C(512)));
  ASSERT_EQ(10, math::Log2Floor64(UINT64_C(1024)));
  ASSERT_EQ(31, math::Log2Floor64(std::numeric_limits<uint32_t>::max()));
  ASSERT_EQ(32, math::Log2Floor64(UINT64_C(1) << 33));
  ASSERT_EQ(63, math::Log2Floor64(std::numeric_limits<uint64_t>::max() >> 1));
}

TEST(math_utils_test, log) {
  ASSERT_EQ(0, math::Log(1, 5));
  ASSERT_EQ(1, math::Log(125, 5));
  ASSERT_EQ(2, math::Log(25, 5));
  ASSERT_EQ(3, math::Log(125, 5));
  ASSERT_EQ(4, math::Log(625, 5));
  ASSERT_EQ(5, math::Log(3125, 5));
  ASSERT_EQ(31, math::Log(std::numeric_limits<uint32_t>::max(), 2));
}

TEST(math_utils_test, log2_32) {
  ASSERT_EQ(0, math::Log232(1));
  ASSERT_EQ(1, math::Log232(2));
  ASSERT_EQ(2, math::Log232(4));
  ASSERT_EQ(3, math::Log232(8));
  ASSERT_EQ(7, math::Log232(128));
  ASSERT_EQ(10, math::Log232(1024));
  ASSERT_EQ(30, math::Log232(std::numeric_limits<uint32_t>::max() >> 1));
}

TEST(math_utils_test, log2_64) {
  ASSERT_EQ(0, math::Log264(1));
  ASSERT_EQ(1, math::Log264(2));
  ASSERT_EQ(2, math::Log264(4));
  ASSERT_EQ(3, math::Log264(8));
  ASSERT_EQ(7, math::Log264(128));
  ASSERT_EQ(10, math::Log264(1024));
  ASSERT_EQ(31, math::Log264(std::numeric_limits<uint32_t>::max()));
  ASSERT_EQ(62, math::Log264(std::numeric_limits<uint64_t>::max() >> 2));
}

TEST(math_utils, DivCeil32) {
  ASSERT_EQ(7, math::DivCeil32(49, 7));
  ASSERT_EQ(7, math::DivCeil32(50, 7));
  ASSERT_EQ(6, math::DivCeil32(40, 7));
  ASSERT_EQ(6, math::DivCeil32(41, 7));
  ASSERT_EQ(1, math::DivCeil32(1, 1));
  ASSERT_EQ(2, math::DivCeil32(5, 3));
  ASSERT_EQ(1, math::DivCeil32(3, 5));
  ASSERT_EQ(0, math::DivCeil32(0, 13));
  ASSERT_EQ(13, math::DivCeil32(13, 1));
  ASSERT_EQ(1, math::DivCeil32(std::numeric_limits<uint32_t>::max() / 3,
                               std::numeric_limits<uint32_t>::max() / 3));
  ASSERT_EQ(2, math::DivCeil32(1 + std::numeric_limits<uint32_t>::max() / 3,
                               1 + std::numeric_limits<uint32_t>::max() / 3));
}

TEST(math_utils, DivCeil64) {
  ASSERT_EQ(7, math::DivCeil64(49, 7));
  ASSERT_EQ(7, math::DivCeil64(55, 7));
  ASSERT_EQ(6, math::DivCeil64(39, 7));
  ASSERT_EQ(6, math::DivCeil64(40, 7));
  ASSERT_EQ(1, math::DivCeil64(1, 1));
  ASSERT_EQ(2, math::DivCeil64(7, 4));
  ASSERT_EQ(1, math::DivCeil64(3, 7));
  ASSERT_EQ(0, math::DivCeil64(0, 11));
  ASSERT_EQ(11, math::DivCeil64(11, 1));
  ASSERT_EQ(1, math::DivCeil64(std::numeric_limits<uint64_t>::max() / 3,
                               std::numeric_limits<uint64_t>::max() / 3));
  ASSERT_EQ(2, math::DivCeil64(1 + std::numeric_limits<uint64_t>::max() / 3,
                               1 + std::numeric_limits<uint64_t>::max() / 3));
}

TEST(math_utils, ceil32) {
  ASSERT_EQ(41, math::Ceil32(41, 1));
  ASSERT_EQ(0, math::Ceil32(0, 11));
  ASSERT_EQ(42, math::Ceil32(38, 7));
  ASSERT_EQ(49, math::Ceil32(44, 7));
  ASSERT_EQ(56, math::Ceil32(50, 7));
  ASSERT_EQ(uint32_t(std::numeric_limits<uint32_t>::max() - 1),
            math::Ceil32(std::numeric_limits<uint32_t>::max() - 2, 2));
  ASSERT_EQ(uint32_t(std::numeric_limits<uint32_t>::max()),
            math::Ceil32(std::numeric_limits<uint32_t>::max() - 1, 2));
}

TEST(math_utils, ceil64) {
  ASSERT_EQ(41, math::Ceil64(41, 1));
  ASSERT_EQ(0, math::Ceil64(0, 13));
  ASSERT_EQ(42, math::Ceil64(37, 7));
  ASSERT_EQ(49, math::Ceil64(45, 7));
  ASSERT_EQ(56, math::Ceil64(51, 7));
  ASSERT_EQ(uint64_t(std::numeric_limits<uint64_t>::max() - 1),
            math::Ceil64(std::numeric_limits<uint64_t>::max() - 2, 2));
  ASSERT_EQ(uint64_t(std::numeric_limits<uint64_t>::max()),
