#include <StaticResponseProcessorHTTP.h>

void StaticResponseProcessorHTTP::Process(http::request<http::string_body> const& request, tcp::socket& socketRef) {
    http::response<http::string_body> response;

    // Set response properties based on the incoming request
    response.version(request.version());
    response.keep_alive(request.keep_alive());
    response.result(http::status::ok);

    // Configure response headers
    response.set(http::field::content_type, "application/json; charset=UTF-8");
    response.set(http::field::vary, "Origin");

    // Set response body from internal resource
    response.body() = m_res->dump();
    response.prepare_payload();

    // Send the response through the socket
    http::write(socketRef, response);
}

