// Test Match functionality for RoleBase
TEST(RoleTest, rolebase_match) {
  RoleAttributes attrs;
  attrs.set_host_name("autolink");
  attrs.set_process_id(11223);
  attrs.set_node_id(5);
  RoleBase role(attrs, 9876543);

  RoleAttributes target_attrs;
  EXPECT_TRUE(role.Match(target_attrs));

  target_attrs.set_host_name("different");
  EXPECT_FALSE(role.Match(target_attrs));

  target_attrs.set_host_name("autolink");
  EXPECT_TRUE(role.Match(target_attrs));

  target_attrs.set_process_id(99999);
  EXPECT_FALSE(role.Match(target_attrs));

  target_attrs.set_process_id(11223);
  EXPECT_TRUE(role.Match(target_attrs));

  target_attrs.set_node_id(7);
  EXPECT_FALSE(role.Match(target_attrs));

  target_attrs.set_node_id(5);
  EXPECT_TRUE(role.Match(target_attrs));
}

