using namespace Cangjie;
using namespace Unicode;

TEST(UnicodeTest, GeneratedNFCTests)
{
    int testCount{sizeof(NORMALISATION_TEST_DATA) / sizeof(NormalisationTest)};
    for (int index{0}; index < testCount; ++index) {
        auto result = CanonicalRecompose(
            reinterpret_cast<const UTF8*>(NORMALISATION_TEST_DATA[index].source.begin()),
            reinterpret_cast<const UTF8*>(NORMALISATION_TEST_DATA[index].source.end())
        );
        EXPECT_EQ(result, NORMALISATION_TEST_DATA[index].nfc);
    }
}

