#include "HybridRunAnywhereCoreSpec.hpp"

namespace margelo::nitro::runanywhere {

  void HybridRunAnywhereCoreSpec::loadHybridMethods() {
    // Initialize base functionality first
    HybridObject::loadHybridMethods();

    // Register all custom hybrid methods via prototype
    registerHybrids(this, [](Prototype& proto) {
      // Authentication & session management
      proto.registerHybridMethod("initialize", &HybridRunAnywhereCoreSpec::initCore);
      proto.registerHybridMethod("destroy", &HybridRunAnywhereCoreSpec::shutdownCore);
      proto.registerHybridMethod("isInitialized", &HybridRunAnywhereCoreSpec::checkIfInitialized);

      // Identity & auth tokens
      proto.registerHybridMethod("getBackendInfo", &HybridRunAnywhereCoreSpec::fetchBackendDetails);
      proto.registerHybridMethod("authenticate", &HybridRunAnywhereCoreSpec::performAuthentication);
      proto.registerHybridMethod("isAuthenticated", &HybridRunAnywhereCoreSpec::verifyAuthStatus);
      proto.registerHybridMethod("getUserId", &HybridRunAnywhereCoreSpec::obtainCurrentUserId);
      proto.registerHybridMethod("getOrganizationId", &HybridRunAnywhereCoreSpec::obtainCurrentOrgId);
      proto.registerHybridMethod("setAuthTokens", &HybridRunAnywhereCoreSpec::storeAuthTokens);

      // Device registration
      proto.registerHybridMethod("registerDevice", &HybridRunAnywhereCoreSpec::enrollDevice);
      proto.registerHybridMethod("isDeviceRegistered", &HybridRunAnywhereCoreSpec::checkDeviceEnrollment);
      proto.registerHybridMethod("clearDeviceRegistration", &HybridRunAnywhereCoreSpec::removeDeviceEnrollment);
      proto.registerHybridMethod("getDeviceId", &HybridRunAnywhereCoreSpec::retrieveDeviceIdentifier);

      // Model management
      proto.registerHybridMethod("getAvailableModels", &HybridRunAnywhereCoreSpec::listAvailableModels);
      proto.registerHybridMethod("getModelInfo", &HybridRunAnywhereCoreSpec::describeModel);
      proto.registerHybridMethod("isModelDownloaded", &HybridRunAnywhereCoreSpec::hasModelDownloaded);
      proto.registerHybridMethod("getModelPath", &HybridRunAnywhereCoreSpec::locateModelFile);
      proto.registerHybridMethod("registerModel", &HybridRunAnywhereCoreSpec::addModelToRegistry);
      proto.registerHybridMethod("checkCompatibility", &HybridRunAnywhereCoreSpec::validateModelCompatibility);

      // Download control
      proto.registerHybridMethod("downloadModel", &HybridRunAnywhereCoreSpec::initiateDownload);
      proto.registerHybridMethod("cancelDownload", &HybridRunAnywhereCoreSpec::abortDownload);
      proto.registerHybridMethod("getDownloadProgress", &HybridRunAnywhereCoreSpec::queryDownloadProgress);

      // Storage operations
      proto.registerHybridMethod("getStorageInfo", &HybridRunAnywhereCoreSpec::inspectStorageUsage);
      proto.registerHybridMethod("clearCache", &HybridRunAnywhereCoreSpec::purgeCache);
      proto.registerHybridMethod("deleteModel", &HybridRunAnywhereCoreSpec::eraseModel);

      // Event system
      proto.registerHybridMethod("emitEvent", &HybridRunAnywhereCoreSpec::fireEvent);
      proto.registerHybridMethod("pollEvents", &HybridRunAnywhereCoreSpec::drainEventQueue);

      // HTTP layer
      proto.registerHybridMethod("configureHttp", &HybridRunAnywhereCoreSpec::setupHttpClient);
      proto.registerHybridMethod("httpPost", &HybridRunAnywhereCoreSpec::submitHttpPost);
      proto.registerHybridMethod("httpGet", &HybridRunAnywhereCoreSpec::submitHttpGet);
      proto.registerHybridMethod("getLastError", &HybridRunAnywhereCoreSpec::lastErrorString);

      // Archive handling
      proto.registerHybridMethod("extractArchive", &HybridRunAnywhereCoreSpec::unpackArchive);

      // Device capabilities
      proto.registerHybridMethod("getDeviceCapabilities", &HybridRunAnywhereCoreSpec::probeHardwareFeatures);
      proto.registerHybridMethod("getMemoryUsage", &HybridRunAnywhereCoreSpec::measureMemoryFootprint);

      // Text generation
      proto.registerHybridMethod("loadTextModel", &HybridRunAnywhereCoreSpec::loadLanguageModel);
      proto.registerHybridMethod("isTextModelLoaded", &HybridRunAnywhereCoreSpec::isLanguageModelReady);
      proto.registerHybridMethod("unloadTextModel", &HybridRunAnywhereCoreSpec::releaseLanguageModel);
      proto.registerHybridMethod("generate", &HybridRunAnywhereCoreSpec::produceText);
      proto.registerHybridMethod("generateStream", &HybridRunAnywhereCoreSpec::streamText);
      proto.registerHybridMethod("cancelGeneration", &HybridRunAnywhereCoreSpec::interruptGeneration);
      proto.registerHybridMethod("generateStructured", &HybridRunAnywhereCoreSpec::produceStructuredOutput);

      // Speech-to-text (STT)
      proto.registerHybridMethod("loadSTTModel", &HybridRunAnywhereCoreSpec::loadSpeechToTextModel);
      proto.registerHybridMethod("isSTTModelLoaded", &HybridRunAnywhereCoreSpec::isSpeechToTextReady);
      proto.registerHybridMethod("unloadSTTModel", &HybridRunAnywhereCoreSpec::releaseSpeechToTextModel);
      proto.registerHybridMethod("transcribe", &HybridRunAnywhereCoreSpec::convertSpeechToText);
      proto.registerHybridMethod("transcribeFile", &HybridRunAnywhereCoreSpec::convertFileToText);

      // Text-to-speech (TTS)
      proto.registerHybridMethod("loadTTSModel", &HybridRunAnywhereCoreSpec::loadTextToSpeechModel);
      proto.registerHybridMethod("isTTSModelLoaded", &HybridRunAnywhereCoreSpec::isTextToSpeechReady);
      proto.registerHybridMethod("unloadTTSModel", &HybridRunAnywhereCoreSpec::releaseTextToSpeechModel);
      proto.registerHybridMethod("synthesize", &HybridRunAnywhereCoreSpec::produceSpeech);
      proto.registerHybridMethod("getTTSVoices", &HybridRunAnywhereCoreSpec::listAvailableVoices);
      proto.registerHybridMethod("cancelTTS", &HybridRunAnywhereCoreSpec::stopSpeechSynthesis);

      // Voice activity detection (VAD)
      proto.registerHybridMethod("loadVADModel", &HybridRunAnywhereCoreSpec::loadVoiceActivityDetector);
      proto.registerHybridMethod("isVADModelLoaded", &HybridRunAnywhereCoreSpec::isVoiceActivityReady);
      proto.registerHybridMethod("unloadVADModel", &HybridRunAnywhereCoreSpec::releaseVoiceActivityDetector);
      proto.registerHybridMethod("processVAD", &HybridRunAnywhereCoreSpec::analyzeAudioForSpeech);
      proto.registerHybridMethod("resetVAD", &HybridRunAnywhereCoreSpec::resetVoiceActivityState);

      // Secure storage
      proto.registerHybridMethod("secureStorageSet", &HybridRunAnywhereCoreSpec::putSecureValue);
      proto.registerHybridMethod("secureStorageGet", &HybridRunAnywhereCoreSpec::fetchSecureValue);
      proto.registerHybridMethod("secureStorageDelete", &HybridRunAnywhereCoreSpec::removeSecureEntry);
      proto.registerHybridMethod("secureStorageExists", &HybridRunAnywhereCoreSpec::checkSecureEntry);
      proto.registerHybridMethod("secureStorageStore", &HybridRunAnywhereCoreSpec::persistSecureData);
      proto.registerHybridMethod("secureStorageRetrieve", &HybridRunAnywhereCoreSpec::reclaimSecureData);

      // Device identity
      proto.registerHybridMethod("getPersistentDeviceUUID", &HybridRunAnywhereCoreSpec::obtainUniqueDeviceId);

      // Telemetry
      proto.registerHybridMethod("flushTelemetry", &HybridRunAnywhereCoreSpec::sendPendingMetrics);
      proto.registerHybridMethod("isTelemetryInitialized", &HybridRunAnywhereCoreSpec::telemetryIsSetup);

      // Voice agent
      proto.registerHybridMethod("initializeVoiceAgent", &HybridRunAnywhereCoreSpec::activateVoiceAgent);
      proto.registerHybridMethod("initializeVoiceAgentWithLoadedModels", &HybridRunAnywhereCoreSpec::activateVoiceAgentWithPreloadedModels);
      proto.registerHybridMethod("isVoiceAgentReady", &HybridRunAnywhereCoreSpec::isVoiceAgentOperational);
      proto.registerHybridMethod("getVoiceAgentComponentStates", &HybridRunAnywhereCoreSpec::inspectVoiceAgentComponents);
      proto.registerHybridMethod("processVoiceTurn", &HybridRunAnywhereCoreSpec::handleVoiceInteraction);
      proto.registerHybridMethod("voiceAgentTranscribe", &HybridRunAnywhereCoreSpec::agentTranscribe);
      proto.registerHybridMethod("voiceAgentGenerateResponse", &HybridRunAnywhereCoreSpec::agentComposeReply);
      proto.registerHybridMethod("voiceAgentSynthesizeSpeech", &HybridRunAnywhereCoreSpec::agentSpeak);
      proto.registerHybridMethod("cleanupVoiceAgent", &HybridRunAnywhereCoreSpec::deactivateVoiceAgent);

      // Tool calling & prompting
      proto.registerHybridMethod("parseToolCallFromOutput", &HybridRunAnywhereCoreSpec::extractToolInvocation);
      proto.registerHybridMethod("formatToolsForPrompt", &HybridRunAnywhereCoreSpec::prepareToolsForContext);
      proto.registerHybridMethod("buildInitialPrompt", &HybridRunAnywhereCoreSpec::constructInitialPrompt);
      proto.registerHybridMethod("buildFollowupPrompt", &HybridRunAnywhereCoreSpec::constructSubsequentPrompt);

      // RAG pipeline
      proto.registerHybridMethod("ragCreatePipeline", &HybridRunAnywhereCoreSpec::createRagPipeline);
      proto.registerHybridMethod("ragDestroyPipeline", &HybridRunAnywhereCoreSpec::destroyRagPipeline);
      proto.registerHybridMethod("ragAddDocument", &HybridRunAnywhereCoreSpec::ingestDocument);
      proto.registerHybridMethod("ragAddDocumentsBatch", &HybridRunAnywhereCoreSpec::batchIngestDocuments);
      proto.registerHybridMethod("ragQuery", &HybridRunAnywhereCoreSpec::askRagPipeline);
      proto.registerHybridMethod("ragClearDocuments", &HybridRunAnywhereCoreSpec::clearRagIndex);
      proto.registerHybridMethod("ragGetDocumentCount", &HybridRunAnywhereCoreSpec::countRagDocs);
      proto.registerHybridMethod("ragGetStatistics", &HybridRunAnywhereCoreSpec::summarizeRagStats);
    });
  }

