namespace conv {
auto WideToNarrow(const std::wstring& wstr) -> std::string {
  std::string result;
  utf8::utf16to8(wstr.begin(), wstr.end(), std::back_inserter(result));
  return result;
}

auto WideToNarrow(std::wstring&& wstr) -> std::string {
  std::string result;
  utf8::utf16to8(wstr.begin(), wstr.end(), std::back_inserter(result));
  return result;
}

auto NarrowToWide(const std::string& str) -> std::wstring {
  std::wstring wresult;
  utf8::utf8to16(str.begin(), str.end(), std::back_inserter(wresult));
  return wresult;
}

auto NarrowToWide(std::string&& str) -> std::wstring {
  std::wstring wresult;
  utf8::utf8to16(str.begin(), str.end(), std::back_inserter(wresult));
  return wresult;
}
};  // namespace conv

