#include <PartyDetailsNotification.h>

// Modified constructor: initializes payload using party ID string
PartyDetailsNotification::PartyDetailsNotification(const std::string& id, SpectreRpcType type) :
	Notification(type) {
	payload = PartyDatabase::Get().GetPartyRes(id);
}

// Constructor variant: directly assigns from PartyResponse object
PartyDetailsNotification::PartyDetailsNotification(const PartyResponse& response, SpectreRpcType type) :
	Notification(type) {
	payload = response;
}

// Constructor variant: copies from Party object into payload
PartyDetailsNotification::PartyDetailsNotification(const Party& sourceParty, SpectreRpcType type) :
	Notification(type) {
	payload.mutable_party()->CopyFrom(sourceParty);
}

// Sends notification via websocket with serialized payload
void PartyDetailsNotification::TransmitTo(SpectreWebsocket& connection) const {
	connection.SendNotification(PartyDatabase::SerializePartyToString(payload), GetNotificationType());
}

