#include "relaxed_escaper.h"
#include <library/cpp/testing/unittest/registar.h>
#define TEST_STRING_LITERAL(s) TStringBuf(s, sizeof(s) - 1)
static const TStringBuf TestDataset[] = {
    // Valid UTF-8 sequences.
    TEST_STRING_LITERAL("http://ya.ru/"), TEST_STRING_LITERAL("http://ya.ru/"),
    TEST_STRING_LITERAL("http://ya.ru/\\x17\\n"), TEST_STRING_LITERAL("http://ya.ru/\x17\n"),
    TEST_STRING_LITERAL("http://ya.ru/\\0"), TEST_STRING_LITERAL("http://ya.ru/\0"),
    TEST_STRING_LITERAL("http://ya.ru/\\0\\0"), TEST_STRING_LITERAL("http://ya.ru/\0\0"),
    TEST_STRING_LITERAL("http://ya.ru/\\0\\0000"), TEST_STRING_LITERAL("http://ya.ru/\0\0"
                                                                       "0"),
    TEST_STRING_LITERAL("http://ya.ru/\\0\\0001"), TEST_STRING_LITERAL("http://ya.ru/\0\x00"
                                                                       "1"),
    TEST_STRING_LITERAL("\\2\\4\\00678"), TEST_STRING_LITERAL("\2\4\6"
                                                             "78"),
    TEST_STRING_LITERAL("\\2\\4\\689"), TEST_STRING_LITERAL("\2\4\689"),
    TEST_STRING_LITERAL("\\\"Hello\\\", Bob said."), TEST_STRING_LITERAL("\"Hello\", Bob said."),
    TEST_STRING_LITERAL("Backslash\\\\slash!"), TEST_STRING_LITERAL("Backslash\\slash!"),
    TEST_STRING_LITERAL("Line\\nbreaks\\r\\nhere."), TEST_STRING_LITERAL("Line\nbreaks\r\nhere."),
    TEST_STRING_LITERAL("Space\\ttab\\tseparated."), TEST_STRING_LITERAL("Space\ttab\tseparated.")};
#undef TEST_STRING_LITERAL
Y_UNIT_TEST_SUITE(TRelaxedEscaperTest) {
    Y_UNIT_TEST(TestEscapingFunctionality) {
        using namespace NEscJ;
        for (size_t idx = 0; idx < Y_ARRAY_SIZE(TestDataset); idx += 2) {
            TString expected(TestDataset[idx].data(), TestDataset[idx].size());
            TString input(TestDataset[idx + 1].data(), TestDataset[idx + 1].size());
            TString result(EscapeJ<false>(input));
            TString reverse(UnescapeC(expected));
            UNIT_ASSERT_VALUES_EQUAL(expected, result);
            UNIT_ASSERT_VALUES_EQUAL(input, reverse);
        }
        UNIT_ASSERT_VALUES_EQUAL("http://ya.ru/\\x17\\n\xAB", EscapeJ<false>("http://ya.ru/\x17\n\xab"));
        TString temp = EscapeJ<false, true>("http://ya.ru/\x17\n\xab\xff");
        UNIT_ASSERT_VALUES_EQUAL("http://ya.ru/\\u0017\\n\xAB\\xFF", temp);
        UNIT_ASSERT_VALUES_EQUAL("http://ya.ru/\\x17\n\xAB", EscapeJ<false>("http://ya.ru/\x17\n\xab", "\n"));
        UNIT_ASSERT_VALUES_EQUAL("http:\\x2F\\x2Fya.ru\\x2F\\x17\n\xAB'", EscapeJ<false>("http://ya.ru/\x17\n\xab'", "\n'", "/"));
        UNIT_ASSERT_VALUES_EQUAL("http://ya.ru/\x17\n\xab", UnescapeC("http:\\x2F\\x2Fya.ru\\x2F\\x17\n\xAB"));
        UNIT_ASSERT_VALUES_EQUAL("http://ya.ru/\x17\n\xab", UnescapeC("http://ya.ru/\\x17\\n\xAB"));
        UNIT_ASSERT_VALUES_EQUAL("a", EscapeJ<false>("a"));
        UNIT_ASSERT_VALUES_EQUAL("\"a\"", EscapeJ<true>("a"));
        UNIT_ASSERT_VALUES_EQUAL("a", UnescapeC("a"));
        UNIT_ASSERT_VALUES_EQUAL("\\xFF", EscapeJ<false>("\xFF"));
        UNIT_ASSERT_VALUES_EQUAL("\"\\xFF\"", EscapeJ<true>("\xFF"));
        UNIT_ASSERT_VALUES_EQUAL("\xFF", UnescapeC("\\xFF"));
        UNIT_ASSERT_VALUES_EQUAL("\\377z", EscapeJ<false>("\xff"
                                                          "z"));
        UNIT_ASSERT_VALUES_EQUAL("\xff"
                                 "z",
                                 UnescapeC("\\377z"));
        UNIT_ASSERT_VALUES_EQUAL("\\xFFy", EscapeJ<false>("\xff"
                                                          "y"));
        UNIT_ASSERT_VALUES_EQUAL("\xff"
                                 "y",
                                 UnescapeC("\\xFFy"));
    }
}

