namespace rocprofsys
{
namespace
{
// Helper function to suppress unused parameter warnings
template <typename... Args>
void
ignore_arguments(Args&&...)
{}

// Generate backtrace string with optional arguments
template <typename... Args>
auto
capture_backtrace(Args... _args)
{
    ignore_arguments(_args...);
    auto trace_stream = std::stringstream{};

    if constexpr(sizeof...(Args) > 0)
    {
        ((trace_stream << _args), ...) << "\n";
    }

    tim::unwind::detailed_backtrace<2>(trace_stream, true);
    return strdup(trace_stream.str().c_str());
}
}  // namespace

// Exception template implementation
template <typename BaseExceptionType>
exception<BaseExceptionType>::exception(const std::string& message)
: BaseExceptionType{ message }
, m_message{ capture_backtrace(message) }
{}

template <typename BaseExceptionType>
exception<BaseExceptionType>::exception(const char* message)
: BaseExceptionType{ message }
, m_message{ capture_backtrace(message) }
{}

template <typename BaseExceptionType>
exception<BaseExceptionType>::exception(const std::string& message, bool include_backtrace)
: BaseExceptionType{ message }
, m_message{ include_backtrace ? capture_backtrace(message) : strdup(message.c_str()) }
{}

template <typename BaseExceptionType>
exception<BaseExceptionType>::~exception()
{
    free(m_message);
}

template <typename BaseExceptionType>
exception<BaseExceptionType>::exception(const exception& other)
: BaseExceptionType{ other }
, m_message{ strdup(other.m_message) }
{}

template <typename BaseExceptionType>
exception<BaseExceptionType>&
exception<BaseExceptionType>::operator=(const exception& other)
{
    if(this != &other)
    {
        BaseExceptionType::operator=(other);
        m_message = strdup(other.m_message);
    }
    return *this;
}

template <typename BaseExceptionType>
const char*
exception<BaseExceptionType>::what() const noexcept
{
    return (m_message) ? m_message : BaseExceptionType::what();
}

