namespace dap {

struct SampleDataStructure {
  dap::integer value;
  dap::number decimal;
};

DAP_STRUCT_TYPEINFO(SampleDataStructure,
                    "SampleDataStructure",
                    DAP_FIELD(value, "value"),
                    DAP_FIELD(decimal, "decimal"));

}  // namespace dap

TEST(Variant, DefaultInitialization) {
  dap::variant<dap::integer, dap::boolean, dap::SampleDataStructure> var;
  ASSERT_TRUE(var.is<dap::integer>());
  ASSERT_FALSE(var.is<dap::boolean>());
  ASSERT_FALSE(var.is<dap::SampleDataStructure>());
}

TEST(Variant, BooleanValue) {
  dap::variant<dap::integer, dap::boolean, dap::SampleDataStructure> var(
      dap::boolean(false));
  ASSERT_TRUE(var.is<dap::boolean>());
  ASSERT_EQ(var.get<dap::boolean>(), dap::boolean(false));
}

TEST(Variant, IntegerValue) {
  dap::variant<dap::integer, dap::boolean, dap::SampleDataStructure> var(
      dap::integer(20));
  ASSERT_TRUE(var.is<dap::integer>());
  ASSERT_EQ(var.get<dap::integer>(), dap::integer(20));
}

TEST(Variant, StructValue) {
  dap::variant<dap::integer, dap::boolean, dap::SampleDataStructure> var(
      dap::SampleDataStructure{7, 2.5});
  ASSERT_TRUE(var.is<dap::SampleDataStructure>());
  ASSERT_EQ(var.get<dap::SampleDataStructure>().value, 7);
  ASSERT_EQ(var.get<dap::SampleDataStructure>().decimal, 2.5);
}

TEST(Variant, Assignment) {
  dap::variant<dap::integer, dap::boolean, dap::SampleDataStructure> var(
      dap::integer(30));

  var = dap::integer(40);
  ASSERT_TRUE(var.is<dap::integer>());
  ASSERT_FALSE(var.is<dap::boolean>());
  ASSERT_FALSE(var.is<dap::SampleDataStructure>());
  ASSERT_EQ(var.get<dap::integer>(), dap::integer(40));

  var = dap::boolean(true);
  ASSERT_FALSE(var.is<dap::integer>());
  ASSERT_TRUE(var.is<dap::boolean>());
  ASSERT_FALSE(var.is<dap::SampleDataStructure>());
  ASSERT_EQ(var.get<dap::boolean>(), dap::boolean(true));

  var = dap::SampleDataStructure{9, 1.5};
  ASSERT_FALSE(var.is<dap::integer>());
  ASSERT_FALSE(var.is<dap::boolean>());
  ASSERT_TRUE(var.is<dap::SampleDataStructure>());
  ASSERT_EQ(var.get<dap::SampleDataStructure>().value, 9);
  ASSERT_EQ(var.get<dap::SampleDataStructure>().decimal, 1.5);
}

TEST(Variant, AcceptsType) {
  using var_type = dap::variant<dap::integer, dap::boolean, dap::SampleDataStructure>;
  ASSERT_TRUE(var_type::accepts<dap::integer>());
  ASSERT_TRUE(var_type::accepts<dap::boolean>());
  ASSERT_TRUE(var_type::accepts<dap::SampleDataStructure>());
  ASSERT_FALSE(var_type::accepts<dap::number>());
  ASSERT_FALSE(var_type::accepts<dap::string>());
}

