std::string InterpreterObj::evaluateExpression(const std::string& expression)
{
  pybind11::object evaluationResult;
  execute([&evaluationResult, &expression]() { evaluationResult = pybind11::eval(expression); });
  return evaluationResult ? pybind11::str(evaluationResult).cast<std::string>() : "";
}

void InterpreterObj::executeCode(const std::string& codeBlock)
{
  execute([&codeBlock]() { pybind11::exec(codeBlock); });
}

void InterpreterObj::executeFile(const std::string& filePath)
{
  execute([&filePath]() { pybind11::eval_file(filePath); });
}

void InterpreterObj::execute(std::function<void()>&& task) const
{
  pybind11::gil_scoped_acquire gilLock;
  try
  {
    task();
  }
  catch (pybind11::error_already_set& error)
  {
    getLogger()->error(error.what());
    error.discard_as_unraisable("py::interpreter");
  }
  catch (const pybind11::attribute_error& attrError)
  {
    getLogger()->error(attrError.what());
    throwRuntimeError(attrError.what());
  }
  catch (...)
  {
    getLogger()->error("interpreter: unexpected exception occurred");
    throwRuntimeError("interpreter: unexpected exception occurred");
  }
}
