// Helper structure for binary-level comparison of VPack Slices
struct BinaryEquivalent {
  // Returns true if both Slices are identical at the binary level
  static bool IsIdentical(Slice left, Slice right) { 
    return left.binaryEquals(right); 
  }

  struct HashFunction {
    size_t operator()(vpack::Slice slice) const {
      return static_cast<size_t>(slice.hash());
    }
  };

  struct EqualityChecker {
    const vpack::Options* config = nullptr;
    EqualityChecker() = default;
    explicit EqualityChecker(const vpack::Options* opts) : config{opts} {}
    bool operator()(vpack::Slice first, vpack::Slice second) const {
      return BinaryEquivalent::IsIdentical(first, second);
    }
  };
};

TEST(BinaryEquivalentTest, PrimitiveTypes) {
  ASSERT_TRUE(BinaryEquivalent::IsIdentical(Slice::noneSlice(), Slice::noneSlice()));
  ASSERT_FALSE(BinaryEquivalent::IsIdentical(Slice::noneSlice(), Slice::nullSlice()));
  ASSERT_FALSE(BinaryEquivalent::IsIdentical(Slice::nullSlice(), Slice::noneSlice()));
  ASSERT_TRUE(BinaryEquivalent::IsIdentical(Slice::nullSlice(), Slice::nullSlice()));
  ASSERT_TRUE(BinaryEquivalent::IsIdentical(Slice::falseSlice(), Slice::falseSlice()));
  ASSERT_TRUE(BinaryEquivalent::IsIdentical(Slice::trueSlice(), Slice::trueSlice()));
  ASSERT_FALSE(BinaryEquivalent::IsIdentical(Slice::trueSlice(), Slice::falseSlice()));
  ASSERT_FALSE(BinaryEquivalent::IsIdentical(Slice::falseSlice(), Slice::trueSlice()));

  Builder builderA;
  Builder builderB;

  builderA.add(int64_t(42));
  builderB.add(int64_t(42));

  ASSERT_TRUE(builderA.slice().isInt());
  ASSERT_TRUE(builderB.slice().isInt());
  ASSERT_TRUE(BinaryEquivalent::IsIdentical(builderA.slice(), builderB.slice()));

  builderB.clear();
  builderB.add(uint64_t(42));

  ASSERT_TRUE(builderA.slice().isInt());
  ASSERT_TRUE(builderB.slice().isUInt());
  ASSERT_FALSE(BinaryEquivalent::IsIdentical(builderA.slice(), builderB.slice()));

  builderA.clear();
  builderB.clear();

  builderA.add(uint64_t(42));
  builderB.add(uint64_t(42));

  ASSERT_TRUE(builderA.slice().isUInt());
  ASSERT_TRUE(builderB.slice().isUInt());
  ASSERT_TRUE(BinaryEquivalent::IsIdentical(builderA.slice(), builderB.slice()));
}

