#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"

static safety_check_abort_hook_t safety_check_failure_handler;

void safety_check_fail_sized_dealloc(bool is_current_free, const void *address,
    size_t actual_size, size_t expected_size) {
	char *origin = is_current_free ? "the current pointer being freed" :
	    "in thread cache, possibly from previous deallocations";
	safety_check_fail("<jemalloc>: size mismatch detected (true size %zu "
	    "vs input size %zu), likely caused by application sized "
	    "deallocation bugs (source address: %p, %s). Suggest building with "
	    "--enable-debug or address sanitizer for debugging. Abort.\n",
	    actual_size, expected_size, address, origin);
}

void safety_check_set_abort(safety_check_abort_hook_t handler) {
	safety_check_failure_handler = handler;
}

void safety_check_fail(const char *message, ...) {
	char buffer[MALLOC_PRINTF_BUFSIZE];
	va_list args;
	va_start(args, message);
	malloc_vsnprintf(buffer, MALLOC_PRINTF_BUFSIZE, message, args);
	va_end(args);
	if (safety_check_failure_handler == NULL) {
		malloc_write(buffer);
		abort();
	} else {
		safety_check_failure_handler(buffer);
	}
}

#include "autolink/transport/common/identity.hpp"
#include "gtest/gtest.h"

namespace autolink {
namespace transport {

// Test identity construction with false value
TEST(IdentityTest, testConstructFalse) {
  Identity id(false);
  EXPECT_EQ(id.HashValue(), static_cast<uint64_t>(0));
  EXPECT_EQ(id.ToString(), "0");
}

// Test identity construction with true value
TEST(IdentityTest, testConstructTrue) {
  Identity id(true);
  EXPECT_NE(id.HashValue(), static_cast<uint64_t>(0));
  EXPECT_NE(id.ToString(), "0");
}

// Test identity equality and assignment operations
TEST(IdentityTest, testIdentityEqual) {
  Identity a;
  Identity b;
  Identity c;

  EXPECT_NE(a, b);
  EXPECT_NE(b, c);
  EXPECT_NE(a, c);
  EXPECT_NE(a.HashValue(), c.HashValue());

  b = b;
  EXPECT_NE(b, c);

  b = c;
  EXPECT_EQ(b, c);

  Identity d(a);
  EXPECT_EQ(a, d);
  EXPECT_EQ(a.ToString(), d.ToString());
  EXPECT_EQ(a.HashValue(), d.HashValue());
}

// Test operator= functionality for identity objects
TEST(IdentityTest, testOperatorEqual) {
  Identity src(true);
  Identity dest(false);

  dest = src;
  EXPECT_EQ(src.HashValue(), dest.HashValue());
  EXPECT_EQ(src.ToString(), dest.ToString());
  EXPECT_EQ(dest.Length(), src.Length());

  src.set_data(nullptr);
  Identity third;
  third.set_data(src.data());

  EXPECT_EQ(third.HashValue(), dest.HashValue());
  EXPECT_EQ(third.ToString(), dest.ToString());
  EXPECT_EQ(dest.Length(), third.Length());
}

