using namespace llvm;

cl::opt<std::string> InputFilename(cl::Positional, cl::desc("<input file>"),
                                   cl::init("-"));
cl::opt<std::string> OutputFilename("o", cl::desc("Specify output filename"),
                                    cl::value_desc("filename"), cl::Required);

int main(int argc, char **argv) {
  cl::ParseCommandLineOptions(argc, argv);

  LLVMContext llvmContext;
  SMDiagnostic diag;
  auto irModule = parseIRFile(InputFilename, diag, llvmContext);

  if (!irModule) {
    diag.print(InputFilename.data(), errs());
    return -1;
  }

  dynamic::MemoryInstrument().runOnModule(*irModule);

  std::error_code errCode;
  ToolOutputFile outputFile(OutputFilename, errCode, sys::fs::OF_None);
  outputFile.keep();

  WriteBitcodeToFile(*irModule, outputFile.os());
}

