#ifdef LLK_TRISC_UNPACK
#include "llk_unpack_A.h"
#include "llk_unpack_common.h"

void run_kernel(const volatile struct RuntimeParams* runtimeParams)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& formats = runtimeParams->formats;
#endif

    // Configure unpack hardware with face dimensions and number of faces
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        formats.unpack_A_src, formats.unpack_B_src, formats.unpack_A_dst, formats.unpack_B_dst,
        FACE_R_DIM, FACE_R_DIM, runtimeParams->num_faces, runtimeParams->num_faces);

    // Initialize unpack A operation
    _llk_unpack_A_init_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
        runtimeParams->UNPACK_TRANSPOSE_FACES, 0, FACE_R_DIM, runtimeParams->num_faces,
        formats.unpack_A_src, formats.unpack_A_dst);

    // Unpack all input tiles
    for (int tileIndex = 0; tileIndex < runtimeParams->TILE_CNT; ++tileIndex)
    {
        _llk_unpack_A_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
            L1_ADDRESS(runtimeParams->buffer_A[tileIndex]), formats.unpack_A_src, formats.unpack_A_dst);
    }

    // Set dummy valid for source B (unpack)
    for (int tileIndex = 0; tileIndex < runtimeParams->TILE_CNT; ++tileIndex)
    {
        _llk_unpack_set_srcb_dummy_valid_();
    }
}
#endif

#ifdef LLK_TRISC_MATH
#include "llk_math_common.h"
#include "llk_math_eltwise_unary_datacopy.h"
#include "llk_math_transpose_dest.h"
using namespace ckernel;

void run_kernel(const volatile struct RuntimeParams* runtimeParams)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& formats = runtimeParams->formats;
#endif

    constexpr bool is32 = is_fp32_dest_acc_en;

#ifdef ARCH_BLACKHOLE
    // Initialize data copy from A to destination
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, false>(
        runtimeParams->num_faces, formats.math);
#else
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false>(
        runtimeParams->num_faces, formats.math);
#endif

    // Initialize packer sync and configure math unit
    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(formats.math, formats.math);
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Process each tile: data copy
    for (int tileIndex = 0; tileIndex < runtimeParams->TILE_CNT; ++tileIndex)
    {
        LLK_ASSERT(
            tileIndex < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");

#ifdef ARCH_BLACKHOLE
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            tileIndex, formats.math, formats.math);
#else
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            tileIndex, formats.math, formats.math);
#endif
    }

    // Setup transpose destination
    _llk_math_transpose_dest_init_<MATH_TRANSPOSE_FACES, is32>();

    // Perform transpose on each tile
    for (int tileIndex = 0; tileIndex < runtimeParams->TILE_CNT; ++tileIndex)
    {
        LLK_ASSERT(
            tileIndex < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");

#ifdef ARCH_BLACKHOLE
        _llk_math_transpose_dest_<is_fp32_dest_acc_en, MATH_TRANSPOSE_FACES, is32>(tileIndex);
#else
        _llk_math_transpose_dest_<MATH_TRANSPOSE_FACES, is32>(tileIndex);
#endif
    }

    // Signal end of destination section
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"

void run_kernel(const volatile struct RuntimeParams* runtimeParams)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& formats = runtimeParams->formats;
#endif

#ifdef ARCH_BLACKHOLE
    // Configure packer hardware with fixed buffer size (1024 bytes = 16×16×4)
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(
        formats.pack_src, formats.pack_dst, 1024, FACE_R_DIM, TILE_C_DIM, runtimeParams->num_faces);
    _llk_pack_init_<false, false, false>(
        formats.pack_dst, FACE_R_DIM, TILE_C_DIM, runtimeParams->num_faces);
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(
        formats.pack_src, formats.pack_dst, 1024, FACE_R_DIM, runtimeParams->num_faces);
    _llk_pack_init_<false, false>(
        formats.pack_dst, FACE_R_DIM, runtimeParams->num_faces);
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>();
#endif

    // Wait until math operations are complete
    _llk_packer_wait_for_math_done_();

    // Pack output tiles
    for (int tileIndex = 0; tileIndex < runtimeParams->TILE_CNT; ++tileIndex)
    {
        LLK_ASSERT(
            tileIndex < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");
        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(
            tileIndex, L1_ADDRESS(runtimeParams->buffer_Res[tileIndex]));
    }

    // Signal end of packed destination section
    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#include <mesh_globals.h>
#include <panel4.h>

// Apply rotation to quad mesh elements using Euler angles
void rotateQuadMesh(std::vector<Panel4> &elements, double angleZ, double angleY)
{
    Vector3d centerPoint;
    for(uint elementIndex = 0; elementIndex < elements.size(); elementIndex++)
    {
        Panel4 &currentPanel = elements[elementIndex];
        for(int nodeIndex = 0; nodeIndex < 4; nodeIndex++)
        {
            currentPanel.m_Node[nodeIndex].rotateZ(centerPoint, angleZ);
            currentPanel.m_Node[nodeIndex].rotateY(centerPoint, angleZ);
        }
        currentPanel.setPanelFrame();
    }
}

