#define TILING_KEY_UNQUANTIZED 10000
#define TILING_KEY_QUANTIZED   10002

extern "C" __global__ __aicore__ void cam_moe_dispatch_normal(
    GM_ADDR inputTensor, 
    GM_ADDR expertIndices, 
    GM_ADDR sendDisplacements, 
    GM_ADDR sendTokenPositions, 
    GM_ADDR recvDisplacements, 
    GM_ADDR recvCounts,
    GM_ADDR expertGlobalOffsets, 
    GM_ADDR srcRankInExpertOffsets, 
    GM_ADDR rInSrcRankOffsets, 
    GM_ADDR expandedOutputX,
    GM_ADDR dynamicScaleFactors, 
    GM_ADDR combineAssistInfo, 
    GM_ADDR recvWaitCostStats, 
    GM_ADDR workspaceGlobalMemory,
    GM_ADDR tilingParametersGM)
{
    REGISTER_TILING_DEFAULT(CamMoeDispatchNormalTilingData);
    TPipe pipeline;

#if (ORIG_DTYPE_RECV_X == DT_BF16 || ORIG_DTYPE_RECV_X == DT_FLOAT16)
    if (TILING_KEY_IS(TILING_KEY_UNQUANTIZED)) {
        GET_TILING_DATA_WITH_STRUCT(CamMoeDispatchNormalTilingData, tilingConfig, tilingParametersGM);
        CamMoeDispatchNormal<DTYPE_X, DTYPE_RECV_X, false, false, false> operation;
        operation.Init(inputTensor, expertIndices, sendDisplacements, sendTokenPositions, recvDisplacements, recvCounts,
                       expertGlobalOffsets, srcRankInExpertOffsets, rInSrcRankOffsets, expandedOutputX, dynamicScaleFactors,
                       combineAssistInfo, recvWaitCostStats, workspaceGlobalMemory, &pipeline, tilingParametersGM);
        operation.Run();
        return;
    }
#elif (ORIG_DTYPE_RECV_X == DT_INT8)
    if (TILING_KEY_IS(TILING_KEY_QUANTIZED)) {
        GET_TILING_DATA_WITH_STRUCT(CamMoeDispatchNormalTilingData, tilingConfig, tilingParametersGM);
        CamMoeDispatchNormal<DTYPE_X, DTYPE_RECV_X, true, false, false> operation;
        operation.Init(inputTensor, expertIndices, sendDisplacements, sendTokenPositions, recvDisplacements, recvCounts,
                       expertGlobalOffsets, srcRankInExpertOffsets, rInSrcRankOffsets, expandedOutputX, dynamicScaleFactors,
                       combineAssistInfo, recvWaitCostStats, workspaceGlobalMemory, &pipeline, tilingParametersGM);
        operation.Run();
        return;
    }
#endif
}

