/* Wrapper for setenv with thread safety */
void
x_cgo_setenv(char **parameters)
{
	_cgo_tsan_acquire();
	setenv(parameters[0], parameters[1], 1);
	_cgo_tsan_release();
}
/* Wrapper for unsetenv with thread safety */
void
x_cgo_unsetenv(char **env_var)
{
	_cgo_tsan_acquire();
	unsetenv(env_var[0]);
	_cgo_tsan_release();
}

