namespace pulse {

// Test that adding a disequality first prevents subsequent equality
TEST(PulseFormulaTest, DisequalityContradictsEquality) {
    PulseFormula formula;
    AbstractValue val1(nullptr, 10);
    AbstractValue val2(nullptr, 20);
    EXPECT_TRUE(formula.addDisequality(val1, val2));
    EXPECT_FALSE(formula.addEquality(val1, val2));
}

// Test that adding an equality first prevents subsequent disequality
TEST(PulseFormulaTest, EqualityContradictsDisequality) {
    PulseFormula formula;
    AbstractValue val1(nullptr, 10);
    AbstractValue val2(nullptr, 20);
    EXPECT_TRUE(formula.addEquality(val1, val2));
    EXPECT_FALSE(formula.addDisequality(val1, val2));
}

// Test that disequality is preserved when values are transitively linked via unions
TEST(PulseFormulaTest, DisequalityPreservedThroughUnion) {
    PulseFormula formula;
    AbstractValue x(nullptr, 10);
    AbstractValue y(nullptr, 20);
    AbstractValue z(nullptr, 30);
    EXPECT_TRUE(formula.addDisequality(x, y));
    EXPECT_TRUE(formula.addEquality(y, z));
    EXPECT_TRUE(formula.areDisequal(x, z));
}

// Test that attempting to violate a transitive disequality fails
TEST(PulseFormulaTest, InconsistentWhenUnionViolatesDisequality) {
    PulseFormula formula;
    AbstractValue x(nullptr, 10);
    AbstractValue y(nullptr, 20);
    AbstractValue z(nullptr, 30);
    EXPECT_TRUE(formula.addDisequality(x, y));
    EXPECT_TRUE(formula.addEquality(y, z));
    EXPECT_FALSE(formula.addEquality(x, z));
}

