#include "testing/testing.hpp"
#include "geometry/point2d.hpp"
#include "geometry/segment2d.hpp"

namespace segment2d_tests
{
using namespace m2;

double const kTolerance = 1e-10;

void ValidateIntersectionResult(IntersectionResult const & result, IntersectionResult::Type expectedType,
                                PointD const & expectedPoint)
{
  TEST_EQUAL(result.m_type, expectedType, ());
  TEST(AlmostEqualAbs(result.m_point, expectedPoint, kTolerance), (result.m_point, expectedPoint, kTolerance));
}

bool CheckSegmentsIntersect(PointD p1, PointD p2, PointD p3, PointD p4)
{
  bool const res = SegmentsIntersect(p1, p2, p3, p4);
  TEST_EQUAL(res, SegmentsIntersect(p1, p2, p4, p3), (p1, p2, p3, p4));
  TEST_EQUAL(res, SegmentsIntersect(p2, p1, p3, p4), (p1, p2, p3, p4));
  TEST_EQUAL(res, SegmentsIntersect(p2, p1, p4, p3), (p1, p2, p3, p4));
  TEST_EQUAL(res, SegmentsIntersect(p3, p4, p1, p2), (p1, p2, p3, p4));
  TEST_EQUAL(res, SegmentsIntersect(p3, p4, p2, p1), (p1, p2, p3, p4));
  TEST_EQUAL(res, SegmentsIntersect(p4, p3, p1, p2), (p1, p2, p3, p4));
  TEST_EQUAL(res, SegmentsIntersect(p4, p3, p2, p1), (p1, p2, p3, p4));
  return res;
}

UNIT_TEST(SegmentIntersection_Collinear)
{
  TEST(!CheckSegmentsIntersect({0.0, 0.0}, {1.0, 1.0}, {2.0, 3.0}, {3.0, 3.0}), ("Far away"));
  TEST(CheckSegmentsIntersect({0.0, 0.0}, {1.0, 1.0}, {1.0, 1.0}, {3.0, 3.0}), ("Border intersection"));
  TEST(CheckSegmentsIntersect({0.0, 0.0}, {2.0, 2.0}, {1.0, 1.0}, {3.0, 3.0}), ("Normal intersection"));
  TEST(CheckSegmentsIntersect({0.0, 0.0}, {2.0, 2.0}, {0.0, 0.0}, {3.0, 3.0}), ("Border inclusion"));
  TEST(CheckSegmentsIntersect({1.0, 1.0}, {2.0, 2.0}, {0.0, 0.0}, {3.0, 3.0}), ("Normal inclusion"));
}

UNIT_TEST(SegmentIntersection_NoIntersection)
{
  TEST(!CheckSegmentsIntersect({0.0, 1.0}, {2.0, 5.0}, {7.0, 7.0}, {15.0, 7.0}), ("Far away"));
  TEST(!CheckSegmentsIntersect({0.0, 0.0}, {2.0, 4.0}, {1.0, 1.0}, {4.0, 3.0}), ("Rect intersect, segments don't"));
  TEST(!CheckSegmentsIntersect({0.0, 0.0}, {8.0, 8.0}, {1.0, 2.0}, {4.0, 8.0}), ("Only one cross product is 0"));
}

UNIT_TEST(SegmentIntersection_Intersect)
{
  TEST(CheckSegmentsIntersect({0.0, 0.0}, {2.0, 4.0}, {0.0, 3.0}, {4.0, 0.0}), ("Normal"));
  TEST(CheckSegmentsIntersect({1.0, 2.0}, {3.0, 4.0}, {1.0, 2.0}, {5.0, 1.0}), ("Fan"));
  TEST(CheckSegmentsIntersect({1.0, 2.0}, {3.0, 4.0}, {1.0, 2.0}, {3.0, -2.0}), ("Fan"));
  TEST(CheckSegmentsIntersect({0.0, 0.0}, {2.0, 2.0}, {0.0, 4.0}, {4.0, 0.0}), ("Border"));
}

UNIT_TEST(SegmentIntersection_NoIntersectionPoint)
{
  TEST_EQUAL(Intersect(Segment2D({0.0, 0.0}, {1.0, 0.0}), Segment2D({2.0, 0.0}, {4.0, 0.0}), kTolerance).m_type,
             IntersectionResult::Type::Zero, ());
  TEST_EQUAL(Intersect(Segment2D({0.0, 0.0}, {1.0, 1.0}), Segment2D({2.0, 0.0}, {4.0, 0.0}), kTolerance).m_type,
             IntersectionResult::Type::Zero, ());
  TEST_EQUAL(Intersect(Segment2D({0.0, 0.0}, {1.0, 1.0}), Segment2D({4.0, 4.0}, {2.0, 2.0}), kTolerance).m_type,
             IntersectionResult::Type::Zero, ());
  TEST_EQUAL(Intersect(Segment2D({0.0, 0.0}, {4.0, 4.0}), Segment2D({10.0, 0.0}, {6.0, 4.0}), kTolerance).m_type,
             IntersectionResult::Type::Zero, ());
}

UNIT_TEST(SegmentIntersection_OneIntersectionPoint)
{
  // Two intersected segments. The intersection point is in the middle of both of them.
  {
    auto const result = Intersect(Segment2D({-1.0, -1.0}, {1.0, 1.0}), Segment2D({-1.0, 0.0}, {1.0, 0.0}), kTolerance);
    ValidateIntersectionResult(result, IntersectionResult::Type::One, {0.0, 0.0});
  }
  {
    auto const result = Intersect(Segment2D({0.0, 0.0}, {10.0, 10.0}), Segment2D({10.0, 0.0}, {0.0, 10.0}), kTolerance);
    ValidateIntersectionResult(result, IntersectionResult::Type::One, {5.0, 5.0});
  }
  // Two intersected segments. The intersection point is in an end of both of them.
  {
    auto const result = Intersect(Segment2D({-1.0, -1.0}, {0.0, 0.0}), Segment2D({0.0, 0.0}, {11.0, 0.0}), kTolerance);
    ValidateIntersectionResult(result, IntersectionResult::Type::One, {0.0, 0.0});
  }
}

UNIT_TEST(SegmentIntersection_InfinityIntersectionPoints)
{
  TEST_EQUAL(Intersect(Segment2D({0.0, 0.0}, {2.0, 0.0}), Segment2D({1.0, 0.0}, {4.0, 0.0}), kTolerance).m_type,
             IntersectionResult::Type::Infinity, ());
  TEST_EQUAL(Intersect(Segment2D({0.0, 0.0}, {2.0, 4.0}), Segment2D({1.0, 2.0}, {2.0, 4.0}), kTolerance).m_type,
             IntersectionResult::Type::Infinity, ());
}
}  // namespace segment2d_tests

