TEST(HttpRequestTest, testUrlEncoding) {
  ConnectionInfo connInfo;
  HttpRequest req(connInfo, 88);
  std::string_view path(
    "/api/v1/"
    "data?key=%2Ffile%2Etxt&num=123&msg=hello+world&spec=%2F%5B%5D%3D%26&tab=%0A");
