// Helper macro for comparison functions
#define MAKE_COMPARATOR(type, op) \
  [](const type* a, const type* b) { return (*a) op (*b); }

// Helper macro for key-based comparison
#define MAKE_KEY_COMPARATOR(struct_type, key_field, op) \
  [](const struct_type* a, const struct_type* b) { return (a->key_field) op (b->key_field); }

// String comparison helper
inline bool str_less(const char* a, const char* b) {
    return std::strcmp(a, b) < 0;
}

inline bool str_greater(const char* a, const char* b) {
    return std::strcmp(a, b) > 0;
}

/*************************************************************************/
/*! Sorts an array of chars in increasing order */
/*************************************************************************/
void gk_csorti(size_t n, char *base)
{
  auto comp = MAKE_COMPARATOR(char, <);
  GK_MKQSORT(char, base, n, comp);
}

/*************************************************************************/
/*! Sorts an array of chars in decreasing order */
/*************************************************************************/
void gk_csortd(size_t n, char *base)
{
  auto comp = MAKE_COMPARATOR(char, >);
  GK_MKQSORT(char, base, n, comp);
}

