struct Uint8ConversionTest : public VariantConversionFixture<uint8_t>
{
};

TEST_P(Uint8ConversionTest, PerformConversion) { executeValidation(); };

INSTANTIATE_TEST_SUITE_P(
  VariantAdapterTest,
  Uint8ConversionTest,
  ::testing::Values(
    make_tuple(UInt8Type::get(), Var(uint8_t {17}), UInt8Type::get(), uint8_t {17}),
    make_tuple(UInt16Type::get(), Var(uint16_t {17}), UInt8Type::get(), uint8_t {17}),
    make_tuple(UInt32Type::get(), Var(uint32_t {17}), UInt8Type::get(), uint8_t {17}),
    make_tuple(UInt64Type::get(), Var(uint64_t {17}), UInt8Type::get(), uint8_t {17}),
    make_tuple(Int16Type::get(), Var(int16_t {17}), UInt8Type::get(), uint8_t {17}),
    make_tuple(Int32Type::get(), Var(int32_t {17}), UInt8Type::get(), uint8_t {17}),
    make_tuple(Int64Type::get(), Var(int64_t {17}), UInt8Type::get(), uint8_t {17}),
    make_tuple(Float32Type::get(), Var(float32_t {17}), UInt8Type::get(), uint8_t {17}),
    make_tuple(Float64Type::get(), Var(float64_t {17}), UInt8Type::get(), uint8_t {17}),
    /* overflow conversions: we expect capping to max target type */
    make_tuple(UInt16Type::get(), Var(uint16_t {35535}), UInt8Type::get(), numeric_limits<uint8_t>::max()),
    make_tuple(UInt32Type::get(), Var(uint32_t {65536}), UInt8Type::get(), numeric_limits<uint8_t>::max()),
    make_tuple(UInt64Type::get(), Var(uint64_t {65536}), UInt8Type::get(), numeric_limits<uint8_t>::max()),
    make_tuple(Int16Type::get(), Var(int32_t {31234}), UInt8Type::get(), numeric_limits<uint8_t>::max()),
    make_tuple(Int32Type::get(), Var(int32_t {65536}), UInt8Type::get(), numeric_limits<uint8_t>::max()),
    make_tuple(Int64Type::get(), Var(int64_t {65536}), UInt8Type::get(), numeric_limits<uint8_t>::max()),
    /* underflow conversions: we expect capping to lowest target type */
    make_tuple(Int16Type::get(), Var(int16_t {-17}), UInt8Type::get(), numeric_limits<uint8_t>::lowest()),
    make_tuple(Int32Type::get(), Var(int32_t {-17}), UInt8Type::get(), numeric_limits<uint8_t>::lowest()),
    make_tuple(Int64Type::get(), Var(int64_t {-17}), UInt8Type::get(), numeric_limits<uint8_t>::lowest()),
    /* underflow/rounding conversions: we expect capping to max target type */
    make_tuple(Float32Type::get(), Var(float32_t {-1.7}), UInt8Type::get(), numeric_limits<uint8_t>::lowest()),
    make_tuple(Float64Type::get(), Var(float64_t {-1.7}), UInt8Type::get(), numeric_limits<uint8_t>::lowest())),
  [](const testing::TestParamInfo<Uint8ConversionTest::ParamType>& info)
  { return generateTestName(std::get<0>(info.param), std::get<1>(info.param), std::get<2>(info.param)); });

