#include "sdfg/codegen/dispatchers/if_else_dispatcher.h"
#include "sdfg/codegen/dispatchers/sequence_dispatcher.h"

namespace sdfg {
namespace codegen {

IfElseDispatcher::IfElseDispatcher(
    LanguageExtension& lang_ext,
    StructuredSDFG& graph,
    analysis::AnalysisManager& analyzer,
    structured_control_flow::IfElse& branch_node,
    InstrumentationPlan& instrument_plan,
    ArgCapturePlan& arg_capture_plan
)
    : NodeDispatcher(lang_ext, graph, analyzer, branch_node, instrument_plan, arg_capture_plan),
      node_(branch_node) {
}

void IfElseDispatcher::dispatch_node(
    PrettyPrinter& main_stream, 
    PrettyPrinter& globals_stream, 
    CodeSnippetFactory& library_snippet_factory
) {
    for (size_t idx = 0; idx < node_.size(); ++idx) {
        auto branch = node_.at(idx);
        if (idx == 0) {
            main_stream << "if";
        } else {
            main_stream << "else if";
        }
        main_stream << "(";
        main_stream << language_extension_.expression(branch.second);
        main_stream << ")";
        main_stream << std::endl;
        main_stream << "{" << std::endl;
        main_stream.setIndent(main_stream.indent() + 4);

        SequenceDispatcher dispatcher(
            language_extension_, sdfg_, analysis_manager_, branch.first, instrumentation_plan_, arg_capture_plan_
        );
        dispatcher.dispatch(main_stream, globals_stream, library_snippet_factory);

        main_stream.setIndent(main_stream.indent() - 4);
        main_stream << "}" << std::endl;
    }
}

} // namespace codegen
} // namespace sdfg

