template <>
struct ScalarEnumerationTraits<plugin::Plugin::Type> {
  static void enumeration(IO &Stream, plugin::Plugin::Type &Kind) {
    Stream.enumCase(Kind, "SectionMatcher", plugin::Plugin::Type::SectionMatcher);
    Stream.enumCase(Kind, "SectionIterator", plugin::Plugin::Type::SectionIterator);
    Stream.enumCase(Kind, "OutputSectionIterator",
                    plugin::Plugin::Type::OutputSectionIterator);
    Stream.enumCase(Kind, "", plugin::Plugin::Type::OutputSectionIterator);
    Stream.enumCase(Kind, "ControlFileSize", plugin::Plugin::Type::ControlFileSize);
    Stream.enumCase(Kind, "ControlMemorySize",
                    plugin::Plugin::Type::ControlMemorySize);
    Stream.enumCase(Kind, "LinkerPlugin", plugin::Plugin::Type::LinkerPlugin);
  }
};

void MappingTraits<Config>::mapping(IO &Stream, Config &Settings) {
  Stream.mapOptional("GlobalPlugins", Settings.GlobalPlugins);
  Stream.mapOptional("OutputSectionPlugins", Settings.OutputSectionPlugins);
}

void MappingTraits<GlobalPlugin>::mapping(IO &Stream, GlobalPlugin &Entry) {
  Stream.mapRequired("Type", Entry.PluginType);
  Stream.mapRequired("Name", Entry.PluginName);
  Stream.mapRequired("Library", Entry.LibraryName);
  Stream.mapOptional("Options", Entry.Options);
}

void MappingTraits<OutputSectionPlugin>::mapping(
    IO &Stream, OutputSectionPlugin &SectionEntry) {
  Stream.mapRequired("OutputSection", SectionEntry.OutputSection);
  Stream.mapRequired("Type", SectionEntry.PluginType);
  Stream.mapRequired("Name", SectionEntry.PluginName);
  Stream.mapRequired("Library", SectionEntry.LibraryName);
  Stream.mapOptional("Options", SectionEntry.Options);
}

