namespace snap::drawing {

static CompositorPlaneList executeComposition(DisplayListBuilder& builder,
                                              Ref<DisplayList>* resultDisplayList = nullptr) {
    CompositorPlaneList layerList;
    Compositor compositor(ConsoleLogger::getLogger());
    auto displayList = compositor.performComposition(*builder.displayList, layerList);
    if (resultDisplayList != nullptr) {
        *resultDisplayList = displayList;
    }
    return layerList;
}

TEST(Compositor, doesNothingWhenNoExternalSurfacesArePresent) {
    DisplayListBuilder builder(100, 100);
    builder.context(Vector(0, 0), 1.0, [&]() {
        builder.rectangle(Size(50, 50), 1.0);
        builder.context(Vector(25, 25), 1.0, [&]() { builder.rectangle(Size(10, 10), 1.0); });
        builder.context(Vector(35, 35), 1.0, [&]() { builder.rectangle(Size(50, 50), 1.0); });
        builder.rectangle(Size(25, 25), 1.0);
    });
    Ref<DisplayList> outputDisplayList;
    auto layerList = executeComposition(builder, &outputDisplayList);
    ASSERT_EQ(static_cast<size_t>(1), layerList.getPlanesCount());
    ASSERT_EQ(CompositorPlaneTypeDrawable, layerList.getPlaneAtIndex(0).getType());
    ASSERT_TRUE(layerList.getPlaneAtIndex(0).getExternalSurface() == nullptr);
    ASSERT_EQ(builder.displayList, outputDisplayList);
}

