void commandline_handler_metadb_handle::on_file(const char* path) {
    metadb_handle_list list;
    try {
        metadb_io::get()->path_to_handles_simple(path, list);
    } catch (const std::exception& err) {
        console::complain("Path resolution error", err);
        return;
    }
    for (size_t index = 0; index < list.get_size(); ++index) {
        on_file(list[index]);
    }
}

