#include "OnlineAGSCallbackManager.h"

void FOnlineAGSCallbackManager::RegisterActiveCallback(AmazonGames::ICallback* NewCallback)
{
	ActiveCallbacks.Add(NewCallback);
}

void FOnlineAGSCallbackManager::OnCallbackFinished(AmazonGames::ICallback* FinishedCallback)
{
	ActiveCallbacks.Remove(FinishedCallback);
	CompletedCallbacks.Add(FinishedCallback);
}

void FOnlineAGSCallbackManager::ProcessFrame()
{
	while (CompletedCallbacks.Num() > 0)
	{
		delete CompletedCallbacks[0];
		CompletedCallbacks.RemoveAt(0);
	}
}

#define _BSD_SOURCE
#include <unistd.h>
#include "syscall.h"
#include <stdarg.h>
#undef syscall

// Wrapper function for system calls with variable arguments
long syscall(long number, ...)
{
    va_list args;
    syscall_arg_t arg1, arg2, arg3, arg4, arg5, arg6;

    va_start(args, number);
    arg1 = va_arg(args, syscall_arg_t);
    arg2 = va_arg(args, syscall_arg_t);
    arg3 = va_arg(args, syscall_arg_t);
    arg4 = va_arg(args, syscall_arg_t);
    arg5 = va_arg(args, syscall_arg_t);
    arg6 = va_arg(args, syscall_arg_t);
    va_end(args);

    return __syscall_ret(__syscall(number, arg1, arg2, arg3, arg4, arg5, arg6));
}

