#define VERIFY_UINT32_HEX_CONVERSION(input, expected, tempBuffer)          \
  resultLength = StringUInt32HexInPlace((uint32_t)input, (char*)&tempBuffer); \
  EXPECT_EQ(resultLength, strlen(expected));                               \
  EXPECT_EQ(std::string(tempBuffer), std::string(expected));

#define VERIFY_UINT64_HEX_CONVERSION(input, expected, tempBuffer)          \
  resultLength = StringUInt64HexInPlace((uint64_t)input, (char*)&tempBuffer); \
  EXPECT_EQ(resultLength, strlen(expected));                               \
  EXPECT_EQ(std::string(tempBuffer), std::string(expected));

TEST(CConversionsTest, test_uint32_hex_formatting) {
  char storage[128];
  size_t resultLength;

  VERIFY_UINT32_HEX_CONVERSION(0UL, "0", storage)
  VERIFY_UINT32_HEX_CONVERSION(1UL, "1", storage)
  VERIFY_UINT32_HEX_CONVERSION(9UL, "9", storage)
  VERIFY_UINT32_HEX_CONVERSION(10UL, "A", storage)
  VERIFY_UINT32_HEX_CONVERSION(128UL, "80", storage)
  VERIFY_UINT32_HEX_CONVERSION(3254UL, "CB6", storage)
  VERIFY_UINT32_HEX_CONVERSION(65535UL, "FFFF", storage)
  VERIFY_UINT32_HEX_CONVERSION(65536UL, "10000", storage)
  VERIFY_UINT32_HEX_CONVERSION(68863UL, "10CFF", storage)
  VERIFY_UINT32_HEX_CONVERSION(465765536ULL, "1BC304A0", storage)
  VERIFY_UINT32_HEX_CONVERSION(UINT32_MAX, "FFFFFFFF", storage)
}

TEST(CConversionsTest, test_uint64_hex_formatting) {
  char storage[128];
  size_t resultLength;

  VERIFY_UINT64_HEX_CONVERSION(0ULL, "0", storage)
  VERIFY_UINT64_HEX_CONVERSION(1ULL, "1", storage)
  VERIFY_UINT64_HEX_CONVERSION(9ULL, "9", storage)
  VERIFY_UINT64_HEX_CONVERSION(10ULL, "A", storage)
  VERIFY_UINT64_HEX_CONVERSION(128ULL, "80", storage)
  VERIFY_UINT64_HEX_CONVERSION(3254ULL, "CB6", storage)
  VERIFY_UINT64_HEX_CONVERSION(65535ULL, "FFFF", storage)
  VERIFY_UINT64_HEX_CONVERSION(65536ULL, "10000", storage)
  VERIFY_UINT64_HEX_CONVERSION(68863ULL, "10CFF", storage)
  VERIFY_UINT64_HEX_CONVERSION(465765536ULL, "1BC304A0", storage)
  VERIFY_UINT64_HEX_CONVERSION(47634665765536ULL, "2B52CF54FAA0", storage)
  VERIFY_UINT64_HEX_CONVERSION(8668398959769325ULL, "1ECBDCE8C4B6ED", storage)
  VERIFY_UINT64_HEX_CONVERSION(UINT64_MAX, "FFFFFFFFFFFFFFFF", storage)
}

