template <typename T>
void copyIntoBufferAsBytes(BufferedTestReader& reader, const T value)
{
  if constexpr (std::is_same_v<T, std::string>)
  {
    sen::test::TestWriter writer;
    sen::OutputStream out(writer);
    out.writeString(value);
    reader.getBuffer() = writer.getBuffer();
  }
  else
  {
    // NOLINTNEXTLINE(cppcoreguidelines-pro-type-reinterpret-cast)
    auto valuePtr = reinterpret_cast<const uint8_t*>(&value);  // NOSONAR
    for (std::size_t idx = 0U; idx < sizeof(T); ++idx)
    {
      reader.getBuffer().push_back(*(std::next(valuePtr, static_cast<int>(idx))));
    }
  }
}
void copyIntoBufferAsBytes(BufferedTestReader& reader, const sen::Duration& value)
{
  copyIntoBufferAsBytes(reader, (value.getNanoseconds()));
}
void copyIntoBufferAsBytesT(BufferedTestReader& reader, const sen::TimeStamp& value)
{
  auto duration = value.sinceEpoch();
  copyIntoBufferAsBytes(reader, duration);
}
void checkBasicRead(const uint8_t value)
{
  BufferedTestReader reader;
  copyIntoBufferAsBytes(reader, value);
  InputStream in(reader.getBuffer());
  uint8_t result {};
  in.readUInt8(result);
  EXPECT_EQ(result, value);
  EXPECT_EQ(sizeof(uint8_t), reader.getBuffer().size() * sizeof(uint8_t));
}
