#include <tabulate/table.hpp>
#include <iostream>

using namespace tabulate;
using TableLine = Table::Row_t;

int main() {
  Table display;

  // Add rows with color-related text
  display.add_row(TableLine{"Text in Red", "Text in Blue", "Text in Green"});
  display.add_row(TableLine{"All Red Theme", "All Blue Theme", "All Green Theme"});
  display.add_row(
      TableLine{"Red Background", "Blue Background", "Green Background"});

  // Format first row: colored bold text
  display[0][0].format().font_color(Color::red).font_style({FontStyle::bold});
  display[0][1].format().font_color(Color::blue).font_style({FontStyle::bold});
  display[0][2].format().font_color(Color::green).font_style({FontStyle::bold});

  // Format second row: border and font colors matching cell content
  display[1][0]
      .format()
      .border_left_color(Color::red)
      .border_left_background_color(Color::red)
      .font_background_color(Color::red)
      .font_color(Color::red);
  display[1][1]
      .format()
      .border_left_color(Color::blue)
      .border_left_background_color(Color::blue)
      .font_background_color(Color::blue)
      .font_color(Color::blue);
  display[1][2]
      .format()
      .border_left_color(Color::green)
      .border_left_background_color(Color::green)
      .font_background_color(Color::green)
      .font_color(Color::green)
      .border_right_color(Color::green)
      .border_right_background_color(Color::green);

  // Format third row: colored backgrounds with bold text
  display[2][0].format().font_background_color(Color::red).font_style({FontStyle::bold});
  display[2][1].format().font_background_color(Color::blue).font_style({FontStyle::bold});
  display[2][2].format().font_background_color(Color::green).font_style({FontStyle::bold});

  std::cout << display << std::endl;
  return 0;
}

