// Initialize the display with default settings
void DspCore::initDisplay() {
  initR(DTYPE);
  if(DEF_SPI_FREQ > 0) setSPISpeed(DEF_SPI_FREQ);
  cp437(true);
  invert();
  flip();
  setTextWrap(false);
}

// Clear the screen with either black or background color
void DspCore::clearDsp(bool black){ fillScreen(black?0:config.theme.background); }

// Set screen rotation based on configuration
void DspCore::flip(){ 
  if(ROTATE_90) 
    setRotation(config.store.flipscreen?2:0); 
  else 
    setRotation(config.store.flipscreen?3:1); 
}

// Invert display colors conditionally based on display type
void DspCore::invert(){
  invertDisplay((DTYPE==INITR_MINI160x80)?!config.store.invertdisplay:config.store.invertdisplay);
}

// Put display into sleep mode
void DspCore::sleep(void){
  enableSleep(true); 
  delay(150); 
  enableDisplay(false); 
  delay(150); 
}

// Wake up display from sleep mode
void DspCore::wake(void){
  enableDisplay(true); 
  delay(150); 
  enableSleep(false); 
  delay(150); 
}
