#include "client.h"
#include "server.h"
#include <csignal>
#include <thread>

// Signal handler to gracefully stop client and server on Ctrl+C
void signal_handler(int signum) {
    (void)signum; // Suppress unused parameter warning
    StopClient();
    StopServer();
}

int main() {
    signal(SIGINT, signal_handler);

    {
        std::thread server_thread(RunServer);
        std::thread client_thread(RunClient);

        client_thread.join();
        server_thread.join();
    }

    return 0;
}

