void SMessagingDebuggerToolbar::Construct(const FArguments& InArgs, const TSharedRef<ISlateStyle>& InStyle, const TSharedRef<FUICommandList>& InCommandList)
{
	ChildSlot
	[
		BuildToolbar(InCommandList)
	];
}

TSharedRef<SWidget> SMessagingDebuggerToolbar::BuildToolbar(const TSharedRef<FUICommandList>& CommandList)
{
	FToolBarBuilder ToolbarBuilder(CommandList, FMultiBoxCustomization::None);
	ToolbarBuilder.BeginSection("MessagingDebugger");
	{
		ToolbarBuilder.AddToolBarButton(FMessagingDebuggerCommands::Get().StartDebugger, NAME_None, LOCTEXT("LaunchDebugger", "Start"));
		ToolbarBuilder.AddToolBarButton(FMessagingDebuggerCommands::Get().ContinueDebugger, NAME_None, LOCTEXT("ResumeDebugger", "Continue"));
		ToolbarBuilder.AddToolBarButton(FMessagingDebuggerCommands::Get().StepDebugger, NAME_None, LOCTEXT("StepForward", "Step"));
		ToolbarBuilder.AddToolBarButton(FMessagingDebuggerCommands::Get().BreakDebugger, NAME_None, LOCTEXT("PauseAtNext", "Break"));
		ToolbarBuilder.AddToolBarButton(FMessagingDebuggerCommands::Get().StopDebugger, NAME_None, LOCTEXT("TerminateSession", "Stop"));
		ToolbarBuilder.AddSeparator();
		ToolbarBuilder.AddToolBarButton(FMessagingDebuggerCommands::Get().ClearHistory, NAME_None, LOCTEXT("PurgeMessages", "Clear History"));
	}
	return ToolbarBuilder.MakeWidget();
}

