int main(int argc, const char* argv[]) {
    Y_THROW_UNLESS(argc == 2);

    auto binary = Y_LLVM_RAISE(llvm::object::ObjectFile::createObjectFile(argv[1]));

    NPerforator::NThreadLocal::TTlsParser tlsParser{binary->getBinary()};

    tlsParser.VisitVariables([](auto&& symbol) {
        Cerr 
