TEST(TScopedEnvironment, SingleValue) {
    auto initial = GetEnv("ARCADIA_SOURCE_ROOT");
    {
        NTesting::TScopedEnvironment environmentGuard("ARCADIA_SOURCE_ROOT", "source");
        EXPECT_EQ("source", GetEnv("ARCADIA_SOURCE_ROOT"));
    }
    EXPECT_EQ(initial, GetEnv("ARCADIA_SOURCE_ROOT"));
}

TEST(TScopedEnvironment, MultiValue) {
    TVector<TString> initialValues{GetEnv("ARCADIA_SOURCE_ROOT"), GetEnv("ARCADIA_BUILD_ROOT")};
    {
        NTesting::TScopedEnvironment environmentGuard{{
            {"ARCADIA_SOURCE_ROOT", "source"},
            {"ARCADIA_BUILD_ROOT", "build"},
