        EXPECT_EQ("build", GetEnv("ARCADIA_BUILD_ROOT"));
    }
    TVector<TString> finalValues{GetEnv("ARCADIA_SOURCE_ROOT"), GetEnv("ARCADIA_BUILD_ROOT")};
