#include <boost/bind.hpp>

namespace http {
namespace server {

void connection_manager::init(connection_ptr conn)
{
  active_connections_.insert(conn);
  conn->init();
}

void connection_manager::terminate(connection_ptr conn)
{
  active_connections_.erase(conn);
  conn->terminate();
}

void connection_manager::terminate_all()
{
  std::for_each(active_connections_.begin(), active_connections_.end(),
      boost::bind(&connection::terminate, _1));
  active_connections_.clear();
}

