    CHECK(!terraces::is_root(non_root));
}

TEST_CASE("is_leaf(leaf_node)", "[trees]") {
    auto leaf = terraces::node{0, none, none, none};
    CHECK(terraces::is_leaf(leaf));
}

TEST_CASE("is_leaf(non_leaf_node)", "[trees]") {
