    CHECK(!terraces::is_leaf(non_leaf));
}

TEST_CASE("is_rooted_tree(valid_tree)", "[trees]") {
    tree t{
        {none, 1, 2, none},    {0, 9, 6, none},       {0, 3, 4, none},
        {2, 5, 8, none},       {2, none, none, none}, {3, none, none, none},
        {1, none, none, none}, {9, none, none, none}, {3, none, none, none},
        {1, 10, 7, none},      {9, none, none, none},
    };
    check_rooted_tree(t);
}

TEST_CASE("foreach_postorder(tree_example)", "[trees]") {
    tree t{
        {none, 1, 2, none},    {0, 9, 6, none},       {0, 3, 4, none},
        {2, 5, 8, none},       {2, none, none, none}, {3, none, none, none},
        {1, none, none, none}, {9, none, none, none}, {3, none, none, none},
        {1, 10, 7, none},      {9, none, none, none},
    };
    std::vector<index> expected_order{10, 7, 9, 6, 1, 5, 8, 3, 4, 2, 0};
    std::vector<index> traversal_result;
    foreach_postorder(t, [&](index idx) { traversal_result.push_back(idx); });
    CHECK(traversal_result == expected_order);
}

TEST_CASE("foreach_preorder(tree_example)", "[trees]") {
    tree t{
        {none, 1, 2, none},    {0, 9, 6, none},       {0, 3, 4, none},
        {2, 5, 8, none},       {2, none, none, none}, {3, none, none, none},
        {1, none, none, none}, {9, none, none, none}, {3, none, none, none},
        {1, 10, 7, none},      {9, none, none, none},
    };
    std::vector<index> expected_sequence{0, 1, 9, 10, 7, 6, 2, 3, 5, 8, 4};
    std::vector<index> collected_nodes;
    foreach_preorder(t, [&](index idx) { collected_nodes.push_back(idx); });
    CHECK(collected_nodes == expected_sequence);
}

TEST_CASE("foreach_postorder(single_node)", "[trees]") {
    tree t{{}};
    std::vector<index> postorder_result;
    foreach_postorder(t, [&](index idx) { postorder_result.push_back(idx); });
    CHECK(postorder_result.size() == 1);
    CHECK(postorder_result[0] == 0);
}

TEST_CASE("foreach_preorder(single_node)", "[trees]") {
    tree t{{}};
    std::vector<index> preorder_result;
    foreach_preorder(t, [&](index idx) { preorder_result.push_back(idx); });
    CHECK(preorder_result.size() == 1);
    CHECK(preorder_result[0] == 0);
}

TEST_CASE("tree_printing(newick_format)", "[trees][tree-printing]") {
    auto t = tree{{none, 1, 2, none},
                  {0, none, none, 1},
                  {0, 3, 4, none},
                  {2, none, none, 3},
                  {2, none, none, 4}};
    const auto labels = name_map{"root", "foo", "", "bar", "baz"};
    std::ostringstream output_stream;
    output_stream << as_newick(t, labels);
    CHECK(output_stream.str() == "(foo,(bar,baz));");
}

