TEST_CASE("TrainingRunLogger::log_sol_estimate handles unsupported dtypes gracefully") {
    TrainingRunLogger logger("test-sol-logger.json", /*rank=*/0, TrainingRunLogger::SILENT);
    // ETensorDType::BYTE is not supported by the SOL estimator.
    // The logging function must handle this without crashing or causing division-by-zero errors.
    std::vector<std::pair<ETensorDType, long>> operations = {
        {ETensorDType::BYTE, 1},
