  prevent_optimization(&hardware[0]);

  // Print all device IDs
  for (unsigned index = 0; index < 4; ++index) {
    printf("id=%d\n", hardware[index].device_id);
  }

  int value = nd_int();
  __CRAB_assume(value >= 0);
  __CRAB_assume(value < 4);
  __CRAB_assert(hardware[value].device_id >= 0);
