// Memory requirements for the test:
// - For async_scan: must exceed max_key * n_partitions * value_sz * n_tables
// - For syn_scan: must exceed max_key * value_sz * n_tables
// - General case: should be greater than n_partitions * (keys_per_batch + num_readers_per_partition) * value_sz * n_tables
// Note: Larger memory reduces time cost but increases resource usage.
// Approximate data size stored during testing:
//   n_partitions * max_key * (12B + value_sz) * n_tables
// Expected number of modifications per key:
//   keys_per_batch * ops_per_partition / (max_key - active_width)
// Expected number of verifications per key:
//   max_verify_ops_per_write * ops_per_partition / (max_key - active_width)
// Recommended settings:
//   max_verify_ops_per_write >= keys_per_batch
//   keys_per_batch <= active_width / 5 (to reduce random key generation overhead)
//   num_readers_per_partition <= max_verify_ops_per_write

// Configuration file path
DEFINE_string(options, "", "Path to configuration INI file");
// Database storage location
DEFINE_string(db_path, "data/stress_test", "Directory path for database files");
// Shared state directory for coordination
DEFINE_string(shared_state_path,
              "data/db_stress_helper",
              "Directory path for shared stress-test state information");

// Number of tables/threads used in the test
DEFINE_uint32(n_tables, 10, "Number of concurrent threads or tables");
// Number of partitions across which data is distributed
DEFINE_uint32(n_partitions, 10, "Number of partitions in the database");

// Operations per partition (large default to ensure long-running tests)
DEFINE_uint64(ops_per_partition,
              300000000000000,
              "Number of batch write operations per partition");

// Crash simulation probability: 1 out of this many killpoints triggers a crash
DEFINE_uint32(kill_odds, 0, "Crash probability: 1 in this many killpoints");

// Total number of client threads handling requests
DEFINE_uint32(num_client_threads, 1, "Total number of client threads");

// Maximum key value allowed in the system
DEFINE_int64(max_key, 10000, "Upper bound for key values");

// Size of the active working set range
DEFINE_int64(active_width, 10000, "Width of the active key range");

// Hot-key distribution parameter (Zipfian alpha); higher means more skew
DEFINE_double(hot_key_alpha, 0, "Zipfian skew factor for hot keys (recommend [0.8, 1.5])");

// Random seed for reproducibility
DEFINE_uint64(seed, 2341234, "Seed for random number generation");

// Percentage of write (upsert) operations vs delete
DEFINE_uint32(write_percent, 75, "Percentage of upsert operations in write/delete mix");

// Number of keys to check in floor scan operations
DEFINE_uint32(floor_size, 2, "Number of keys examined in floor request tests");

// Ratio of floor reads among all scan read operations
DEFINE_uint32(floor_read_percent,
              50,
              "Percentage of floor reads within scan read operations (e.g., 50% means floor reads are half of scans)");

// Percentage of point reads among point_read/scan_read operations
DEFINE_uint32(point_read_percent,
              25,
              "Percentage of point reads in point_read/scan_read mix");

// Enable batched operation stress testing
DEFINE_bool(test_batched_ops_stress, false, "Enable stress testing of batched operations");

// Number of reader threads per partition
DEFINE_uint32(num_readers_per_partition,
              10,
              "Number of reader threads assigned to each partition (minimum 1)");

// Maximum verification operations triggered after each write
DEFINE_uint32(max_verify_ops_per_write, 15, "Maximum verification operations per write");

// Keys written per batch; 0 means randomly choose between 100 and 500
DEFINE_uint32(keys_per_batch,
              2000,
              "Keys per write batch (0 = random in [100,500]; must be < active_width)");

// Use file-based storage and verification (required for crash-resilience tests)
