#include "datetime.h"
#include <library/cpp/testing/unittest/registar.h>
#include <util/string/builder.h>

Y_UNIT_TEST_SUITE(TSimpleTMTest) {
    TString GenerateLabel(const TString& testName, int lineNumber) {
        return TStringBuilder() << "test case " << testName << " at line " << lineNumber;
    }

    TString AppendTimestamp(const TString& label, time_t timestamp) {
        return TStringBuilder() << label << " (timestamp=" << timestamp << ")";
    }

    TString GenerateLabel(const TString& testName, int lineNumber, time_t timestamp) {
        return AppendTimestamp(GenerateLabel(testName, lineNumber), timestamp);
    }

    void VerifyTmStructure(const TString& context, const struct tm& reference, const NDatetime::TSimpleTM& testValue) {
        UNIT_ASSERT_VALUES_EQUAL_C((int)testValue.Sec, reference.tm_sec, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testValue.Min, reference.tm_min, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testValue.Hour, reference.tm_hour, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testValue.WDay, reference.tm_wday, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testValue.MDay, reference.tm_mday, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testValue.Mon, reference.tm_mon, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testValue.YDay, reference.tm_yday, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testValue.Year, reference.tm_year, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testValue.IsDst, reference.tm_isdst, context);
#ifndef _win_
        UNIT_ASSERT_VALUES_EQUAL_C((int)testValue.GMTOff, reference.tm_gmtoff, context);
#endif
    }

    void ValidateSimpleTM(const TString& label,
                          const NDatetime::TSimpleTM& testObj,
                          time_t expectedTime, ui32 expectedYear, ui32 expectedMonth, ui32 expectedDay,
                          ui32 expectedHour, ui32 expectedMinute, ui32 expectedSecond) {
        TString context = AppendTimestamp(label, expectedTime);
        struct tm referenceTm;
        Zero(referenceTm);
        GmTimeR(&expectedTime, &referenceTm);
        VerifyTmStructure(context, referenceTm, testObj);

        referenceTm = testObj.AsStructTmUTC();
        time_t reconstructedTime = TimeGM(&referenceTm);
        UNIT_ASSERT_VALUES_EQUAL_C(expectedTime, reconstructedTime, context);
        UNIT_ASSERT_VALUES_EQUAL_C(expectedTime, testObj.AsTimeT(), context);

        UNIT_ASSERT_VALUES_EQUAL_C((int)testObj.RealYear(), expectedYear, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testObj.RealMonth(), expectedMonth, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testObj.MDay, expectedDay, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testObj.Hour, expectedHour, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testObj.Min, expectedMinute, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)testObj.Sec, expectedSecond, context);
    }

    Y_UNIT_TEST(TestLeapYearFunctionality) {
        using namespace NDatetime;
        UNIT_ASSERT(LeapYearAD(2000));
        UNIT_ASSERT(LeapYearAD(2012));
        UNIT_ASSERT(!LeapYearAD(1999));
        UNIT_ASSERT(LeapYearAD(2004));
        UNIT_ASSERT(!LeapYearAD(1900));
    }

    Y_UNIT_TEST(TestDayOfYearConversion) {
        using namespace NDatetime;
        ui32 monthIndex;
        ui32 dayOfMonth;

        for (ui32 dayOfYear = 0; dayOfYear < 365; ++dayOfYear) {
            YDayToMonthAndDay(dayOfYear, false, &monthIndex, &dayOfMonth);
            UNIT_ASSERT_VALUES_EQUAL(dayOfYear, YDayFromMonthAndDay(monthIndex, dayOfMonth, false));
        }

        for (ui32 dayOfYear = 0; dayOfYear < 366; ++dayOfYear) {
            YDayToMonthAndDay(dayOfYear, true, &monthIndex, &dayOfMonth);
            UNIT_ASSERT_VALUES_EQUAL(dayOfYear, YDayFromMonthAndDay(monthIndex, dayOfMonth, true));
        }

        UNIT_ASSERT_EXCEPTION(YDayToMonthAndDay(365, false, &monthIndex, &dayOfMonth), yexception);
        UNIT_ASSERT_EXCEPTION(YDayToMonthAndDay(366, true, &monthIndex, &dayOfMonth), yexception);
    }

    Y_UNIT_TEST(SimpleTMFunctionalityTests) {
        using namespace NDatetime;
        tzset();

        TSimpleTM::New(-1); // Ensure no crash occurs

        UNIT_ASSERT_VALUES_EQUAL((ui32)0, (ui32)TSimpleTM::New(0));
        UNIT_ASSERT((ui32)TSimpleTM::New(0).IsUTC());

        time_t currentTime = time(nullptr);

        // UTC tests
        {
            struct tm utcTm;
            Zero(utcTm);
            gmtime_r(&currentTime, &utcTm);

            UNIT_ASSERT_VALUES_EQUAL_C((i64)currentTime, (i64)TSimpleTM::New(currentTime).AsTimeT(), ToString(currentTime));
            UNIT_ASSERT_VALUES_EQUAL_C((i64)currentTime, (i64)TSimpleTM::New(utcTm).AsTimeT(), ToString(currentTime));

            VerifyTmStructure(GenerateLabel("UTC:from_time_t", __LINE__, currentTime),
                              utcTm, TSimpleTM::New(currentTime));
            VerifyTmStructure(GenerateLabel("UTC:from_tm", __LINE__, currentTime),
                              utcTm, TSimpleTM::New(utcTm));

            UNIT_ASSERT(TSimpleTM::New(currentTime).IsUTC());
            UNIT_ASSERT(TSimpleTM::New(utcTm).IsUTC());
        }

        // Local time tests
        {
            struct tm localTm;
            Zero(localTm);
            localtime_r(&currentTime, &localTm);

            UNIT_ASSERT_VALUES_EQUAL((i64)currentTime, (i64)TSimpleTM::NewLocal(currentTime).AsTimeT());
            UNIT_ASSERT_VALUES_EQUAL((i64)currentTime, (i64)TSimpleTM::New(localTm).AsTimeT());

            VerifyTmStructure(GenerateLabel("local:from_time_t", __LINE__, currentTime),
                              localTm, TSimpleTM::NewLocal(currentTime));
            VerifyTmStructure(GenerateLabel("local:from_tm", __LINE__, currentTime),
                              localTm, TSimpleTM::New(localTm));
            VerifyTmStructure(GenerateLabel("local:regenerated_fields", __LINE__, currentTime),
                              localTm, TSimpleTM::New(localTm).RegenerateFields());
            VerifyTmStructure(GenerateLabel("local:set_real_date", __LINE__, currentTime),
                              localTm, TSimpleTM::NewLocal(currentTime).SetRealDate(
                                  localTm.tm_year + 1900,
                                  localTm.tm_mon + 1,
                                  localTm.tm_mday,
                                  localTm.tm_hour,
                                  localTm.tm_min,
                                  localTm.tm_sec,
                                  localTm.tm_isdst));
        }

        // Date arithmetic and manipulation tests
        {
            TSimpleTM dt = TSimpleTM::New(0);

            dt.SetRealDate(2012, 3, 30, 5, 6, 7);
            ValidateSimpleTM(GenerateLabel("UTC:set_date_1", __LINE__),
                             dt, 1333083967, 2012, 3, 30, 5, 6, 7);

            dt.SetRealDate(2012, 3, 8, 5, 6, 7);
            ValidateSimpleTM(GenerateLabel("UTC:set_date_2", __LINE__),
                             dt, 1331183167, 2012, 3, 8, 5, 6, 7);

            dt.SetRealDate(2010, 10, 4, 5, 6, 7);
            ValidateSimpleTM(GenerateLabel("UTC:set_date_3", __LINE__),
                             dt, 1286168767, 2010, 10, 4, 5, 6, 7);

            dt.Add(TSimpleTM::F_MON);
            ValidateSimpleTM(GenerateLabel("UTC:add_month", __LINE__),
                             dt, 1288847167, 2010, 11, 4, 5, 6, 7);

            dt.Add(TSimpleTM::F_DAY);
            ValidateSimpleTM(GenerateLabel("UTC:add_day", __LINE__),
                             dt, 1288933567, 2010, 11, 5, 5, 6, 7);

            dt.Add(TSimpleTM::F_YEAR);
            ValidateSimpleTM(GenerateLabel("UTC:add_year", __LINE__),
                             dt, 1320469567, 2011, 11, 5, 5, 6, 7);

            for (ui32 i = 0; i < 365; ++i) {
                dt.Add(TSimpleTM::F_DAY);
            }
            ValidateSimpleTM(GenerateLabel("UTC:365_days_addition", __LINE__),
                             dt, 1352005567, 2012, 11, 4, 5, 6, 7);

            dt.Add(TSimpleTM::F_MON, -10);
            ValidateSimpleTM(GenerateLabel("UTC:subtract_months", __LINE__),
                             dt, 1325653567, 2012, 1, 4, 5, 6, 7);

            dt.Add(TSimpleTM::F_HOUR, -24 * 4 - 6);
            ValidateSimpleTM(GenerateLabel("UTC:subtract_hours", __LINE__),
                             dt, 1325286367, 2011, 12, 30, 23, 6, 7);
        }

        // Leap year and various date validation tests
        {
            TSimpleTM dt = TSimpleTM::New();

            dt.SetRealDate(2012, 2, 29);
            ValidateSimpleTM(GenerateLabel("UTC:leap_day", __LINE__),
                             dt, 1330473600, 2012, 2, 29, 0, 0, 0);

            dt.SetRealDate(2013, 12, 28);
            ValidateSimpleTM(GenerateLabel("UTC:end_of_year", __LINE__),
                             dt, 1388188800, 2013, 12, 28, 0, 0, 0);

            dt.SetRealDate(2012, 10, 23);
            ValidateSimpleTM(GenerateLabel("UTC:october_date", __LINE__),
                             dt, 1350950400, 2012, 10, 23, 0, 0, 0);

            dt.SetRealDate(2013, 3, 16);
            ValidateSimpleTM(GenerateLabel("UTC:spring_date", __LINE__),
                             dt, 1363392000, 2013, 3, 16, 0, 0, 0);

            dt.SetRealDate(2013, 2, 17);
            ValidateSimpleTM(GenerateLabel("UTC:february_date", __LINE__),
                             dt, 1361059200, 2013, 2, 17, 0, 0, 0);

            dt.SetRealDate(2012, 12, 23);
            ValidateSimpleTM(GenerateLabel("UTC:christmas_eve", __LINE__),
                             dt, 1356220800, 2012, 12, 23, 0, 0, 0);

            dt.SetRealDate(2012, 5, 17);
            ValidateSimpleTM(GenerateLabel("UTC:may_date", __LINE__),
                             dt, 1337212800, 2012, 5, 17, 0, 0, 0);

            dt.SetRealDate(2012, 6, 15);
            ValidateSimpleTM(GenerateLabel("UTC:june_date", __LINE__),
                             dt, 1339718400, 2012, 6, 15, 0, 0, 0);

            dt.SetRealDate(2009, 3, 17);
            ValidateSimpleTM(GenerateLabel("UTC:march_2009", __LINE__),
                             dt, 1237248000, 2009, 3, 17, 0, 0, 0);

            dt.SetRealDate(2013, 8, 12);
            ValidateSimpleTM(GenerateLabel("UTC:august_2013", __LINE__),
                             dt, 1376265600, 2013, 8, 12, 0, 0, 0);

            dt.SetRealDate(2015, 12, 11, 10, 9, 8);
            ValidateSimpleTM(GenerateLabel("UTC:specific_timestamp", __LINE__),
                             dt, 1449828548, 2015, 12, 11, 10, 9, 8);
        }
    }
} // Y_UNIT_TEST_SUITE(TSimpleTMTest)

#include <iostream>
#include <string>
#include <vector>
#include "../include/parser.h"
#include <cassert>

// Evaluate integer arithmetic expressions
void evaluate_integer_ops(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, std::string>> test_cases = {
        {"42", "42"},
        {"-15", "-15"},
        {"(+ 10 20)", "30"},
        {"(- 50 30)", "20"},
        {"(* 6 7)", "42"},
        {"(div 20 5)", "4"},
        {"(mod 17 5)", "2"},
        {"(abs -42)", "42"}
    };

    std::cout << "=== Integer Arithmetic Evaluation ===" << std::endl;
    for (const auto& entry : test_cases) {
        std::cout << "Input: " << entry.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> output = parser->mkExpr(entry.first);
        assert(output);
        std::string actual = parser->toString(output);
        std::cout << "  Output: " << actual << std::endl;
        assert(actual == entry.second && "integer result mismatch");
        std::cout << std::endl;
    }
}

// Evaluate real number arithmetic expressions
void evaluate_real_ops(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, std::string>> test_cases = {
        {"3.14159", "3.14159"},
        {"-2.71828", "-2.71828"},
        {"(+ 3.5 2.7)", "6.2"},
        {"(- 10.5 4.2)", "6.3"},
        {"(* 2.5 4.0)", "10"},
        {"(/ 15.0 3.0)", "5"},
        {"(^ 2.0 3.0)", "8"},
        {"(sqrt 16.0)", "4"},
        {"(abs -9.81)", "9.81"}
    };

    std::cout << "=== Real Number Arithmetic Evaluation ===" << std::endl;
    for (const auto& entry : test_cases) {
        std::cout << "Input: " << entry.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> output = parser->mkExpr(entry.first);
        assert(output);
        std::string actual = parser->toString(output);
        std::cout << "  Output: " << actual << std::endl;
        assert(actual == entry.second && "real arithmetic result mismatch");
        std::cout << std::endl;
    }
}

// Evaluate comparison operations
void evaluate_comparison_ops(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> test_cases = {
        {"(< 5 10)", true},
        {"(<= 7 7)", true},
        {"(> 15 5)", true},
        {"(>= 12 12)", true},
        {"(= 42 42)", true},
        {"(distinct 3 5 7)", true}
    };

    std::cout << "=== Comparison Operations Evaluation ===" << std::endl;
    for (const auto& entry : test_cases) {
        std::cout << "Input: " << entry.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> output = parser->mkExpr(entry.first);
        assert(output);
        std::cout << "  Output: " << parser->toString(output) << std::endl;
        assert(output->isTrue() == entry.second && "comparison result mismatch");
        std::cout << std::endl;
    }
}

// Test precision handling in arithmetic
void evaluate_precision(SMTParser::ParserPtr& parser) {
    std::cout << "=== Precision Handling Tests ===" << std::endl;

    // Default precision (128 bits)
    std::cout << "=== Using Default Precision (128 bits) ===" << std::endl;
    auto res1 = parser->mkExpr("(+ 3.5 2.7)");
    auto res2 = parser->mkExpr("(- 10.5 4.2)");
    assert(res1 && res2);
    std::cout << "Expression: (+ 3.5 2.7)" << std::endl;
    std::cout << "  Result: " << parser->toString(res1) << std::endl;
    assert(parser->toString(res1) == "6.2");
    std::cout << "Expression: (- 10.5 4.2)" << std::endl;
    std::cout << "  Result: " << parser->toString(res2) << std::endl;
    assert(parser->toString(res2) == "6.3");

    // Higher precision (256 bits)
    parser->setEvaluatePrecision(256);
    std::cout << "\n=== Using Higher Precision (256 bits) ===" << std::endl;
    auto res3 = parser->mkExpr("(+ 3.5 2.7)");
    auto res4 = parser->mkExpr("(- 10.5 4.2)");
    assert(res3 && res4);
    std::cout << "Expression: (+ 3.5 2.7)" << std::endl;
    std::cout << "  Result: " << parser->toString(res3) << std::endl;
    std::cout << "Expression: (- 10.5 4.2)" << std::endl;
    std::cout << "  Result: " << parser->toString(res4) << std::endl;
    assert(parser->toString(res3) == "6.2" && parser->toString(res4) == "6.3");

    // Disable floating point mode
    parser->setEvaluateUseFloating(false);
    std::cout << "\n=== Floating Point Mode Disabled ===" << std::endl;
    auto res5 = parser->mkExpr("(+ 3.5 2.7)");
    auto res6 = parser->mkExpr("(- 10.5 4.2)");
    assert(res5 && res6);
    std::cout << "Expression: (+ 3.5 2.7)" << std::endl;
    std::cout << "  Result: " << parser->toString(res5) << std::endl;
    std::cout << "Expression: (- 10.5 4.2)" << std::endl;
    std::cout << "  Result: " << parser->toString(res6) << std::endl;
    assert(parser->toString(res5) == "6.2" && parser->toString(res6) == "6.3");
}

int main() {
    std::cout << "======= Arithmetic Operations Test Suite =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    evaluate_integer_ops(parser);
    evaluate_real_ops(parser);
    evaluate_comparison_ops(parser);
    evaluate_precision(parser);

    return 0;
}

#include "src_location.h"
#include <util/stream/output.h>
template <>
void Out<TSourceLocation>(IOutputStream& stream, const TSourceLocation& loc) {
#if defined(_win_)
    TString path(loc.File);
    std::replace(path.begin(), path.end(), '\\', '/');
    stream << path;
#else
    stream << loc.File;
#endif
    stream << ':' << loc.Line;
}

#include <iostream>
