using namespace std;

class MedianCalculator {
public:
    vector<double> computeRunningMedians(vector<int> inputArray) {
        vector<double> result;
        priority_queue<int> maxHeap; // for smaller half
        priority_queue<int, vector<int>, greater<int>> minHeap; // for larger half

        for (int num : inputArray) {
            if (maxHeap.empty() || num <= maxHeap.top()) {
                maxHeap.push(num);
            } else {
                minHeap.push(num);
            }

            // Balance the heaps
            if (maxHeap.size() > minHeap.size() + 1) {
                minHeap.push(maxHeap.top());
                maxHeap.pop();
            } else if (minHeap.size() > maxHeap.size()) {
                maxHeap.push(minHeap.top());
                minHeap.pop();
            }

            // Calculate median
            double median;
            if (maxHeap.size() == minHeap.size()) {
                median = (maxHeap.top() + minHeap.top()) / 2.0;
            } else {
                median = maxHeap.top();
            }
            result.push_back(median);
        }

        return result;
    }
};

int main() {
    MedianCalculator calculator;
    vector<int> testArray = {5, 2, 8, 1, 9};
    vector<double> medians = calculator.computeRunningMedians(testArray);

    for (double m : medians) {
        cout << m << " ";
    }
    cout << endl;

    return 0;
}

