void CleanupFunctions::registerFunction(
  std::unique_ptr<CleanupFunctions::CleanupFunction> func) {
  std::lock_guard<std::mutex> guard{gFunctionsMutex};
  gCleanupFunctions.push_back(std::move(func));
}

void CleanupFunctions::run(int exitCode, void* userData) {
  std::lock_guard<std::mutex> guard{gFunctionsMutex};
