// Test for filling publisher attributes with various QoS settings
TEST(AttributesFillerTest, fill_in_pub_attr_test) {
  QosProfile qos;
  AttributesFiller filler;
  eprosima::fastrtps::PublisherAttributes pub_attrs;

  // First configuration: KEEP_LAST, TRANSIENT_LOCAL, BEST_EFFORT
  qos.set_history(QosHistoryPolicy::HISTORY_KEEP_LAST);
  qos.set_durability(QosDurabilityPolicy::DURABILITY_TRANSIENT_LOCAL);
  qos.set_reliability(QosReliabilityPolicy::RELIABILITY_BEST_EFFORT);
  qos.set_mps(32);
  filler.FillInPubAttr("channel", qos, &pub_attrs);

  EXPECT_EQ(eprosima::fastrtps::KEEP_LAST_HISTORY_QOS, pub_attrs.topic.historyQos.kind);
  EXPECT_EQ(eprosima::fastrtps::TRANSIENT_LOCAL_DURABILITY_QOS, pub_attrs.qos.m_durability.kind);
  EXPECT_EQ(eprosima::fastrtps::BEST_EFFORT_RELIABILITY_QOS, pub_attrs.qos.m_reliability.kind);
  AINFO << "heartbeat period: " << pub_attrs.times.heartbeatPeriod.seconds << ", "
        << pub_attrs.times.heartbeatPeriod.fraction();

  // Second configuration: set depth and verify override behavior
  qos.set_depth(1024);
  pub_attrs.topic.historyQos.depth = 512;
  filler.FillInPubAttr("channel", qos, &pub_attrs);
  AINFO << qos.depth() << ", " << QosProfileConf::QOS_HISTORY_DEPTH_SYSTEM_DEFAULT << ", "
        << pub_attrs.topic.historyQos.depth;
  EXPECT_EQ(qos.depth(), pub_attrs.topic.historyQos.depth);

  // Third configuration: KEEP_ALL, VOLATILE, RELIABLE
  qos.set_history(QosHistoryPolicy::HISTORY_KEEP_ALL);
  qos.set_durability(QosDurabilityPolicy::DURABILITY_VOLATILE);
  qos.set_reliability(QosReliabilityPolicy::RELIABILITY_RELIABLE);
  qos.set_mps(65);
  filler.FillInPubAttr("channel", qos, &pub_attrs);
  EXPECT_EQ(eprosima::fastrtps::KEEP_ALL_HISTORY_QOS, pub_attrs.topic.historyQos.kind);
  EXPECT_EQ(eprosima::fastrtps::VOLATILE_DURABILITY_QOS, pub_attrs.qos.m_durability.kind);
  EXPECT_EQ(eprosima::fastrtps::RELIABLE_RELIABILITY_QOS, pub_attrs.qos.m_reliability.kind);
  AINFO << "heartbeat period: " << pub_attrs.times.heartbeatPeriod.seconds << ", "
        << pub_attrs.times.heartbeatPeriod.fraction();

  // Fourth configuration: SYSTEM_DEFAULT policies
  qos.set_history(QosHistoryPolicy::HISTORY_SYSTEM_DEFAULT);
  qos.set_durability(QosDurabilityPolicy::DURABILITY_SYSTEM_DEFAULT);
  qos.set_reliability(QosReliabilityPolicy::RELIABILITY_SYSTEM_DEFAULT);
  qos.set_mps(1025);
  filler.FillInPubAttr("channel", qos, &pub_attrs);
  EXPECT_EQ(eprosima::fastrtps::KEEP_ALL_HISTORY_QOS, pub_attrs.topic.historyQos.kind);
  EXPECT_EQ(eprosima::fastrtps::VOLATILE_DURABILITY_QOS, pub_attrs.qos.m_durability.kind);
  EXPECT_EQ(eprosima::fastrtps::RELIABLE_RELIABILITY_QOS, pub_attrs.qos.m_reliability.kind);
  AINFO << "heartbeat period: " << pub_attrs.times.heartbeatPeriod.seconds << ", "
        << pub_attrs.times.heartbeatPeriod.fraction();

  // Fifth configuration: zero MPS
  qos.set_mps(0);
  filler.FillInPubAttr("channel", qos, &pub_attrs);
  AINFO << "heartbeat period: " << pub_attrs.times.heartbeatPeriod.seconds << ", "
        << pub_attrs.times.heartbeatPeriod.fraction();
}

