// Comprehensive test for UnderlayMessage functionality
TEST(UnderlayMessageTest, underlay_message_test) {
  UnderlayMessage msg;

  // Test timestamp manipulation
  msg.timestamp(1024);
  int32_t& ts_ref = msg.timestamp();
  ts_ref = 256;
  EXPECT_EQ(256, msg.timestamp());

  // Test sequence number manipulation
  msg.seq(1024);
  int32_t& seq_ref = msg.seq();
  seq_ref = 256;
  EXPECT_EQ(256, msg.seq());

  // Test data string manipulation
  msg.data("data");
  std::string& data_ref = msg.data();
  data_ref = "data string";
  EXPECT_EQ(data_ref, msg.data());

  // Test move semantics for data
  msg.data(std::forward<std::string>("data forward"));
  EXPECT_EQ("data forward", msg.data());

  // Test datatype string manipulation
  msg.datatype("datatype");
  std::string& dtype_ref = msg.datatype();
  dtype_ref = "datatype string";
  EXPECT_EQ(dtype_ref, msg.datatype());

  // Test assignment for datatype
  msg.datatype("datatype assign");
  EXPECT_EQ("datatype assign", msg.datatype());

  // Test move semantics for datatype
  msg.datatype(std::forward<std::string>("datatype forward"));
  EXPECT_EQ("datatype forward", msg.datatype());

  // Test const accessors
  const UnderlayMessage const_msg(msg);
  std::string data_val = const_msg.data();
  std::string datatype_val = const_msg.datatype();
  EXPECT_EQ(256, const_msg.timestamp());
  EXPECT_EQ(256, const_msg.seq());
  EXPECT_EQ("data forward", const_msg.data());
  EXPECT_EQ("datatype forward", const_msg.datatype());

  // Test copy assignment
  UnderlayMessage msg_copy;
  msg_copy = msg;
  EXPECT_EQ(256, msg_copy.timestamp());
  EXPECT_EQ(256, msg_copy.seq());
  EXPECT_EQ("data forward", msg_copy.data());
  EXPECT_EQ("datatype forward", msg_copy.datatype());

  // Test move assignment
  UnderlayMessage msg_move;
  msg_move = std::forward<UnderlayMessage>(msg_copy);
  EXPECT_EQ(256, msg_move.timestamp());
  EXPECT_EQ(256, msg_move.seq());
  EXPECT_EQ("data forward", msg_move.data());
  EXPECT_EQ("datatype forward", msg_move.datatype());

  // Test copy constructor
  UnderlayMessage msg_constructed(msg_move);
  EXPECT_EQ(256, msg_constructed.timestamp());
  EXPECT_EQ(256, msg_constructed.seq());
  EXPECT_EQ("data forward", msg_constructed.data());
  EXPECT_EQ("datatype forward", msg_constructed.datatype());

  // Test move constructor
  UnderlayMessage msg_moved(std::forward<UnderlayMessage>(msg_constructed));
  EXPECT_EQ(256, msg_moved.timestamp());
  EXPECT_EQ(256, msg_moved.seq());
  EXPECT_EQ("data forward", msg_moved.data());
  EXPECT_EQ("datatype forward", msg_moved.datatype());

  // Verify source objects are moved-from (empty)
  EXPECT_EQ("", msg_constructed.data());
  EXPECT_EQ("", msg_constructed.datatype());
}

