// Implementation based on clibs' sha1: https://github.com/clibs/sha1
#define rotateLeft(val, shift) (((val) << (shift)) | ((val) >> (32 - (shift))))
#define block0(idx) m_workspaceBlock->l[idx]
#define block(idx)                                                                          \
    (m_workspaceBlock->l[idx & 15] =                                                       \
         rotateLeft(m_workspaceBlock->l[idx & 15] ^ m_workspaceBlock->l[(idx + 2) & 15]    \
                        ^ m_workspaceBlock->l[(idx + 8) & 15]                               \
                        ^ m_workspaceBlock->l[(idx + 13) & 15],                             \
                    1))

/* SHA-1 round functions */
#define ROUND0(v, w, x, y, z, idx)                                                          \
    z += ((w & (x ^ y)) ^ y) + block0(idx) + 0x5A827999 + rotateLeft(v, 5);                 \
    w = rotateLeft(w, 30);
#define ROUND1(v, w, x, y, z, idx)                                                          \
    z += ((w & (x ^ y)) ^ y) + block(idx) + 0x5A827999 + rotateLeft(v, 5);                  \
    w = rotateLeft(w, 30);
#define ROUND2(v, w, x, y, z, idx)                                                          \
    z += (w ^ x ^ y) + block(idx) + 0x6ED9EBA1 + rotateLeft(v, 5);                          \
    w = rotateLeft(w, 30);
#define ROUND3(v, w, x, y, z, idx)                                                          \
    z += (((w | x) & y) | (w & x)) + block(idx) + 0x8F1BBCDC + rotateLeft(v, 5);            \
    w = rotateLeft(w, 30);
#define ROUND4(v, w, x, y, z, idx)                                                          \
    z += (w ^ x ^ y) + block(idx) + 0xCA62C1D6 + rotateLeft(v, 5);                          \
    w = rotateLeft(w, 30);

void CSHA1::Transform(unsigned int *stateArray, const unsigned char *inputBuffer) {
    unsigned int regA, regB, regC, regD, regE;
    regA = stateArray[0];
    regB = stateArray[1];
    regC = stateArray[2];
    regD = stateArray[3];
    regE = stateArray[4];

    memcpy(m_workspaceBlock->c, inputBuffer, 64);

    // First 20 rounds
    ROUND0(regA, regB, regC, regD, regE, 0);
    ROUND0(regE, regA, regB, regC, regD, 1);
    ROUND0(regD, regE, regA, regB, regC, 2);
    ROUND0(regC, regD, regE, regA, regB, 3);
    ROUND0(regB, regC, regD, regE, regA, 4);
    ROUND0(regA, regB, regC, regD, regE, 5);
    ROUND0(regE, regA, regB, regC, regD, 6);
    ROUND0(regD, regE, regA, regB, regC, 7);
    ROUND0(regC, regD, regE, regA, regB, 8);
    ROUND0(regB, regC, regD, regE, regA, 9);
    ROUND0(regA, regB, regC, regD, regE, 10);
    ROUND0(regE, regA, regB, regC, regD, 11);
    ROUND0(regD, regE, regA, regB, regC, 12);
    ROUND0(regC, regD, regE, regA, regB, 13);
    ROUND0(regB, regC, regD, regE, regA, 14);
    ROUND0(regA, regB, regC, regD, regE, 15);

    // Rounds 16-19
    ROUND1(regE, regA, regB, regC, regD, 16);
    ROUND1(regD, regE, regA, regB, regC, 17);
    ROUND1(regC, regD, regE, regA, regB, 18);
    ROUND1(regB, regC, regD, regE, regA, 19);

    // Rounds 20-39
    ROUND2(regA, regB, regC, regD, regE, 20);
    ROUND2(regE, regA, regB, regC, regD, 21);
    ROUND2(regD, regE, regA, regB, regC, 22);
    ROUND2(regC, regD, regE, regA, regB, 23);
    ROUND2(regB, regC, regD, regE, regA, 24);
    ROUND2(regA, regB, regC, regD, regE, 25);
    ROUND2(regE, regA, regB, regC, regD, 26);
    ROUND2(regD, regE, regA, regB, regC, 27);
    ROUND2(regC, regD, regE, regA, regB, 28);
    ROUND2(regB, regC, regD, regE, regA, 29);
    ROUND2(regA, regB, regC, regD, regE, 30);
    ROUND2(regE, regA, regB, regC, regD, 31);
    ROUND2(regD, regE, regA, regB, regC, 32);
    ROUND2(regC, regD, regE, regA, regB, 33);
    ROUND2(regB, regC, regD, regE, regA, 34);
    ROUND2(regA, regB, regC, regD, regE, 35);
    ROUND2(regE, regA, regB, regC, regD, 36);
    ROUND2(regD, regE, regA, regB, regC, 37);
    ROUND2(regC, regD, regE, regA, regB, 38);
    ROUND2(regB, regC, regD, regE, regA, 39);

    // Rounds 40-59
    ROUND3(regA, regB, regC, regD, regE, 40);
    ROUND3(regE, regA, regB, regC, regD, 41);
    ROUND3(regD, regE, regA, regB, regC, 42);
    ROUND3(regC, regD, regE, regA, regB, 43);
    ROUND3(regB, regC, regD, regE, regA, 44);
    ROUND3(regA, regB, regC, regD, regE, 45);
    ROUND3(regE, regA, regB, regC, regD, 46);
    ROUND3(regD, regE, regA, regB, regC, 47);
    ROUND3(regC, regD, regE, regA, regB, 48);
    ROUND3(regB, regC, regD, regE, regA, 49);
    ROUND3(regA, regB, regC, regD, regE, 50);
    ROUND3(regE, regA, regB, regC, regD, 51);
    ROUND3(regD, regE, regA, regB, regC, 52);
    ROUND3(regC, regD, regE, regA, regB, 53);
    ROUND3(regB, regC, regD, regE, regA, 54);
    ROUND3(regA, regB, regC, regD, regE, 55);
    ROUND3(regE, regA, regB, regC, regD, 56);
    ROUND3(regD, regE, regA, regB, regC, 57);
    ROUND3(regC, regD, regE, regA, regB, 58);
    ROUND3(regB, regC, regD, regE, regA, 59);

    // Rounds 60-79
    ROUND4(regA, regB, regC, regD, regE, 60);
    ROUND4(regE, regA, regB, regC, regD, 61);
    ROUND4(regD, regE, regA, regB, regC, 62);
    ROUND4(regC, regD, regE, regA, regB, 63);
    ROUND4(regB, regC, regD, regE, regA, 64);
    ROUND4(regA, regB, regC, regD, regE, 65);
    ROUND4(regE, regA, regB, regC, regD, 66);
    ROUND4(regD, regE, regA, regB, regC, 67);
    ROUND4(regC, regD, regE, regA, regB, 68);
    ROUND4(regB, regC, regD, regE, regA, 69);
    ROUND4(regA, regB, regC, regD, regE, 70);
    ROUND4(regE, regA, regB, regC, regD, 71);
    ROUND4(regD, regE, regA, regB, regC, 72);
    ROUND4(regC, regD, regE, regA, regB, 73);
    ROUND4(regB, regC, regD, regE, regA, 74);
    ROUND4(regA, regB, regC, regD, regE, 75);
    ROUND4(regE, regA, regB, regC, regD, 76);
    ROUND4(regD, regE, regA, regB, regC, 77);
    ROUND4(regC, regD, regE, regA, regB, 78);
    ROUND4(regB, regC, regD, regE, regA, 79);

    stateArray[0] += regA;
    stateArray[1] += regB;
    stateArray[2] += regC;
    stateArray[3] += regD;
    stateArray[4] += regE;
}

void CSHA1::Update(const unsigned char *data, unsigned int length) {
    unsigned int bufferIndex, tempCount;
    bufferIndex = m_count[0];
    bufferIndex = (bufferIndex / 8) % 64;
    m_count[0] += length * 8;

    if (m_count[0] < length * 8) {
        m_count[1]++;
    }

    m_count[1] += (length >> 29);

    if ((bufferIndex + length) > 63) {
        unsigned int copySize = 64 - bufferIndex;
        memcpy(&m_buffer[bufferIndex], data, copySize);
        Transform(m_state, m_buffer);

        for (; bufferIndex + 63 < length; bufferIndex += 64) {
            Transform(m_state, &data[bufferIndex]);
        }

        bufferIndex = 0;
    } else {
        bufferIndex = 0;
    }

    if (length - bufferIndex != 0)
        memcpy(&m_buffer[bufferIndex], &data[bufferIndex], length - bufferIndex);
}

const CSHA1::Digest &CSHA1::Final() {
    unsigned int i;
    unsigned char finalCount[8];
    unsigned char paddingByte;

    for (i = 0; i < 8; i++) {
        finalCount[i] =
            (unsigned char)((m_count[(i >= 4 ? 0 : 1)] >> ((3 - (i & 3)) * 8)) & 255);
    }

    Update((const unsigned char *)"\x80", 1);

    while ((m_count[0] & 504) != 448) {
        Update((const unsigned char *)"\x00", 1);
    }

    Update(finalCount, 8);

    for (i = 0; i < 20; i++) {
        m_digest.digits[i] =
            (unsigned char)((m_state[i >> 2] >> ((3 - (i & 3)) * 8)) & 255);
    }

    memset(m_buffer, 0, 64);
    memset(m_state, 0, 20);
    memset(m_count, 0, 8);
    memset(finalCount, 0, 8);
    Transform(m_state, m_buffer);

    return m_digest;
}

void CSHA1::Digest::Copy(unsigned char *dest) const { 
    memcpy(dest, this, 20); 
}

void CSHA1::Digest::ReportHash(char *output, unsigned char formatType) const {
    char tempBuffer[24];
    unsigned int loopIndex;

    if (output) {
        if (formatType == 0) {
            sprintf(tempBuffer, "%02X", digits[0]);
            strcpy(output, tempBuffer);

            for (loopIndex = 1; loopIndex < 20; loopIndex++) {
                sprintf(tempBuffer, "%02X", digits[loopIndex & 0xFF]);
                strcat(output, tempBuffer);
            }
        } else if (formatType == 1) {
            sprintf(tempBuffer, "%u", digits[0]);
            strcpy(output, tempBuffer);

            for (loopIndex = 1; loopIndex < 20; loopIndex++) {
                sprintf(tempBuffer, " %u", digits[loopIndex & 0xFF]);
                strcat(output, tempBuffer);
            }
        } else {
            strcpy(output, "Error: Unknown report type!");
        }
    }
}

BinStream &operator<<(BinStream &stream, const CSHA1::Digest &digest) {
    stream.Write(digest.digits, 20);
    return stream;
}

BinStream &operator>>(BinStream &stream, CSHA1::Digest &digest) {
    stream.Read(digest.digits, 20);
    return stream;
}

