#ifdef CRT_HAS_128BIT
// Computes the remainder of unsigned 128-bit division
COMPILER_RT_ABI tu_int __umodti3(tu_int dividend, tu_int divisor) {
  tu_int remainder;
  __udivmodti4(dividend, divisor, &remainder);
  return remainder;
}
#endif // CRT_HAS_128BIT

