void save_to_file(const std::string& path, const ui_tree::sptr& instance)
{
    std::ofstream file_stream(path);
    if(file_stream.is_open() && file_stream.good())
    {
        file_stream.write(instance->content.c_str(), instance->content.length());
    }
}

void save_to_file_bin(const std::string& path, const ui_tree::sptr& instance)
{
    std::ofstream file_stream(path, std::ios::binary);
    if(file_stream.is_open() && file_stream.good())
    {
        ser20::oarchive_binary_t archive(file_stream);
        try_save(archive, ser20::make_nvp("ui_tree", *instance));
    }
}

void load_from_file(const std::string& path, ui_tree::sptr& instance)
{
    std::ifstream file_stream(path);
    if(file_stream.is_open() && file_stream.good())
    {
        instance->content = fs::read_stream_str(file_stream);
    }
}

void load_from_file_bin(const std::string& path, ui_tree::sptr& instance)
{
    std::ifstream file_stream(path, std::ios::binary);
    if(file_stream.is_open() && file_stream.good())
    {
        ser20::iarchive_binary_t archive(file_stream);
        try_load(archive, ser20::make_nvp("ui_tree", *instance));
    }
}
} // namespace unravel

