#define DST_TYPE double
#include "int_to_fp_impl.inc"
// Converts a 128-bit unsigned integer to a double, using round-to-even rounding.
// Assumes: double follows IEEE 754 64-bit format,
//          tu_int represents a 128-bit unsigned integer.
// Bit layout:
// sEEE EEEE EEEE MMMM MMMM MMMM MMMM MMMM | MMMM MMMM MMMM MMMM MMMM MMMM MMMM
// MMMM
COMPILER_RT_ABI double __floatuntidf(tu_int value) {
    return __floatXiYf__(value);
}
#endif // CRT_HAS_128BIT

#include "Serializers.hpp"

// Convert SkColor4f to JSON array format
void to_json(nlohmann::json& j, const SkColor4f& color) {
    j = nlohmann::json::array();
    j.push_back(color.fR);
    j.push_back(color.fG);
    j.push_back(color.fB);
    j.push_back(color.fA);
}

// Parse JSON array to SkColor4f
void from_json(const nlohmann::json& j, SkColor4f& color) {
    j.at(0).get_to(color.fR);
    j.at(1).get_to(color.fG);
    j.at(2).get_to(color.fB);
    j.at(3).get_to(color.fA);
}

