// Bind the serialization validation function to Python
void bind_version_check(py::module& module) {
  module.def("_check_serialization_compatibility",
             &qdk::chemistry::data::validate_serialization_version,
             R"(
Check if serialization versions are compatible.
This function ensures that major and minor version numbers match exactly.
Patch-level differences are acceptable for backward compatibility.
Args:
    required_version: The version string expected by the current implementation (e.g., "0.1.0")
    actual_version: The version string present in the loaded data
Raises:
    RuntimeError: Thrown when major or minor version numbers do not match
Examples:
    >>> check_serialization_compatibility("0.1.0", "0.1.0")  # Valid
    >>> check_serialization_compatibility("0.1.0", "0.1.2")  # Valid (patch differs)
    >>> check_serialization_compatibility("0.1.0", "0.2.0")  # Raises RuntimeError
)",
             py::arg("required_version"), py::arg("actual_version"));
}

