#include "autolink/service_discovery/container/graph.hpp"
#include <string>
#include "gtest/gtest.h"

namespace autolink {
namespace service_discovery {

// Test for Vertice class functionality
TEST(GraphTest, vertice) {
  Vertice x;
  EXPECT_TRUE(x.IsDummy());

  Vertice y(x);
  EXPECT_TRUE(y.IsDummy());
  EXPECT_EQ(y, x);

  Vertice z = x;
  EXPECT_TRUE(z.IsDummy());
  EXPECT_EQ(z.GetKey(), x.GetKey());

  x = x; // self-assignment

  Vertice w("w");
  EXPECT_FALSE(w.IsDummy());
  EXPECT_NE(w, x);
  EXPECT_NE(w.GetKey(), x.GetKey());
  EXPECT_EQ(w.value(), "w");
}

// Test for Edge class functionality
TEST(GraphTest, edge) {
  Edge e1;
  EXPECT_FALSE(e1.IsValid());

  Edge e2(e1);
  EXPECT_FALSE(e2.IsValid());
  EXPECT_EQ(e2, e1);
  EXPECT_EQ(e2.GetKey(), e1.GetKey());

  Edge e3 = e1;
  EXPECT_FALSE(e3.IsValid());
  EXPECT_EQ(e3, e1);
  EXPECT_EQ(e3.GetKey(), e1.GetKey());

  e1 = e1; // self-assignment

  Edge e4;
  e4 = e3;
  EXPECT_FALSE(e4.IsValid());
  EXPECT_EQ(e4, e3);
  EXPECT_EQ(e4.GetKey(), e3.GetKey());

  const std::string val = "value";
  e1.set_value(val);
  EXPECT_EQ(e1.value(), val);
  EXPECT_FALSE(e1 == e2);
  EXPECT_FALSE(e1.IsValid());

  e2.set_value(val);
  EXPECT_EQ(e1, e2);

  Vertice source("src");
  Vertice target("dst");
  e1.set_src(source);
  e2.set_dst(target);

  EXPECT_EQ(e1.src(), source);
  EXPECT_EQ(e2.dst(), target);
  EXPECT_FALSE(e1 == e2);
  EXPECT_TRUE(e1.IsValid());
  EXPECT_TRUE(e2.IsValid());

  e1.set_dst(target);
  e2.set_src(source);
  EXPECT_EQ(e1, e2);
  EXPECT_EQ(e1.GetKey(), "value_dst");

  Edge e5(source, target, val);
  EXPECT_EQ(e5, e1);
}

// Test for Graph class functionality
TEST(GraphTest, graph) {
  Graph g;
  EXPECT_EQ(g.GetNumOfEdge(), 0);

  Vertice dummy;
  Vertice v1("v1");
  Vertice v2("v2");
  Edge e_ab;

  g.Insert(e_ab);
  EXPECT_EQ(g.GetNumOfEdge(), 0);

  e_ab.set_src(v1);
  e_ab.set_dst(v2);
  e_ab.set_value("e_ab");
  g.Insert(e_ab);
  EXPECT_EQ(g.GetNumOfEdge(), 1);

  // Repeated insert should not increase count
  g.Insert(e_ab);
  EXPECT_EQ(g.GetNumOfEdge(), 1);

  Vertice v3("v3");
  Vertice v4("v4");
  Edge e_cd(v3, v4, "e_cd");
  g.Insert(e_cd);
  EXPECT_EQ(g.GetNumOfEdge(), 2);

  Vertice v5("v5");
  Edge e_ce(v3, v5, "e_ce");
  g.Insert(e_ce);
  EXPECT_EQ(g.GetNumOfEdge(), 3);

  Edge e_ac;
  e_ac.set_src(v1);
  e_ac.set_dst(dummy);
  e_ac.set_value("e_ac");
  g.Insert(e_ac);
  EXPECT_EQ(g.GetNumOfEdge(), 3);

  e_ac.set_src(dummy);
  e_ac.set_dst(v3);
  g.Insert(e_ac);
  EXPECT_EQ(g.GetNumOfEdge(), 4);

  Edge e_be;
  e_be.set_src(dummy);
  e_be.set_dst(v5);
  e_be.set_value("e_be");
  g.Insert(e_be);
  EXPECT_EQ(g.GetNumOfEdge(), 4);

  e_be.set_dst(dummy);
  e_be.set_src(v2);
  g.Insert(e_be);
  EXPECT_EQ(g.GetNumOfEdge(), 5);

  // Directional checks
  EXPECT_EQ(g.GetDirectionOf(v1, v2), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v2, v1), DOWNSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v1, v3), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v3, v1), DOWNSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v2, v5), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v5, v2), DOWNSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v3, v4), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v4, v3), DOWNSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v3, v5), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v5, v3), DOWNSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v1, v5), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v5, v1), DOWNSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v1, v4), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(v4, v1), DOWNSTREAM);

  EXPECT_EQ(g.GetDirectionOf(v2, v4), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(v4, v2), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(v4, v5), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(v5, v4), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(dummy, dummy), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(v1, dummy), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(dummy, v1), UNREACHABLE);

  Vertice v6("v6");
  EXPECT_EQ(g.GetDirectionOf(v1, v6), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(v6, v1), UNREACHABLE);

  // Deletion tests
  g.Delete(e_be);
  EXPECT_EQ(g.GetDirectionOf(v2, v5), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(v5, v2), UNREACHABLE);
  EXPECT_EQ(g.GetNumOfEdge(), 4);

  g.Delete(e_be);
  g.Delete(e_ac);
  EXPECT_EQ(g.GetNumOfEdge(), 3);
  EXPECT_EQ(g.GetDirectionOf(v1, v3), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(v4, v1), UNREACHABLE);

  g.Delete(e_cd);
  EXPECT_EQ(g.GetNumOfEdge(), 2);
  EXPECT_EQ(g.GetDirectionOf(v3, v4), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(v4, v3), UNREACHABLE);

  g.Delete(e_ab);
  EXPECT_EQ(g.GetNumOfEdge(), 1);

  g.Delete(e_ce);
  EXPECT_EQ(g.GetNumOfEdge(), 0);

  Vertice v7("v7");
  Edge e_qa;
  g.Delete(e_qa);

  e_qa.set_src(v7);
  e_qa.set_dst(v1);
  e_qa.set_value("e_qa");
  g.Delete(e_qa);
}

