TEST(TEnumTest, Ordering)
{
    ESimple val1(ESimple::X);
    ESimple val2(ESimple::Y);
    ESimple val3(ESimple::Y);
    ESimple val4(ESimple::Z);

    EXPECT_FALSE(val1 < val1); EXPECT_FALSE(val1 > val1);
    EXPECT_TRUE (val1 < val2); EXPECT_TRUE (val2 > val1);
    EXPECT_TRUE (val1 < val3); EXPECT_TRUE (val3 > val1);
    EXPECT_TRUE (val1 < val4); EXPECT_TRUE (val4 > val1);
    EXPECT_FALSE(val2 < val1); EXPECT_FALSE(val1 > val2);
    EXPECT_FALSE(val2 < val2); EXPECT_FALSE(val2 > val2);
    EXPECT_FALSE(val2 < val3); EXPECT_FALSE(val3 > val2);
    EXPECT_TRUE (val2 < val4); EXPECT_TRUE (val4 > val2);
    EXPECT_FALSE(val3 < val1); EXPECT_FALSE(val1 > val3);
    EXPECT_FALSE(val3 < val2); EXPECT_FALSE(val2 > val3);
    EXPECT_FALSE(val3 < val3); EXPECT_FALSE(val3 > val3);
    EXPECT_TRUE (val3 < val4); EXPECT_TRUE (val4 > val3);
    EXPECT_FALSE(val4 < val1); EXPECT_FALSE(val1 > val4);
    EXPECT_FALSE(val4 < val2); EXPECT_FALSE(val2 > val4);
    EXPECT_FALSE(val4 < val3); EXPECT_FALSE(val3 > val4);
    EXPECT_FALSE(val4 < val4); EXPECT_FALSE(val4 > val4);
    EXPECT_TRUE (val1 <= val2);
    EXPECT_TRUE (val2 <= val3);
    EXPECT_TRUE (val3 <= val4);
    EXPECT_TRUE (val1 == val1);
    EXPECT_FALSE(val1 == val2);
    EXPECT_TRUE (val2 == val3);
    EXPECT_FALSE(val3 == val4);
    EXPECT_FALSE(val4 == val1);
    EXPECT_FALSE(val1 != val1);
    EXPECT_TRUE (val1 != val2);
    EXPECT_FALSE(val2 != val3);
    EXPECT_TRUE (val3 != val4);
    EXPECT_TRUE (val4 != val1);
}

TEST(TEnumTest, OrderingWithDomainValues)
{
    EColor color(EColor::Black);
    EXPECT_LT(EColor::Red, color);
    EXPECT_LT(color, EColor::White);
    EXPECT_GT(color, EColor::Red);
    EXPECT_GT(EColor::White, color);
    EXPECT_LE(EColor::Red, color);
    EXPECT_LE(color, EColor::White);
    EXPECT_GE(EColor::White, color);
    EXPECT_GE(color, EColor::Red);
    EXPECT_EQ(color, EColor::Black);
    EXPECT_EQ(EColor::Black, color);
    EXPECT_NE(color, EColor::Blue);
    EXPECT_NE(EColor::Blue, color);
}

