    system("chmod 444 sample.txt");
#else
    SetFileAttributes(L"sample.txt", FILE_ATTRIBUTE_READONLY);
#endif

    REQUIRE_FALSE(fs::IsWritable("sample.txt"));

#ifdef LINUX
    system("chmod 644 sample.txt");
#else
    SetFileAttributes(L"sample.txt", FILE_ATTRIBUTE_NORMAL);
#endif

    fs::Delete("sample.txt");
    REQUIRE_FALSE(fs::IsWritable("sample.txt"));
}

