TEST_CASE("Copy directory", "[Copy]") {
    fs::CreateDirectory("somedir/subdir");
    std::string str = "This is a test\n";
    str.push_back(0);
    fs::Save("somedir/sample.bin", str);
    fs::Save("somedir/subdir/sample.txt", "This is a test\n");

    REQUIRE(fs::Copy("somedir", "sampledir"));
    REQUIRE(fs::IsDirectory("sampledir"));
    REQUIRE(fs::IsDirectory("sampledir/subdir"));
    REQUIRE(fs::Load("sampledir/sample.bin") == str);
    REQUIRE(fs::Load("sampledir/subdir/sample.txt") == "This is a test\n");

    fs::Delete("sampledir");

    fs::Iterator begin("somedir"), end;
    fs::CreateDirectory("sampledir");
    REQUIRE(fs::Copy("somedir", begin, end, "sampledir"));
    REQUIRE(fs::IsDirectory("sampledir"));
    REQUIRE(fs::IsDirectory("sampledir/subdir"));
    REQUIRE(fs::Load("sampledir/sample.bin") == str);
    REQUIRE(fs::Load("sampledir/subdir/sample.txt") == "This is a test\n");

    fs::Delete("sampledir");

    std::vector<std::string> fileList;
    REQUIRE(fs::Copy(fileList, "sampledir"));
    fs::CreateDirectory("sampledir");
    fileList.push_back("somedir/subdir");
    fileList.push_back("somedir/sample.bin");
    REQUIRE(fs::Copy(fileList, "sampledir"));
    REQUIRE(fs::IsDirectory("sampledir"));
    REQUIRE(fs::IsDirectory("sampledir/subdir"));
    REQUIRE(fs::Load("sampledir/sample.bin") == str);
    REQUIRE(fs::Load("sampledir/subdir/sample.txt") == "This is a test\n");

    fs::Delete("somedir");
    fs::Delete("sampledir");
    REQUIRE_FALSE(fs::Copy(fileList, "sampledir"));
    fs::Delete("sampledir");
}

