// Compute the length of the diagonal of the axis-aligned bounding box
IGL_INLINE double igl::bounding_box_diagonal(
  const Eigen::MatrixXd & vertices)
{
  using namespace Eigen;
  VectorXd max_vals, min_vals;
  VectorXi max_indices, min_indices;
  mat_max(vertices, 1, max_vals, max_indices);
  mat_min(vertices, 1, min_vals, min_indices);
  return std::sqrt((max_vals - min_vals).array().square().sum());
}
