/// @brief Compute CRC32 checksum for given data buffer
/// @param data_ptr pointer to the input data
/// @param data_len length of the input data
/// @return CRC32 checksum value
UInt32 compute_crc32(const VoidPtr data_ptr, Int32 data_len) {
  if (!data_ptr) return ~0;
  UInt32 current_crc = 0xffffffff;
  Char* data = static_cast<Char*>(data_ptr);
  while ((data_len--) > 0) 
    current_crc = (current_crc >> 8) ^ crc_lookup_table[(current_crc ^ *(data++)) & 0xFF];
  return ~current_crc;
}
