#include <vector>

class Solution {
public:
    // Count elements that are not divisible by 3
    int minimumOperations(std::vector<int>& numbers) {
        int remaining = numbers.size();
        for (int index = 0; index < numbers.size(); remaining -= ((numbers[index++] % 3 == 0)));
        return remaining;
    }
};

