// Enumerate image kinds for YAML serialization
void ScalarEnumerationTraits<object::ImageKind>::enumeration(
    IO &Stream, object::ImageKind &Kind) {
#define ECase(Name) Stream.enumCase(Kind, #Name, object::Name)
  ECase(IMG_None);
  ECase(IMG_Object);
  ECase(IMG_Bitcode);
  ECase(IMG_Cubin);
  ECase(IMG_Fatbinary);
  ECase(IMG_PTX);
  ECase(IMG_LAST);
#undef ECase
  Stream.enumFallback<Hex16>(Kind);
}

// Enumerate offload kinds for YAML serialization
void ScalarEnumerationTraits<object::OffloadKind>::enumeration(
    IO &Stream, object::OffloadKind &Kind) {
#define ECase(Name) Stream.enumCase(Kind, #Name, object::Name)
  ECase(OFK_None);
  ECase(OFK_OpenMP);
  ECase(OFK_Cuda);
  ECase(OFK_HIP);
  ECase(OFK_LAST);
#undef ECase
  Stream.enumFallback<Hex16>(Kind);
}

// Mapping for OffloadYAML::Binary structure
void MappingTraits<OffloadYAML::Binary>::mapping(
    IO &Stream, OffloadYAML::Binary &BinaryInfo) {
  assert(!Stream.getContext() && "IO context already set");
  Stream.setContext(&BinaryInfo);
  Stream.mapTag("!Offload", true);
  Stream.mapOptional("Version", BinaryInfo.Version);
  Stream.mapOptional("Size", BinaryInfo.Size);
  Stream.mapOptional("EntryOffset", BinaryInfo.EntryOffset);
  Stream.mapOptional("EntrySize", BinaryInfo.EntrySize);
  Stream.mapRequired("Members", BinaryInfo.Members);
  Stream.setContext(nullptr);
}

// Mapping for StringEntry within Binary
void MappingTraits<OffloadYAML::Binary::StringEntry>::mapping(
    IO &Stream, OffloadYAML::Binary::StringEntry &Entry) {
  assert(Stream.getContext() && "IO context not initialized");
  Stream.mapRequired("Key", Entry.Key);
  Stream.mapRequired("Value", Entry.Value);
}

// Mapping for Member within Binary
void MappingTraits<OffloadYAML::Binary::Member>::mapping(
    IO &Stream, OffloadYAML::Binary::Member &Member) {
  assert(Stream.getContext() && "IO context not initialized");
  Stream.mapOptional("ImageKind", Member.ImageKind);
  Stream.mapOptional("OffloadKind", Member.OffloadKind);
  Stream.mapOptional("Flags", Member.Flags);
  Stream.mapOptional("String", Member.StringEntries);
  Stream.mapOptional("Content", Member.Content);
}

