REGISTER_DMX_ARCHIVE(FDMXProtocolE131RootLayerPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolE131FramingLayerPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolE131DMPLayerPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolUDPE131FramingLayerPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolUDPE131DiscoveryLayerPacket);

TSharedPtr<FBufferArchive> FDMXProtocolE131RootLayerPacket::Pack()
{
	TSharedPtr<FBufferArchive> Serializer = MakeShared<FBufferArchive>();
	*Serializer << *this;
	return Serializer;
}

void FDMXProtocolE131RootLayerPacket::Serialize(FArchive & Stream)
{
	Stream.SetByteSwapping(true);
	Stream << PreambleSize;
	Stream << PostambleSize;
	Stream.SetByteSwapping(false);
	Stream.Serialize((void*)ACNIdentifier, ACN_IDENTIFIER_SIZE);
	Stream.SetByteSwapping(true);
	Stream << FlagsAndLength;
	Stream << Vector;
	Stream.SetByteSwapping(false);
	Stream.Serialize((void*)ConnectionID, ACN_CIDBYTES);
}

TSharedPtr<FBufferArchive> FDMXProtocolE131FramingLayerPacket::Pack()
{
	TSharedPtr<FBufferArchive> Serializer = MakeShared<FBufferArchive>();
	*Serializer << *this;
	return Serializer;
}

void FDMXProtocolE131FramingLayerPacket::Serialize(FArchive & Stream)
{
	Stream.SetByteSwapping(true);
	Stream << FlagsAndLength;
	Stream << Vector;
	Stream.SetByteSwapping(false);
	Stream.Serialize((void*)SourceIdentifier, ACN_SOURCE_NAME_SIZE);
	Stream.SetByteSwapping(true);
	Stream << PriorityLevel;
	Stream << SyncAddress;
	Stream << FrameSequence;
	Stream << OptionFlags;
	Stream << UniverseID;
}

TSharedPtr<FBufferArchive> FDMXProtocolE131DMPLayerPacket::Pack()
{
	TSharedPtr<FBufferArchive> Serializer = MakeShared<FBufferArchive>();
	*Serializer << *this;
	return Serializer;
}

void FDMXProtocolE131DMPLayerPacket::Serialize(FArchive & Stream)
{
	Stream.SetByteSwapping(true);
	Stream << FlagsAndLength;
	Stream << Vector;
	Stream << AddressModeAndDataFormat;
	Stream << FirstRegisterAddress;
	Stream << RegisterIncrement;
	Stream << DataElementCount;
	Stream << StartCode;
	Stream.SetByteSwapping(false);
	Stream.Serialize((void*)ChannelData, ACN_DMX_SIZE);
}

TSharedPtr<FBufferArchive> FDMXProtocolUDPE131FramingLayerPacket::Pack()
{
	TSharedPtr<FBufferArchive> Serializer = MakeShared<FBufferArchive>();
	*Serializer << *this;
	return Serializer;
}

void FDMXProtocolUDPE131FramingLayerPacket::Serialize(FArchive & Stream)
{
	Stream.SetByteSwapping(true);
	Stream << FlagsAndLength;
	Stream << Vector;
	Stream.SetByteSwapping(false);
	Stream.Serialize((void*)OriginatorName, ACN_SOURCE_NAME_SIZE);
	Stream.Serialize((void*)PaddingBytes, sizeof(PaddingBytes));
}

TSharedPtr<FBufferArchive> FDMXProtocolUDPE131DiscoveryLayerPacket::Pack()
{
	TSharedPtr<FBufferArchive> Serializer = MakeShared<FBufferArchive>();
	*Serializer << *this;
	return Serializer;
}

void FDMXProtocolUDPE131DiscoveryLayerPacket::Serialize(FArchive & Stream)
{
	Stream.SetByteSwapping(true);
	Stream << FlagsAndLength;
	Stream << Vector;
	Stream << CurrentPage;
	Stream << FinalPageFlag;
	Stream.SetByteSwapping(false);
	Stream.Serialize((void*)UniverseList, sizeof(UniverseList));
}

#include "Misc/AutomationTest.h"

BEGIN_DEFINE_SPEC(AutomationSpec, "System.Automation.Spec", EAutomationTestFlags::EngineFilter | EAutomationTestFlags::ApplicationContextMask)
	bool bTestFlag;
	FString ExecutionSequence; 
END_DEFINE_SPEC(AutomationSpec)

void AutomationSpec::Define()
{
	Describe("A top-level description block 1", [this]()
	{
		It("includes a test case with an assertion", [this]()
		{
			bTestFlag = true;
			TestEqual("TestFlag", bTestFlag, true);
		});
	});

	Describe("A top-level description block 2", [this]()
	{
		BeforeEach([&]()
		{
			bTestFlag = false;
		});
		xIt("skips disabled test cases", [this]()
		{
			TestEqual("TestFlag", bTestFlag, true);
		});
		xDescribe("with nested disabled descriptions", [this]()
		{
			It("does not execute tests inside those blocks", [this]()
			{
				TestEqual("TestFlag", bTestFlag, true);
			});
		});
	});

	Describe("A test group using setup and teardown callbacks", [this]()
	{
		BeforeEach([this]()
		{
			ExecutionSequence = TEXT("First");
		});
		It("executes setup before each test and teardown after each test", [this]()
		{
			TestEqual("ExecutionSequence", ExecutionSequence, TEXT("First"));
		});
		AfterEach([this]()
		{
			ExecutionSequence += TEXT("Final");
			TestEqual("ExecutionSequence", ExecutionSequence, TEXT("FirstFinal"));
		});
	});

	Describe("Another test group with setup and teardown", [this]()
	{
		AfterEach([this]()
		{
			ExecutionSequence += TEXT("End");
			TestEqual("ExecutionSequence", ExecutionSequence, TEXT("StartMiddleEnd"));
		});
		Describe("within another description block", [this]()
		{
			It("runs all applicable setup and teardown steps in order", [this]()
			{
				TestEqual("ExecutionSequence", ExecutionSequence, TEXT("StartMiddle"));
			});
			AfterEach([this]()
			{
				ExecutionSequence += TEXT("MidEnd");
			});
			BeforeEach([this]()
			{
				ExecutionSequence += TEXT("Middle");
			});
		});
		BeforeEach([this]()
		{
			ExecutionSequence = TEXT("Start");
		});
	});

	Describe("Complex nesting test group with layered callbacks", [this]()
	{
		BeforeEach([this]()
		{
			ExecutionSequence = TEXT("Layer1");
		});
		AfterEach([this]()
		{
			ExecutionSequence += TEXT("Exit3");
			TestEqual("ExecutionSequence", ExecutionSequence, TEXT("Layer1Layer2Layer3Exit3"));
		});
		BeforeEach([this]()
		{
			ExecutionSequence += TEXT("Layer2");
		});
		Describe("nested one level deeper", [this]()
		{
			AfterEach([this]()
			{
				ExecutionSequence += TEXT("Exit2");
			});
			BeforeEach([this]()
			{
				ExecutionSequence += TEXT("Layer3");
			});
			Describe("nested two levels deeper", [this]()
			{
				It("executes all setup and teardown phases correctly", [this]()
				{
					TestEqual("ExecutionSequence", ExecutionSequence, TEXT("Layer1Layer2Layer3"));
				});
				AfterEach([this]()
				{
					ExecutionSequence += TEXT("Exit1");
				});
				BeforeEach([this]()
				{
					ExecutionSequence += TEXT("Layer4");
				});
			});
		});
	});
}

