template<typename Func, typename... TArgs>
void ABSL_ATTRIBUTE_NOINLINE InvokeFunction(Func f, TArgs&&... args) {
  f(std::forward<TArgs>(args)...);
}

template<typename Func, typename Callable, typename... TArgs>
void SetupAndInvokeBenchmark(benchmark::State& state,
                             const Callable& c, TArgs&&... args) {
  for (auto _ : state) {
    InvokeFunction<Func>(c, std::forward<TArgs>(args)...);
  }
}

