// Doesn't include construction or copy overhead in the loop.
template<typename Func, typename Callable, typename... TArgs>
void DirectCallBenchmark(benchmark::State& state, const Callable& c,
                         TArgs... args) {
  Func f = c;
  for (auto _ : state) {
    benchmark::DoNotOptimize(&f);
    f(args...);
  }
}

