namespace nb = nanobind;
using namespace mscclpp;

// Register proxy channel bindings for Python
void bind_proxy_interface(nb::module_& module) {
  // Bind BaseProxyService class
  nb::class_<BaseProxyService>(module, "BaseProxyService")
      .def("start_proxy", &BaseProxyService::startProxy)
      .def("stop_proxy", &BaseProxyService::stopProxy);

  // Bind ProxyService class inheriting from BaseProxyService
  nb::class_<ProxyService, BaseProxyService>(module, "ProxyService")
      .def(nb::init<size_t>(), nb::arg("fifo_capacity") = DEFAULT_FIFO_SIZE)
      .def("start_proxy", &ProxyService::startProxy)
      .def("stop_proxy", &ProxyService::stopProxy)
      .def("build_and_add_semaphore", &ProxyService::buildAndAddSemaphore, nb::arg("comm"), nb::arg("conn"))
      .def("add_semaphore", &ProxyService::addSemaphore, nb::arg("semaphore_obj"))
      .def("add_memory", &ProxyService::addMemory, nb::arg("memory_obj"))
      .def("semaphore", &ProxyService::semaphore, nb::arg("index"))
      .def("base_proxy_channel", &ProxyService::baseProxyChannel, nb::arg("index"))
      .def("proxy_channel", &ProxyService::proxyChannel, nb::arg("index"), nb::arg("dst_rank"), nb::arg("src_rank"));

  // Bind BaseProxyChannel class
  nb::class_<BaseProxyChannel>(module, "BaseProxyChannel")
      .def(nb::init<SemaphoreId, std::shared_ptr<Host2DeviceSemaphore>, std::shared_ptr<Proxy>>(),
           nb::arg("semaphore_id"), nb::arg("semaphore_ptr"), nb::arg("proxy_ptr"))
      .def("device_handle", &BaseProxyChannel::deviceHandle);

  // Bind BaseProxyChannel::DeviceHandle inner class
  nb::class_<BaseProxyChannel::DeviceHandle>(module, "BaseProxyChannelDeviceHandle")
      .def(nb::init<>())
      .def_rw("semaphoreId_", &BaseProxyChannel::DeviceHandle::semaphoreId_)
      .def_rw("semaphore_", &BaseProxyChannel::DeviceHandle::semaphore_)
      .def_rw("fifo_", &BaseProxyChannel::DeviceHandle::fifo_)
      .def_prop_ro("raw", [](const BaseProxyChannel::DeviceHandle& handle) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&handle), sizeof(handle));
      });

  // Bind ProxyChannel class
  nb::class_<ProxyChannel>(module, "ProxyChannel")
      .def(nb::init<SemaphoreId, std::shared_ptr<Host2DeviceSemaphore>, std::shared_ptr<Proxy>, MemoryId, MemoryId>(),
           nb::arg("semaphore_id"), nb::arg("semaphore_ptr"), nb::arg("proxy_ptr"), nb::arg("dst_mem"), nb::arg("src_mem"))
      .def("device_handle", &ProxyChannel::deviceHandle);

  // Bind ProxyChannel::DeviceHandle inner class
  nb::class_<ProxyChannel::DeviceHandle>(module, "ProxyChannelDeviceHandle")
      .def(nb::init<>())
      .def_rw("semaphoreId_", &ProxyChannel::DeviceHandle::semaphoreId_)
      .def_rw("semaphore_", &ProxyChannel::DeviceHandle::semaphore_)
      .def_rw("fifo_", &ProxyChannel::DeviceHandle::fifo_)
      .def_rw("src_", &ProxyChannel::DeviceHandle::src_)
      .def_rw("dst_", &ProxyChannel::DeviceHandle::dst_)
      .def_prop_ro("raw", [](const ProxyChannel::DeviceHandle& handle) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&handle), sizeof(handle));
      });
}

