using namespace MOBase;

DisableProxyPluginDialog::DisableProxyPluginDialog(
    MOBase::IPlugin* proxyPlugin, std::vector<MOBase::IPlugin*> const& dependencies,
    QWidget* parent)
    : QDialog(parent), ui(new Ui::DisableProxyPluginDialog)
{
  ui->setupUi(this);

  ui->topLabel->setText(QObject::tr("Disabling the '%1' plugin will prevent the "
                                    "following %2 plugin(s) from working:",
                                    "", dependencies.size())
                            .arg(proxyPlugin->localizedName())
                            .arg(dependencies.size()));

  connect(ui->cancelBtn, &QPushButton::clicked, this, &QDialog::reject);
  connect(ui->confirmBtn, &QPushButton::clicked, this, &QDialog::accept);

  ui->dependentPlugins->setSelectionMode(QAbstractItemView::NoSelection);
  ui->dependentPlugins->setRowCount(dependencies.size());
  for (int index = 0; index < dependencies.size(); ++index) {
    ui->dependentPlugins->setItem(index, 0,
                                  new QTableWidgetItem(dependencies[index]->localizedName()));
    ui->dependentPlugins->setItem(index, 1,
                                  new QTableWidgetItem(dependencies[index]->description()));
    ui->dependentPlugins->setRowHeight(index, 9);
  }
  ui->dependentPlugins->verticalHeader()->setVisible(false);
  ui->dependentPlugins->sortByColumn(0, Qt::AscendingOrder);
}

