void save_to_file(const std::string& file_path, const style_sheet::sptr& sheet)
{
    std::ofstream output_stream(file_path);
    if(output_stream.is_open())
    {
        output_stream.write(sheet->content.c_str(), sheet->content.size());
    }
}

void save_to_file_bin(const std::string& file_path, const style_sheet::sptr& sheet)
{
    std::ofstream output_stream(file_path, std::ios::binary);
    if(output_stream.is_open())
    {
        ser20::oarchive_binary_t archive(output_stream);
        try_save(archive, ser20::make_nvp("style_sheet", *sheet));
    }
}

void load_from_file(const std::string& file_path, style_sheet::sptr& sheet)
{
    std::ifstream input_stream(file_path);
    if(input_stream.is_open())
    {
        sheet->content = fs::read_stream_str(input_stream);
    }
}

void load_from_file_bin(const std::string& file_path, style_sheet::sptr& sheet)
{
    std::ifstream input_stream(file_path, std::ios::binary);
    if(input_stream.is_open())
    {
        ser20::iarchive_binary_t archive(input_stream);
        try_load(archive, ser20::make_nvp("style_sheet", *sheet));
    }
}
