#include <Pith/Config.hpp>
#include <Pith/LockGuard.hpp>
#include <Pith/SharedLock.hpp>
#include <gtest/gtest.h>

using namespace Pith;

// Test that multiple shared locks can be acquired simultaneously
TEST(SharedLock, multipleShared) {
    SharedLock lock;
    SharedLockGuard<SharedLock> guard1(lock);
    EXPECT_TRUE(trySharedLock(lock));
}

// Verify that a shared lock holder cannot acquire an exclusive lock
TEST(SharedLock, DISABLED_failToTakeExclusive) {
    SharedLock lock;
    SharedLockGuard<SharedLock> guard(lock);
    EXPECT_FALSE(tryExclusiveLock(lock));
}

// Test transition from exclusive to shared locking and back
TEST(SharedLock, DISABLED_exclusiveThenShared) {
    SharedLock lock;

    // Acquire exclusive lock and verify state
    {
        ExclusiveLockGuard<SharedLock> guard(lock);
        EXPECT_TRUE(lock.isLocked<Access::EXCLUSIVE>());
    }

    // After releasing exclusive lock, verify it's no longer locked exclusively
    EXPECT_FALSE(lock.isLocked<Access::EXCLUSIVE>());

    // Now acquire a shared lock and verify state
    {
        SharedLockGuard<SharedLock> guard(lock);
        EXPECT_TRUE(lock.isLocked<Access::SHARED>());
    }

    // After releasing shared lock, verify it's no longer locked
    EXPECT_FALSE(lock.isLocked<Access::SHARED>());
}

