namespace {
class AndroidAssetReader
{
public:
    explicit AndroidAssetReader(const std::string& assetPath):
        m_assetPath(assetPath),
        m_assetHandle(nullptr)
    {
        m_assetHandle = AAssetManager_open(yarrar::android::getAssetManager(), m_assetPath.c_str(), AASSET_MODE_BUFFER);
        if (!m_assetHandle)
        {
            throw std::runtime_error("Unable to open asset: " + m_assetPath);
        }
    }

    ~AndroidAssetReader()
    {
        if (m_assetHandle)
        {
            AAsset_close(m_assetHandle);
        }
    }

    void readInto(std::string& outputBuffer)
    {
        if (!m_assetHandle)
        {
            throw std::runtime_error("Asset is not valid: " + m_assetPath);
        }

        size_t totalSize = static_cast<size_t>(AAsset_getLength(m_assetHandle));
        outputBuffer.clear();
        outputBuffer.reserve(totalSize);
        outputBuffer.resize(totalSize);

        int bytesRead = AAsset_read(m_assetHandle, &outputBuffer[0], totalSize);
        if (bytesRead <= 0 || static_cast<size_t>(bytesRead) != totalSize)
        {
            throw std::runtime_error("Failed to fully read asset: " + m_assetPath);
        }
    }

private:
    std::string m_assetPath;
    AAsset* m_assetHandle;
};
}

namespace yarrar {
namespace filesystem {

void loadFileContents(const std::string& relativePath, std::string& destinationBuffer)
{
    yarrar::android::log("Loading asset: " + relativePath);
    AndroidAssetReader reader(relativePath);
    reader.readInto(destinationBuffer);
}

}
