		QString expectedCtrl = QString("<C-%1>").arg(converter.specialKeys.value(key));
#endif
		QCOMPARE(converter.convertKey("", key, Qt::ControlModifier), expectedCtrl);

		// Test Alt modifier
		QString expectedAlt = QString("<A-%1>").arg(converter.specialKeys.value(key));
		QCOMPARE(converter.convertKey("", key, Qt::AltModifier), expectedAlt);

		// Test Meta modifier
