// Enqueue a message to the specified queue only if sufficient space is available
void conditionalEnqueue(QUEUE_TYPE(uint8_t)* queue, uint8_t* message,
        int messageLength) {
    // Check if there's enough room: message + 2 termination bytes
    if (queue_remaining_space(queue) < static_cast<int>(messageLength + 2)) {
        debug("Dropped incoming CAN message -- send queue full\r\n");
        return;
    }

    // Copy message bytes into the queue
    for (int idx = 0; idx < messageLength; ++idx) {
        QUEUE_PUSH(uint8_t, queue, message[idx]);
    }

    // Append line ending characters
    QUEUE_PUSH(uint8_t, queue, '\r');
    QUEUE_PUSH(uint8_t, queue, '\n');
}

// Route and enqueue a message via USB or serial depending on connection status
void sendMessage(Listener* listener, uint8_t* message, int messageLength) {
    // Prefer USB if configured; otherwise fall back to serial
    if (listener->usb->is_configured) {
        conditionalEnqueue(&listener->usb->sendQueue, message, messageLength);
    } else {
        conditionalEnqueue(&listener->serial->sendQueue, message, messageLength);
    }
}

// Handle input processing for active communication interfaces
void processListenerQueues(Listener* listener) {
    // USB processing is mandatory (required for enumeration and control)
    processInputQueue(listener->usb);

    // Only process serial queue when USB is not yet configured
    if (!listener->usb->is_configured) {
        processInputQueue(listener->serial);
    }
}

