#include "cmbf.h"
#include <unordered_map>
#include <cstdint>
#include <cstdio>
#include <vector>
#include <random>

using sketch::cmbf::cmbf_exp_t;
using sketch::cmbf::cmbf_t;

int main(int argc, char *argv[]) {
    // Initialize approximate and exact Count-Min/Count-Bloom filters
    cmbf_exp_t bf_approx(4, 16, 1);
    cmbf_t bf_exact(4, 16, 5);

    // Query memory usage
    size_t stack_usage = 0;
    size_t heap_usage = 0;
    std::tie(stack_usage, heap_usage) = bf_approx.est_memory_usage();
    std::fprintf(stderr, "stack space: %zu\theap space:%zu\n", stack_usage, heap_usage);

    // Determine number of items to generate
    size_t total_items = 100000;
    if (argc > 1) {
        char *endptr = nullptr;
        total_items = std::strtoull(argv[1], &endptr, 10);
    }

    // Generate random 64-bit keys
    std::vector<uint64_t> keys;
    keys.reserve(total_items);
    std::mt19937_64 rng{std::random_device{}()};
    for (size_t i = 0; i < total_items; ++i) {
        keys.push_back(rng());
    }

    // Verify initial state: all counters should be zero
    const auto &approx_ref = bf_approx.ref();
    for (const auto val : approx_ref) {
        if (unsigned(val) != 0) {
            std::abort();  // equivalent to assert(false)
        }
    }

    // Insert all items conservatively into both filters
    for (const uint64_t key : keys) {
        bf_approx.add_conservative(key);
        bf_exact.add_conservative(key);
    }

    // Build histograms of estimated counts
    std::unordered_map<uint64_t, uint64_t> exact_hist, approx_hist;
    for (const uint64_t k : keys) {
        ++approx_hist[bf_approx.est_count(k)];
        ++exact_hist[bf_exact.est_count(k)];
    }

    // Output exact histogram
    for (const auto &[count_val, freq] : exact_hist) {
        std::fprintf(stderr, "Exact %" PRIu64 "\t%" PRIu64 "\n", count_val, freq);
    }

    // Output approximate histogram
    for (const auto &[count_val, freq] : approx_hist) {
        std::fprintf(stderr, "Approx %" PRIu64 "\t%" PRIu64 "\n", count_val, freq);
    }

    return 0;
}

