using namespace realm;
using namespace realm::_impl;

// Constructor - initializes the helper with parent coordinator reference
ExternalCommitHelper::ExternalCommitHelper(RealmCoordinator& parent)
: m_parent(parent)
{
    // Initialize the commit history and shared group for change tracking
    m_history = realm::make_client_history(parent.get_path(), parent.get_encryption_key().data());

    SharedGroup::durability_level durability = parent.is_in_memory() 
        ? SharedGroup::durability_MemOnly 
        : SharedGroup::durability_Full;

    m_sg = std::make_unique<SharedGroup>(*m_history, durability, parent.get_encryption_key().data());

    // Start background monitoring in async mode
    m_monitor_thread = std::async(std::launch::async, [this]() {
        monitor_changes();
    });
}

// Destructor - ensures clean shutdown of background monitoring
ExternalCommitHelper::~ExternalCommitHelper()
{
    if (m_sg) {
        m_sg->wait_for_change_release();
    }
    if (m_monitor_thread.valid()) {
        m_monitor_thread.wait();
    }
}

// Internal method to handle the change monitoring loop
void ExternalCommitHelper::monitor_changes()
{
    if (!m_sg) return;

    m_sg->begin_read();
    while (m_sg->wait_for_change()) {
        m_sg->end_read();
        m_sg->begin_read();
        m_parent.on_change();
    }
}

