namespace xchainer {
namespace py = pybind11;

void InitXchainerDevice(pybind11::module& m) {
    // Expose Device class to Python
    py::class_<Device>(m, "Device")
        .def(py::init(&MakeDevice))
        .def("__eq__", py::overload_cast<const Device&, const Device&>(&operator==))
        .def("__ne__", py::overload_cast<const Device&, const Device&>(&operator!=))
        .def("__repr__",
             [](Device device) {
                 std::ostringstream stream;
                 stream << "<Device " << device.name << ">";
                 return stream.str();
             });

    // Provide functions to get/set current device
    m.def("get_current_device", []() { return GetCurrentDevice(); });
    m.def("set_current_device", [](const Device& dev) { SetCurrentDevice(dev); });
    m.def("set_current_device", [](const std::string& dev_name) { SetCurrentDevice(dev_name); });
}
}  // namespace xchainer

