  }
};

// Global variable to store the captured argument
volatile uint64_t recorded_arg = 0;

// Custom handler for XRay argument logging
void custom_handler(int32_t, XRayEntryType, uint64_t arg_value) {
  recorded_arg = arg_value;
}

int main() {
  // Set up the handler to capture the first argument
  __xray_set_handler_arg1(custom_handler);

  // Create an instance of class A and invoke its method
  A obj;
  obj.f();

  // Remove the handler after use
  __xray_remove_handler_arg1();

  // Verify that the captured value matches the address of the object
  assert(recorded_arg == (uint64_t)&obj);

  return 0;
}

