// Custom matrix class to replace CMatrix::Matrix
template<typename T>
class Matrix {
private:
    T** data;
    int rows, cols;

public:
    Matrix(int r, int c) : rows(r), cols(c) {
        data = new T*[rows];
        for (int i = 0; i < rows; ++i) {
            data[i] = new T[cols];
        }
    }

    ~Matrix() {
        for (int i = 0; i < rows; ++i) {
            delete[] data[i];
        }
        delete[] data;
    }

    T& operator()(int r, int c) {
        return data[r][c];
    }

    const T& operator()(int r, int c) const {
        return data[r][c];
    }

    int getRows() const { return rows; }
    int getCols() const { return cols; }

    // Replace fillByPosition with a custom implementation
    template<typename Func>
    void populate(Func func, double centerX, double centerY, double scaleX, double scaleY) {
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                double x = (i - centerX) * scaleX;
                double y = (j - centerY) * scaleY;
                data[i][j] = static_cast<T>(func(x, y));
            }
        }
    }

    friend std::ostream& operator<<(std::ostream& os, const Matrix& m) {
        for (int i = 0; i < m.rows; ++i) {
            for (int j = 0; j < m.cols; ++j) {
                os << m.data[i][j] << " ";
            }
            os << "\n";
        }
        return os;
    }
};

// Function object similar to testFunctionoid but renamed and slightly adjusted logic
class CustomEvaluator {
public:
    double evaluate(double x, double y) const {
        return (std::sin(x * y) + 1.0) / 2.0;
    }

    double operator()(double x, double y) const {
        return evaluate(x, y);
    }
};

int main() {
    int size = 5;
    Matrix<double> matrix(size, size);

    CustomEvaluator evaluator;
    // Use the new populate method instead of fillByPosition
    matrix.populate(evaluator, size/2.0, size/2.0, 1.0/size, 1.0/size);

    std::cout << matrix << std::endl;
    return 0;
}

