// Constructor for GpsdConnection - establishes connection to GPS daemon
GpsdConnection::GpsdConnection( QObject* parent )
    : QObject( parent ),
      m_timer( nullptr )  // Initialize timer pointer explicitly
{
    gps_data_t* initialData = m_gpsd.open();
    if ( initialData != nullptr ) {
#if GPSD_API_MAJOR_VERSION == 3
        // Enable streaming of GPS data for API version 3
        m_gpsd.stream( WATCH_ENABLE );
#endif
        // Set up periodic updates every second
        connect( &m_timer, SIGNAL( timeout() ), this, SLOT( update() ) );
        m_timer.start( 1000 );
    } else {
        // Log failure to connect to GPS daemon
        mDebug() << "Failed to establish connection with gpsd; position information will be unavailable.";
    }
}

// Update method: fetches latest GPS data and emits signal with the information
void GpsdConnection::update()
{
    gps_data_t* currentData;

#if GPSD_API_MAJOR_VERSION == 2
    // For API version 2, query for observational data
    currentData = m_gpsd.query( "o" );
#elif GPSD_API_MAJOR_VERSION == 3
    // For API version 3, poll until policy is set (avoid stale data)
    do {
        currentData = m_gpsd.poll();
    } while (currentData && !(currentData->set & POLICY_SET));
#endif

    // Emit signal with GPS data if available
    if ( currentData != nullptr ) {
        emit gpsdInfo( *currentData );
    }
}

