    PlayerHUD::PlayerHUD()
    {
        m_font.loadFromFile("data/fonts/visitor1.ttf");

        // Initialize speed display
        m_speedText.setFont(m_font);
        m_speedText.setColor(sf::Color::White);
        m_speedText.setCharacterSize(18);

        // Initialize gravity display with same properties
        m_gravityText = m_speedText;

