    {
        // Format speed value with rounding to avoid floating-point artifacts
        std::stringstream sstream;
        sstream << "Speed: " << static_cast<int>(std::round(player.getSpeed().x));
        m_speedText.setString(sstream.str());

        // Clear stream and format gravity value
        sstream.clear();
        sstream.str("");
        sstream << "Gravity: " << static_cast<int>(std::round(player.getGravitation()));
        m_gravityText.setString(sstream.str());
    }

    void PlayerHUD::render(sf::RenderWindow &window)
    {
        window.draw(m_speedText);
        window.draw(m_gravityText);
    }
}

