// Benchmark function for FarmHash with varying input sizes
static void BM_Farmhash(benchmark::State& state) {
    // Create a string of dots with length specified by the current argument
    std::string payload(state.range(0), '.');

    // Run the benchmark loop
    for (auto _ : state) {
        // Compute the 64-bit hash of the payload string
        util::Hash64(payload);
    }

    // Update statistics: bytes processed = iterations * payload size
    state.SetBytesProcessed(
        static_cast<int64_t>(state.iterations()) * 
        static_cast<int64_t>(state.range(0))
    );
}

// Register the benchmark with multiple argument sizes
BENCHMARK(BM_Farmhash)
    ->Arg(4)
    ->Arg(11)
    ->Arg(25)
    ->Arg(100)
    ->Arg(1000)
    ->Arg(10000);

BENCHMARK_MAIN();

