#include "buffers.h"
#include "strutil.h"
#include "log.h"

// Process incoming queue data with validation and recovery logic
void handleIncomingData(ByteQueue* inputQueue, bool (*handler)(uint8_t*)) {
    uint8_t bufferCopy[QUEUE_MAX_LENGTH(uint8_t)];
    queue_snapshot(inputQueue, bufferCopy);

    if (handler == nullptr) {
        debug("Handler function pointer is NULL (%p) -- cannot process queue at %p\r\n",
                handler, inputQueue);
        return;
    }

    // Attempt to process using the provided handler
    if (handler(bufferCopy)) {
        // Handler succeeded, reset the queue
        queue_init(inputQueue);
    } 
    // Check for overflow condition
    else if (queue_full(inputQueue)) {
        debug("Received data exceeds buffer capacity\r\n");
        queue_init(inputQueue);
    } 
    // Check for string corruption (presence of unexpected null terminator)
    else if (strnchr((char*)bufferCopy, queue_length(inputQueue), '\0') != nullptr) {
        debug("Buffered data appears corrupted -- resetting buffer\r\n");
        queue_init(inputQueue);
    }
}

