HtmlSnap::HtmlSnap()
{
    connect(&page, SIGNAL(loadFinished(bool)), this, SLOT(onLoadCompleted()));
}

void HtmlSnap::loadHtml(char* htmlContent)
{
    page.mainFrame()->setHtml(QString(htmlContent), QUrl());
}

void HtmlSnap::onLoadCompleted()
{
    // Adjust viewport to fit content dimensions
    page.setViewportSize(page.mainFrame()->contentsSize());

    // Create image buffer with ARGB32 format
    QImage snapshot(page.viewportSize(), QImage::Format_ARGB32);
    QPainter renderer(&snapshot);

    // Render web frame into image
    page.mainFrame()->render(&renderer);
    renderer.end();

    // Encode image as PNG and convert to base64 string
    QByteArray imageData;
    QBuffer outputBuffer(&imageData);
    outputBuffer.open(QBuffer::WriteOnly);

    if (!snapshot.save(&outputBuffer, "PNG")) {
        std::cerr << "Failed to encode snapshot to PNG" << std::endl;
    } else {
        std::cout << imageData.toBase64().constData();
    }

    // Emit finished signal asynchronously
    QTimer::singleShot(0, this, SIGNAL(finished()));
}

