// Exported flag to signal DLL initialization completion for debugger detection
extern "C" {
    __declspec(dllexport)
    volatile char dllInitialized;

    __declspec(dllexport) __declspec(noinline)
    void SignalInitialization() {
        volatile char temp = 0;
    }
}

