// Threshold in megabytes for determining low-memory devices
#define ANDROID_LOW_MEMORY_DEVICE_THRESHOLD_MB 512

// Convert MB to bytes: 1024 KB/MB * 1024 bytes/KB
const int64 kLowEndMemoryThresholdBytes =
    1024LL * 1024LL * ANDROID_LOW_MEMORY_DEVICE_THRESHOLD_MB;

// Minimum SDK version required for low-end device detection (JB MR2 = API 18)
const int kMinimumSdkForLowEndDetection = 18;

// JNI function implementation
static jboolean IsLowEndDevice(JNIEnv* env, jclass clazz) {
  return base::android::SysUtils::IsLowEndDevice() ? JNI_TRUE : JNI_FALSE;
}

namespace base {
namespace android {

bool SysUtils::Register(JNIEnv* env) {
  return RegisterNativesImpl(env);
}

bool SysUtils::IsLowEndDevice() {
  // Check if physical memory is at or below threshold AND SDK version is above minimum
  const int64 current_memory = SysInfo::AmountOfPhysicalMemory();
  const int current_sdk_version = BuildInfo::GetInstance()->sdk_int();

  return (current_memory <= kLowEndMemoryThresholdBytes) &&
         (current_sdk_version > kMinimumSdkForLowEndDetection);
}

SysUtils::SysUtils() { }

}  // namespace android
}  // namespace base

#include <common.hpp>

// Initialize and configure the radio module for 433MHz operation
void radio_reset()
{
    // Perform hardware reset sequence
    radio::select();
    radio::wcmd<radio::SRES>();
    radio::release();

    // Re-select radio for configuration
    radio::select();

    // Set center frequency to 433 MHz (FREQ2=0x10, FREQ1=0xa7, FREQ0=0x63)
    radio::set<radio::FREQ2>(0x10);
    radio::set<radio::FREQ1>(0xa7);
    radio::set<radio::FREQ0>(0x63);

    // Configure modulation settings
    radio::set<radio::MDMCFG2>(0x1e);

    // Perform frequency synthesizer calibration
    radio::set<radio::FSCAL3>(0xea);
    radio::set<radio::FSCAL2>(0x2a);
    radio::set<radio::FSCAL1>(0x00);
    radio::set<radio::FSCAL0>(0x1f);

    // Setup test registers
    radio::set<radio::TEST2>(0x81);
    radio::set<radio::TEST1>(0x35);
    radio::set<radio::TEST0>(0x09);

    // Configure packet control and power
    radio::set<radio::PKTCTRL1>(0x2c);
    radio::set<radio::PATABLE>(0xc0);

    // Trigger frequency synthesizer calibration
    radio::wcmd<radio::SCAL>();

    // Configure main radio control state machine
    radio::set<radio::MCSM1>(0x3c);
    radio::set<radio::MCSM0>(0x34);

    // Set packet length to 32 bytes
    radio::set<radio::PKTLEN>(32);

