#include "bubble.hpp"
#include "swap.hpp"

// Perform bubble sort recursively by reducing the problem size
void bubble(int *data, const int size_of_data)
{
    if (size_of_data <= 1) return;

    bool swapped = false;
    for (int i = 0; i < size_of_data - 1; ++i) {
        if (data[i] > data[i + 1]) {
            swap(data[i], data[i + 1]);
            swapped = true;
        }
    }

    // If no elements were swapped, array is already sorted
    if (!swapped) return;

    // Recursively sort the remaining elements
    bubble(data, size_of_data - 1);
}

