// Helper macros for encoder name stringification
#define FUZZ_ENCODER_STRINGIFY(x) #x
#define FUZZ_ENCODER_EXPAND_AND_STRINGIFY(x) FUZZ_ENCODER_STRINGIFY(x)

#ifndef FUZZ_ENCODER
#define FUZZ_ENCODER FUZZ_ENCODER_EXPAND_AND_STRINGIFY(FUZZ_IMAGEMAGICK_ENCODER)
#endif

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *inputData, size_t inputSize) {
  // Initialize blob with fuzzer-provided data
  const Magick::Blob inputBlob(inputData, inputSize);

  // Create image object and configure for decoding
  Magick::Image decodedImage;
  decodedImage.magick(FUZZ_ENCODER);
  decodedImage.fileName(std::string(FUZZ_ENCODER) + ":");

  // Attempt to decode the input
  try {
    decodedImage.read(inputBlob);
  }
  catch (const Magick::Exception&) {
    return 0;  // Silently handle decode failures
  }

  // Prepare output blob for re-encoding
  Magick::Blob encodedBlob;
  try {
    // Re-encode the processed image using the same format
    decodedImage.write(&encodedBlob, FUZZ_ENCODER);
  }
  catch (const Magick::Exception&) {
    // Silently ignore encoding errors
  }

  return 0;
}

#include "check_unique_char.h"

CheckUniqueChar::CheckUniqueChar() {
}

CheckUniqueChar::~CheckUniqueChar() {
}

// Determines uniqueness using a boolean array for ASCII characters - O(n) time, O(1) space
bool CheckUniqueChar::solver_boolean(std::string test_string) {
    if (test_string.length() > 256) return false; // More chars than possible unique ASCII values

    bool seen[256] = {false};
    for (char c : test_string) {
        int index = static_cast<int>(c);
        if (seen[index]) {
            return false;
        }
        seen[index] = true;
    }
    return true;
}

// Determines uniqueness by sorting the string first - O(n log n) time due to sorting
bool CheckUniqueChar::solver_sorted(std::string test_string) {
    if (test_string.empty()) return true;

    // Sort the string in-place
    std::sort(test_string.begin(), test_string.end());

    // Check adjacent characters for duplicates
    for (size_t i = 0; i < test_string.length() - 1; ++i) {
        if (test_string[i] == test_string[i + 1]) {
