bool CheckUniqueChar::test_case() {
    std::string test1 = "abcde";      // All unique
    std::string test2 = "hello";      // Has duplicate 'l'
    std::string test3 = "";           // Empty string
    std::string test4 = "aA";         // Different case considered different

    bool result1_bool = solver_boolean(test1);
    bool result2_bool = solver_boolean(test2);
    bool result3_bool = solver_boolean(test3);
    bool result4_bool = solver_boolean(test4);

    bool result1_sort = solver_sorted(test1);
    bool result2_sort = solver_sorted(test2);
    bool result3_sort = solver_sorted(test3);
    bool result4_sort = solver_sorted(test4);

    return (result1_bool && !result2_bool && result3_bool && result4_bool &&
            result1_sort && !result2_sort && result3_sort && result4_sort);
}

