// Base class with two member functions
class X {
public:
    void method1();
    void method2();
};

// Derived class from X, overrides method1
class Y : public X {
public:
    void method1();
};

// Class with virtual function for polymorphic behavior
class Z {
public:
    virtual void method1();
    void method2();
};

// Derived class from Z, overrides the virtual method1
class W : public Z {
public:
    void method1();
};

// Implementation of X's methods
void X::method1() {
    std::cout << "X\n";
}

void X::method2() {
    method1();
}

// Implementation of Y's overridden method
void Y::method1() {
    std::cout << "Y\n";
}

// Implementation of Z's virtual method
void Z::method1() {
    std::cout << "Z\n";
}

void Z::method2() {
    method1();
}

// Implementation of W's overridden virtual method
void W::method1() {
    std::cout << "W\n";
}

int main() {
    // Create Y object and reference it as X
    Y y;
    X& refX = y;
    refX.method2();  // Outputs: Y (since Y overrides method1)

    // Create W object and reference it as Z
    W w;
    Z& refZ = w;
    refZ.method2();  // Outputs: W (virtual dispatch to W::method1)

    return 0;
}

