// Function to decrypt a single character using additive cipher with given key
char decryptChar(char c, int key) {
    if (c >= 'A' && c <= 'Z') {
        return ((c - 'A' - key + 26) % 26) + 'A';
    } else if (c >= 'a' && c <= 'z') {
        return ((c - 'a' - key + 26) % 26) + 'a';
    }
    return c; // Non-alphabetic characters remain unchanged
}

// Generate decrypted text for a specific key value
std::string generateDecryption(const std::string& cipherText, int key) {
    std::string result = "";
    for (size_t i = 0; i < cipherText.length(); ++i) {
        result += decryptChar(cipherText[i], key);
    }
    return result;
}

void findPossiblePlainTexts(const std::string& cipherText, int num);
int main(int argc, char** argv) {
    std::cout << "Letter Frequency attack on additive cipher\n";
    std::cout << "Enter the cipher text: ";
    std::string ciphertext;
    std::cin >> ciphertext;

    int count;
    std::cout << "Total possible plaintext sets: ";
    std::cin >> count;

    findPossiblePlainTexts(ciphertext, count);
    return 0;
}

void findPossiblePlainTexts(const std::string& cipherText, int count) {
    int key = 0;
    while (key < count) {
        std::cout << key + 1 << ": " << generateDecryption(cipherText, key) << "\n";
        key++;
    }
}

