int main() {
    std::string inputLine;
    std::regex zipPattern("\\d{5}-?\\d{4}");
    std::smatch matchResult;
    const std::string formatTemplate = "$1-$2";

    while (std::getline(std::cin, inputLine)) {
        std::string modifiedLine = inputLine;

        // Use regex_replace to transform matching patterns
        modifiedLine = std::regex_replace(modifiedLine, zipPattern, 
            [&formatTemplate](const std::smatch& m) {
                return m.prefix().str() + formatTemplate + m.suffix().str();
            });

        // Actually, let's do it properly with capture groups
        std::regex properZipPattern("(\\d{5})(\\d{4})");
        std::string result = std::regex_replace(inputLine, properZipPattern, formatTemplate);
        std::cout << result << std::endl;
    }

