char *dynamic_buffer = nullptr;

// Allocate memory and copy a PROGMEM string to RAM, freeing previous allocation
char *copyPgmStringToRam(PROGMEM char *source) {
    if (dynamic_buffer != nullptr) {
        free(dynamic_buffer);
    }
    size_t len = strlen_P(source) + 1;
    dynamic_buffer = static_cast<char *>(malloc(len));
    strcpy_P(dynamic_buffer, source);
    return dynamic_buffer;
}

