// Add message to queue only if sufficient space is available
void addToQueueIfRoom(QUEUE_TYPE(uint8_t)* q, uint8_t* data, int len) {
    // Check if queue has enough room for message plus line ending characters
    if(queue_remaining_space(q) < static_cast<int>(len + 2)) {
        debug("CAN message discarded - transmit buffer (%p) exhausted\r\n", q);
        return;
    }

    // Copy each byte of the message to the queue
    int idx = 0;
    while(idx < len) {
        QUEUE_PUSH(uint8_t, q, data[idx]);
        idx++;
    }

    // Append line termination sequence
    QUEUE_PUSH(uint8_t, q, '\r');
    QUEUE_PUSH(uint8_t, q, '\n');
}

// Route message to appropriate output interface based on connection status
void dispatchMessage(Listener* lstnr, uint8_t* payload, int size) {
    // Prefer USB transmission when available
    if(lstnr->usbPort->isConfigured) {
        addToQueueIfRoom(&lstnr->usbPort->txBuffer, payload, size);
    } else {
        // Fall back to serial port when USB isn't configured
        addToQueueIfRoom(&lstnr->serialPort->txBuffer, payload, size);
    }
}

// Handle incoming data from all active interfaces
void handleInputProcessing(Listener* listener) {
    // USB processing is mandatory - it includes essential USB stack operations
    handleReceiveQueue(listener->usbPort);

    // Only process serial input when USB is not active
    if(!listener->usbPort->isConfigured) {
        handleReceiveQueue(listener->serialPort);
    }
}

