// Check if source-level debugging is active and debugger is attached
HRESULT Library_corlib_native_System_Diagnostics_Debugger::get_IsAttached___STATIC__BOOLEAN( CLR_RT_StackFrame& frame )
{
    NATIVE_PROFILE_CLR_CORE();
    NANOCLR_HEADER();

#if defined(NANOCLR_ENABLE_SOURCELEVELDEBUGGING)
    bool isDebuggingActive = CLR_EE_DBG_IS( SourceLevelDebugging );
    frame.SetResult_Boolean( isDebuggingActive );
#else
    frame.SetResult_Boolean( false );
#endif

    NANOCLR_NOCLEANUP_NOLABEL();
}

// Trigger a debug break — only effective when source-level debugging is enabled
HRESULT Library_corlib_native_System_Diagnostics_Debugger::Break___STATIC__VOID( CLR_RT_StackFrame& frame )
{
    NATIVE_PROFILE_CLR_CORE();
    NANOCLR_HEADER();

#if defined(NANOCLR_ENABLE_SOURCELEVELDEBUGGING)
    // First call: request breakpoint; second call resumes execution after suspension
    if (frame.m_customState == 0) {
        frame.m_customState = 1;
        g_CLR_RT_ExecutionEngine.Breakpoint_StackFrame_Break( &frame );

        // Simulate rescheduling by returning special status
        NANOCLR_SET_AND_LEAVE(CLR_E_RESCHEDULE);
    }
    // If custom state non-zero, just complete normally (break already processed)
#else
    // Suppress unused parameter warning in release builds
    (void)frame;
#endif

    NANOCLR_NOCLEANUP();
}

