// Allocate aligned memory for heap objects
void *swift::swift_slowAlloc(size_t size, size_t alignMask) {
  // Compute actual alignment value (alignMask + 1)
  size_t alignment = alignMask + 1;

  void *memoryBlock = nullptr;
  // Attempt allocation with specified alignment
  if (posix_memalign(&memoryBlock, alignment, size) != 0) {
    swift::crash("Memory allocation failed: insufficient memory or invalid alignment.");
  }

  return memoryBlock;
}

// Deallocate aligned memory previously allocated by swift_slowAlloc
void swift::swift_slowDealloc(void *ptr, size_t /*bytes*/, size_t /*alignMask*/) {
  // Free the aligned memory block
  free(ptr);
}

