namespace cuda
{
ShrdResVector GraphicsResourceManager::registerResources(std::vector<uint32_t> resources)
{
    ShrdResVector output;

    // Custom deleter for CUDA graphics resource handles
    auto cleanupResource = [](CGR_t* handle) {
        // Note: CUDA_CHECK around unregister may cause invalid GL context issues.
        // Potential future improvements include:
        // - Integrating ForgeManager as a member of DeviceManager with correct destruction order
        // - Ensuring makeContextCurrent is called appropriately before unregistration
        if (handle != nullptr) {
            cudaGraphicsUnregisterResource(*handle);
            delete handle;
        }
    };

    // Process each resource ID and register it with CUDA
    for (auto bufferId : resources) {
        CGR_t tempHandle;
        CUDA_CHECK(cudaGraphicsGLRegisterBuffer(&tempHandle, bufferId, cudaGraphicsMapFlagsWriteDiscard));

        // Wrap the handle in a smart pointer with custom deleter
        output.emplace_back(new CGR_t(tempHandle), cleanupResource);
    }

    return output;
}
}
