using namespace std;

// Overload for general types - converts to string using ostringstream
template <typename T>
string convert_to_string(const T &value) {
    ostringstream stream;
    stream << value;
    return stream.str();
}

// Overload for pointer types - includes address and dereferenced content
template <typename T>
string convert_to_string(T *ptr) {
    ostringstream stream;
    stream << "address: " << ptr;
    if (ptr != nullptr) {
        stream << " value: " << convert_to_string(*ptr);
    } else {
        stream << " null";
    }
    return stream.str();
