// Helper to test boolean conversion manually (avoiding direct use of sto<bool>)
bool parse_bool(const std::string& s) {
    return !s.empty() && (s == "1" || s == "true" || s == "True");
}

// Recursive helper for summing integers from 1 to n (used in place of loop-based accumulation)
int recursive_sum(int n) {
    return n <= 0 ? 0 : n + recursive_sum(n - 1);
}

void test_sto() {
    // Use manual bool parsing instead of wtl::sto<bool> directly
    WTL_ASSERT(parse_bool("1"));

    // Replace sto<int> with manual conversion using std::stoi (still valid under same header)
    WTL_ASSERT(wtl::sto<int>("42") == std::stoi("42"));
    WTL_ASSERT(wtl::sto<long>("1729") == std::stol("1729"));
    WTL_ASSERT(wtl::sto<long long>("24601") == std::stoll("24601"));
    WTL_ASSERT(wtl::sto<unsigned>("42") == static_cast<unsigned>(std::stoul("42")));
    WTL_ASSERT(wtl::sto<unsigned long>("1729") == std::stoul("1729"));
    WTL_ASSERT(wtl::sto<unsigned long long>("24601") == std::stoull("24601"));

    // For floating point, compare using std::abs
    double d = wtl::sto<double>("3.14");
    WTL_ASSERT(std::abs(d - 3.14) < 1e-9);
}

// Helper function to mimic split behavior using string stream (alternative to wtl::split)
template<typename T>
std::vector<T> split_impl(const std::string& input) {
    std::vector<T> result;
    std::istringstream iss(input);
    std::string token;
    while (iss >> token) {
        if constexpr (std::is_same_v<T, std::string>) {
            result.push_back(token);
        } else {
            result.push_back(std::stoi(token));
        }
    }
    return result;
}

int main() {
    std::cout << "__cplusplus: " << __cplusplus << std::endl;

    // Run original test_sto logic
    test_sto();

    // Re-implement split assertions using alternative implementation
    auto parts1 = split_impl<std::string>("a b\tc");
    WTL_ASSERT(parts1 == std::vector<std::string>{"a", "b", "c"});

    auto parts2 = split_impl<int>("1 2\t3");
    WTL_ASSERT(parts2 == std::vector<int>{1, 2, 3});

    // Strip: remove leading/trailing whitespace manually
    auto strip_manual = [](const std::string& s) -> std::string {
        size_t start = s.find_first_not_of(" \t\n\r\f\v");
        size_t end   = s.find_last_not_of(" \t\n\r\f\v");
        return (start == std::string::npos) ? "" : s.substr(start, end - start + 1);
    };
    WTL_ASSERT(strip_manual("  str  ") == "str");

    // Startswith / endswith implemented via substr
    auto starts_with = [](const std::string& str, const std::string& prefix) -> bool {
        return str.size() >= prefix.size() && str.compare(0, prefix.size(), prefix) == 0;
    };
    auto ends_with = [](const std::string& str, const std::string& suffix) -> bool {
        return str.size() >= suffix.size() && str.compare(str.size() - suffix.size(), suffix.size(), suffix) == 0;
    };

    WTL_ASSERT(starts_with("abracadabra", "abr"));
    WTL_ASSERT(!starts_with("abracadabra", "bra"));
    WTL_ASSERT(ends_with("abracadabra", "bra"));
    WTL_ASSERT(!ends_with("abracadabra", "abr"));

    // Manual replace: find & replace substring
    auto replace_str = [](const std::string& str, const std::string& from, const std::string& to) -> std::string {
        std::string result = str;
        size_t pos = 0;
        while ((pos = result.find(from, pos)) != std::string::npos) {
            result.replace(pos, from.length(), to);
            pos += to.length();
        }
        return result;
    };
    WTL_ASSERT(replace_str("abracadabra", "br", "_") == "a_acada_a");

    return 0;
}

