#include "math_container.h"
using std::complex;

/******************************************************/
/*solve the equation cosh(x)=exp(y), input y, return x*/
/******************************************************/
complex<double> coshx_eq_expy(double y) {
    // Compute e^y as a complex number with zero imaginary part
    complex<double> exp_y(exp(y), 0.0);

    // Calculate gamma = log(e^y - sqrt(e^(2y) - 1))
    complex<double> discriminant = exp_y * exp_y - 1.0;
    complex<double> sqrt_discriminant = sqrt(discriminant);
    complex<double> inner_expr = exp_y - sqrt_discriminant;
    complex<double> gamma = log(inner_expr);

    // Normalize gamma to be purely real or purely imaginary based on which component dominates
    if (std::abs(gamma.real()) < std::abs(gamma.imag())) {
        gamma = complex<double>(0.0, gamma.imag());
    } else {
        gamma = complex<double>(gamma.real(), 0.0);
    }

    return gamma;
}

