// Function to display the elements of the vector
void printVector(const std::vector<int>& vec) {
    for (size_t i = 0; i < vec.size(); ++i) {
        std::cout << vec[i] << "\t";
    }
    std::cout << std::endl;
}

// Generate and print all permutations of the input vector
void generatePermutations(std::vector<int> elements) {
    // Sort the elements to start from the lexicographically smallest permutation
    std::sort(elements.begin(), elements.end());

    // Print each permutation using next_permutation
    do {
        printVector(elements);
    } while (std::next_permutation(elements.begin(), elements.end()));

    // Print the final state after all permutations (which is the largest permutation)
    printVector(elements);
}

int main() {
    // Initialize data array and convert to vector
    int raw_data[] = {1, 4, -1};
    std::vector<int> values(raw_data, raw_data + 3);

    // Generate and print all permutations
    generatePermutations(values);

    return 0;
}

