#include "photoeffects.hpp"
using namespace cv;

// Test for sepia effect with single-channel input (should fail)
TEST(photoeffects, SepiaInvalidInputTest) {
    Mat source(10, 10, CV_8UC1), result;
    EXPECT_EQ(1, sepia(source, result));
}

// Test for sepia effect with three-channel input (should succeed)
TEST(photoeffects, SepiaValidInputTest) {
    Mat source(10, 10, CV_8UC3), result;
    EXPECT_EQ(0, sepia(source, result));
}

// Comprehensive test for sepia effect correctness using HSV color space
TEST(photoeffects, SepiaColorAccuracyTest) {
    Mat input(10, 10, CV_8UC1), output, hsvOutput;
    vector<Mat> channels(3);

    // Apply sepia filter
    EXPECT_EQ(0, sepia(input, output));

    // Convert to HSV for analysis
    cvtColor(output, hsvOutput, COLOR_BGR2HSV);
    split(hsvOutput, channels);

    // Check hue value around expected 19 degrees (±1 tolerance)
    EXPECT_LE(18, channels[0].at<uchar>(0, 0));
    EXPECT_GE(20, channels[0].at<uchar>(0, 0));

    // Check saturation value around expected 78 (±1 tolerance)
    EXPECT_LE(77, channels[1].at<uchar>(0, 0));
    EXPECT_GE(79, channels[1].at<uchar>(0, 0));

    // Check brightness/value offset by ~20 from original (±1 tolerance)
    int originalValue = input.at<uchar>(0, 0);
    EXPECT_LE(originalValue + 19, channels[2].at<uchar>(0, 0));
    EXPECT_GE(originalValue + 21, channels[2].at<uchar>(0, 0));
}

