#include "gtest/gtest.h"
#include "lms/endian.h"

// Test endianness conversion for 16-bit unsigned integers
TEST(Endian, uint16_conversion) {
    using lms::Endian;
    uint16_t original = 0xCAFEu;

    // Test little-endian to host conversion after big-endian transformation
    uint16_t le_to_h = Endian::letoh(Endian::htobe(original));
    ASSERT_EQ(0xFECAu, le_to_h);

    // Test big-endian to host conversion after little-endian transformation
    uint16_t be_to_h = Endian::betoh(Endian::htole(original));
    ASSERT_EQ(0xFECAu, be_to_h);
}

// Test endianness conversion for 32-bit unsigned integers
TEST(Endian, uint32_conversion) {
    using lms::Endian;
    uint32_t original = 0xDEADBEEFu;

    // Test little-endian to host conversion after big-endian transformation
    uint32_t le_to_h = Endian::letoh(Endian::htobe(original));
    ASSERT_EQ(0xEFBEADDEu, le_to_h);

    // Test big-endian to host conversion after little-endian transformation
    uint32_t be_to_h = Endian::betoh(Endian::htole(original));
    ASSERT_EQ(0xEFBEADDEu, be_to_h);
}

// Test endianness conversion for 64-bit unsigned integers
TEST(Endian, uint64_conversion) {
    using lms::Endian;
    uint64_t original = 0xFEEDCAFEDEADBEEFu;

    // Test little-endian to host conversion after big-endian transformation
    uint64_t le_to_h = Endian::letoh(Endian::htobe(original));
    ASSERT_EQ(0xEFBEADDEFECAEDFEu, le_to_h);

    // Test big-endian to host conversion after little-endian transformation
    uint64_t be_to_h = Endian::betoh(Endian::htole(original));
    ASSERT_EQ(0xEFBEADDEFECAEDFEu, be_to_h);
}

