void verify_cell_containing_point(Triangulation<3> &mesh) {
    Point<3> target_point(0.75, 0.0, 0.0);

    Triangulation<3>::active_cell_iterator found_cell
        = GridTools::find_active_cell_around_point(mesh, target_point);
    deallog << found_cell << std::endl;

    for (unsigned int vertex_index = 0; 
         vertex_index < GeometryInfo<2>::vertices_per_cell; 
         ++vertex_index) {
        deallog << "<" << found_cell->vertex(vertex_index) << "> ";
    }
    deallog << std::endl;

    Assert(target_point.distance(found_cell->center()) < found_cell->diameter() / 2.0,
           ExcInternalError());
}

int main() {
    std::ofstream log_file("find_cell_1/output");
    deallog.attach(log_file);
    deallog.depth_console(0);
    deallog.threshold_double(1.e-10);

    Triangulation<3> initial_grid;
    GridGenerator::hyper_cube(initial_grid);
    initial_grid.refine_global(3);

    verify_cell_containing_point(initial_grid);
}

