// Helper macros for wrapping AddressSanitizer interface functions {{{1
static FARPROC getRealProcAddressOrDie(const char *name) {
  FARPROC ret = GetProcAddress(GetModuleHandle(NULL), name);
  if (!ret)
    abort();
  return ret;
}

#define WRAP_VV(name)                                                          \
  extern "C" void name() {                                                     \
    typedef void (*fntype)();                                                  \
    fntype fn = (fntype)getRealProcAddressOrDie(#name);                        \
    fn();                                                                      \
  }

#define WRAP_VW(name)                                                          \
  extern "C" void name(void *arg) {                                            \
    typedef void (*fntype)(void *);                                            \
    fntype fn = (fntype)getRealProcAddressOrDie(#name);                        \
    fn(arg);                                                                   \
  }

#define WRAP_VWW(name)                                                         \
  extern "C" void name(void *arg1, void *arg2) {                               \
    typedef void (*fntype)(void *, void *);                                    \
    fntype fn = (fntype)getRealProcAddressOrDie(#name);                        \
    fn(arg1, arg2);                                                            \
  }
