#include <base/job_identifier.h>
#include <ctime>
#include <string>

JobIdentifier::JobIdentifier()
{
  // Get current time and convert to string
  std::time_t currentTime = std::time(nullptr);
  char timeBuffer[100];
  std::strftime(timeBuffer, sizeof(timeBuffer), "%c", std::localtime(&currentTime));

  // Initialize ID with program identifier
  id = std::string(program_id());

#if defined(HAVE_GETHOSTNAME) && !defined(DEBUG)
  char hostname[100];
  gethostname(hostname, sizeof(hostname) - 1);
  id += std::string(hostname) + " ";
#endif

  // Append formatted time string instead of using ctime directly
  id += std::string(timeBuffer);
}

const std::string
JobIdentifier::operator ()() const
{
  return id;
}

