#include <cassert>
#include <stdexcept>

struct A {};
A global_a;
const A const_global_a = A();

void run_test_one()
{
    try
    {
        throw &global_a;
        // Should not reach here
        std::abort();
    }
    catch (const A* ptr)
    {
        // Expected: catch const A* first
        static_cast<void>(ptr);
    }
    catch (A* ptr)
    {
        // Should not reach here
        static_cast<void>(ptr);
        std::abort();
    }
}

void run_test_two()
{
    try
    {
        throw &global_a;
        // Should not reach here
        std::abort();
    }
    catch (A* ptr)
    {
        // This branch is now valid for non-const pointer
        static_cast<void>(ptr);
    }
    catch (const A* ptr)
    {
        // Should not reach here since non-const matches first
        static_cast<void>(ptr);
        std::abort();
    }
}

void run_test_three()
{
    try
    {
        throw &const_global_a;
        // Should not reach here
        std::abort();
    }
    catch (const A* ptr)
    {
        // Only this overload can bind to const pointer
        static_cast<void>(ptr);
    }
    catch (A* ptr)
    {
        // Should not reach here
        static_cast<void>(ptr);
        std::abort();
    }
}

void run_test_four()
{
    try
    {
        throw &const_global_a;
        // Should not reach here
        std::abort();
    }
    catch (A* ptr)
    {
        // Cannot bind const A* to A*
        static_cast<void>(ptr);
        std::abort();
    }
    catch (const A* ptr)
    {
        // This will be executed
        static_cast<void>(ptr);
    }
}

int main()
{
    run_test_one();
    run_test_two();
    run_test_three();
    run_test_four();
    return 0;
}

