// Helper function to extract directory from full path
std::string get_directory(const std::string& path) {
    size_t pos = path.find_last_of("/\\");
    if (pos != std::string::npos) {
        return path.substr(0, pos + 1);
    }
    return "./";
}

// Helper function to build command arguments string
std::string build_arguments(int argc, char** argv) {
    std::ostringstream oss;
    for (int i = 1; i < argc; ++i) {
        oss << " \"" << argv[i] << "\"";
    }
    return oss.str();
}

int main(int argc, char** argv) {
    // Extract executable directory safely
    std::string exe_path = (argc > 0) ? argv[0] : "./";
    std::string dir_path = get_directory(exe_path);

    // Change to executable directory if possible
    if (chdir(dir_path.c_str()) != 0) {
        std::cerr << "Warning: Could not change to directory " << dir_path << std::endl;
    }

    // Read configuration file
    std::string config_path = "lib/Rel.ini";
    std::ifstream file(config_path);

    if (!file.is_open()) {
        std::cerr << "Missing or Damaged .ini File: Unable to find " << config_path << std::endl;
        return 10;
    }

    // Read file content line by line
    std::ostringstream content;
    std::string line;
    while (std::getline(file, line)) {
        content << line << "\n";
    }
    file.close();

    // Check if file is empty
    if (content.str().empty()) {
        std::cerr << "Missing or Damaged .ini File: Unable to find " << config_path << std::endl;
        return 10;
    }

    // Build final command
    std::string base_command = content.str();
    std::string args = build_arguments(argc, argv);

    // Set environment variable
    setenv("SWT_GTK3", "0", 1);

    // Execute command
    return system((base_command + args).c_str());
}

