#include <test/unit/math/test_ad.hpp>
#include <limits>

TEST(mathMixScalFun, lccdf_derivatives) {
  // Define wrapper for normal_lccdf with fixed parameters
  auto normal_lccdf_wrapper = [](double mean, double stddev) {
    return [&](const auto& value) { 
      return stan::math::normal_lccdf(value, mean, stddev); 
    };
  };

  // Standard tolerance tests for various points
  stan::test::expect_ad(normal_lccdf_wrapper(0.0, 1.0), -50.0);
  stan::test::expect_ad(normal_lccdf_wrapper(0.0, 1.0), -20.0 * stan::math::SQRT_TWO);
  stan::test::expect_ad(normal_lccdf_wrapper(0.0, 1.0), -5.5);
  stan::test::expect_ad(normal_lccdf_wrapper(0.0, 1.0), 0.0);
  stan::test::expect_ad(normal_lccdf_wrapper(0.0, 1.0), 0.15);
  stan::test::expect_ad(normal_lccdf_wrapper(0.0, 1.0), 1.14);
  stan::test::expect_ad(normal_lccdf_wrapper(0.0, 1.0), 3.00);
  stan::test::expect_ad(normal_lccdf_wrapper(0.0, 1.0), 10.00);

  // Test with different parameter sets
  stan::test::expect_ad(normal_lccdf_wrapper(-1.0, 2.0), 1.50);
  stan::test::expect_ad(normal_lccdf_wrapper(2.0, 1.0), 0.50);

  // Higher-order autodiff with relaxed tolerances near boundary
  stan::test::ad_tolerances custom_tols;
  custom_tols.grad_hessian_grad_hessian_ = 1e1;
  stan::test::expect_ad(custom_tols, normal_lccdf_wrapper(0.0, 1.0), 
                        0.1 * stan::math::SQRT_TWO);
}

