    : ss_(), 
      tz_(new boost::local_time::posix_time_zone("CST-06")),  // Adjusted offset to CST-06 for demonstration
      output_facet_(new boost::local_time::local_time_facet()), 
      input_facet_(new boost::local_time::local_time_input_facet()) {

    // Set up output formatting with extended ISO time format
    std::locale loc1(std::locale::classic(), output_facet_);
    ss_.imbue(loc1);

    // Set up input parsing locale
    std::locale loc2(ss_.getloc(), input_facet_);
    ss_.imbue(loc2);

    // Configure output format to extended ISO time specification
    output_facet_->format(boost::local_time::local_time_facet::iso_time_format_extended_specifier);
}

