#include "buffers.h"
#include "strutil.h"
#include "log.h"

void handleIncomingData(ByteQueue* buffer, bool (*handler)(uint8_t*)) {
    size_t bufSize = queue_length(buffer);
    uint8_t tempBuffer[bufSize];
    queue_snapshot(buffer, tempBuffer);

    if (handler == nullptr) {
        debug("Handler function pointer is null (%p) -- cannot process data in queue at %p\r\n",
              handler, buffer);
        return;
    }

    if (handler(tempBuffer)) {
        queue_init(buffer);
    } else if (queue_full(buffer)) {
        debug("Received data exceeds buffer capacity\r\n");
        queue_init(buffer);
    } else if (strnchr(reinterpret_cast<char*>(tempBuffer), bufSize - 1, '\0') != nullptr) {
        debug("Buffered input contains unexpected null terminator (%s) -- resetting buffer\r\n",
              tempBuffer);
        queue_init(buffer);
    }
}

