using namespace caf;
using std::endl;

int main() {
  // Seed random number generator with current time
  std::srand(static_cast<unsigned>(std::time(nullptr)));

  // Spawn 50 actors to perform their tasks
  for (int actor_id = 1; actor_id <= 50; ++actor_id) {
    spawn<blocking_api>([actor_id](blocking_actor* self) {
      // Print initial greeting message
      aout(self) << "Hi there! This is actor nr. "
                 << actor_id << "!" << endl;

      // Generate random delay between 0 and 9 milliseconds
      std::random_device rd;
      std::default_random_engine engine(rd());
      std::chrono::milliseconds delay{engine() % 10};

      // Send delayed 'done' message to self
      self->delayed_send(self, delay, atom("done"));

      // Wait for the delayed message
      self->receive(others() >> [actor_id, self] {
        aout(self) << "Actor nr. "
                   << actor_id << " says goodbye!" << endl;
      });
    });
  }

  // Wait for all spawned actors to complete
  await_all_actors_done();

  // Terminate CAF runtime
  shutdown();
  return 0;
}

