// Enqueue a message into the queue only if sufficient space is available;
// appends a newline character at the end.
void conditionalEnqueue(QUEUE_TYPE(uint8_t)* q, uint8_t* msg, int len) {
    // Check if there's enough room: need 'len' bytes + 1 for '\n'
    if (QUEUE_AVAILABLE(q) < static_cast<int>(len + 1)) {
        debug("Dropped incoming CAN message -- send queue full\r\n");
        return;
    }

    // Copy each byte from the message buffer
    int idx = 0;
    while (idx < len) {
        QUEUE_PUSH(uint8_t, q, msg[idx]);
        ++idx;
    }

    // Append line feed terminator
    QUEUE_PUSH(uint8_t, q, static_cast<uint8_t>('\n'));
}

// Broadcast a message to all applicable output queues (USB always, serial conditionally)
void sendMessage(Listener* lstnr, uint8_t* payload, int size) {
    // Enqueue to USB output first
    conditionalEnqueue(&lstnr->usb->outQueue, payload, size);

#ifdef SERIAL
    // Then enqueue to serial output if enabled
    conditionalEnqueue(&lstnr->serial->outQueue, payload, size);
#endif
}

// Process input data from active interfaces
void processListenerQueues(Listener* lstnr) {
    // Always handle USB input
    processInputQueue(lstnr->usb);

#ifdef SERIAL
    // Also handle serial input when compiled with SERIAL support
    processInputQueue(lstnr->serial);
#endif
}

