int main(int argc, char* argv[])
{
    using namespace std;
    using namespace boost::program_options;

    // Define command line argument groups
    options_description file_paths("File path configuration");
    options_description processing_modes("Processing method selection");

    // Add input/output path parameters
    file_paths.add_options()
        ("input,i", value<string>(), "specify input file path")
        ("output,o", value<string>(), "specify output file path");

    // Add calculation mode flags
    processing_modes.add_options()
        ("amp_exp", "activate exponential amplification algorithm")
        ("cutback", "activate pixel cutback via average subtraction");

    // Combine all options for parsing
    options_description combined_options("");
    combined_options.add(file_paths).add(processing_modes);

    variables_map parsed_args;

    try 
    {
        // Parse command line arguments
        store(parse_command_line(argc, argv, combined_options), parsed_args);
        notify(parsed_args);

        // Check if required input parameter is missing
        if (!parsed_args.count("input") || !parsed_args.count("output"))
        {
            cout << combined_options << endl;
            return 1;
        }
    }
    catch (exception& err)
    {
        cerr << "Error: " << err.what() << endl;
        return 1;
    }

    return 0;
}

