int APIENTRY wWinMain(_In_ HINSTANCE instance,
                      _In_opt_ HINSTANCE previous_instance,
                      _In_ wchar_t* command_line,
                      _In_ int show_command) {
  // Attempt to attach to the parent console if available, otherwise create one for debugging
  if (!::AttachConsole(ATTACH_PARENT_PROCESS) && ::IsDebuggerPresent()) {
    ::AllocConsole();
  }

  // Set up COM threading model for compatibility with plugins and native libraries
  ::CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);

  RunLoop event_loop;

  flutter::DartProject project(L"data");
#ifndef _DEBUG
  // Disable Dart assertions in release builds for performance
  project.SetEngineSwitches({"--disable-dart-asserts"});
#endif

  FlutterWindow flutter_window(&event_loop, project);
  Win32Window::Point initial_position(kFlutterWindowOriginX, kFlutterWindowOriginY);
  Win32Window::Size window_dimensions(kFlutterWindowWidth, kFlutterWindowHeight);

  if (!flutter_window.CreateAndShow(kFlutterWindowTitle, initial_position, window_dimensions)) {
    return EXIT_FAILURE;
  }

  flutter_window.SetQuitOnClose(true);

  event_loop.Run();

  ::CoUninitialize();
  return EXIT_SUCCESS;
}

