#include <gtest/gtest.h>
#include "keystore.h"
#include "zcash/Address.hpp"

TEST(keystore_tests, store_and_retrieve_spending_key) {
    CBasicKeyStore keyStore;
    libzcash::SpendingKey retrievedKey;
    std::set<libzcash::PaymentAddress> addresses;

    // Initially, no addresses should be stored
    keyStore.GetPaymentAddresses(addresses);
    EXPECT_EQ(0u, addresses.size());

    // Generate a new random spending key and its corresponding address
    auto spendingKey = libzcash::SpendingKey::random();
    auto paymentAddr = spendingKey.address();

    // Verify the key is not present before adding it
    EXPECT_FALSE(keyStore.HaveSpendingKey(paymentAddr));
    EXPECT_FALSE(keyStore.GetSpendingKey(paymentAddr, retrievedKey));

    // Add the spending key to the keystore
    keyStore.AddSpendingKey(spendingKey);

    // Now verify the key is present and can be retrieved correctly
    EXPECT_TRUE(keyStore.HaveSpendingKey(paymentAddr));
    EXPECT_TRUE(keyStore.GetSpendingKey(paymentAddr, retrievedKey));
    EXPECT_EQ(spendingKey, retrievedKey);

    // Confirm that the address was added to the set of known addresses
    keyStore.GetPaymentAddresses(addresses);
    EXPECT_EQ(1u, addresses.size());
    EXPECT_EQ(1u, addresses.count(paymentAddr));
}

#include "testing/gtest/include/gtest/gtest.h"
#include "tools/gn/value.h"

TEST(Value, StringConversion) {
  Value string_val(NULL, "hi\" $me\\you\\$\\\"");
  EXPECT_EQ("hi\" $me\\you\\$\\\"", string_val.ToString(false));
  EXPECT_EQ("\"hi\\\" \\$me\\you\\\\\\$\\\\\\\"\"", string_val.ToString(true));

  // Construct a list containing various types
  Value list_val(NULL, Value::LIST);
  list_val.list_value().emplace_back(NULL, "hi\"me");
  list_val.list_value().emplace_back(NULL, true);
  list_val.list_value().emplace_back(NULL, false);
  list_val.list_value().emplace_back(NULL, static_cast<int64_t>(42));

  // List serialization always quotes inner strings regardless of the flag
  EXPECT_EQ("[\"hi\\\"me\", true, false, 42]", list_val.ToString(false));
  EXPECT_EQ("[\"hi\\\"me\", true, false, 42]", list_val.ToString(true));

  // Edge cases for special value types
  EXPECT_EQ("<void>", Value().ToString(false));
  EXPECT_EQ("<scope>", Value(NULL, Value::SCOPE).ToString(false));
}

