// Template class definition with modified naming
template<typename T>
class Container {
public:
    explicit Container(T* ptr = nullptr);
};

// Redesigned class structure with equivalent semantics
class Entity {
public:
    // Constructor with single parameter
    Entity(int val) : value(val), companion(nullptr) {}

    // Constructor with two parameters — reordering initialization order
    Entity(int val, Entity* partner) 
        : companion(nullptr), value(val) {
        companion = partner;
    }

    virtual ~Entity() {}

private:
    int value;
    Container<Entity> companion;
};

int main(int argc, char** argv) {
