    return 0;
}

#include "mainwindow.hpp"
#include <QApplication>
#include <QCommandLineParser>
#include <QDebug>
#include <cstdio>

bool verboseMode = false;

void customMessageHandler(QtMsgType type, const QMessageLogContext &context, const QString &message)
{
    QByteArray localizedMessage = message.toLocal8Bit();

    switch (type)
    {
    case QtDebugMsg:
        if (verboseMode)
            std::fprintf(stdout, "DEBUG %s:%s(%d): %s\n", context.file, context.function, context.line, localizedMessage.constData());
        break;
    case QtInfoMsg:
        std::fprintf(stdout, "INFO %s:%s(%d): %s\n", context.file, context.function, context.line, localizedMessage.constData());
        break;
    case QtWarningMsg:
        std::fprintf(stderr, "WARN %s:%s(%d): %s\n", context.file, context.function, context.line, localizedMessage.constData());
        break;
    case QtCriticalMsg:
        std::fprintf(stderr, "CRIT %s:%s(%d): %s\n", context.file, context.function, context.line, localizedMessage.constData());
        break;
    case QtFatalMsg:
        std::fprintf(stderr, "FATAL %s:%s(%d): %s\n", context.file, context.function, context.line, localizedMessage.constData());
        break;
    }
}

int main(int argc, char *argv[])
{
    qInstallMessageHandler(customMessageHandler);

    QApplication app(argc, argv);
    app.setApplicationName("KShare");
    app.setOrganizationName("ArsenArsen");
    app.setApplicationVersion("1.0");

    QCommandLineParser cliParser;
    cliParser.addHelpOption();

    QCommandLineOption startHidden({ "b", "background" }, "Starts the application in system tray without showing main window.");
    QCommandLineOption enableVerbose({ "v", "verbose" }, "Activates debug output messages.");

    cliParser.addOption(startHidden);
    cliParser.addOption(enableVerbose);
    cliParser.process(app);

    verboseMode = cliParser.isSet(enableVerbose);

    MainWindow mainWindow;
    if (!cliParser.isSet(startHidden)) {
        mainWindow.show();
    }

    return app.exec();
}

