int main() {
    // Define bounds for system dimensions and constraints
    Eigen::Vector2i output_dim_range(2, 2);
    Eigen::Vector2i integrator_count_range(2, 2);

    // Set state and input box constraints
    Eigen::Vector4d state_bounds;
    state_bounds << -1, 10, -2, 10;

    Eigen::Vector4d input_bounds;
    input_bounds << -1, 1, -1, 1;

    // Time period limits
    Eigen::Vector2d time_step_limits(0.05, 0.1);

    // Goal and obstacle count ranges
    Eigen::Vector2i goal_count_range(1, 2);
    Eigen::Vector2i obstacle_count_range(0, 1);

    // Seed random number generator
    std::srand(static_cast<unsigned>(std::time(nullptr)));

    // Generate a random problem instance
    Problem* instance = Problem::random(
        output_dim_range,
        integrator_count_range,
        state_bounds,
        input_bounds,
        goal_count_range,
        obstacle_count_range,
        time_step_limits
    );

    // Output the problem description to stdout
    std::cout << *instance << std::endl;

    // Serialize logical formula to stderr
