std::string get_error_message(int error_code)
{
    char temp_buffer[1024];
#ifdef _WIN32
    if (strerror_s(temp_buffer, sizeof(temp_buffer), error_code) != 0) 
        throw std::runtime_error("Failed to retrieve error string via strerror_s");
    return std::string(temp_buffer);
#else
    // Use the reentrant version of strerror on POSIX systems
    strerror_r(error_code, temp_buffer, sizeof(temp_buffer));
    return std::string(temp_buffer);
#endif
}

#ifdef _WIN32
std::string get_windows_system_error(int error_code)
{
    std::unique_ptr<wchar_t[], LocalFreeDeleter> message_buffer;
