TEST_CASE("accessor_functionality", "[subscripts-accessors]") {
    json::value container = { json::object{ {"sample", 1} }, nullptr, "example_string", 2.5 };
    json::value obj = json::object{ {"label", "text"}, {"count", 42} };

    SECTION("array_element_access") {
        REQUIRE(container[0].is<json::object>());
        REQUIRE(container[1].is<json::null>());
        REQUIRE(container[2].is<std::string>());
        REQUIRE(container[3].is<double>());
        REQUIRE(container[3].is<float>());
        REQUIRE(container[3].is<int>());
        REQUIRE(container[4].is<json::null>()); // Always safe, returns null instead of throwing
    }

    SECTION("object_key_access") {
        REQUIRE(obj["label"].is<std::string>());
        REQUIRE(obj["count"].is<int>());
        REQUIRE(obj["missing_key"].is<json::null>()); // Safe access, returns null for non-existent keys
    }

    SECTION("nested_structure_access") {
        REQUIRE(container[0]["sample"].is<int>());
        REQUIRE(container[0]["sample"].as<int>() == 1);
    }
}

