// Conditional compilation flag to suppress reporting
#define SUPPRESS_ALIAS_REPORT

extern "C" {
  // Report when two values are aliased but should not be
  void ReportMissingAlias(unsigned varID1, unsigned varID2, void *ptr) {
#ifdef SUPPRESS_ALIAS_REPORT
    // Reporting is disabled; do nothing
#else
    fprintf(stderr, "alias detected: value(%u) == value(%u) == %p\n", 
            varID1, varID2, ptr);
#endif
  }

  // Terminate program if two pointers are equal (and non-null), indicating a missed alias
  void AbortIfMissed(void *addr1, unsigned varID1,
                     void *addr2, unsigned varID2) {
    if (addr1 == addr2 && addr1 != nullptr) {
      ReportMissingAlias(varID1, varID2, addr1);
      std::abort();
    }
  }

