// Template function to test type compatibility
template <typename U>
void validate(const U&) {}

int main()
{
    using ClockType = std::chrono::file_clock;

    // Verify that the clock's representation matches its duration's representation
    static_assert(std::is_same<ClockType::rep, ClockType::duration::rep>::value, "");

    // Verify that the clock's period matches its duration's period
    static_assert(std::is_same<ClockType::period, ClockType::duration::period>::value, "");

    // Verify that the clock's duration matches its time_point's duration
    static_assert(std::is_same<ClockType::duration, ClockType::time_point::duration>::value, "");

    // Verify that the time_point's associated clock is the same as the original clock
    static_assert(std::is_same<ClockType::time_point::clock, ClockType>::value, "");

    // Verify that file_clock is not steady (non-monotonic)
    static_assert(!ClockType::is_steady, "");

