struct DataProcessor {
    std::mutex mtx;
    int value;

    DataProcessor() : value(0) {}

    void multiply(int factor) {
        std::lock_guard<std::mutex> guard(mtx);
        value *= factor;
    }

    void divide(int divisor) {
        std::lock_guard<std::mutex> guard(mtx);
        value /= divisor;
    }

    void process(int mult, int div) {
        std::lock_guard<std::mutex> lock(mtx);
        multiply(mult);
        divide(div);
    }
};

