using namespace ofp;

void MPTableStatsBuilder::write(Writable *channel) {
    uint8_t ver = channel->version();

    if (ver >= OFP_VERSION_4) {
        // Write header and first part of the message
        channel->write(&msg_, 4);
        // Write remaining fields: activeCount_ and subsequent data
        channel->write(&msg_.activeCount_, 20);
        channel->flush();
    } else if (ver == OFP_VERSION_1) {
        // For version 1, write the entire message structure at once
        size_t totalSize = sizeof(msg_);
        channel->write(&msg_, totalSize);
        channel->flush();
    } else {
        // Unsupported version
        log::debug("MPTableStatsBuilder does not support the specified OpenFlow version:", ver);
    }
}

