using namespace llvm;

namespace {

// Verify that the timer accumulates time correctly across multiple start-stop cycles
TEST(Timer, Additivity) {
  Timer T("TimerTest");
  ASSERT_TRUE(T.isInitialized());

  // First measurement: minimal timing
  T.startTimer();
  T.stopTimer();
  auto Time1 = T.getTotalTime();

  // Second measurement: after a short delay
  T.startTimer();
  std::this_thread::sleep_for(std::chrono::milliseconds(1));
  T.stopTimer();
  auto Time2 = T.getTotalTime();

  // Confirm that accumulated time increased after the delay
  EXPECT_LT(Time1, Time2);
}

// Test the trigger state behavior of the timer
TEST(Timer, TriggerState) {
  Timer T("TriggerTest");

  // Initially, timer should not be triggered
  EXPECT_FALSE(T.hasTriggered());

  // After starting, it should be considered triggered
  T.startTimer();
  EXPECT_TRUE(T.hasTriggered());

  // Even after stopping, it remains triggered
  T.stopTimer();
  EXPECT_TRUE(T.hasTriggered());

  // Clearing resets the trigger state
  T.clear();
  EXPECT_FALSE(T.hasTriggered());
}

} // end anonymous namespace

