#include "SimpleString.h"
#include <cstring>
#include <cstdio>
#include <cstdlib>

// Constructor: initializes an empty string
SimpleString::SimpleString()
    : buffer(new char[1]) {
    buffer[0] = '\0';
}

// Constructor: initializes from a C-string
SimpleString::SimpleString(const char* otherBuffer)
    : buffer(new char[std::strlen(otherBuffer) + 1]) {
    std::strcpy(buffer, otherBuffer);
}

// Copy constructor: deep copy of another SimpleString
SimpleString::SimpleString(const SimpleString& other) {
    size_t len = other.size();
    buffer = new char[len + 1];
    std::strcpy(buffer, other.buffer);
}

// Assignment operator: deep copy with self-assignment check
SimpleString& SimpleString::operator=(const SimpleString& other) {
    if (this != &other) {
        delete[] buffer;
        size_t len = other.size();
        buffer = new char[len + 1];
        std::strcpy(buffer, other.buffer);
    }
    return *this;
}

// Returns the underlying C-string representation
char* SimpleString::asCharString() const {
    return buffer;
}

// Returns the length of the stored string
int SimpleString::size() const {
    return static_cast<int>(std::strlen(buffer));
}

// Destructor: frees allocated memory
SimpleString::~SimpleString() {
    delete[] buffer;
}

// Global equality operator: compares two SimpleString objects
bool operator==(const SimpleString& left, const SimpleString& right) {
    return std::strcmp(left.asCharString(), right.asCharString()) == 0;
}

