namespace base {

void safe_strerror_r(int err, char* buf, size_t len) {
#if defined(__GLIBC__) || \
   (defined(OS_ANDROID) && defined(_GNU_SOURCE) && __ANDROID_API__ >= 23)
  // Use GNU-specific strerror_r: returns char* (may be same as buf or static string)
  char* result = strerror_r(err, buf, len);
  if (result != buf) {
    // If result points elsewhere, copy it into buf safely
    snprintf(buf, len, "%s", result);
  }
#else
  // Use POSIX strerror_r: returns int error code
  int status = strerror_r(err, buf, len);
  if (status != 0) {
    // On error, provide informative fallback message
    int actual_errno = (status > 0) ? status : errno;
    snprintf(buf, len, "Error %d while retrieving error %d", actual_errno, err);
  }
#endif
}

std::string safe_strerror(int err) {
  char buffer[256];
  safe_strerror_r(err, buffer, sizeof(buffer));
  return std::string(buffer);
}

