// Display elements in a range
template<typename IteratorT>
void show(const range<IteratorT>& r)
{
    for (auto element : r)
        std::cout << element << " ";
    std::cout << std::endl;
}

// Compute the number of elements in a range
template<typename IteratorT>
size_t count_elements(const range<IteratorT>& r)
{
    return std::distance(r.begin(), r.end());
}

int main()
{
    // Initialize a list with specific values
    std::list<int> data_list{ 3, 1, 4, 22, 31 };

    // Create a range from the list's iterators
    auto first_range = make_range(data_list.begin(), data_list.end());

    // Show contents and size of the first range
    show(first_range);
    std::cout << "Element count: " << count_elements(first_range) << std::endl;

    // Copy list elements into a vector
    std::vector<int> data_vector;
    std::copy(data_list.begin(), data_list.end(), std::back_inserter(data_vector));

    // Create a second range covering only the first four elements of the vector
    auto range_end = std::next(data_vector.begin(), 4);
    auto second_range = make_range(data_vector.begin(), range_end);

    // Show contents and size of the second range
    show(second_range);
    std::cout << "Element count: " << count_elements(second_range) << std::endl;

    // Randomize and shuffle the second range
    randomize();
    std::shuffle(second_range.begin(), second_range.end(), global_urng());

    // Output shuffled second range
    std::copy(second_range.begin(), second_range.end(), std::ostream_iterator<int>(std::cout, " "));
    std::cout << std::endl;

    // Output original first range (unchanged by shuffling)
    std::copy(first_range.begin(), first_range.end(), std::ostream_iterator<int>(std::cout, " "));
    std::cout << std::endl;

    return 0;
}

