    cmd::CmdMessenger arduino(argv[1], 115200);

    // Set timeout for command responses
    cmd::Timeout timeout = cmd::Timeout::simpleTimeout(1000);
    arduino.setTimeout(timeout);

    // Define command ID for LED control
    const int kSetLedCmdId = 1; // Renamed enum value for clarity

    // Prepare command object for LED control
    cmd::Cmd ledCommand(kSetLedCmdId);

    char userChoice;
    while (true) {
        std::cout << "'1' turns on, '0' turns off, 'q' quits: ";
        std::cin >> userChoice;
        std::cout << std::endl;

        switch (userChoice) {
            case '1':
                ledCommand << true << cmd::CmdEnd();
                arduino.send(ledCommand);
                std::cout << ledCommand.getNumArgs() << std::endl;
                ledCommand.clear();
                break;

            case '0':
                ledCommand << false << cmd::CmdEnd();
                arduino.send(ledCommand);
                ledCommand.clear();
                break;

            case 'q':
                std::cout << "Exiting program...\n";
                return 0;

            default:
                std::cout << "Invalid input. Please enter '1', '0', or 'q'.\n";
                continue;
        }

