// Custom deleter struct with empty implementation
struct custom_deleter {
    void operator()(int* ptr) const noexcept {}
};

int main() {
    // Define two unique_ptr types with different deleters
    using pointer_type = int*;

    // Type T uses function pointer deleter (void (*)(int*))
    using smart_ptr_func = std::unique_ptr<int, void (*)(int*)>;

    // Type U uses struct-based deleter (custom_deleter)
    using smart_ptr_struct = std::unique_ptr<int, custom_deleter>;

    // Static assertions to check size characteristics
    static_assert(std::is_same_v<typename smart_ptr_func::deleter_type, void (*)(int*)>);
    static_assert(std::is_same_v<typename smart_ptr_struct::deleter_type, custom_deleter>);

    // Verify size difference due to deleter storage requirements
    static_assert(sizeof(smart_ptr_func) == sizeof(pointer_type) * 2);
    static_assert(sizeof(smart_ptr_struct) == sizeof(pointer_type));

    return 0;
}

