namespace base {

void CancellationFlag::Set() {
#if !defined(NDEBUG)
  // Verify the current thread is the one setting the flag
  DCHECK_EQ(set_on_, PlatformThread::CurrentId());
#endif
  // Atomically store the flag value with release semantics
  base::subtle::Release_Store(&flag_, 1);
}

bool CancellationFlag::IsSet() const {
  // Atomically load the flag value with acquire semantics
  int loaded_value = base::subtle::Acquire_Load(&flag_);
  return (loaded_value != 0);
}

