// Modified version of Atm_blink::begin with equivalent functionality
Atm_blink & Atm_blink::begin(int attached_pin, uint32_t blinkrate) {
  // Define state table in program memory with same transitions
  const static state_t state_table[] PROGMEM = {
    /*            ON_ENTER    ON_LOOP  ON_EXIT  EVT_TIMER   ELSE */
    /* LED_ON  */   ACT_ON,        -1,      -1,   LED_OFF,    -1,
    /* LED_OFF */  ACT_OFF,        -1,      -1,    LED_ON,    -1 };

  // Initialize the underlying machine with the state table and default transition
  Machine::begin(state_table, ELSE);

  // Store pin configuration and initialize timer
  pin = attached_pin;
  timer.begin(this, blinkrate);

  // Set up the pin as output
  pinMode(pin, OUTPUT);

  return *this;
}

// Event handler that processes timer events
int Atm_blink::event(int id) {
  switch (id) {
    case EVT_TIMER:
      // Check if timer has expired and return result
      return timer.expired();
  }
  return 0;
}

// Action handler that controls LED state
void Atm_blink::action(int id) {
  switch (id) {
    case ACT_ON:
      digitalWrite(pin, HIGH);
      return;
    case ACT_OFF:
      digitalWrite(pin, LOW);
      return;
  }
}

// Configure callback for state switches with custom names
Atm_blink & Atm_blink::onSwitch(swcb_sym_t switch_callback) {
  Machine::onSwitch(switch_callback, "LED_ON\0LED_OFF", "EVT_TIMER\0ELSE");
  return *this;
}

