// Configuration flags for the Dart VM initialization
static const char* kDartVMOptions[] = {
    "--enable_mirrors=false",
    "--load_deferred_eagerly=true",
};

void InitializeDartVM() {
  // Set VM-specific command-line arguments and verify success
  CHECK(Dart_SetVMFlags(arraysize(kDartVMOptions), kDartVMOptions));

  // Initialize the Dart runtime using the VM isolate snapshot
  // All additional parameters are null as per current usage
  CHECK(
      Dart_Initialize(
          reinterpret_cast<uint8_t*>(&kDartVmIsolateSnapshotBuffer),
          nullptr, nullptr, nullptr, nullptr,
          nullptr, nullptr, nullptr, nullptr,
          nullptr, nullptr, nullptr) == nullptr);
}

Dart_Isolate GenerateDartIsolate() {
  // Ensure the isolate snapshot buffer is available
  CHECK(kDartIsolateSnapshotBuffer);

  char* error_message = nullptr;

  // Create a new Dart isolate using the provided snapshot
  Dart_Isolate new_isolate = Dart_CreateIsolate(
      "dart:snapshot", 
      "main",
      reinterpret_cast<uint8_t*>(&kDartIsolateSnapshotBuffer),
      nullptr, nullptr, &error_message);

  // Verify isolate creation succeeded
  CHECK(new_isolate) << error_message;

  // Register the library tag handler and confirm no errors occurred
  CHECK(!LogIfError(Dart_SetLibraryTagHandler(HandleLibraryTag)));

  // Exit the isolate context before returning
  Dart_ExitIsolate();

  return new_isolate;
}

