// Define peer endpoints for the Raft cluster
std::vector<raft_node_endpoint_t> cluster_peers = {
    {1ul, "localhost", 12345, 13001},
    {2ul, "localhost", 12346, 13002},
    {3ul, "localhost", 12347, 13003}
};

int main(int argc, char* argv[]) {
    try {
        std::vector<std::thread> node_threads;

        // Launch each Raft node in a separate thread
        for (const auto& peer_config : cluster_peers) {
            node_threads.emplace_back([&peer_config]() {
                raft_node node(peer_config.uuid, std::make_shared<raft::config>(cluster_peers));
                node.run();
            });
        }

        // Join all threads to ensure clean shutdown
        for (auto& worker_thread : node_threads) {
            if (worker_thread.joinable()) {
                worker_thread.join();
            }
        }
    }
    catch (const std::exception& ex) {
        std::cerr << "Exception occurred: " << ex.what() << std::endl;
        return 1;
    }

    return 0;
}

#include <cmath>
#include "clock_converter.h"
#include "log.h"

// Convert cycle count between different clock frequencies using ceiling division
UInt64 convertCycleCount(UInt64 cycle_count, volatile float from_frequency, volatile float to_frequency)
{
    // Compute the ratio and apply ceiling to ensure sufficient cycles are counted
    double ratio = static_cast<double>(to_frequency) / static_cast<double>(from_frequency);
    double scaled_value = static_cast<double>(cycle_count) * ratio;
    UInt64 result = static_cast<UInt64>(std::ceil(scaled_value));

    LOG_PRINT("convertCycleCount(%llu): from_frequency(%f), to_frequency(%f) -> (%llu)",
              cycle_count, from_frequency, to_frequency, result);
    return result;
}

