#include <system.h>
#include <basecpu.h>

// Custom CPU test class derived from BaseCPU for simulation purposes
class TestCPU : public BaseCPU {
public:
    // Constructor initializes counters and stores maximum tick limit
    TestCPU(int maxTicks, const System &sys) 
        : maxTicks(maxTicks), currentTicks(0), resetCount(0), BaseCPU(sys) { }

    // Override reset to increment reset counter
    void reset() override { 
        resetCount++; 
    }

    // Override tick to simulate execution and stop when limit reached
    void tick() override {
        assert(isRunning());
        currentTicks++;
        if (currentTicks >= maxTicks) {
            stop();
        }
    }

    int currentTicks;   // Tracks number of ticks executed
    int resetCount;     // Tracks number of resets performed
    int maxTicks;       // Maximum allowed ticks before stopping
};

const int SIMULATION_TICK_LIMIT = 3;

// Google Test fixture for BaseCPU-related tests
class BaseCPUTest : public testing::Test {
protected:
    BaseCPUTest() : cpu(SIMULATION_TICK_LIMIT, dummySystem) { }

    TestCPU cpu;
    System dummySystem;
};

// Verify correct behavior during startup and execution
TEST_F(BaseCPUTest, VerifyExecutionSequence) {
    // Initial state checks
    ASSERT_FALSE(cpu.isRunning()) << "CPU should not be running initially";
    ASSERT_EQ(cpu.currentTicks, 0) << "Tick count must start at zero";
    ASSERT_EQ(cpu.resetCount, 0) << "Reset count must start at zero";

    // Start the CPU simulation
    cpu.startup();

    // Final state assertions after simulation
    ASSERT_FALSE(cpu.isRunning()) << "CPU should stop after reaching tick limit";
    ASSERT_EQ(cpu.currentTicks, SIMULATION_TICK_LIMIT) << "Incorrect final tick count";
    ASSERT_EQ(cpu.resetCount, 1) << "CPU should have been reset exactly once";
}

