// Constructor: opens the SQLite database file
Database::Database(string filename) {
    char dbPath[256];
    // Safely copy the string to a C-style character array
    snprintf(dbPath, sizeof(dbPath), "%s", filename.c_str());
    sqlite3_open(dbPath, &db);
}

// Destructor: closes the database connection
Database::~Database() { 
    if (db) {
        sqlite3_close(db); 
    }
}

// Callback function for sqlite3_exec to process query results
int resultHandler(void *userData, int fieldCount, char **fieldValues, char **fieldNames) {
    // Cast user data to expected type: reference to vector of vectors of strings
    vector<vector<string>> &queryResults = 
        *(static_cast<vector<vector<string>> *>(userData));

    vector<string> currentRow;

    // Process each column in the current row
    for (int idx = 0; idx < fieldCount; ++idx) {
        string value = fieldValues[idx] ? fieldValues[idx] : "NULL";
        currentRow.push_back(value);
        cout << value << ", ";
    }

    // Store the completed row
    queryResults.push_back(currentRow);
    return 0;
}

// Execute SQL command and return results as vector of rows
vector<vector<string>> Database::runQuery(string sqlStatement) const {
    cout << "Running SQL: " << sqlStatement << endl;
    cout << "Result set: ";

    vector<vector<string>> outputData;
    char *errorMsg = nullptr;

    // Execute the SQL statement with callback processing
    int executionResult = sqlite3_exec(
        db, 
        sqlStatement.c_str(), 
        resultHandler, 
        &outputData, 
        &errorMsg
    );

    cout << endl;
    cout << "Execution status: " << executionResult;

    // Handle any errors
    if (errorMsg) {
        cout << ", Error: " << errorMsg;
        sqlite3_free(errorMsg);
    }
    cout << endl;

    return outputData;
}

#include <iostream>
using namespace std;

// Shell sort implementation using different variable names and loop structure
int shellSort(int data[], int size) {
    // Start with a large gap, then reduce the gap
    for (int gap = size / 2; gap > 0; gap /= 2) {
        // Perform insertion sort for elements at gap intervals
        for (int idx = gap; idx < size; idx++) {
            int temp = data[idx];
            int pos = idx;

            // Shift earlier gap-sorted elements until correct location is found
            while (pos >= gap && data[pos - gap] > temp) {
                data[pos] = data[pos - gap];
                pos -= gap;
            }

            // Place temp in its correct position
            data[pos] = temp;
        }
    }
    return 0;
}

int main() {
    int count, array[10000];

    // Read number of elements
    cin >> count;

    // Read array elements
    for (int i = 0; i < count; i++) {
        cin >> array[i];
    }

    // Sort the array
    shellSort(array, count);

    // Output sorted array
    cout << "Array after sorting: \n";
    for (int i = 0; i < count; i++) {
        cout << array[i] << " ";
    }
    cout << endl;

    return 0;
}

