#include <iostream>

template <class R> class Returner {};
template <class A> class Derived;
template <class A>
class Base
{
  static Derived<A>* create();
};
template <class A>
class Derived : public Base<A> {
public:
  static void foo();
};
class Foo
{
  Foo();
  static Returner<Base<Foo> > all();
};
Foo::Foo(){}

// Helper function to handle the recursion differently
Returner<Base<Foo> > Foo::all()
{
  // Call the derived class method first
  Derived<Foo>::foo();

  // Create a local instance for the return value
  Returner<Base<Foo> > result;

  // Instead of direct recursion, we could use iteration or other patterns
  // For this clone, we'll keep similar behavior but with clearer structure
  return result;
}

