    rng_split_b.split(3, 1);

    trng::lcg64_shift rng_split_c;
    rng_split_c.split(3, 2);

    trng::lcg64_shift rng_jump_variant_1;
    trng::lcg64_shift rng_jump_variant_2;

    std::cout << "# default, seed 111, split 3-0, split 3-1, split 3-2, jump-6361, jump2-5657" << std::endl;

    for (int idx = 0; idx < 1009; ++idx) {
        std::cout << static_cast<long long>(rng_default()) << ',';
        std::cout << static_cast<long long>(rng_seed_111()) << ',';
        std::cout << static_cast<long long>(rng_split_a()) << ',';
        std::cout << static_cast<long long>(rng_split_b()) << ',';
        std::cout << static_cast<long long>(rng_split_c()) << ',';

        rng_jump_variant_1.jump(idx);
        std::cout << static_cast<long long>(rng_jump_variant_1()) << ',';

        rng_jump_variant_2.jump2(idx % 64);
        std::cout << static_cast<long long>(rng_jump_variant_2()) << '\n';
    }

