  std::string param_prefix = "pattern";
  if (!nh.getParam(param_prefix, pattern_names)) {
    return;
  }

  for (const auto& entry : pattern_names) {
    const std::string& key = entry.first;
    const std::string& value = entry.second;

    std::vector<double> posture_config;
    std::string full_param_name = param_prefix + "/" + value;

    if (!nh.getParam(full_param_name, posture_config)) {
      return;
