// Converts Bish AST to bash script and outputs to given stream
void translate_to_bash(std::ostream &out, Bish::AST *tree) {
    out << "#!/bin/bash\n";
    Bish::CompileToBash translator(out);
    tree->accept(&translator);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <SOURCE_FILE>\n";
        std::cerr << "  Translates a Bish source file into bash script.\n";
        return 1;
    }

    std::string filename(argv[1]);
    Bish::Parser parser;
    Bish::AST *ast = parser.parse(filename);
    translate_to_bash(std::cout, ast);

    return 0;
}

