// Regression test for bug captured in #1347 - Type III clone with modified logic
BOOST_AUTO_TEST_CASE(regression_test_1347_variant)
{
    // Create coordinates with slightly different initialization approach
    FixedPointCoordinate start_point;
    start_point.lat = 10 * COORDINATE_PRECISION;
    start_point.lon = -100 * COORDINATE_PRECISION;

    FixedPointCoordinate end_point;
    end_point.lat = static_cast<int>(10.001 * COORDINATE_PRECISION);
    end_point.lon = static_cast<int>(-100.002 * COORDINATE_PRECISION);

    FixedPointCoordinate test_point;
    test_point.lat = static_cast<int>(10.002 * COORDINATE_PRECISION);
    test_point.lon = static_cast<int>(-100.001 * COORDINATE_PRECISION);

    // First distance calculation using original method signature
    float distance_simple = FixedPointCoordinate::ComputePerpendicularDistance(start_point, end_point, test_point);

    // Second calculation with additional output parameters
    float ratio_value = 0.0f;
    FixedPointCoordinate closest_point;
    float distance_with_params = FixedPointCoordinate::ComputePerpendicularDistance(
        start_point, end_point, test_point, closest_point, ratio_value);

    // Verify the two distance calculations are within tolerance
    BOOST_CHECK_LE(std::abs(distance_simple - distance_with_params), 0.01f);
}

