__attribute__((no_sanitize("thread")))
void PerformExternalWrite(void *memory_address) {
  __tsan_external_write(memory_address, __builtin_return_address(0), external_tag);
}
int main(int argc, char *argv[]) {
  barrier_init(&barrier, 2);
  external_tag = __tsan_external_register_tag("HelloWorld");
  fprintf(stderr, "Start.\n");
  // CHECK: Start.

  int phase1_counter = 0;
  while (phase1_counter < 4) {
    void *opaque_object = malloc(16);
    std::thread worker1([opaque_object] {
      PerformExternalWrite(opaque_object);
      barrier_wait(&barrier);
    });
    std::thread worker2([opaque_object] {
      barrier_wait(&barrier);
      PerformExternalWrite(opaque_object);
    });
    // CHECK: WARNING: ThreadSanitizer: race on a library object
    worker1.join();
    worker2.join();
    phase1_counter++;
  }

  fprintf(stderr, "First phase done.\n");
  // CHECK: First phase done.
  int phase2_counter = 0;
  while (phase2_counter < 4) {
    void *opaque_object = malloc(16);
    std::thread worker1([opaque_object] {
      PerformExternalWrite(opaque_object);
      barrier_wait(&barrier);
    });
    std::thread worker2([opaque_object] {
