// Create a Status object using printf-style arguments with variable arguments
Status ToStatusF(Code code, const char* format, ...) {
    va_list args;
    va_start(args, format);

    char* message_buffer = nullptr;
    if (vasprintf(&message_buffer, format, args) < 0) {
        abort();
    }

    va_end(args);

    Status result(code, message_buffer);
    free(message_buffer);

    return result;
