namespace {

// Wrapper function to intercept and process consume hit events
void __declspec(naked) onConsumeHit() {
    static CUnit *victim, *attacker;

    __asm {
        PUSHAD              // Save all general-purpose registers
        MOV attacker, ESI   // Store the caster/unit performing the action
        MOV victim, EAX     // Store the target/unit being hit
    }

    // Delegate to the custom hook handler
    hooks::onConsumeHit(victim, attacker);

    __asm {
        POPAD               // Restore all general-purpose registers
        RETN                // Return to original execution flow
    }
}

} // unnamed namespace

namespace hooks {

// Install the hook at the specified memory location
void applyConsumeHooks() {
    callPatch(onConsumeHit, 0x0048BB27);
}

} // hooks

