}

void LocalServer::respond(std::size_t length) {
    std::cout << "Remote address: " << remote_endpoint_ << std::endl;
    socket_.async_send_to(
        boost::asio::buffer(buffer_, length),
        remote_endpoint_,
        [this](boost::system::error_code err, std::size_t /*sent*/) {
            if (!err) {
                start_receiving();
            }
        }
    );
}

void LocalServer::process_incoming_message(boost::system::error_code error, std::size_t received_bytes) {
    if (!error && received_bytes > 0) {
        std::cout << "Received: '";
        std::cout.write(buffer_, received_bytes);
        std::cout << "'" << std::endl;
        respond(received_bytes);
        return;
    }

    if (error == boost::asio::error::message_size) {
        std::cerr << "Warning: incoming message exceeds buffer capacity" << std::endl;
        // TODO: send appropriate error response
    }

    start_receiving();
}

}

