// Type III clone: restructuring control flow and renaming identifiers while preserving behavior
int main() {
    struct Base {
        void bar(int i) {
            std::cout << "Base::bar(int)" << std::endl;
        }
    protected:
        int value = 0;
    };

    struct Derived1 : virtual public Base {
        void bar(char c) {
            std::cout << "Derived1::bar(char)" << std::endl;
        }
        void process_char(char c) {
            std::cout << "Derived1::process_char(char)" << std::endl;
        }
    protected:
        char letter = 'c';
    };

    struct Derived2 : virtual public Base {
        void process_int(int i) {
            std::cout << "Derived2::process_int(int)" << std::endl;
        }
    protected:
        int value = 1;
        char letter = 'd';
    };

    class VMI : public Derived1, public Derived2 {
    public:
        void show_base_value() {
            std::cout << Base::value << std::endl;
        }

        void show_derived_letter() {
            std::cout << Derived1::letter << std::endl;
        }
    };

    VMI instance;
    instance.show_base_value();
    instance.show_derived_letter();
    instance.Derived1::process_char('c');
    instance.bar(1);
    instance.bar('c');
    instance.Base::bar(1);

    return 0;
}

