#include <cmath>
#include <ros/ros.h>
#include <rviz_visual_tools/rviz_visual_tools.h>
#include <tf2_eigen/tf2_eigen.h>
#include <tf2_ros/transform_listener.h>
#include <Eigen/Geometry>

int main(int argc, char** argv)
{
  ros::init(argc, argv, "body_angle_visualizer");
  ros::NodeHandle nh {};
  ros::Rate loop_rate {5};

  tf2_ros::Buffer tf_cache {};
  tf2_ros::TransformListener tf_subscriber {tf_cache};
  rviz_visual_tools::RvizVisualTools visualizer {"openni_depth_frame", "rviz_visual_markers"};

  do {
    try {
      // Get transforms manually using tf2::convert to avoid direct transformToEigen usage
      geometry_msgs::TransformStamped head_msg = tf_cache.lookupTransform("openni_depth_frame", "head_1", ros::Time{0});
      geometry_msgs::TransformStamped torso_msg = tf_cache.lookupTransform("openni_depth_frame", "torso_1", ros::Time{0});

      Eigen::Vector3d head_translation;
      Eigen::Quaterniond head_rotation;
      tf2::convert(head_msg.transform.translation, head_translation);
      tf2::convert(head_msg.transform.rotation, head_rotation);

      Eigen::Vector3d torso_translation;
      Eigen::Quaterniond torso_rotation;
      tf2::convert(torso_msg.transform.translation, torso_translation);
      tf2::convert(torso_msg.transform.rotation, torso_rotation);

      // Compute direction vector from torso to head
      Eigen::Vector3d direction_vector = head_translation - torso_translation;

      // Ensure non-zero vector; if zero, default to X-axis
      if (direction_vector.norm() < 1e-6) {
        direction_vector = Eigen::Vector3d::UnitX();
      }

      // Create orientation that aligns X-axis with direction_vector
      Eigen::Quaterniond orientation = Eigen::Quaterniond::FromTwoVectors(Eigen::Vector3d::UnitX(), direction_vector);

      // Build transformation: position at torso, oriented by computed quaternion
      Eigen::Isometry3d arrow_transform = Eigen::Isometry3d::Identity();
      arrow_transform.translation() = torso_translation;
      arrow_transform.linear() = orientation.matrix();

      // Clear previous markers and publish new arrow
      visualizer.deleteAllMarkers();
      visualizer.publishArrow(arrow_transform);
      visualizer.trigger();
    } catch (const tf2::TransformException& ex) {
      ROS_WARN_STREAM("TF lookup failed: " << ex.what());
    }

    ros::spinOnce();
    loop_rate.sleep();
  } while (ros::ok());

  return 0;
}

