struct NixArgs : virtual MultiCommand, virtual MixCommonArgs
{
    NixArgs() : MultiCommand(*RegisterCommand::commands), MixCommonArgs("nix")
    {
        mkFlag('h', "help", "display this help message", [=]() {
            printHelp(programName, std::cout);
            std::cout << "\nNote: this program is EXPERIMENTAL and subject to change.\n";
            throw Exit();
        });
        mkFlag(0, "version", "print version details", std::bind(printVersion, programName));
    }
};

void mainWrapped(int argc, char * * argv)
{
    initNix();
    initGC();
    std::string programName = baseNameOf(argv[0]);

    // Check for legacy command handlers first
    auto it = (*RegisterLegacyCommand::commands).find(programName);
    if (it != (*RegisterLegacyCommand::commands).end() && it->second) {
        it->second(argc, argv);
        return;
    }

    NixArgs args;
    args.parseCmdline(argvToStrings(argc, argv));

    if (!args.command) {
        throw UsageError("no command specified");
    }

    args.command->prepare();
    args.command->run();
}

}

int main(int argc, char * * argv)
{
    return nix::handleExceptions(argv[0], [&]() {
        nix::mainWrapped(argc, argv);
    });
}

