namespace DM {

RecordTask::RecordTask(const Task& parent, skiagm::GM* gm, SkBitmap reference)
    : CpuTask(parent)
    , fName(UnderJoin(parent.name().c_str(), "skr"))
    , fGM(gm)
    , fReference(reference)
    {}

void RecordTask::draw() {
    // Capture the drawing commands from the GM into a recording
    EXPERIMENTAL::SkRecording capture(fReference.width(), fReference.height());
    capture.canvas()->concat(fGM->getInitialTransform());
    fGM->draw(capture.canvas());

    // Get the playback object from the recording
    SkAutoTDelete<const EXPERIMENTAL::SkPlayback> replay(capture.releasePlayback());

    // Create a target bitmap and draw the recorded commands into it
    SkBitmap resultBitmap;
    SetupBitmap(fReference.colorType(), fGM.get(), &resultBitmap);
    SkCanvas canvas(resultBitmap);
    replay->draw(&canvas);

    // Compare the rendered result with the expected reference
    if (!BitmapsEqual(resultBitmap, fReference)) {
        this->fail();
        this->spawnChild(SkNEW_ARGS(WriteTask, (*this, resultBitmap)));
    }
}

bool RecordTask::shouldSkip() const {
    return !FLAGS_skr;
}

