namespace native
{
    // Use a different random engine instance (still default_random_engine)
    static std::default_random_engine rng_engine;

    // Compute square root using standard library with explicit casting
    double Math::sqrt(double value)
    {
        return static_cast<double>(std::sqrt(static_cast<long double>(value)));
    }

    // Generate random number in range [min, max) for long double
    long double Math::random(long double min_val, long double max_val)
    {
        std::uniform_real_distribution<long double> dist(min_val, max_val);
        return dist(rng_engine);
    }

    // Generate random number in range [min, max) for double
    double Math::random(double min_val, double max_val)
    {
        std::uniform_real_distribution<double> dist(min_val, max_val);
        return dist(rng_engine);
    }

    // Generate random number in range [min, max) for float
    float Math::random(float min_val, float max_val)
    {
        std::uniform_real_distribution<float> dist(min_val, max_val);
        return dist(rng_engine);
    }

    // Generate random integer in range [min, max)
    int Math::random(int min_val, int max_val)
    {
        std::uniform_real_distribution<double> dist(static_cast<double>(min_val), 
                                                    static_cast<double>(max_val));
        return static_cast<int>(dist(rng_engine));
    }
