#include <QDebug>
#include "../QPubNub.h"

int main(int argc, char *argv[]) {
    QCoreApplication app(argc, argv);

    QNetworkAccessManager manager;
    QPubNub pubnub(&manager);

    // Set up trace logging
    QObject::connect(&pubnub, &QPubNub::trace, [](const QString &msg) {
        qDebug() << "Trace:" << qPrintable(msg);
    });

    // Get current time from PubNub service
    pubnub.time();

    // Configure credentials
    pubnub.setPublishKey("demo");
    pubnub.setSubscribeKey("demo");

    // Handle errors
    QObject::connect(&pubnub, &QPubNub::error, [](const QString &err, int /*code*/) {
        qDebug() << "Error:" << qPrintable(err);
    });

    // Set encryption key
    pubnub.setCipherKey("enigma");

    // Publish a test message
    pubnub.publish("qwertz", QJsonValue(QString("test")));

    // Subscribe to the same channel
    pubnub.subscribe("qwertz");

    // Handle incoming messages
    QObject::connect(&pubnub, &QPubNub::message, [](const QJsonValue &val, const QString &timeToken, const QString &channel) {
        qDebug().nospace() << "[" << qPrintable(channel) << "]:" << val;
    });

    return app.exec();
}

