// Unit tests for the Text and Utf16 string classes in apLib
TEST_CASE("string::Str") {
    SECTION("Text functionality") {
        // Test implicit conversion from string literal
        SECTION("Implicit cast") {
            Text test = "test";
            REQUIRE(!Txtcmp(test, "test"));
            REQUIRE(static_cast<bool>(test));
        }

        // Test move assignment operator
        SECTION("Move assign") {
            Text source = "Hi";
            Text target = std::move(source);
            REQUIRE(target == "Hi");
            REQUIRE(source.empty());

            Text another = std::move(target);
            REQUIRE(target.empty());
            REQUIRE(another == "Hi");
        }

        // Test move constructor
        SECTION("Move construct") {
            Text original = "Hi";
            Text copy(std::move(original));
            REQUIRE(copy == "Hi");
            REQUIRE(original.empty());

            Text final = std::move(copy);
            REQUIRE(copy.empty());
            REQUIRE(final == "Hi");
        }

        // Test comparison operators
        SECTION("Comparison") {
            REQUIRE(Text("hi there") < Text("hi there1"));
            REQUIRE(Text("hi there1") > Text("hi there"));
            REQUIRE_FALSE(Text("hi there") > Text("hi there"));
            REQUIRE_FALSE(Text("hi there") < Text("hi there"));
        }

        // Test case conversion methods
        SECTION("lowerCase") {
            REQUIRE(Text("WHY ARE YOU YELLING").lowerCase() == "why are you yelling");
        }

        SECTION("upperCase") {
            REQUIRE(Text("i can't hear you").upperCase() == "I CAN'T HEAR YOU");
        }

        // Test whitespace trimming
        SECTION("trim") {
            REQUIRE(Text("   i can't hear you    ").trim() == "i can't hear you");
        }

        // Test quote removal
        SECTION("removeQuotes") {
            REQUIRE(Text("\"Fact\"").removeQuotes() == "Fact");
        }

        // Test string splitting
        SECTION("split") {
            auto parts = Text(",1,2,3,4,").split(',');
            REQUIRE(parts == std::vector<Text>{"1", "2", "3", "4"});

            parts = Text(",1,2,3,4,").split(',', true);
            REQUIRE(parts == std::vector<Text>{"", "1", "2", "3", "4", ""});
        }

        // Test concatenation with separator
        SECTION("concat") {
            REQUIRE(concat(std::vector<Text>{"1", "2", "3", "4"}, ",") == "1,2,3,4");
            REQUIRE(concat(std::vector<Text>{"1", "2", "3", "4"}, "") == "1234");
            REQUIRE(concat(std::vector<Text>{"1", "2", "", "4"}, ",", false) == "1,2,4");
            REQUIRE(concat(std::vector<Text>{"1", "2", "", "4"}, ",", true) == "1,2,,4");
        }

        // Test suffix checking
        SECTION("endsWith") {
            REQUIRE(Text("There once was a").endsWith("once was a"));
            REQUIRE(Text("There once was a").endsWith("nce was a"));
            REQUIRE(Text("There once was a").endsWith("ce was a"));
            REQUIRE(Text("There once was a").endsWith("e was a"));
            REQUIRE(Text("There once was a").endsWith("a"));
            REQUIRE_FALSE(Text("There once was a").endsWith(""));

            // Case-insensitive checks
            REQUIRE(Text("There once was a").endsWith("once was A", false));
            REQUIRE(Text("There once was a").endsWith("nce Was a", false));
            REQUIRE(Text("There once was a").endsWith("cE was a", false));
            REQUIRE(Text("There once was a").endsWith("e was A", false));
            REQUIRE(Text("There once was a").endsWith("A", false));

            // Case-sensitive checks should fail
            REQUIRE_FALSE(Text("There once was a").endsWith("once was A", true));
            REQUIRE_FALSE(Text("There once was a").endsWith("nce Was a", true));
            REQUIRE_FALSE(Text("There once was a").endsWith("cE was a", true));
            REQUIRE_FALSE(Text("There once was a").endsWith("e was A", true));
            REQUIRE_FALSE(Text("There once was a").endsWith("A", true));
        }

        // Test prefix checking
        SECTION("startsWith") {
            REQUIRE(Text("There once was a").startsWith("There once was a"));
            REQUIRE(Text("There once was a").startsWith("There once "));
            REQUIRE(Text("There once was a").startsWith("There "));
            REQUIRE(Text("There once was a").startsWith("T"));
            REQUIRE_FALSE(Text("There once was a").startsWith(""));

            // Case-insensitive checks
            REQUIRE(Text("There once was a").startsWith("there Once was a", false));
            REQUIRE(Text("There once was a").startsWith("there once ", false));
            REQUIRE(Text("There once was a").startsWith("ThErE", false));
            REQUIRE(Text("There once was a").startsWith("t", false));

            // Case-sensitive checks should fail
            REQUIRE_FALSE(Text("There once was a").startsWith("there Once was a", true));
            REQUIRE_FALSE(Text("There once was a").startsWith("there once ", true));
            REQUIRE_FALSE(Text("There once was a").startsWith("ThErE", true));
            REQUIRE_FALSE(Text("There once was a").startsWith("t", true));
        }

        // Test string removal operations
        SECTION("remove") {
            REQUIRE(Text("DO NOT CENSOR ME").remove("NOT ") == "DO CENSOR ME");
            REQUIRE(Text("DO NOT NOT NOT CENSOR ME").remove("NOT ") == "DO CENSOR ME");
            REQUIRE(Text("I SAID, DO NOT CENSOR ME")
                        .remove("I ", "SAID, ", " NOT") == "DO CENSOR ME");
        }

        // Test string replacement
        SECTION("replace") {
            REQUIRE(Text("DO NOT CENSOR ME").replace("DO NOT ", "DO ") == "DO CENSOR ME");
            REQUIRE(Text("DO NOT NOT NOT CENSOR ME").replace("NOT ", "") == "DO CENSOR ME");
            REQUIRE(Text("I SAID, DO NOT CENSOR ME")
                        .replace("I SAID, ", "I DIDN'T SAY, ") == "I DIDN'T SAY, DO NOT CENSOR ME");
        }

        // Test character replacement
        SECTION("replaceAnyOf") {
            REQUIRE(Text("ABCDEF").replaceAnyOf("ACF", 'X') == "XBXDEX");
        }

        // Test append with rvalue reference
        SECTION("Append rvalue") {
            Text left;
            Text right("right");
            left.append(_mv(right));
            REQUIRE(left == "right");
            REQUIRE(right.empty());
        }

        // Test += operator with rvalue reference
        SECTION("operator += rvalue") {
            Text left;
            Text right("right");
            left += _mv(right);
            REQUIRE(left == "right");
            REQUIRE(right.empty());
        }

        // Test substring operations
        SECTION("substr") {
            using string::npos;
            Text str("excellent");

            auto verify = [&](size_t pos, size_t count, TextView expected) {
                REQUIRE(str.substr(pos, count) == expected);
                REQUIRE(str.substrView(pos, count) == expected);
