            REQUIRE(Utf16ieql(L"Do you equal me", L"Do you equal me"));
            REQUIRE_FALSE(Utf16eql(L"Do you equal me", L"do you equal me"));
            REQUIRE(Utf16ieql(L"Do you equal me", L"do you equal me"));
        }

        // Test string removal operations
        SECTION("remove") {
            REQUIRE(Utf16(L"DO NOT CENSOR ME").remove(L"NOT ") == L"DO CENSOR ME");
            REQUIRE(Utf16(L"DO NOT NOT NOT CENSOR ME").remove(L"NOT ") == L"DO CENSOR ME");
            REQUIRE(Utf16(L"I SAID, DO NOT CENSOR ME")
                        .remove(L"I ", L"SAID, ", L" NOT") == L"DO CENSOR ME");
        }

        // Test string replacement
        SECTION("replace") {
            REQUIRE(Utf16(L"DO NOT CENSOR ME").replace(L"DO NOT ", L"DO ") == L"DO CENSOR ME");
            REQUIRE(Utf16(L"DO NOT NOT NOT CENSOR ME").replace(L"NOT ", L"") == L"DO CENSOR ME");
            REQUIRE(Utf16(L"I SAID, DO NOT CENSOR ME")
                        .replace(L"I SAID, ", L"I DIDN'T SAY, ") == L"I DIDN'T SAY, DO NOT CENSOR ME");
        }
    }
#endif
}

