    generate_curl(), generate_cool_warm()
}};

// Helper function to get colormap by index
const std::array<unsigned char, 3>& get_color(const std::array<std::array<unsigned char, 3>, 256>& table, int idx) {
    return table[idx];
}

// Get colormap table by type
std::array<std::array<unsigned char, 3>, 256> colormap_table(COLORMAP type) {
    return colormap_data[static_cast<int>(type)];
}

// Get individual color as Vector4i
Eigen::Vector4i colormap(COLORMAP type, int x) {
    x = std::max(0, std::min(255, x));
    const auto& table = colormap_data[static_cast<int>(type)];
    return Eigen::Vector4i(table[x][0], table[x][1], table[x][2], 255);
}

// Get individual color as Vector4f
Eigen::Vector4f colormapf(COLORMAP type, float x_) {
    int x = std::max<int>(0, std::min<int>(255, static_cast<int>(x_ * 255.0f)));
    return colormap(type, x).cast<float>() / 255.0f;
}

// Categorical colormap
Eigen::Vector4i colormap_categorical(COLORMAP type, int x_, int num_categories) {
    x_ = x_ % num_categories;
    int step = 256 / num_categories;
    int x = x_ * step + step / 2;
    return colormap(type, x);
}

// Categorical colormap with float output
Eigen::Vector4f colormap_categoricalf(COLORMAP type, int x_, int num_categories) {
    x_ = x_ % num_categories;
    int step = 256 / num_categories;
    int x = x_ * step + step / 2;
    return colormapf(type, static_cast<float>(x) / 255.0f);
}

