int main(int argc, char *argv[])
{
  // Initialize ROS node with a unique name based on the robot
  const std::string robotName = "humanoid";
  ros::init(argc, argv, robotName + "_gait_publisher");
  ros::NodeHandle nh;

  // Retrieve gait command file path from parameter server
  std::string gaitConfigPath;
  nh.getParam("/gaitCommandFile", gaitConfigPath);

  // Log the loaded configuration file for debugging
  std::cerr << "Loading gait configuration: " << gaitConfigPath << std::endl;

  // Instantiate the gait publisher with keyboard input support
  humanoid::GaitKeyboardPublisher gaitPublisher(nh, gaitConfigPath, robotName, true);

  // Main event loop - continue until shutdown signal received or ROS master unavailable
  while (ros::ok() && ros::master::check())
  {
    gaitPublisher.processKeyboardInput();
  }

  return 0;
}

#include "llvm/DWARFLinker/DWARFLinkerBase.h"
#include "llvm/ADT/StringSwitch.h"
using namespace llvm;
using namespace llvm::dwarf_linker;

std::optional<DebugSectionKind>
llvm::dwarf_linker::parseDebugTableName(llvm::StringRef SecName) {
  // Extract the actual section name by stripping leading '.' or '_' characters
  StringRef CleanName = SecName.drop_while([](char C) { return C == '.' || C == '_'; });

  // Use StringSwitch to map cleaned section names to DebugSectionKind enum values
  return StringSwitch<std::optional<DebugSectionKind>>(CleanName)
      .Case(getSectionName(DebugSectionKind::DebugInfo), DebugSectionKind::DebugInfo)
      .Case(getSectionName(DebugSectionKind::DebugLine), DebugSectionKind::DebugLine)
      .Case(getSectionName(DebugSectionKind::DebugFrame), DebugSectionKind::DebugFrame)
      .Case(getSectionName(DebugSectionKind::DebugRange), DebugSectionKind::DebugRange)
      .Case(getSectionName(DebugSectionKind::DebugRngLists), DebugSectionKind::DebugRngLists)
      .Case(getSectionName(DebugSectionKind::DebugLoc), DebugSectionKind::DebugLoc)
      .Case(getSectionName(DebugSectionKind::DebugLocLists), DebugSectionKind::DebugLocLists)
      .Case(getSectionName(DebugSectionKind::DebugARanges), DebugSectionKind::DebugARanges)
      .Case(getSectionName(DebugSectionKind::DebugAbbrev), DebugSectionKind::DebugAbbrev)
      .Case(getSectionName(DebugSectionKind::DebugMacinfo), DebugSectionKind::DebugMacinfo)
      .Case(getSectionName(DebugSectionKind::DebugMacro), DebugSectionKind::DebugMacro)
      .Case(getSectionName(DebugSectionKind::DebugAddr), DebugSectionKind::DebugAddr)
      .Case(getSectionName(DebugSectionKind::DebugStr), DebugSectionKind::DebugStr)
      .Case(getSectionName(DebugSectionKind::DebugLineStr), DebugSectionKind::DebugLineStr)
      .Case(getSectionName(DebugSectionKind::DebugStrOffsets), DebugSectionKind::DebugStrOffsets)
      .Case(getSectionName(DebugSectionKind::DebugPubNames), DebugSectionKind::DebugPubNames)
      .Case(getSectionName(DebugSectionKind::DebugPubTypes), DebugSectionKind::DebugPubTypes)
      .Case(getSectionName(DebugSectionKind::DebugNames), DebugSectionKind::DebugNames)
      .Case(getSectionName(DebugSectionKind::AppleNames), DebugSectionKind::AppleNames)
      .Case(getSectionName(DebugSectionKind::AppleNamespaces), DebugSectionKind::AppleNamespaces)
      .Case(getSectionName(DebugSectionKind::AppleObjC), DebugSectionKind::AppleObjC)
      .Case(getSectionName(DebugSectionKind::AppleTypes), DebugSectionKind::AppleTypes)
      .Default(std::nullopt);
}

