template <>
struct MappingTraits<Kernel::Attrs::Metadata> {
  static void mapping(IO &YIO, Kernel::Attrs::Metadata &MD) {
    auto mapOptVec = [&](const char *key, std::vector<uint32_t> &val) {
      YIO.mapOptional(key, val, std::vector<uint32_t>{});
    };
    auto mapOptStr = [&](const char *key, std::string &val) {
      YIO.mapOptional(key, val, std::string{});
    };

    mapOptVec(Kernel::Attrs::Key::ReqdWorkGroupSize, MD.mReqdWorkGroupSize);
    mapOptVec(Kernel::Attrs::Key::WorkGroupSizeHint, MD.mWorkGroupSizeHint);
    mapOptStr(Kernel::Attrs::Key::VecTypeHint, MD.mVecTypeHint);
    mapOptStr(Kernel::Attrs::Key::RuntimeHandle, MD.mRuntimeHandle);
  }
};

// --- Kernel::Arg::Metadata ---
template <>
struct MappingTraits<Kernel::Arg::Metadata> {
  static void mapping(IO &YIO, Kernel::Arg::Metadata &MD) {
    auto mapOptStr = [&](const char *key, std::string &val) {
      YIO.mapOptional(key, val, std::string{});
    };
    auto mapOptEnum = [&](const char *key, auto &val, auto def) {
      YIO.mapOptional(key, val, def);
    };

    mapOptStr(Kernel::Arg::Key::Name, MD.mName);
    mapOptStr(Kernel::Arg::Key::TypeName, MD.mTypeName);
    YIO.mapRequired(Kernel::Arg::Key::Size, MD.mSize);
    YIO.mapRequired(Kernel::Arg::Key::Align, MD.mAlign);
    YIO.mapRequired(Kernel::Arg::Key::ValueKind, MD.mValueKind);

    // Hidden deprecated field: kept for parsing only
    std::optional<ValueType> unusedValType;
    YIO.mapOptional(Kernel::Arg::Key::ValueType, unusedValType);

    mapOptEnum(Kernel::Arg::Key::PointeeAlign, MD.mPointeeAlign, uint32_t(0));
    mapOptEnum(Kernel::Arg::Key::AddrSpaceQual, MD.mAddrSpaceQual,
               AddressSpaceQualifier::Unknown);
    mapOptEnum(Kernel::Arg::Key::AccQual, MD.mAccQual,
               AccessQualifier::Unknown);
    mapOptEnum(Kernel::Arg::Key::ActualAccQual, MD.mActualAccQual,
               AccessQualifier::Unknown);
    mapOptEnum(Kernel::Arg::Key::IsConst, MD.mIsConst, false);
    mapOptEnum(Kernel::Arg::Key::IsRestrict, MD.mIsRestrict, false);
    mapOptEnum(Kernel::Arg::Key::IsVolatile, MD.mIsVolatile, false);
    mapOptEnum(Kernel::Arg::Key::IsPipe, MD.mIsPipe, false);
  }
};

