    auto mapOptU16 = [&](const char *key, uint16_t &val) {
      YIO.mapOptional(key, val, uint16_t(0));
    };
    auto mapOptU32 = [&](const char *key, uint32_t &val) {
      YIO.mapOptional(key, val, uint32_t(0));
