    mapOptU16(Kernel::CodeProps::Key::NumVGPRs, MD.mNumVGPRs);
    mapOptU32(Kernel::CodeProps::Key::MaxFlatWorkGroupSize, MD.mMaxFlatWorkGroupSize);
    mapOptBool(Kernel::CodeProps::Key::IsDynamicCallStack, MD.mIsDynamicCallStack);
    mapOptBool(Kernel::CodeProps::Key::IsXNACKEnabled, MD.mIsXNACKEnabled);
    mapOptU16(Kernel::CodeProps::Key::NumSpilledSGPRs, MD.mNumSpilledSGPRs);
