std::error_code fromString(StringRef inputStr, Metadata &outMetadata) {
  yaml::Input yIn(inputStr);
  yIn >> outMetadata;
  return yIn.error();
}

std::error_code toString(Metadata inMetadata, std::string &outStr) {
  raw_string_ostream yStream(outStr);
  yaml::Output yOut(yStream, nullptr, std::numeric_limits<int>::max());
  yOut << inMetadata;
  return std::error_code{};
}

