void Generate_LLVM_Functions() {
    PointerType *floatPtrTy, *int8PtrTy;
    floatPtrTy = Type::getFloatTy(*TheContext)->getPointerTo();
    int8PtrTy = Type::getInt8Ty(*TheContext)->getPointerTo();

    // Helper lambda to create function types and insert them
    auto createFunction = [&](const std::string& name, Type* returnType, 
                             const std::vector<Type*>& paramTypes, bool isVarArg = false) {
        FunctionType* funcTy = FunctionType::get(returnType, paramTypes, isVarArg);
        TheModule->getOrInsertFunction(name, funcTy);
    };

    // Helper lambda for string functions (returning int8Ptr)
    auto createStrFunc = [&](const std::string& name, 
                            const std::vector<Type*>& paramTypes, 
                            bool isVarArg = false) {
        createFunction(name, int8PtrTy, paramTypes, isVarArg);
    };

    // Helper lambda for void functions
    auto createVoidFunc = [&](const std::string& name, 
                             const std::vector<Type*>& paramTypes,
                             bool isVarArg = false) {
        createFunction(name, Type::getVoidTy(*TheContext), paramTypes, isVarArg);
    };

    // Helper lambda for float functions
    auto createFloatFunc = [&](const std::string& name, 
                              const std::vector<Type*>& paramTypes,
                              bool isVarArg = false) {
        createFunction(name, Type::getFloatTy(*TheContext), paramTypes, isVarArg);
    };

    // Helper lambda for int functions
    auto createIntFunc = [&](const std::string& name, 
                            const std::vector<Type*>& paramTypes,
                            bool isVarArg = false) {
        createFunction(name, Type::getInt32Ty(*TheContext), paramTypes, isVarArg);
    };

    // Helper lambda for int64 functions
    auto createInt64Func = [&](const std::string& name, 
                              const std::vector<Type*>& paramTypes,
                              bool isVarArg = false) {
        createFunction(name, Type::getInt64Ty(*TheContext), paramTypes, isVarArg);
    };

    // Helper lambda for bool functions
    auto createBoolFunc = [&](const std::string& name, 
                             const std::vector<Type*>& paramTypes,
                             bool isVarArg = false) {
        createFunction(name, Type::getInt1Ty(*TheContext), paramTypes, isVarArg);
    };

    // String operations
    createStrFunc("str_Create", {int8PtrTy});
    createStrFunc("str_Copy", {int8PtrTy, int8PtrTy});
    createStrFunc("str_CopyArg", {int8PtrTy, int8PtrTy, int8PtrTy});
    createStrFunc("str_str_add", {int8PtrTy, int8PtrTy, int8PtrTy});
    createStrFunc("str_int_add", {int8PtrTy, int8PtrTy, Type::getInt32Ty(*TheContext)});
    createStrFunc("str_float_add", {int8PtrTy, int8PtrTy, Type::getFloatTy(*TheContext)});
    createStrFunc("int_str_add", {int8PtrTy, Type::getInt32Ty(*TheContext), int8PtrTy});
    createStrFunc("float_str_add", {int8PtrTy, Type::getFloatTy(*TheContext), int8PtrTy});
    createStrFunc("str_bool_add", {int8PtrTy, int8PtrTy, Type::getInt1Ty(*TheContext)});
    createStrFunc("bool_str_add", {int8PtrTy, Type::getInt1Ty(*TheContext), int8PtrTy});

    // Print and conversion functions
    createFloatFunc("PrintStr", {int8PtrTy});
    createStrFunc("cat_str_float", {int8PtrTy, Type::getFloatTy(*TheContext)});
    createStrFunc("str_split_idx", {int8PtrTy, int8PtrTy, int8PtrTy, Type::getInt32Ty(*TheContext)});
    createBoolFunc("can_convert_to_float", {int8PtrTy, int8PtrTy});
    createFloatFunc("str_to_float", {int8PtrTy, int8PtrTy});
    createBoolFunc("str_str_different", {int8PtrTy, int8PtrTy, int8PtrTy});
    createBoolFunc("str_str_equal", {int8PtrTy, int8PtrTy, int8PtrTy});
    createVoidFunc("str_Delete", {int8PtrTy});
    createStrFunc("readline", {int8PtrTy});
    createFloatFunc("dir_exists", {int8PtrTy});
    createFloatFunc("path_exists", {int8PtrTy});

    // Scope management functions
    createVoidFunc("scope_struct_Alloc_GC", {int8PtrTy});
    createStrFunc("GetEmptyChar", {int8PtrTy});
    createVoidFunc("FreeCharFromFunc", {int8PtrTy, int8PtrTy});
    createVoidFunc("FreeChar", {int8PtrTy});
    createStrFunc("CopyString", {int8PtrTy, int8PtrTy});
    createStrFunc("ConcatStr", {int8PtrTy, int8PtrTy, int8PtrTy});
    createStrFunc("ConcatStrFreeLeft", {int8PtrTy, int8PtrTy, int8PtrTy});
    createStrFunc("ConcatFloatToStr", {int8PtrTy, int8PtrTy, Type::getFloatTy(*TheContext)});
    createStrFunc("ConcatNumToStrFree", {int8PtrTy, int8PtrTy, Type::getFloatTy(*TheContext)});
