extern "C" void __fastcall entry(void* param1, void* param2)
{
    // Ignore unused parameters to avoid compiler warnings
    (void)param1;
    (void)param2;

    // Retrieve standard output handle from the current process environment
    HANDLE hOutput = NtCurrentPeb()->ProcessParameters->StandardOutput;

    const char message[] = "Hello, World!\n";
    DWORD bytesWritten = 0;

    // Write the message to console using the imported function
    WriteConsoleA(hOutput,
                  message,
                  sizeof(message) - 1,
                  &bytesWritten,
                  nullptr);
}

