// Display received data in hexadecimal format
void displayHexStream(const std::string &buffer) {
  if (!buffer.empty()) {
    std::cout << "hex stream: ";
    for (size_t idx = 0; idx < buffer.size(); ++idx) {
      std::cout << std::hex << std::setfill('0') << std::setw(2)
                << static_cast<int>(static_cast<uint8_t>(buffer[idx])) << " ";
    }
    std::cout << std::endl;
  }
}

int main(int argc, char **argv) {
  ros::init(argc, argv, "linktrack_parser");
  ros::NodeHandle node;
  serial::Serial device;
  initializeSerialPort(&device);

  NProtocolExtracter parser;
  linktrack::Init initializer(&parser, &device);

  ros::Rate update_rate(1000);

  while (ros::ok()) {
    size_t bytes_ready = device.available();
    std::string incoming_data;

    if (bytes_ready > 0) {
      device.read(incoming_data, bytes_ready);
      // displayHexStream(incoming_data);
      parser.InjectData(incoming_data);
    }

    ros::spinOnce();
    update_rate.sleep();
  }

  return EXIT_SUCCESS;
}

