void MinecraftWorld_RunStaticCtors()
{
    // Core engine & block/item systems — early dependencies
    Packet::staticCtor();
    MaterialColor::staticCtor();
    Material::staticCtor();
    Tile::staticCtor();

    // Tools/items
    HatchetItem::staticCtor();
    PickaxeItem::staticCtor();
    ShovelItem::staticCtor();

    // World generation & block replacement
    BlockReplacements::staticCtor();
    Biome::staticCtor();

    // Items base + recipes
    Item::staticCtor();
    FurnaceRecipes::staticCtor();
    Recipes::staticCtor();

    // Stats & achievements (via helper)
    InitializeStatsSystem();

    // Mobs
    Skeleton::staticCtor();
    PigZombie::staticCtor();

    // Tile entities & entity I/O
    TileEntity::staticCtor();
    EntityIO::staticCtor();

    // Additional core systems
    MobCategory::staticCtor();
    Item::staticInit();  // Note: separate from staticCtor()

    // Level & chunk handling
    LevelChunk::staticCtor();
    LevelType::staticCtor();

    // Structures & features
    MineShaftPieces::staticCtor();
    StrongholdFeature::staticCtor();
    InitializeVillageSmithy();  // Explicit call for nested class
    VillageFeature::staticCtor();
    RandomScatteredLargeFeature::staticCtor();

    // Late-initialization systems
    EnderMan::staticCtor();
    PotionBrewing::staticCtor();
    Enchantment::staticCtor();
    SharedConstants::staticCtor();
    ServerLevel::staticCtor();
    SparseLightStorage::staticCtor();
    CompressedTileStorage::staticCtor();  // Added missing declaration (assumed present)
    SparseDataStorage::staticCtor();
    McRegionChunkStorage::staticCtor();
    Villager::staticCtor();
    GameType::staticCtor();
}

#include "camera_component.hpp"
#include <engine/meta/rendering/camera.hpp>
#include <engine/meta/layers/layer_mask.hpp>
#include <serialization/associative_archive.h>
#include <serialization/binary_archive.h>

namespace unravel
{
    // Helper lambdas to determine current projection type
    auto is_orthographic_mode = [](const entt::meta_any& any_val) -> bool {
        if (auto* cam_comp = any_val.try_cast<camera_component>())
            return cam_comp->get_projection_mode() == projection_mode::orthographic;
        return false;
    };

    auto is_perspective_mode = [](const entt::meta_any& any_val) -> bool {
        if (auto* cam_comp = any_val.try_cast<camera_component>())
            return cam_comp->get_projection_mode() == projection_mode::perspective;
        return false;
    };

    // Register metadata for camera_component
    void register_camera_component_metadata()
    {
        using namespace entt;

        meta_factory<camera_component> factory{"camera_component"_hs};

        factory
            .type("camera_component"_hs)
            .custom(attributes{
                attribute{"name", "camera_component"},
                attribute{"category", "RENDERING"},
                attribute{"pretty_name", "Camera"}
            });

        // Component lifecycle functions
        factory
            .func<&component_meta<camera_component>::exists>("component_exists"_hs)
            .func<&component_meta<camera_component>::add>("component_add"_hs)
            .func<&component_meta<camera_component>::save>("component_save"_hs)
            .func<&component_meta<camera_component>::load>("component_load"_hs)
            .func<&component_meta<camera_component>::remove>("component_remove"_hs);

        // Projection mode property
        factory
            .data<&camera_component::set_projection_mode, &camera_component::get_projection_mode>("projection_mode"_hs)
            .custom(attributes{
                attribute{"name", "projection_mode"},
                attribute{"pretty_name", "Projection Mode"}
            });

        // Field of View (only relevant in perspective mode)
        factory
            .data<&camera_component::set_fov, &camera_component::get_fov>("field_of_view"_hs)
            .custom(attributes{
                attribute{"name", "field_of_view"},
                attribute{"pretty_name", "Field Of View"},
                attribute{"min", 5.0f},
                attribute{"max", 150.0f},
                attribute{"predicate", is_perspective_mode}
            });

        // Orthographic size (only relevant in orthographic mode)
        factory
            .data<&camera_component::set_ortho_size, &camera_component::get_ortho_size>("orthographic_size"_hs)
            .custom(attributes{
                attribute{"name", "orthographic_size"},
                attribute{"pretty_name", "Orthographic Size"},
                attribute{"min", 0.1f},
                attribute{"tooltip", "This is half of the vertical size of the viewing volume.\nHorizontal viewing size varies depending on viewport's aspect ratio.\nOrthographic size is ignored when camera is not orthographic."},
                attribute{"predicate", is_orthographic_mode}
            });

        // Pixels per unit (read-only, only meaningful in ortho mode)
        factory
            .data<nullptr, &camera_component::get_ppu>("pixels_per_unit"_hs)
            .custom(attributes{
                attribute{"name", "pixels_per_unit"},
                attribute{"pretty_name", "Pixels Per Unit"},
                attribute{"tooltip", "Pixels per unit only usable in orthographic mode."}
            });

        // Viewport dimensions
        factory
            .data<nullptr, &camera_component::get_viewport_size>("viewport_size"_hs)
            .custom(attributes{
                attribute{"name", "viewport_size"},
                attribute{"pretty_name", "Viewport Size"}
            });

        // Near/Far clipping planes
        factory
            .data<&camera_component::set_near_clip, &camera_component::get_near_clip>("near_clip_distance"_hs)
            .custom(attributes{
                attribute{"name", "near_clip_distance"},
                attribute{"pretty_name", "Near Clip"},
                attribute{"min", 0.1f}
            });

        factory
            .data<&camera_component::set_far_clip, &camera_component::get_far_clip>("far_clip_distance"_hs)
            .custom(attributes{
                attribute{"name", "far_clip_distance"},
                attribute{"pretty_name", "Far Clip"}
            });

        // Layer masks: include/exclude + derived render mask
        factory
            .data<&camera_component::set_render_include_mask, &camera_component::get_render_include_mask>("include_layers"_hs)
            .custom(attributes{
                attribute{"name", "include_layers"},
                attribute{"pretty_name", "Include Layers"},
                attribute{"tooltip", "Layers to include when rendering."}
            });

        factory
            .data<&camera_component::set_render_exclude_mask, &camera_component::get_render_exclude_mask>("exclude_layers"_hs)
            .custom(attributes{
                attribute{"name", "exclude_layers"},
                attribute{"pretty_name", "Exclude Layers"},
                attribute{"tooltip", "Layers to exclude when rendering."}
            });

        factory
            .data<nullptr, &camera_component::get_render_mask>("render_layers"_hs)
            .custom(attributes{
                attribute{"name", "render_layers"},
                attribute{"pretty_name", "Render Layers"},
                attribute{"tooltip", "Layers (Include - Exclude) used when rendering."}
            });
    }

    REFLECT(camera_component)
    {
        register_camera_component_metadata();
    }

    // Serialization: Save
    template<typename Archive>
    void save(Archive& ar, const camera_component& obj)
    {
        try_save(ar, ser20::make_nvp("camera", obj.get_camera()));
        try_save(ar, ser20::make_nvp("render_include_layers", obj.get_render_include_mask()));
        try_save(ar, ser20::make_nvp("render_exclude_layers", obj.get_render_exclude_mask()));
    }

    SAVE_INSTANTIATE(camera_component, ser20::oarchive_associative_t);
    SAVE_INSTANTIATE(camera_component, ser20::oarchive_binary_t);

    // Serialization: Load
    template<typename Archive>
    void load(Archive& ar, camera_component& obj)
    {
        try_load(ar, ser20::make_nvp("camera", obj.get_camera()));

        layer_mask included_layers{layer_reserved::everything_layer};
        if (try_load(ar, ser20::make_nvp("render_include_layers", included_layers)))
        {
            obj.set_render_include_mask(included_layers);
        }

        layer_mask excluded_layers{layer_reserved::nothing_layer};
        if (try_load(ar, ser20::make_nvp("render_exclude_layers", excluded_layers)))
        {
            obj.set_render_exclude_mask(excluded_layers);
        }
    }

    LOAD_INSTANTIATE(camera_component, ser20::iarchive_associative_t);
    LOAD_INSTANTIATE(camera_component, ser20::iarchive_binary_t);
} // namespace unravel

#include "TuyaDatapoints.h"

/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandBool(
  ZigbeeGateway *gateway, zbg_device_params_t *device, uint8_t dp_id,
  bool value, bool synchronous, uint8_t command_code) {

  Tuya_dp_zcl_payload_t payload;

  // Convert boolean to integer representation (0 or 1)
  uint8_t int_value = value ? 1 : 0;
  makeTuyaDPBool(payload, dp_id, int_value);

  return gateway->sendCustomClusterCmd(
    device, TUYA_PRIVATE_CLUSTER_EF00, command_code, ESP_ZB_ZCL_ATTR_TYPE_SET,
    TUYA_DP_ZCL_PAYLOAD_8, reinterpret_cast<uint8_t*>(&payload), synchronous);
}

/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandEnum8(
  ZigbeeGateway *gateway, zbg_device_params_t *device, uint8_t dp_id,
  uint8_t value, bool synchronous, uint8_t command_code) {

  Tuya_dp_zcl_payload_t payload;

  makeTuyaDPEnum8(payload, dp_id, value);

  return gateway->sendCustomClusterCmd(
    device, TUYA_PRIVATE_CLUSTER_EF00, command_code, ESP_ZB_ZCL_ATTR_TYPE_SET,
    TUYA_DP_ZCL_PAYLOAD_8, reinterpret_cast<uint8_t*>(&payload), synchronous);
}

/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandValue32(
  ZigbeeGateway *gateway, zbg_device_params_t *device, uint8_t dp_id,
  uint32_t value, bool synchronous, uint8_t command_code) {

  Tuya_dp_zcl_payload_t payload;

  makeTuyaDPValue32(payload, dp_id, value);

  return gateway->sendCustomClusterCmd(
    device, TUYA_PRIVATE_CLUSTER_EF00, command_code, ESP_ZB_ZCL_ATTR_TYPE_SET,
    TUYA_DP_ZCL_PAYLOAD_32, reinterpret_cast<uint8_t*>(&payload), synchronous);
}

/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandByType(
  ZigbeeGateway *gateway, zbg_device_params_t *device, uint8_t dp_id,
  uint8_t type, uint32_t value, bool synchronous, uint8_t command_code) {

  switch (type) {
    case TUYA_DP_TYPE_BOOL:
      return transmitTuyaCommandBool(gateway, device, dp_id, static_cast<bool>(value & 0xFF), synchronous, command_code);

    case TUYA_DP_TYPE_VALUE:
      return transmitTuyaCommandValue32(gateway, device, dp_id, value, synchronous, command_code);

    case TUYA_DP_TYPE_ENUM:
      return transmitTuyaCommandEnum8(gateway, device, dp_id, static_cast<uint8_t>(value), synchronous, command_code);

    default:
      log_e("unsupported Tuya datapoint %02x with type %02x", dp_id, type);
      break;
  }

  return false;
}

/*---------------------------------------------------------------------------*/
bool sendTuyaQueryRequest(
  ZigbeeGateway *gateway, zbg_device_params_t *device, bool synchronous) {

  return gateway->sendCustomClusterCmd(
    device, TUYA_PRIVATE_CLUSTER_EF00, TUYA_QUERY_CMD,
    ESP_ZB_ZCL_ATTR_TYPE_NULL, TUYA_DP_ZCL_PAYLOAD_0, nullptr, synchronous);
}

#include <basics/math_utils.hpp>
#include "tests_shared.hpp"
#include <limits>

namespace math = irs::math;

// Test power-of-two detection with alternative assertions
TEST(math_utils_test, IsPower2) {
  using namespace irs::math;
  // static_assert(!IsPower2(0), "Invalid answer"); // 0 gives false negative
  static_assert(IsPower2(1), "Invalid answer");
  static_assert(IsPower2(2), "Invalid answer");
  static_assert(!IsPower2(3), "Invalid answer");
  static_assert(IsPower2(4), "Invalid answer");
  static_assert(!IsPower2(999), "Invalid answer");
  static_assert(IsPower2(1024), "Invalid answer");
  static_assert(IsPower2(UINT64_C(1) << 63), "Invalid answer");
  static_assert(!IsPower2(std::numeric_limits<size_t>::max()),
                "Invalid answer");
}

// Test rounding up to next power of two with different test cases
TEST(math_utils_test, roundup_power2) {
  ASSERT_EQ(0, math::RoundupPower2(0));
  ASSERT_EQ(1, math::RoundupPower2(1));
  ASSERT_EQ(2, math::RoundupPower2(2));
  ASSERT_EQ(4, math::RoundupPower2(3));
  ASSERT_EQ(4, math::RoundupPower2(4));
  ASSERT_EQ(8, math::RoundupPower2(5));
  ASSERT_EQ(16, math::RoundupPower2(11));
  ASSERT_EQ(1024, math::RoundupPower2(900));
  ASSERT_EQ(std::numeric_limits<size_t>::max(),
            math::RoundupPower2(std::numeric_limits<size_t>::max()) -
              1);  // round to the max possible value
  ASSERT_EQ(0, math::RoundupPower2(std::numeric_limits<size_t>::max()));
}

// Test floor log base 2 for 32-bit values
TEST(math_utils_test, Log2Floor32) {
  ASSERT_EQ(0, math::Log2Floor32(1));
  ASSERT_EQ(1, math::Log2Floor32(2));
  ASSERT_EQ(1, math::Log2Floor32(3));
  ASSERT_EQ(2, math::Log2Floor32(4));
  ASSERT_EQ(2, math::Log2Floor32(6));
  ASSERT_EQ(3, math::Log2Floor32(8));
  ASSERT_EQ(9, math::Log2Floor32(999));
  ASSERT_EQ(10, math::Log2Floor32(1024));
  ASSERT_EQ(10, math::Log2Floor32(1025));
  ASSERT_EQ(31, math::Log2Floor32(std::numeric_limits<uint32_t>::max()));
}

// Test floor log base 2 for 64-bit values
TEST(math_utils_test, Log2Floor64) {
  ASSERT_EQ(0, math::Log2Floor64(UINT64_C(1)));
  ASSERT_EQ(1, math::Log2Floor64(UINT64_C(2)));
  ASSERT_EQ(1, math::Log2Floor64(UINT64_C(3)));
  ASSERT_EQ(2, math::Log2Floor64(UINT64_C(4)));
  ASSERT_EQ(2, math::Log2Floor64(UINT64_C(6)));
  ASSERT_EQ(3, math::Log2Floor64(UINT64_C(8)));
  ASSERT_EQ(9, math::Log2Floor64(UINT64_C(999)));
  ASSERT_EQ(10, math::Log2Floor64(UINT64_C(1024)));
  ASSERT_EQ(10, math::Log2Floor64(UINT64_C(1025)));
  ASSERT_EQ(31, math::Log2Floor64(std::numeric_limits<uint32_t>::max()));
  ASSERT_EQ(32, math::Log2Floor64(UINT64_C(1) << 32));
  ASSERT_EQ(32, math::Log2Floor64(UINT64_C(1) + (UINT64_C(1) << 32)));
  ASSERT_EQ(63, math::Log2Floor64(std::numeric_limits<uint64_t>::max()));
}

// Test general logarithm computation
TEST(math_utils_test, log) {
  ASSERT_EQ(0, math::Log(1, 2));
  ASSERT_EQ(1, math::Log(235, 235));
  ASSERT_EQ(2, math::Log(49, 7));
  ASSERT_EQ(3, math::Log(8, 2));
  ASSERT_EQ(4, math::Log(12341, 7));
  ASSERT_EQ(6, math::Log(34563456, 17));
  ASSERT_EQ(31, math::Log(std::numeric_limits<uint32_t>::max(), 2));
}

// Test floor log base 2 for 32-bit values (alternative function)
TEST(math_utils_test, log2_32) {
  ASSERT_EQ(0, math::Log232(1));
  ASSERT_EQ(1, math::Log232(2));
  ASSERT_EQ(1, math::Log232(3));
  ASSERT_EQ(2, math::Log232(4));
  ASSERT_EQ(7, math::Log232(128));
  ASSERT_EQ(10, math::Log232(1025));
  ASSERT_EQ(31, math::Log232(std::numeric_limits<uint32_t>::max()));
}

// Test floor log base 2 for 64-bit values (alternative function)
TEST(math_utils_test, log2_64) {
  ASSERT_EQ(0, math::Log264(1));
  ASSERT_EQ(1, math::Log264(2));
  ASSERT_EQ(1, math::Log264(3));
  ASSERT_EQ(2, math::Log264(4));
  ASSERT_EQ(7, math::Log264(128));
  ASSERT_EQ(10, math::Log264(1025));
  ASSERT_EQ(31, math::Log264(std::numeric_limits<uint32_t>::max()));
  ASSERT_EQ(63, math::Log264(std::numeric_limits<uint64_t>::max()));
}

// Test ceiling division for 32-bit unsigned integers
TEST(math_utils, DivCeil32) {
  ASSERT_EQ(7, math::DivCeil32(49, 7));
  ASSERT_EQ(7, math::DivCeil32(48, 7));
  ASSERT_EQ(6, math::DivCeil32(41, 7));
  ASSERT_EQ(6, math::DivCeil32(42, 7));
  ASSERT_EQ(1, math::DivCeil32(2, 2));
  ASSERT_EQ(2, math::DivCeil32(3, 2));
  ASSERT_EQ(1, math::DivCeil32(5, 7));
  ASSERT_EQ(0, math::DivCeil32(0, 7));
  ASSERT_EQ(0, math::DivCeil32(0, 1));
  ASSERT_EQ(7, math::DivCeil32(7, 1));
  ASSERT_EQ(1, math::DivCeil32(std::numeric_limits<uint32_t>::max() / 2,
                               std::numeric_limits<uint32_t>::max() / 2));
  ASSERT_EQ(1, math::DivCeil32(std::numeric_limits<uint32_t>::max() / 2 - 1,
                               std::numeric_limits<uint32_t>::max() / 2 + 1));
}

// Test ceiling division for 64-bit unsigned integers
TEST(math_utils, DivCeil64) {
  ASSERT_EQ(7, math::DivCeil64(49, 7));
  ASSERT_EQ(7, math::DivCeil64(48, 7));
  ASSERT_EQ(6, math::DivCeil64(41, 7));
  ASSERT_EQ(6, math::DivCeil64(42, 7));
  ASSERT_EQ(1, math::DivCeil64(2, 2));
  ASSERT_EQ(2, math::DivCeil64(3, 2));
  ASSERT_EQ(1, math::DivCeil64(5, 7));
  ASSERT_EQ(0, math::DivCeil64(0, 7));
  ASSERT_EQ(0, math::DivCeil64(0, 1));
  ASSERT_EQ(7, math::DivCeil64(7, 1));
  ASSERT_EQ(1, math::DivCeil64(std::numeric_limits<uint64_t>::max() / 2,
                               std::numeric_limits<uint64_t>::max() / 2));
  ASSERT_EQ(1, math::DivCeil64(std::numeric_limits<uint64_t>::max() / 2 - 1,
                               std::numeric_limits<uint64_t>::max() / 2 + 1));
}

// Test ceiling alignment for 32-bit values
TEST(math_utils, ceil32) {
  ASSERT_EQ(41, math::Ceil32(41, 1));
  ASSERT_EQ(0, math::Ceil32(0, 7));
  ASSERT_EQ(42, math::Ceil32(41, 7));
  ASSERT_EQ(42, math::Ceil32(42, 7));
  ASSERT_EQ(49, math::Ceil32(43, 7));
  ASSERT_EQ(uint32_t(std::numeric_limits<uint32_t>::max() - 3),
            math::Ceil32(std::numeric_limits<uint32_t>::max() - 3, 2));
  ASSERT_EQ(uint32_t(std::numeric_limits<uint32_t>::max() - 3),
            math::Ceil32(std::numeric_limits<uint32_t>::max() - 4, 2));
}

// Test ceiling alignment for 64-bit values
TEST(math_utils, ceil64) {
  ASSERT_EQ(41, math::Ceil64(41, 1));
  ASSERT_EQ(0, math::Ceil64(0, 7));
  ASSERT_EQ(42, math::Ceil64(41, 7));
  ASSERT_EQ(42, math::Ceil64(42, 7));
  ASSERT_EQ(49, math::Ceil64(43, 7));
  ASSERT_EQ(uint64_t(std::numeric_limits<uint64_t>::max() - 3),
            math::Ceil64(std::numeric_limits<uint64_t>::max() - 3, 2));
  ASSERT_EQ(uint64_t(std::numeric_limits<uint64_t>::max() - 3),
            math::Ceil64(std::numeric_limits<uint64_t>::max() - 4, 2));
}

