#include <StaticResponseProcessorHTTP.h>

void StaticResponseProcessorHTTP::Process(http::request<http::string_body> const& req, tcp::socket& sock) {
    // Create response with same HTTP version and connection settings
    http::response<http::string_body> res;
    res.version(req.version());

    // Preserve connection state from incoming request
    if (req.keep_alive()) {
        res.set(http::field::connection, "keep-alive");
    } else {
        res.set(http::field::connection, "close");
    }

    // Set standard response fields
    res.result(http::status::ok);
    res.set(http::field::content_type, "application/json; charset=UTF-8");
    res.set(http::field::vary, "Origin");

    // Populate response body and finalize
    res.body() = m_res->dump();
    res.prepare_payload();

    // Send response over the socket
    http::write(sock, res);
}

#include "autolink/service_discovery/role/role.hpp"
