namespace autolink {
namespace service_discovery {

using proto::RoleAttributes;

// Helper to verify equality in sequence
inline void assert_eq(int actual, int expected) {
    EXPECT_EQ(actual, expected);
}

TEST(RoleTest, constructor_getter_setter_revised) {
  RoleBase r1;
  assert_eq(r1.timestamp_ns(), 0);
  r1.set_timestamp_ns(123);
  assert_eq(r1.timestamp_ns(), 123);

  RoleWriter rw1;
  assert_eq(rw1.timestamp_ns(), 0);

  RoleServer rs1;
  assert_eq(rs1.timestamp_ns(), 0);

  RoleAttributes attrs;
  attrs.set_host_name("caros");
  attrs.set_process_id(12345);
  r1.set_attributes(attrs);
  EXPECT_EQ(r1.attributes().host_name(), "caros");
  EXPECT_EQ(r1.attributes().process_id(), 12345);

  // Test constructors with attributes and timestamp
  RoleBase r2(attrs, 321);
  assert_eq(r2.timestamp_ns(), 321);

  RoleWriter rw2(attrs, 321);
  assert_eq(rw2.timestamp_ns(), 321);

  RoleServer rs2(attrs, 321);
  assert_eq(rs2.timestamp_ns(), 321);
}

TEST(RoleTest, is_earlier_than_revised) {
  RoleBase ra;
  ra.set_timestamp_ns(123);
  RoleBase rb;
  rb.set_timestamp_ns(456);

  EXPECT_TRUE(ra.IsEarlierThan(rb));
  EXPECT_FALSE(rb.IsEarlierThan(ra));
}

TEST(RoleTest, rolebase_match_revised) {
  RoleAttributes base_attrs;
  base_attrs.set_host_name("caros");
  base_attrs.set_process_id(12345);
  base_attrs.set_node_id(1);
  RoleBase role_obj(base_attrs, 1234567);

  RoleAttributes target;
  // Initially empty except for implicit defaults → should match on host/process/node if set
  EXPECT_TRUE(role_obj.Match(target));

  target.set_host_name("sorac");
  EXPECT_FALSE(role_obj.Match(target));

  target.set_host_name("caros");
  EXPECT_TRUE(role_obj.Match(target));

  target.set_process_id(54321);
  EXPECT_FALSE(role_obj.Match(target));

  target.set_process_id(12345);
  EXPECT_TRUE(role_obj.Match(target));

  target.set_node_id(2);
  EXPECT_FALSE(role_obj.Match(target));

  target.set_node_id(1);
  EXPECT_TRUE(role_obj.Match(target));
}

TEST(RoleTest, rolewriter_match_revised) {
  RoleAttributes base;
  base.set_host_name("caros");
  base.set_process_id(12345);
  base.set_node_id(1);
  RoleAttributes target(base);

  base.set_channel_id(2);
  base.set_id(3);
  RoleWriter writer(base, 1234567);

  EXPECT_TRUE(writer.Match(target));

  target.set_id(4);
  EXPECT_FALSE(writer.Match(target));

  target.set_id(3);
  EXPECT_TRUE(writer.Match(target));

  target.set_channel_id(3);
  EXPECT_FALSE(writer.Match(target));

  target.set_channel_id(2);
  EXPECT_TRUE(writer.Match(target));
}

TEST(RoleTest, roleserver_match_revised) {
  RoleAttributes base;
  base.set_host_name("caros");
  base.set_process_id(12345);
  base.set_node_id(1);
  RoleAttributes target(base);

  base.set_service_id(2);
  RoleServer server(base, 1234567);

  EXPECT_TRUE(server.Match(target));

  target.set_service_id(3);
  EXPECT_FALSE(server.Match(target));

  target.set_service_id(2);
  EXPECT_TRUE(server.Match(target));
}

