// Structure to capture scheduler switch event data
struct trace_sched_switch_args {
    u64 reserved;
    char prev_task_name[16];
    u32 previous_process_id;
    u32 previous_priority;
    u64 previous_state_flag;
    char next_task_name[16];
    u32 next_process_id;
    u32 next_priority;
};

SEC("tracepoint/sched/sched_switch")
int handle_sched_switch(struct trace_sched_switch_args* event) {
    BPF_PRINTK("Scheduler context switch detected: %d -> %d\n", 
               event->previous_process_id, 
               event->next_process_id);
    return 0;
}
