    VFTableShape = 0x160b,
    TypeServer2 = 0x160c,
    StringId = 0x160d,
    FuncId = 0x160e,
    UdtSourceLine = 0x160f,
    UdtModSourceLine = 0x1610,
    BuildInfo = 0x1611,
    VFTable = 0x1612,
    Precomp = 0x1613,
    EndPrecomp = 0x1614
};

struct TypeIndex {
    uint32_t index;
    TypeIndex() : index(0) {}
    explicit TypeIndex(uint32_t i) : index(i) {}
    uint32_t getIndex() const { return index; }
    void setIndex(uint32_t i) { index = i; }
};

struct APSInt {
    bool isSigned;
    uint64_t value;
    APSInt() : isSigned(false), value(0) {}
    APSInt(const std::string& s) : isSigned(false), value(0) {
        // Simplified parsing
        for (char c : s) {
            if (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
            }
        }
    }
    void print(std::ostream& os, bool signedness) const {
        if (signedness && static_cast<int64_t>(value) < 0) {
            os << "-" << static_cast<uint64_t>(-static_cast<int64_t>(value));
        } else {
            os << value;
        }
    }
};

struct GUID {
    uint32_t data1;
    uint16_t data2;
    uint16_t data3;
    uint64_t data4;

    friend std::ostream& operator<<(std::ostream& os, const GUID& g) {
        os << "{";
        os.width(8); os.fill('0'); os << std::hex << g.data1 << "-";
        os.width(4); os << g.data2 << "-";
        os.width(4); os << g.data3 << "-";
        os.width(12); os << g.data4 << "}";
        return os;
    }
};

// Base class for type records
class TypeRecord {
public:
    TypeKind kind;
    explicit TypeRecord(TypeKind k) : kind(k) {}
    virtual ~TypeRecord() = default;
    virtual void serialize(std::vector<uint8_t>& buffer) const = 0;
    virtual void deserialize(const std::vector<uint8_t>& buffer, size_t& offset) = 0;
};

// Concrete type record implementations
class FieldListRecord : public TypeRecord {
public:
    std::vector<std::unique_ptr<TypeRecord>> members;
    FieldListRecord() : TypeRecord(TypeKind::FieldList) {}
    void serialize(std::vector<uint8_t>& buffer) const override {
        for (const auto& m : members) {
            m->serialize(buffer);
        }
    }
    void deserialize(const std::vector<uint8_t>& buffer, size_t& offset) override {
        // Simplified deserialization
        while (offset < buffer.size()) {
            uint16_t kind = *reinterpret_cast<const uint16_t*>(&buffer[offset]);
            if (kind == 0) break;
            // In real implementation, would parse based on kind
            offset += 2;
        }
    }
};

class ClassRecord : public TypeRecord {
public:
    uint16_t memberCount;
    std::string name;
    TypeIndex fieldList;
    ClassRecord() : TypeRecord(TypeKind::Class), memberCount(0) {}
    void serialize(std::vector<uint8_t>& buffer) const override {
        buffer.push_back(kind & 0xFF);
        buffer.push_back((kind >> 8) & 0xFF);
        buffer.push_back(memberCount & 0xFF);
        buffer.push_back((memberCount >> 8) & 0xFF);
        // Simplified string serialization
        for (char c : name) buffer.push_back(c);
        buffer.push_back(0);
    }
    void deserialize(const std::vector<uint8_t>& buffer, size_t& offset) override {
        kind = static_cast<TypeKind>(*reinterpret_cast<const uint16_t*>(&buffer[offset]));
        offset += 2;
        memberCount = *reinterpret_cast<const uint16_t*>(&buffer[offset]);
        offset += 2;
        // Simplified string deserialization
        name.clear();
        while (offset < buffer.size() && buffer[offset] != 0) {
            name += buffer[offset];
            offset++;
        }
        offset++; // skip null terminator
    }
};

class ModifierRecord : public TypeRecord {
public:
    TypeIndex modifiedType;
    uint32_t modifiers;
    ModifierRecord() : TypeRecord(TypeKind::Modifier), modifiers(0) {}
    void serialize(std::vector<uint8_t>& buffer) const override {
        buffer.push_back(kind & 0xFF);
        buffer.push_back((kind >> 8) & 0xFF);
        buffer.push_back(modifiers & 0xFF);
        buffer.push_back((modifiers >> 8) & 0xFF);
        buffer.push_back((modifiers >> 16) & 0xFF);
        buffer.push_back((modifiers >> 24) & 0xFF);
    }
    void deserialize(const std::vector<uint8_t>& buffer, size_t& offset) override {
        kind = static_cast<TypeKind>(*reinterpret_cast<const uint16_t*>(&buffer[offset]));
        offset += 2;
        modifiers = *reinterpret_cast<const uint32_t*>(&buffer[offset]);
        offset += 4;
    }
};

class ProcedureRecord : public TypeRecord {
public:
    TypeIndex returnType;
    uint8_t callingConvention;
    uint16_t options;
    uint32_t parameterCount;
    ProcedureRecord() : TypeRecord(TypeKind::Procedure), callingConvention(0), options(0), parameterCount(0) {}
    void serialize(std::vector<uint8_t>& buffer) const override {
        buffer.push_back(kind & 0xFF);
        buffer.push_back((kind >> 8) & 0xFF);
        buffer.push_back(callingConvention);
        buffer.push_back(options & 0xFF);
        buffer.push_back((options >> 8) & 0xFF);
    }
    void deserialize(const std::vector<uint8_t>& buffer, size_t& offset) override {
        kind = static_cast<TypeKind>(*reinterpret_cast<const uint16_t*>(&buffer[offset]));
        offset += 2;
        callingConvention = buffer[offset++];
        options = *reinterpret_cast<const uint16_t*>(&buffer[offset]);
        offset += 2;
    }
};

// Container for type records
class TypeContainer {
public:
    std::vector<std::unique_ptr<TypeRecord>> records;

    void addRecord(std::unique_ptr<TypeRecord> record) {
        records.push_back(std::move(record));
    }

    std::vector<uint8_t> serializeToBuffer() const {
        std::vector<uint8_t> buffer;
        buffer.push_back(0x4); // Magic number for debug section
        buffer.push_back(0x0);
        buffer.push_back(0x0);
        buffer.push_back(0x0);

        for (const auto& r : records) {
            r->serialize(buffer);
        }
        return buffer;
    }

    bool loadFromBuffer(const std::vector<uint8_t>& buffer) {
        if (buffer.size() < 4) return false;
        if (buffer[0] != 0x4 || buffer[1] != 0x0 || buffer[2] != 0x0 || buffer[3] != 0x0) {
            return false;
        }

        size_t offset = 4;
        while (offset < buffer.size()) {
            uint16_t kind = *reinterpret_cast<const uint16_t*>(&buffer[offset]);
            switch (static_cast<TypeKind>(kind)) {
                case TypeKind::FieldList: {
                    auto rec = std::make_unique<FieldListRecord>();
                    rec->deserialize(buffer, offset);
                    records.push_back(std::move(rec));
                    break;
                }
                case TypeKind::Class: {
                    auto rec = std::make_unique<ClassRecord>();
                    rec->deserialize(buffer, offset);
                    records.push_back(std::move(rec));
                    break;
                }
                case TypeKind::Modifier: {
                    auto rec = std::make_unique<ModifierRecord>();
                    rec->deserialize(buffer, offset);
                    records.push_back(std::move(rec));
                    break;
                }
                case TypeKind::Procedure: {
                    auto rec = std::make_unique<ProcedureRecord>();
                    rec->deserialize(buffer, offset);
                    records.push_back(std::move(rec));
                    break;
                }
                default:
                    offset += 2; // Skip unknown types
                    break;
            }
        }
        return true;
    }
};

// YAML-like serialization helper
class YamlSerializer {
public:
    static std::string serializeTypeIndex(const TypeIndex& idx) {
        return std::to_string(idx.getIndex());
    }

    static std::string serializeAPSInt(const APSInt& val) {
        std::string result;
        val.print(std::cout, val.isSigned);
        return "";
    }

    static std::string serializeGUID(const GUID& guid) {
        std::ostringstream oss;
        oss << guid;
        return oss.str();
    }
};

// Helper function to process debug sections
std::vector<std::unique_ptr<TypeRecord>> extractDebugTypes(const std::vector<uint8_t>& sectionData) {
    TypeContainer container;
    if (!container.loadFromBuffer(sectionData)) {
        return {};
    }

    std::vector<std::unique_ptr<TypeRecord>> result;
    for (auto& r : container.records) {
        result.push_back(std::move(r));
    }
    return result;
}

std::vector<uint8_t> createDebugSection(const std::vector<std::unique_ptr<TypeRecord>>& records) {
    TypeContainer container;
    for (auto& r : records) {
        container.addRecord(std::move(r));
    }
    return container.serializeToBuffer();
}

} // namespace cv_debug

int main() {
    // Example usage demonstrating the cloned functionality
    cv_debug::TypeContainer container;

    // Create some sample type records
    auto classRec = std::make_unique<cv_debug::ClassRecord>();
    classRec->name = "SampleClass";
    classRec->memberCount = 2;
    container.addRecord(std::move(classRec));

    auto modRec = std::make_unique<cv_debug::ModifierRecord>();
    modRec->modifiers = 1;
    container.addRecord(std::move(modRec));

    // Serialize to buffer
    std::vector<uint8_t> buffer = container.serializeToBuffer();

    // Deserialize back
    cv_debug::TypeContainer loadedContainer;
    loadedContainer.loadFromBuffer(buffer);

    // Output results
    std::cout << "Processed " << loadedContainer.records.size() << " type records" << std::endl;

    return 0;
}

#include <iostream>
#include <asio.hpp>
#include <functional>

class Counter
{
public:
  Counter(asio::io_context& context)
    : timer_(context, asio::chrono::seconds(1)),
      counter_(0)
  {
    startTimer();
  }

  ~Counter()
  {
    std::cout << "Final count is " << counter_ << std::endl;
  }

private:
  void startTimer()
  {
    timer_.async_wait(std::bind(&Counter::handleTimeout, this, std::placeholders::_1));
  }

  void handleTimeout(const asio::error_code& /*ec*/)
  {
    if (counter_ < 5)
    {
      std::cout << counter_ << std::endl;
      ++counter_;

      // Reset timer for next second
      timer_.expires_at(timer_.expiry() + asio::chrono::seconds(1));
      startTimer();
    }
  }

  asio::steady_timer timer_;
  int counter_;
};

int main()
{
  asio::io_context io;
  Counter printerInstance(io);
  io.run();
  return 0;
}

