// Trim whitespace from string
static std::string clean_whitespace(const std::string & input) {
    std::string result = input;
    // Remove leading whitespace
    size_t start = result.find_first_not_of(" \n\r\t");
    if (start != std::string::npos) {
        result = result.substr(start);
    } else {
        result.clear();
    }
    // Remove trailing whitespace
    size_t end = result.find_last_not_of(" \n\r\t");
    if (end != std::string::npos) {
        result = result.substr(0, end + 1);
    }
    // Clean up indentation
    result = std::regex_replace(result, std::regex("(^|\\n)[ \\t]+"), "$1");
    return result;
}

// Test outcome types
enum class TestResult {
    PASS,
    FAIL
};

// Individual test case container
struct ValidationTest {
    TestResult expected_outcome;
    std::string test_name;
    std::string json_schema;
    std::string expected_grammar_output;

    void print_error_header() const {
        fprintf(stderr, "\n#\n# Test '%s' did not pass.\n#\n%s\n", test_name.c_str(), json_schema.c_str());
    }

    void check_grammar_match(const std::string & actual_output) const {
        if (clean_whitespace(actual_output) != clean_whitespace(expected_grammar_output)) {
            print_error_header();
            fprintf(stderr, "# EXPECTED:\n%s\n# ACTUAL:\n%s\n", expected_grammar_output.c_str(), actual_output.c_str());
            assert(false);
        }
    }

    void verify_grammar_validity() const {
        try {
            // Simulate grammar parsing verification
            llama_grammar_parser parser_state;
            parser_state.parse(expected_grammar_output.c_str());
            if (parser_state.symbol_ids.find("root") == parser_state.symbol_ids.end()) {
                throw std::runtime_error("Grammar failed to parse:\n" + expected_grammar_output);
            }
        } catch (const std::runtime_error & error) {
            print_error_header();
            fprintf(stderr, "# GRAMMAR ERROR: %s\n", error.what());
            assert(false);
        }
    }

    void check_test_result(TestResult actual_result) const {
        if (actual_result != expected_outcome) {
            print_error_header();
            fprintf(stderr, "# EXPECTED RESULT: %s\n", 
                   expected_outcome == TestResult::PASS ? "PASS" : "FAIL");
            fprintf(stderr, "# ACTUAL RESULT: %s\n", 
                   actual_result == TestResult::PASS ? "PASS" : "FAIL");
            assert(false);
        }
    }
};

// File utility functions
static void save_to_file(const std::string & filename, const std::string & content) {
    std::ofstream output_file;
    output_file.open(filename);
    output_file << content;
    output_file.close();
}

static std::string load_from_file(const std::string & filename) {
    std::ifstream input_file(filename);
    std::ostringstream buffer;
    buffer << input_file.rdbuf();
    return buffer.str();
}

