#include <iostream>

// A simple calculator to perform basic arithmetic operations
int main() {
    int choice;
    std::cout << "make any choise\n";
    std::cout << "1.sum of nos\n";
    std::cout << "2.diff of nos\n";
    std::cout << "squre of nos\n";
    std::cout << "cube of nos\n";
    std::cin >> choice;

    switch (choice) {
        case 1: {
            int x, y;
            std::cout << "enter any 2 num";
            std::cin >> x >> y;
            int result = x + y;
            std::cout << "sum= " << result << std::endl;
            break;
        }

        case 2: {
            int p, q;
            std::cout << "diff any 2 num ";
            std::cin >> p >> q;
            int diff = p - q;
            std::cout << "diff= " << diff << std::endl;
            break;
        }

        case 3: {
            int val;
            std::cout << "enter any nos";
            std::cin >> val;
            int square = val * val;
            std::cout << "squre= " << square << std::endl;
            break;
        }

        case 4: {
            int n;
            std::cout << "enter any nos";
            std::cin >> n;
            int cube = n * n * n;
            std::cout << "cubic= " << cube << std::endl;
            break;
        }

        default:
            std::cout << "invalid choise" << std::endl;
            break;
    }

    return 0;
}

#include <build/scripts/c_templates/svnversion.h>
