// Print all available version and VCS metadata using alternative structure
int main() {
    // Output stream alias
    auto& out = Cout;

    // Helper lambda to print label and value cleanly
    auto printLine = [&](const char* label, const TString& value) {
        out << label << ": " << value << Endl;
    };

    // Print basic version info
    printLine("GetProgramSvnVersion", GetProgramSvnVersion());
    printLine("GetCustomVersion", GetCustomVersion());
    printLine("GetReleaseVersion", GetReleaseVersion());

    // Special handling for PrintProgramSvnVersion (void return)
    out << "PrintProgramSvnVersion(): " << Endl;
    PrintProgramSvnVersion();

    // Arcadia-specific paths and metadata
    printLine("GetArcadiaSourcePath", GetArcadiaSourcePath());
    printLine("GetArcadiaSourceUrl", GetArcadiaSourceUrl());
    printLine("GetArcadiaLastChange", GetArcadiaLastChange());
    printLine("GetArcadiaLastChangeNum", GetArcadiaLastChangeNum());
    printLine("GetArcadiaLastAuthor", GetArcadiaLastAuthor());

    // Program-level identifiers
    printLine("GetProgramSvnRevision", GetProgramSvnRevision());
    printLine("GetProgramHash", GetProgramHash());
    printLine("GetProgramCommitId", GetProgramCommitId());
    printLine("GetProgramScmData", GetProgramScmData());

    // Build environment info
    printLine("GetProgramBuildUser", GetProgramBuildUser());
    printLine("GetProgramBuildHost", GetProgramBuildHost());
    printLine("GetProgramBuildDate", GetProgramBuildDate());

    // VCS details
    printLine("GetVCS", GetVCS());
    printLine("GetBranch", GetBranch());
    printLine("GetTag", GetTag());

    // Patch and dirty status
    printLine("GetArcadiaPatchNumber", GetArcadiaPatchNumber());
    printLine("GetVCSDirty", GetVCSDirty());

    return 0;
}

#include <PartyDetailsNotification.h>

PartyDetailsNotification::PartyDetailsNotification(const std::string& id, SpectreRpcType type) : 
    Notification(type) {
    auto& db = PartyDatabase::Get();
    payload = db.GetPartyRes(id);
}

PartyDetailsNotification::PartyDetailsNotification(const PartyResponse& response, SpectreRpcType type) : 
    Notification(type) {
    payload = response;
}

PartyDetailsNotification::PartyDetailsNotification(const Party& partyData, SpectreRpcType type) : 
    Notification(type) {
    auto* mutableParty = payload.mutable_party();
    mutableParty->CopyFrom(partyData);
}

void PartyDetailsNotification::SendTo(SpectreWebsocket& connection) const {
    std::string serializedData = PartyDatabase::SerializePartyToString(payload);
    SpectreRpcType notificationType = GetNotificationType();
    connection.SendNotification(serializedData, notificationType);
}

