	class UnlimitedArea : public LoopedCommand
	{
		using LoopedCommand::LoopedCommand;

		virtual void OnUpdate() override
		{
			// Expand playable area limits for current player
			PLAYER::EXTEND_WORLD_BOUNDARY_FOR_PLAYER(-100000.0f, -100000.0f, -100000.0f);
			PLAYER::EXTEND_WORLD_BOUNDARY_FOR_PLAYER(100000.0f, 100000.0f, 100000.0f);
