#include <exception>
#include <sstream>
#include <cstring>
#include <cstdlib>
#include <new>
#include <timemory/unwind/backtrace.hpp>

namespace rocprofsys
{
namespace detail
{
    // Helper: consume any number of arguments without side effects
    template<typename... T>
    inline void ignore_unused(T&&...) noexcept {}

    // Generate backtrace string; accepts optional message(s)
    char* capture_backtrace(const char* msg = nullptr)
    {
        std::ostringstream oss;
        if (msg != nullptr && *msg != '\0')
        {
            oss << msg;
        }

        // Append backtrace info
        tim::unwind::detailed_backtrace<2>(oss, true);

        const std::string& str = oss.str();
        size_t len = str.size() + 1;
        char* result = new char[len];
        std::strcpy(result, str.c_str());
        return result;
    }
}  // namespace detail

template<typename BaseException>
class exception : public BaseException
{
public:
    explicit exception(const std::string& what_arg)
        : BaseException{ what_arg }
        , m_backtrace{ detail::capture_backtrace(what_arg.c_str()) }
    {}

    explicit exception(const char* what_arg)
        : BaseException{ what_arg }
        , m_backtrace{ detail::capture_backtrace(what_arg) }
    {}

    exception(const std::string& what_arg, bool include_trace)
        : BaseException{ what_arg }
        , m_backtrace{ include_trace ? detail::capture_backtrace(what_arg.c_str())
                                     : detail::copy_string(what_arg.c_str()) }
    {}

    ~exception() noexcept override
    {
        delete[] m_backtrace;
    }

    exception(const exception& other)
        : BaseException{ other }
        , m_backtrace{ detail::copy_string(other.m_backtrace) }
    {}

    exception& operator=(const exception& other)
    {
        if (this != &other)
        {
            BaseException::operator=(other);
            delete[] m_backtrace;
            m_backtrace = detail::copy_string(other.m_backtrace);
        }
        return *this;
    }

    const char* what() const noexcept override
    {
        return (m_backtrace != nullptr) ? m_backtrace : BaseException::what();
    }

private:
    char* m_backtrace;
};

// Explicit instantiations
template class exception<std::runtime_error>;
template class exception<std::logic_error>;
template class exception<std::length_error>;
template class exception<std::out_of_range>;
template class exception<std::invalid_argument>;
template class exception<std::domain_error>;
template class exception<std::range_error>;
template class exception<std::overflow_error>;
template class exception<std::underflow_error>;

}  // namespace rocprofsys

