#include "dlmalloc_gtest.hpp"
#include <cstdint>
using namespace rocshmem;

// Overhead introduced by dlmalloc internal structures
constexpr size_t MALLOC_OVERHEAD = 128 * ALIGNMENT;

class DLMallocTestFixture;

// Helper lambda to check allocation success for non-zero sizes
auto allocate_and_verify = [](DLMallocTestFixture& fixture, char*& ptr, size_t nbytes) {
    ptr = nullptr;
    fixture.strat_.alloc(&ptr, nbytes);
    if (nbytes > 0) {
        ASSERT_NE(ptr, nullptr) << "Allocation of " << nbytes << " bytes failed";
    } else {
        ASSERT_EQ(ptr, nullptr) << "Zero-byte allocation should return null";
    }
};

TEST_F(DLMallocTestFixture, used_0_bytes) {
    constexpr size_t total_heap = 1u << 30;
    ASSERT_LE(strat_.get_used(), MALLOC_OVERHEAD);
    ASSERT_EQ(strat_.get_used() + strat_.get_avail(), total_heap);
}

TEST_F(DLMallocTestFixture, alloc_0_bytes) {
    const size_t before_used = strat_.get_used();
    char* out_ptr = nullptr;
    allocate_and_verify(*this, out_ptr, 0);
    ASSERT_EQ(out_ptr, nullptr);
    ASSERT_EQ(strat_.get_used(), before_used);
}

TEST_F(DLMallocTestFixture, alloc_1_byte) {
    char* result = nullptr;
    allocate_and_verify(*this, result, 1);
}

TEST_F(DLMallocTestFixture, alloc_128_bytes) {
    char* result = nullptr;
    allocate_and_verify(*this, result, 128);
}

TEST_F(DLMallocTestFixture, alloc_256_bytes) {
    char* result = nullptr;
    allocate_and_verify(*this, result, 256);
}

TEST_F(DLMallocTestFixture, alloc_512_bytes) {
    char* result = nullptr;
    allocate_and_verify(*this, result, 512);
}

TEST_F(DLMallocTestFixture, alloc_513_bytes) {
    char* result = nullptr;
    allocate_and_verify(*this, result, 513);
}

TEST_F(DLMallocTestFixture, alloc_4KB) {
    char* result = nullptr;
    allocate_and_verify(*this, result, 4096);
}

TEST_F(DLMallocTestFixture, alloc_128KB) {
    char* result = nullptr;
    allocate_and_verify(*this, result, 131072);
}

TEST_F(DLMallocTestFixture, alloc_1GB) {
    constexpr size_t heap_total = 1u << 30;
    char* result = nullptr;
    size_t alloc_size = heap_total - MALLOC_OVERHEAD;
    allocate_and_verify(*this, result, alloc_size);
    ASSERT_EQ(strat_.get_used() + strat_.get_avail(), heap_total);
}

TEST_F(DLMallocTestFixture, alloc_256_bytes_X2_free_256_bytes_X2) {
    char* block1 = nullptr;
    char* block2 = nullptr;
    constexpr size_t blk_size = 256;

    strat_.alloc(&block1, blk_size);
    strat_.alloc(&block2, blk_size);

    ASSERT_NE(block1, nullptr);
    ASSERT_NE(block2, nullptr);

    strat_.free(block1);
    strat_.free(block2);
}

TEST_F(DLMallocTestFixture, alloc_1GB_free_1GB) {
    constexpr size_t heap_total = 1u << 30;
    char* large_block = nullptr;
    size_t request_size = heap_total - MALLOC_OVERHEAD;

    strat_.alloc(&large_block, request_size);
    ASSERT_NE(large_block, nullptr);
    ASSERT_EQ(strat_.get_used() + strat_.get_avail(), heap_total);

    strat_.free(large_block);
}

