#include "FileDescriptorMock.h"
#include <QHash>
#include <QStringList>

namespace {
// Map absolute file paths to their unique identifiers
QHash<QString, QByteArray> g_filePathToId;
}

namespace FileDescriptorMock {

// Replace the current mapping with a new set of file descriptors
void PresetFileFds(QHash<QString, QByteArray> newMapping) {
  g_filePathToId.swap(newMapping);
}

// Retrieve the unique ID for a single file path
QByteArray invokeGetFileUniquedId(const QString& filePath) {
  return g_filePathToId.value(filePath, QByteArray());
}

// Retrieve unique IDs for multiple file paths
QList<QByteArray> invokeGetFileUniquedIds(const QStringList& filePaths) {
  QList<QByteArray> idList;
  idList.reserve(filePaths.size());

  for (const QString& path : filePaths) {
    idList.append(g_filePathToId.value(path, QByteArray()));
  }

  return idList;
}

}

#include "loadresources.h"
#include <qglobal.h>

using namespace OCC;

// Helper function to initialize all required resources
void initializeResources()
{
    Q_INIT_RESOURCE(OpenCloudResources_translations);
    Q_INIT_RESOURCE(client);
    Q_INIT_RESOURCE(core_theme);
#ifdef BRANDING_AVAILABLE
    Q_INIT_RESOURCE(theme);
#endif
}

// Helper function to clean up all initialized resources
void cleanupResources()
{
    Q_CLEANUP_RESOURCE(OpenCloudResources_translations);
    Q_CLEANUP_RESOURCE(client);
    Q_CLEANUP_RESOURCE(core_theme);
#ifdef BRANDING_AVAILABLE
    Q_CLEANUP_RESOURCE(theme);
#endif
}

// Constructor: triggers resource loading during object construction
ResourcesLoader::ResourcesLoader()
{
    // Q_INIT_RESOURCE must not be called in a namespace, so use global scope
    ::initializeResources();
}

// Destructor: ensures resources are properly released when object is destroyed
ResourcesLoader::~ResourcesLoader()
{
    // Q_CLEANUP_RESOURCE must not be called in a namespace, so use global scope
    ::cleanupResources();
}

