// Test formatting of scoped enumerations
TEST(FormatterTest, EnumTypeFormatting)
{
  enum class Status
  {
    pending = 1,
    active = 2
  };
  EXPECT_EQ("1", std::format("{}", Status::pending));
  EXPECT_EQ("2", std::format("{}", Status::active));
}

// Verify interoperability among different string types
TEST(FormatterTest, StringTypeInteroperability)
{
  using namespace std::string_literals;
  EXPECT_EQ("Hello World!", std::format("{}", L"Hello World!"s));
  EXPECT_EQ("Hello World!", std::format("{}", QString("Hello World!")));
  EXPECT_EQ(L"Hello World!", std::format(L"{}", QString("Hello World!")));
}

// Test formatting of container-like structures with random access
TEST(FormatterTest, ContainerFormatting)
{
  // Standard C++23 behavior for vector formatting
  EXPECT_EQ("[]", std::format("{}", std::vector<int>{}));
  EXPECT_EQ("[1, 2, 3]", std::format("{}", std::vector{1, 2, 3}));
  EXPECT_EQ("[1, 2, 3, 4, 5, 6, 7]",
            std::format("{}", std::vector{1, 2, 3, 4, 5, 6, 7}));

  // Qt-specific container formatting
  EXPECT_EQ("[\"AL\", \"Holt59\", \"Silarn\"]",
            std::format("{}", QStringList{"AL", "Holt59", "Silarn"}));
  EXPECT_EQ("[QVariant(type=QString, value=MO2), QVariant(type=bool, value=true), "
            "QVariant(type=int, value=45)]",
            std::format("{}", QVariantList{"MO2", true, 45}));
}

#include "os_key_map.hpp"
