#include "dap/variant.h"
#include "dap/typeof.h"
#include "dap/types.h"
#include "gmock/gmock.h"
#include "gtest/gtest.h"

namespace dap {

struct VariantTestObject {
  dap::integer i;
  dap::number n;
};

DAP_STRUCT_TYPEINFO(VariantTestObject,
                    "VariantTestObject",
                    DAP_FIELD(i, "i"),
                    DAP_FIELD(n, "n"));

}  // namespace dap

// Test variant default construction - should default to first type (integer)
TEST(Variant, EmptyConstruct) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestObject> var;
  ASSERT_TRUE(var.is<dap::integer>());
  ASSERT_FALSE(var.is<dap::boolean>());
  ASSERT_FALSE(var.is<dap::VariantTestObject>());
}

// Test variant with boolean value
TEST(Variant, Boolean) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestObject> var(
      dap::boolean(true));
  ASSERT_TRUE(var.is<dap::boolean>());
  ASSERT_EQ(var.get<dap::boolean>(), dap::boolean(true));
}

// Test variant with integer value
TEST(Variant, Integer) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestObject> var(
      dap::integer(10));
  ASSERT_TRUE(var.is<dap::integer>());
  ASSERT_EQ(var.get<dap::integer>(), dap::integer(10));
}

// Test variant with custom object
TEST(Variant, TestObject) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestObject> var(
      dap::VariantTestObject{5, 3.0});
  ASSERT_TRUE(var.is<dap::VariantTestObject>());
  const auto& obj = var.get<dap::VariantTestObject>();
  ASSERT_EQ(obj.i, 5);
  ASSERT_EQ(obj.n, 3.0);
}

// Test variant assignment between different types
TEST(Variant, Assign) {
  using variant_type = dap::variant<dap::integer, dap::boolean, dap::VariantTestObject>;
  variant_type var(dap::integer(10));

  // First assignment - keep same type
  var = dap::integer(10);
  ASSERT_TRUE(var.is<dap::integer>());
  ASSERT_FALSE(var.is<dap::boolean>());
  ASSERT_FALSE(var.is<dap::VariantTestObject>());
  ASSERT_EQ(var.get<dap::integer>(), dap::integer(10));

  // Second assignment - change to boolean
  var = dap::boolean(true);
  ASSERT_FALSE(var.is<dap::integer>());
  ASSERT_TRUE(var.is<dap::boolean>());
  ASSERT_FALSE(var.is<dap::VariantTestObject>());
  ASSERT_EQ(var.get<dap::boolean>(), dap::boolean(true));

  // Third assignment - change to custom object
  var = dap::VariantTestObject{5, 3.0};
  ASSERT_FALSE(var.is<dap::integer>());
  ASSERT_FALSE(var.is<dap::boolean>());
  ASSERT_TRUE(var.is<dap::VariantTestObject>());
  const auto& obj2 = var.get<dap::VariantTestObject>();
  ASSERT_EQ(obj2.i, 5);
  ASSERT_EQ(obj2.n, 3.0);
}

// Test variant type acceptance
TEST(Variant, Accepts) {
  using variant =
      dap::variant<dap::integer, dap::boolean, dap::VariantTestObject>;
  ASSERT_TRUE(variant::accepts<dap::integer>());
  ASSERT_TRUE(variant::accepts<dap::boolean>());
  ASSERT_TRUE(variant::accepts<dap::VariantTestObject>());
  ASSERT_FALSE(variant::accepts<dap::number>());
  ASSERT_FALSE(variant::accepts<dap::string>());
}

