namespace sen::components::py
{
std::string InterpreterObj::evalImpl(const std::string& expr)
{
  pybind11::object result;
  executeInGIL([&result, &expr]() { 
    result = pybind11::eval(expr); 
  });
  return result ? pybind11::str(result).cast<std::string>() : "";
}

void InterpreterObj::execImpl(const std::string& code)
{
  executeInGIL([&code]() { 
    pybind11::exec(code); 
  });
}

void InterpreterObj::execFileImpl(const std::string& file)
{
  executeInGIL([&file]() { 
    pybind11::eval_file(file); 
  });
}

void InterpreterObj::executeInGIL(std::function<void()>&& func) const
{
  pybind11::gil_scoped_acquire gil_lock;
  try
  {
    func();
  }
  catch (pybind11::error_already_set& ex)
  {
    getLogger()->error(ex.what());
    ex.discard_as_unraisable("py::interpreter");
  }
  catch (const pybind11::attribute_error& ex)
  {
    getLogger()->error(ex.what());
    throwRuntimeError(ex.what());
  }
  catch (...)
  {
    getLogger()->error("interpreter: unexpected error occurred");
    throwRuntimeError("interpreter: unexpected error occurred");
  }
}
}  // namespace sen::components::py

