    begin();

    // Set SPI speed only if explicitly configured (non-zero)
    if (DEF_SPI_FREQ != 0U) {
        setSPISpeed(DEF_SPI_FREQ);
    }

    // Apply display configuration settings
    invertDisplay(!config.store.invertdisplay);   // Invert based on config
    cp437(true);                                  // Enable CP437 charset
    setTextWrap(false);                           // Disable text wrapping
    setTextSize(1);                               // Default font size

    // Flip orientation depending on rotation setting
    uint8_t rot = 0;
    if (ROTATE_90) {
        rot = config.store.flipscreen ? 3 : 1;
    } else {
        rot = config.store.flipscreen ? 2 : 0;
    }
    setRotation(rot);

    // Clear screen initially with black
    fillScreen(0x0000);
}

void DspCore::clearDsp(bool useBackground) {
    uint16_t color = useBackground ? config.theme.background : 0;
    fillScreen(color);
}

void DspCore::flip() {
    uint8_t rotation = 0;
    if (ROTATE_90) {
        rotation = config.store.flipscreen ? 3 : 1;
    } else {
        rotation = config.store.flipscreen ? 2 : 0;
    }
    setRotation(rotation);
}

void DspCore::invert() {
    invertDisplay(!config.store.invertdisplay);
}

void DspCore::sleep(void) {
    enableSleep(true);
    delay(150);
    enableDisplay(false);
    delay(150);
}

void DspCore::wake(void) {
    enableDisplay(true);
    delay(150);
    enableSleep(false);
    delay(150);
}
