#include "gtest/gtest.h"

using namespace lbug::common;

// Helper macro to reduce boilerplate in exception tests
#define EXPECT_THROW_TIMESTAMP_FROM_DATETIME(expr, expected_msg) \
    try { \
        expr; \
        FAIL() << "Expected ConversionException not thrown"; \
    } catch (const ConversionException& e) { \
        EXPECT_STREQ(e.what(), expected_msg); \
    } catch (const std::exception&) { \
        FAIL() << "Unexpected std::exception thrown"; \
    }

TEST(TimestampTests, FromDatetime) {
    // Invalid day: 42 in December
    EXPECT_THROW_TIMESTAMP_FROM_DATETIME(
        Timestamp::fromDateTime(Date::fromDate(1968, 12, 42), Time::fromTime(21, 32, 51)),
        "Conversion exception: Date out of range: 1968-12-42.");

    // February 29 on non-leap year (2021)
    EXPECT_THROW_TIMESTAMP_FROM_DATETIME(
        Timestamp::fromDateTime(Date::fromDate(2021, 2, 29), Time::fromTime(21, 32, 51)),
        "Conversion exception: Date out of range: 2021-2-29.");

    // Hour out of range (25)
    EXPECT_THROW_TIMESTAMP_FROM_DATETIME(
        Timestamp::fromDateTime(Date::fromDate(1968, 12, 22), Time::fromTime(25, 32, 51)),
        "Conversion exception: Time field value out of range: 25:32:51[.0].");

    // Seconds out of range (70)
    EXPECT_THROW_TIMESTAMP_FROM_DATETIME(
        Timestamp::fromDateTime(Date::fromDate(2021, 2, 28), Time::fromTime(5, 52, 70)),
        "Conversion exception: Time field value out of range: 5:52:70[.0].");

    // Microseconds out of range (>= 1,000,000)
    EXPECT_THROW_TIMESTAMP_FROM_DATETIME(
        Timestamp::fromDateTime(Date::fromDate(2021, 2, 28), Time::fromTime(5, 52, 42, 1000002)),
        "Conversion exception: Time field value out of range: 5:52:42[.1000002].");

    // Valid cases with expected values
    EXPECT_EQ(
        Timestamp::fromDateTime(Date::fromDate(2020, 10, 22), Time::fromTime(21, 32, 51)).value,
        1603402371000000);

    EXPECT_EQ(
        Timestamp::fromDateTime(Date::fromDate(1978, 5, 22), Time::fromTime(0, 54, 32, 7891)).value,
        264646472007891);
}

TEST(TimestampTests, Convert) {
    date_t calendar_date;
    dtime_t time_of_day;

    // Test conversion of timestamp 1603402371000000 → 2020-10-22 21:32:51
    Timestamp::convert(timestamp_t(1603402371000000), calendar_date, time_of_day);
    EXPECT_EQ(calendar_date.days, 18557);
    EXPECT_EQ(time_of_day.micros, 77571000000);

    // Test conversion of timestamp 4501210883005612 → 2112-08-21 08:21:23.005612
    Timestamp::convert(timestamp_t(4501210883005612), calendar_date, time_of_day);
    EXPECT_EQ(calendar_date.days, 52097);
    EXPECT_EQ(time_of_day.micros, 30083005612);
}

TEST(TimestampTests, FromCString) {
    // Standard ISO-like formats
    EXPECT_EQ(
        Timestamp::fromCString("2112-08-21 08:21:23.005612", strlen("2112-08-21 08:21:23.005612")).value,
        4501210883005612);

    EXPECT_EQ(
        Timestamp::fromCString("1992-04-28T09:22:56", strlen("1992-04-28T09:22:56")).value,
        704452976000000);

    EXPECT_EQ(
        Timestamp::fromCString("2023-08-12", strlen("2023-08-12")).value,
        1691798400000000);

    // With timezone suffixes
    EXPECT_EQ(
        Timestamp::fromCString("2112-08-21 08:21:23.005612Z", strlen("2112-08-21 08:21:23.005612Z")).value,
        4501210883005612);

    EXPECT_EQ(
        Timestamp::fromCString("2112-08-21 08:21:23.005612Z+00:00",
            strlen("2112-08-21 08:21:23.005612Z+00:00")).value,
        4501210883005612);

    EXPECT_EQ(
        Timestamp::fromCString("2112-08-21 08:21:23.005612Z+02:00",
            strlen("2112-08-21 08:21:23.005612Z+02:00")).value,
        4501203683005612);

    EXPECT_EQ(
        Timestamp::fromCString("1992-04-28T09:22:56-09:00",
            strlen("1992-04-28T09:22:56-09:00")).value,
        704485376000000);

    EXPECT_EQ(
        Timestamp::fromCString("1992-04-28T09:22:56-09",
            strlen("1992-04-28T09:22:56-09")).value,
        704485376000000);

    EXPECT_EQ(
        Timestamp::fromCString("1992-04-28T09:22:56-09:00   ",
            strlen("1992-04-28T09:22:56-09:00   ")).value,
        704485376000000);

    EXPECT_EQ(
        Timestamp::fromCString("1992-04-28T09:22:56-06:30",
            strlen("1992-04-28T09:22:56-06:30")).value,
        704476376000000);
}

TEST(TimestampTests, toString) {
    EXPECT_EQ(Timestamp::toString(timestamp_t(1691798400000000)), "2023-08-12 00:00:00");
    EXPECT_EQ(Timestamp::toString(timestamp_t(4501210883005612)), "2112-08-21 08:21:23.005612");
    EXPECT_EQ(Timestamp::toString(timestamp_t(704452976000000)), "1992-04-28 09:22:56");
}

