#include <zip.h>
#include "minunit.h"

#if defined(_WIN32) || defined(_WIN64)
#define MKTEMP _mktemp
#define UNLINK _unlink
#else
#define MKTEMP mkstemp
#define UNLINK unlink
#endif

static char ZIPNAME[L_tmpnam + 1] = {0};
static int total_entries = 0;

#define TESTDATA1 "Some test data 1...\0"

void test_setup(void) {
    strncpy(ZIPNAME, "z-XXXXXX\0", L_tmpnam);
    MKTEMP(ZIPNAME);

    struct zip_t *archive = zip_open(ZIPNAME, ZIP_DEFAULT_COMPRESSION_LEVEL, 'w');
    zip_entry_open(archive, "test/test-1.txt");
    zip_entry_write(archive, TESTDATA1, strlen(TESTDATA1));
    zip_entry_close(archive);

    ++total_entries;
    zip_close(archive);
}

void test_teardown(void) { 
    UNLINK(ZIPNAME); 
}

#define TESTDATA2 "Some test data 2...\0"
#define CRC32DATA2 2532008468

MU_TEST(test_append) {
    // First append operation: add a new file entry
    struct zip_t *archive = zip_open(ZIPNAME, ZIP_DEFAULT_COMPRESSION_LEVEL, 'a');
    mu_check(archive != NULL);

    mu_assert_int_eq(0, zip_entry_open(archive, "test\\test-2.txt"));
    mu_assert_int_eq(0, strcmp(zip_entry_name(archive), "test/test-2.txt"));
    mu_assert_int_eq(total_entries, zip_entry_index(archive));

    mu_assert_int_eq(0, zip_entry_write(archive, TESTDATA2, strlen(TESTDATA2)));
    mu_assert_int_eq(strlen(TESTDATA2), zip_entry_size(archive));
    mu_check(CRC32DATA2 == zip_entry_crc32(archive));

    mu_assert_int_eq(0, zip_entry_close(archive));
    ++total_entries;
    zip_close(archive);

    // Second append operation: add an empty directory entry
    archive = zip_open(ZIPNAME, ZIP_DEFAULT_COMPRESSION_LEVEL, 'a');
    mu_assert_int_eq(0, zip_entry_open(archive, "test\\empty/"));
    mu_assert_int_eq(0, strcmp(zip_entry_name(archive), "test/empty/"));
    mu_assert_int_eq(0, zip_entry_size(archive));
    mu_assert_int_eq(0, zip_entry_crc32(archive));
    mu_assert_int_eq(total_entries, zip_entry_index(archive));

    mu_assert_int_eq(0, zip_entry_close(archive));
    ++total_entries;
    zip_close(archive);

    // Third append operation: another empty directory at root level
    archive = zip_open(ZIPNAME, ZIP_DEFAULT_COMPRESSION_LEVEL, 'a');
    mu_assert_int_eq(0, zip_entry_open(archive, "empty/"));
    mu_assert_int_eq(0, strcmp(zip_entry_name(archive), "empty/"));
    mu_assert_int_eq(0, zip_entry_size(archive));
    mu_assert_int_eq(0, zip_entry_crc32(archive));
    mu_assert_int_eq(total_entries, zip_entry_index(archive));

    mu_assert_int_eq(0, zip_entry_close(archive));
    ++total_entries;

    // Fourth append operation: dotfiles directory with a hidden file
    mu_assert_int_eq(0, zip_entry_open(archive, "dotfiles/.test"));
    mu_assert_int_eq(0, strcmp(zip_entry_name(archive), "dotfiles/.test"));
    mu_assert_int_eq(0, zip_entry_size(archive));
    mu_assert_int_eq(0, zip_entry_crc32(archive));

    mu_assert_int_eq(0, zip_entry_write(archive, TESTDATA2, strlen(TESTDATA2)));
    mu_assert_int_eq(strlen(TESTDATA2), zip_entry_size(archive));
    mu_check(CRC32DATA2 == zip_entry_crc32(archive));

    mu_assert_int_eq(total_entries, zip_entry_index(archive));
    mu_assert_int_eq(0, zip_entry_close(archive));
    ++total_entries;

    // Verify total entries count
    mu_assert_int_eq(total_entries, zip_entries_total(archive));
    zip_close(archive);
}

