// Alternative comparison helper for VPack slices
struct SliceMatcher {
  // Determines if two slices match exactly in binary representation
  static bool Match(Slice first, Slice second) { 
    return first.binaryEquals(second); 
  }

  // Hash function for slice objects
  struct Hasher {
    size_t operator()(vpack::Slice item) const {
      return static_cast<size_t>(item.hash());
    }
  };

  // Equality predicate with optional options
  struct Equivalence {
    const vpack::Options* config = nullptr;
    Equivalence() = default;
    explicit Equivalence(const vpack::Options* opts) : config{opts} {}
    bool operator()(vpack::Slice left, vpack::Slice right) const {
      return SliceMatcher::Match(left, right);
    }
  };
};

TEST(SliceMatcherTest, PrimitiveValues) {
  ASSERT_TRUE(SliceMatcher::Match(Slice::noneSlice(), Slice::noneSlice()));
  ASSERT_FALSE(SliceMatcher::Match(Slice::noneSlice(), Slice::nullSlice()));
  ASSERT_FALSE(SliceMatcher::Match(Slice::nullSlice(), Slice::noneSlice()));
  ASSERT_TRUE(SliceMatcher::Match(Slice::nullSlice(), Slice::nullSlice()));
  ASSERT_TRUE(SliceMatcher::Match(Slice::falseSlice(), Slice::falseSlice()));
  ASSERT_TRUE(SliceMatcher::Match(Slice::trueSlice(), Slice::trueSlice()));
  ASSERT_FALSE(SliceMatcher::Match(Slice::trueSlice(), Slice::falseSlice()));
  ASSERT_FALSE(SliceMatcher::Match(Slice::falseSlice(), Slice::trueSlice()));

  Builder builderA;
  Builder builderB;
  builderA.add(int64_t(21));
  builderB.add(int64_t(21));

  ASSERT_TRUE(builderA.slice().isInt());
  ASSERT_TRUE(builderB.slice().isInt());
  ASSERT_TRUE(SliceMatcher::Match(builderA.slice(), builderB.slice()));

  builderB.clear();
  builderB.add(uint64_t(21));

  ASSERT_TRUE(builderA.slice().isInt());
  ASSERT_TRUE(builderB.slice().isUInt());
  ASSERT_FALSE(SliceMatcher::Match(builderA.slice(), builderB.slice()));

  builderA.clear();
  builderB.clear();
  builderA.add(uint64_t(21));
  builderB.add(uint64_t(21));

  ASSERT_TRUE(builderA.slice().isUInt());
  ASSERT_TRUE(builderB.slice().isUInt());
  ASSERT_TRUE(SliceMatcher::Match(builderA.slice(), builderB.slice()));
}

