#ifdef LLK_TRISC_UNPACK
#include "llk_unpack_AB_matmul.h"
#include "llk_unpack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Configure hardware for unpack operations on A and B matrices
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        fmts.unpack_A_src,
        fmts.unpack_B_src,
        fmts.unpack_A_dst,
        fmts.unpack_B_dst,
        FACE_R_DIM,
        FACE_R_DIM,
        params->num_faces_A,
        params->num_faces_B,
        params->TILE_SIZE_UNPACK_A,
        params->TILE_SIZE_UNPACK_B);

    // Initialize unpack matmul engine with tile dimensions
    _llk_unpack_AB_matmul_init_<>(0, params->CT_DIM, params->RT_DIM, params->KT_DIM, FACE_R_DIM, FACE_R_DIM, 4, 4, false, false);

    // Process each K-tile dimension sequentially
    std::uint32_t k_idx = 0;
    while (k_idx < params->KT_DIM) {
        _llk_unpack_AB_matmul_<>(
            L1_ADDRESS(params->buffer_A[0]),
            L1_ADDRESS(params->buffer_B[0]),
            k_idx,
            k_idx * params->CT_DIM,
            params->TILE_SIZE_UNPACK_A,
            params->TILE_SIZE_UNPACK_B,
            false,
            false,
            params->CT_DIM,
            params->RT_DIM,
            params->KT_DIM);
        ++k_idx;
    }
}
#endif

#ifdef LLK_TRISC_MATH
#include "llk_math_common.h"
#include "llk_math_matmul.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Setup math matrix multiplication with fidelity level
    _llk_math_matmul_init_<MATH_FIDELITY>(TILE_R_DIM, TILE_C_DIM, TILE_R_DIM, TILE_C_DIM, false, 0, params->CT_DIM, params->RT_DIM);

    // Prepare destination synchronization and format configuration
    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(fmts.math, fmts.math);

    // Validate tile count fits within destination buffer capacity
    LLK_ASSERT(
        get_dest_max_matmul_tiles(0 /* DST_INDEX */, params->CT_DIM, params->RT_DIM) <
        get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
        "Block tile index exceeds maximum destination tiles for matmul");

    // Wait until destination buffer space becomes available
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Perform matmul for each K-dimension slice
    std::uint32_t k_loop = 0;
    while (k_loop < params->KT_DIM) {
        _llk_math_matmul_<MATH_FIDELITY>(0, params->CT_DIM, params->RT_DIM);
        ++k_loop;
    }

    // Signal completion of destination section
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

#ifdef ARCH_BLACKHOLE
    // Blackhole-specific pack configuration
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(fmts.pack_src, fmts.pack_dst, params->TILE_SIZE_PACK);
    _llk_pack_init_<false, false, false>(fmts.pack_dst);
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    // Generic pack configuration for other architectures
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(fmts.pack_src, fmts.pack_dst, params->TILE_SIZE_PACK);
    _llk_pack_init_<false, false>(fmts.pack_dst);
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>();
#endif

    // Ensure math unit has finished before packing starts
    _llk_packer_wait_for_math_done_();

    // Pack each computed tile into output buffer
    int tile_id = 0;
    while (tile_id < params->TILE_CNT) {
        LLK_ASSERT((tile_id < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()), "Tile ID exceeds max dest tiles");
        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(tile_id, L1_ADDRESS(params->buffer_Res[tile_id]));
        ++tile_id;
    }

    // Finalize destination section
    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

