template<typename T>
IGL_INLINE void igl::svd3x3(const Eigen::Matrix<T, 3, 3>& A,
                            Eigen::Matrix<T, 3, 3>& U_out,
                            Eigen::Matrix<T, 3, 1>& S_diag,
                            Eigen::Matrix<T, 3, 3>& V_out)
{
    // Local scalar storage for intermediate values during computation
    T a11 = A(0, 0), a21 = A(1, 0), a31 = A(2, 0);
    T a12 = A(0, 1), a22 = A(1, 1), a32 = A(2, 1);
    T a13 = A(0, 2), a23 = A(1, 2), a33 = A(2, 2);

    // Placeholder variables that will be populated by kernel body
    T u11 = 0, u21 = 0, u31 = 0;
    T u12 = 0, u22 = 0, u32 = 0;
    T u13 = 0, u23 = 0, u33 = 0;

    T v11 = 0, v21 = 0, v31 = 0;
    T v12 = 0, v22 = 0, v32 = 0;
    T v13 = 0, v23 = 0, v33 = 0;

    T sigma1 = 0, sigma2 = 0, sigma3 = 0;

#include "Singular_Value_Decomposition_Kernel_Declarations.hpp"
#include "Singular_Value_Decomposition_Main_Kernel_Body.hpp"

    // Assign results to output matrices/vectors explicitly
    U_out << u11, u21, u31,
             u12, u22, u32,
             u13, u23, u33;

    V_out << v11, v21, v31,
             v12, v22, v32,
             v13, v23, v33;

    S_diag << sigma1, sigma2, sigma3;
}

