#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"

static safety_check_abort_hook_t abort_handler;

void report_sized_dealloc_error(bool is_current_free, const void *address,
    size_t actual_size, size_t expected_size) {
    const char *source_desc = is_current_free ? 
        "the pointer currently being deallocated" : 
        "in thread cache, possibly from earlier deallocations";

    safety_check_fail("<jemalloc>: size inconsistency detected (actual size %zu "
        "vs provided size %zu), probably due to application errors in sized "
        "deallocation (address: %p, %s). Recommend compiling with "
        "--enable-debug or using AddressSanitizer for diagnostics. Terminating.\n",
        actual_size, expected_size, address, source_desc);
}

void set_safety_abort_callback(safety_check_abort_hook_t callback) {
    abort_handler = callback;
}

void safety_check_fail(const char *msg, ...) {
    char buffer[MALLOC_PRINTF_BUFSIZE];
    va_list args;
    va_start(args, msg);
    malloc_vsnprintf(buffer, MALLOC_PRINTF_BUFSIZE, msg, args);
    va_end(args);

    if (abort_handler == NULL) {
        malloc_write(buffer);
        abort();
    } else {
        abort_handler(buffer);
    }
}

#include "autolink/transport/common/identity.hpp"
#include "gtest/gtest.h"

namespace autolink {
namespace transport {

TEST(IdentityTest, testConstructFalse) {
  Identity obj(false);
  ASSERT_EQ(obj.HashValue(), static_cast<uint64_t>(0));
  ASSERT_EQ(obj.ToString(), "0");
}

TEST(IdentityTest, testConstructTrue) {
  Identity obj(true);
  ASSERT_NE(obj.HashValue(), static_cast<uint64_t>(0));
  ASSERT_NE(obj.ToString(), "0");
}

TEST(IdentityTest, testIdentityEqual) {
  Identity id_a;
  Identity id_b;
  Identity id_c;

  // Verify distinct identities by default
  EXPECT_NE(id_a, id_b);
  EXPECT_NE(id_b, id_c);
  EXPECT_NE(id_a, id_c);
  EXPECT_NE(id_a.HashValue(), id_c.HashValue());

  // Test self-assignment
  id_b = id_b;
  EXPECT_NE(id_b, id_c);

  // Test copy assignment
  id_b = id_c;
  EXPECT_EQ(id_b, id_c);

  // Test copy constructor
  Identity id_d(id_a);
  EXPECT_EQ(id_a, id_d);
  EXPECT_EQ(id_a.ToString(), id_d.ToString());
  EXPECT_EQ(id_a.HashValue(), id_d.HashValue());
}

TEST(IdentityTest, testOperatorEqual) {
  Identity src(true);
  Identity dst(false);

  // Test assignment operator
  dst = src;
  EXPECT_EQ(src.HashValue(), dst.HashValue());
  EXPECT_EQ(src.ToString(), dst.ToString());
  EXPECT_EQ(dst.Length(), src.Length());

  // Test data pointer operations
  src.set_data(nullptr);
  Identity third;
  third.set_data(src.data());
  EXPECT_EQ(third.HashValue(), dst.HashValue());
  EXPECT_EQ(third.ToString(), dst.ToString());
  EXPECT_EQ(dst.Length(), third.Length());
}

