// Tiling key constants for single vs multi-round execution modes
constexpr int32_t SINGLE_ROUND_MODE = 10000;
constexpr int32_t MULTI_ROUND_MODE  = 10001;

extern "C" __global__ __aicore__ void cam_moe_combine_normal(
    GM_ADDR recvX,
    GM_ADDR tokenSrcInfo,
    GM_ADDR epRecvCount,
    GM_ADDR topkWeights,
    GM_ADDR tokenIdx,
    GM_ADDR tpRecvCount,
    GM_ADDR XOut,
    GM_ADDR sendCostStatsOut,
    GM_ADDR workspaceGM,
    GM_ADDR tilingGM)
{
    // Register default tiling data structure
    REGISTER_TILING_DEFAULT(CamMoeCombineNormalTilingData);

    TPipe pipeline;

#if (ORIG_DTYPE_RECV_X == DT_BF16 || ORIG_DTYPE_RECV_X == DT_FLOAT16)
    // Retrieve tiling configuration from GM
    GET_TILING_DATA_WITH_STRUCT(CamMoeCombineNormalTilingData, tilingConfig, tilingGM);

    // Determine execution mode based on tiling key
    const int32_t modeKey = GetTilingKey();

    if (modeKey == MULTI_ROUND_MODE) {
        CamMoeCombineNormalMultiRoundImpl::CamMoeCombineNormalMultiRound<DTYPE_RECV_X, DTYPE_X, int32_t> op;
        op.Init(recvX, tokenSrcInfo, epRecvCount, topkWeights, tokenIdx, tpRecvCount, XOut, sendCostStatsOut,
                workspaceGM, &pipeline, &tilingConfig);
        op.Process();
    } else if (modeKey == SINGLE_ROUND_MODE) {
        CamMoeCombineNormalImpl::CamMoeCombineNormal<DTYPE_RECV_X, DTYPE_X, int32_t> op;
        op.Init(recvX, tokenSrcInfo, epRecvCount, topkWeights, tokenIdx, tpRecvCount, XOut, sendCostStatsOut,
                workspaceGM, &pipeline, &tilingConfig);
        op.Process();
    }
#endif
}

