    void Variable::SetReferenceable(const Data& val) {
        // Enforce immutability for constants
        if (isconstant) {
            throw CastException("Constant", "Non-constant", "During assignment operation");
        }

        const auto& varType = GetTypeRef();

        if (val.IsReference()) {
            varType.Assign(*this, val);
            VirtualMachine::Get().References.Increase(val);
        } else {
            varType.Assign(*this, val);
        }
    }

