#include "Alias/Dynamic/MemoryInstrument.h"
#include <llvm/Bitcode/BitcodeWriter.h>
#include <llvm/IR/LLVMContext.h>
#include <llvm/IR/Module.h>
#include <llvm/IRReader/IRReader.h>
#include <llvm/Support/CommandLine.h>
#include <llvm/Support/FileSystem.h>
#include <llvm/Support/SourceMgr.h>
#include <llvm/Support/ToolOutputFile.h>

using namespace llvm;

static cl::opt<std::string> InputFile(cl::Positional, 
                                      cl::desc("<input IR file>"),
                                      cl::init("-"));
static cl::opt<std::string> OutputFile("o", 
                                       cl::desc("Specify output bitcode filename"),
                                       cl::value_desc("filename"), 
                                       cl::Required);

int main(int argc, char **argv) {
  cl::ParseCommandLineOptions(argc, argv);

  LLVMContext llvmCtx;
  SMDiagnostic diag;

  auto irModule = parseIRFile(InputFile, diag, llvmCtx);
  if (!irModule) {
    diag.print(argv[0], errs());
    return 1;
  }

  dynamic::MemoryInstrument memPass;
  memPass.runOnModule(*irModule);

  std::error_code err;
  ToolOutputFile out(OutputFile, err, sys::fs::OF_None);
  if (err) {
    errs() << "Error opening output file: " << err.message() << "\n";
    return 2;
  }

  out.keep();
  WriteBitcodeToFile(*irModule, out.os());

  return 0;
}

