#ifdef LLK_TRISC_UNPACK
#include "llk_unpack_A.h"
#include "llk_unpack_common.h"

void run_kernel(const volatile struct RuntimeParams* cfg)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = cfg->formats;
#endif

    // Configure hardware for unpacking A and B streams
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        fmts.unpack_A_src, fmts.unpack_B_src, fmts.unpack_A_dst, fmts.unpack_B_dst,
        FACE_R_DIM, FACE_R_DIM, cfg->num_faces, cfg->num_faces);

    // Initialize unpacker for tensor A (no broadcast, no reuse)
    _llk_unpack_A_init_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
        cfg->UNPACK_TRANSPOSE_FACES, 0, FACE_R_DIM, cfg->num_faces, fmts.unpack_A_src, fmts.unpack_A_dst);

    // Process each tile via unpack operation
    int tile_idx = 0;
    do {
        _llk_unpack_A_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
            L1_ADDRESS(cfg->buffer_A[tile_idx]), fmts.unpack_A_src, fmts.unpack_A_dst);
        ++tile_idx;
    } while (tile_idx < cfg->TILE_CNT);

    // Ensure source B is marked valid (dummy usage)
    for (int j = 0; j < cfg->TILE_CNT; ++j) {
        _llk_unpack_set_srcb_dummy_valid_();
    }
}
#endif

#ifdef LLK_TRISC_MATH
#include "llk_math_common.h"
#include "llk_math_eltwise_unary_datacopy.h"
#include "llk_math_transpose_dest.h"
using namespace ckernel;

void run_kernel(const volatile struct RuntimeParams* cfg)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = cfg->formats;
#endif

    constexpr bool is32bit_mode = is_fp32_dest_acc_en;

#ifdef ARCH_BLACKHOLE
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, false>(
        cfg->num_faces, fmts.math);
#else
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false>(
        cfg->num_faces, fmts.math);
#endif

    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(fmts.math, fmts.math);
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Main data copy loop over tiles
    int tidx = 0;
    while (tidx < cfg->TILE_CNT) {
        LLK_ASSERT(
            tidx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");

#ifdef ARCH_BLACKHOLE
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            tidx, fmts.math, fmts.math);
#else
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            tidx, fmts.math, fmts.math);
#endif
        ++tidx;
    }

    // Setup transpose destination
    _llk_math_transpose_dest_init_<MATH_TRANSPOSE_FACES, is32bit_mode>();

    // Perform transpose per tile
    int tidx2 = 0;
    do {
        LLK_ASSERT(
            tidx2 < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");

#ifdef ARCH_BLACKHOLE
        _llk_math_transpose_dest_<is_fp32_dest_acc_en, MATH_TRANSPOSE_FACES, is32bit_mode>(tidx2);
#else
        _llk_math_transpose_dest_<MATH_TRANSPOSE_FACES, is32bit_mode>(tidx2);
#endif
        ++tidx2;
    } while (tidx2 < cfg->TILE_CNT);

    // Signal completion of destination section
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"

void run_kernel(const volatile struct RuntimeParams* cfg)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = cfg->formats;
#endif

#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(
        fmts.pack_src, fmts.pack_dst, 16 * 16 * 4, FACE_R_DIM, TILE_C_DIM, cfg->num_faces);
    _llk_pack_init_<false, false, false>(fmts.pack_dst, FACE_R_DIM, TILE_C_DIM, cfg->num_faces);
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(
        fmts.pack_src, fmts.pack_dst, 16 * 16 * 4, FACE_R_DIM, cfg->num_faces);
    _llk_pack_init_<false, false>(fmts.pack_dst, FACE_R_DIM, cfg->num_faces);
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>();
#endif

    _llk_packer_wait_for_math_done_();

    int pidx = 0;
    for (; pidx < cfg->TILE_CNT; ++pidx) {
        LLK_ASSERT(
            pidx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");
        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(
            pidx, L1_ADDRESS(cfg->buffer_Res[pidx]));
    }

    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#include <mesh_globals.h>
#include <panel4.h>

// Apply rotation to quad mesh nodes around origin with given angles
void rotateQuadMesh(std::vector<Panel4> &panel4, double alpha, double beta)
{
    Vector3d pivotPoint;
    for(uint i = 0; i < panel4.size(); ++i)
    {
        Panel4 &currentPanel = panel4[i];
        for(int nodeIdx = 0; nodeIdx < 4; ++nodeIdx)
        {
            currentPanel.m_Node[nodeIdx].rotateZ(pivotPoint, beta);
            currentPanel.m_Node[nodeIdx].rotateY(pivotPoint, alpha);
        }
        currentPanel.updateFrame();
    }
}

