namespace pulse {

// Test that adding a disequality first prevents subsequent equality
TEST(PulseFormulaTest, DisequalityPrecludesEquality) {
    PulseFormula formula;
    AbstractValue val1(nullptr, 10);
    AbstractValue val2(nullptr, 20);

    ASSERT_TRUE(formula.addDisequality(val1, val2));
    EXPECT_FALSE(formula.addEquality(val1, val2));
}

// Test that adding an equality first prevents subsequent disequality
TEST(PulseFormulaTest, EqualityPrecludesDisequality) {
    PulseFormula formula;
    AbstractValue x(nullptr, 5);
    AbstractValue y(nullptr, 5);

    ASSERT_TRUE(formula.addEquality(x, y));
    EXPECT_FALSE(formula.addDisequality(x, y));
}

// Test transitivity: if a≠b and b=c, then a≠c
TEST(PulseFormulaTest, DisequalityTransitivityWithEquality) {
    PulseFormula formula;
    AbstractValue p(nullptr, 7);
    AbstractValue q(nullptr, 8);
    AbstractValue r(nullptr, 8);

    EXPECT_TRUE(formula.addDisequality(p, q));
    EXPECT_TRUE(formula.addEquality(q, r));
    EXPECT_TRUE(formula.areDisequal(p, r));
}

// Test inconsistency detection when union would violate existing disequality
TEST(PulseFormulaTest, UnionCannotOverrideExistingDisequality) {
    PulseFormula formula;
    AbstractValue m(nullptr, 15);
    AbstractValue n(nullptr, 16);
    AbstractValue o(nullptr, 16);

    EXPECT_TRUE(formula.addDisequality(m, n));
    EXPECT_TRUE(formula.addEquality(n, o));
    EXPECT_FALSE(formula.addEquality(m, o)); // This should fail due to conflict
}

