// Helper lambda to avoid repetition in parsing and asserting URL values
auto parseAndAssertValues = [](HttpRequest& req, std::string_view url,
                               const std::initializer_list<std::pair<std::string_view, std::string_view>>& expected) {
  req.parseUrl(url.data(), url.size());
  for (const auto& [key, val] : expected) {
    EXPECT_EQ(val, req.value(key));
  }
};

TEST(HttpRequestTest, testMessageId) {
  ConnectionInfo conn;
  HttpRequest req(conn, 43);
  EXPECT_EQ(43, req.messageId());
}

TEST(HttpRequestTest, testEmptyUrl) {
  ConnectionInfo conn;
  HttpRequest req(conn, 1);
  std::string_view path("/");
  req.parseUrl(path.data(), path.size());

  EXPECT_EQ("/", req.fullUrl());
  EXPECT_EQ("/", req.requestUrl());
  EXPECT_TRUE(req.values().empty());
}

TEST(HttpRequestTest, testPathOnlyUrl) {
  ConnectionInfo conn;
  HttpRequest req(conn, 1);
  std::string_view path("/a/foo/bar");
  req.parseUrl(path.data(), path.size());

  EXPECT_EQ("/a/foo/bar", req.fullUrl());
  EXPECT_EQ("/a/foo/bar", req.requestUrl());
  EXPECT_TRUE(req.values().empty());
}

TEST(HttpRequestTest, testDuplicateForwardSlashesInUrl) {
  ConnectionInfo conn;
  HttpRequest req(conn, 1);
  std::string_view path("//a//foo//bar");
  req.parseUrl(path.data(), path.size());

  EXPECT_EQ("/a/foo/bar", req.fullUrl());
  EXPECT_EQ("/a/foo/bar", req.requestUrl());
  EXPECT_TRUE(req.values().empty());
}

TEST(HttpRequestTest, testUrlParameters) {
  ConnectionInfo conn;
  HttpRequest req(conn, 1);
  std::string_view path("/foo/bar/baz?a=1&b=23&c=d&e=foobar&f=baz&bark=quxxxx");
  req.parseUrl(path.data(), path.size());

  EXPECT_EQ("1", req.value("a"));
  EXPECT_EQ("23", req.value("b"));
  EXPECT_EQ("d", req.value("c"));
  EXPECT_EQ("foobar", req.value("e"));
  EXPECT_EQ("baz", req.value("f"));
  EXPECT_EQ("quxxxx", req.value("bark"));
}

TEST(HttpRequestTest, testEmptyUrlParameters) {
  ConnectionInfo conn;
  HttpRequest req(conn, 1);
  std::string_view path("/?a=&b=&c=d&e=foobar&f=");
  req.parseUrl(path.data(), path.size());

  EXPECT_EQ("", req.value("a"));
  EXPECT_EQ("", req.value("b"));
  EXPECT_EQ("d", req.value("c"));
  EXPECT_EQ("foobar", req.value("e"));
  EXPECT_EQ("", req.value("f"));
}

TEST(HttpRequestTest, testUrlEncoding) {
  ConnectionInfo conn;
  HttpRequest req(conn, 1);
  std::string_view rawUrl(
    "/foo/bar/"
    "baz?a=%2fa%2eb%2ec&1=abc&foo=foo+bar&bark=%2Fa%5B%5D%3D%3F%26&uff=%09");
  req.parseUrl(rawUrl.data(), rawUrl.size());

  EXPECT_EQ("/a.b.c", req.value("a"));
  EXPECT_EQ("abc", req.value("1"));
  EXPECT_EQ("foo bar", req.value("foo"));
  EXPECT_EQ("/a[]=?&", req.value("bark"));
  EXPECT_EQ("\x09", req.value("uff"));
}

TEST(HttpRequestTest, testWrongUrlEncoding) {
  ConnectionInfo conn;
  HttpRequest req(conn, 1);
  std::string_view badUrl("/foo/?a=%fg");

  // Use EXPECT_THROW with explicit exception type
  EXPECT_THROW({
    try {
      req.parseUrl(badUrl.data(), badUrl.size());
    } catch (const sdb::basics::Exception&) {
      throw;
    }
  }, sdb::basics::Exception);
}

