// Program to search for a specific number in an array of 10 integers
int main() {
    int arr[10];
    int index = 0;

    // Input phase: read 10 integers into the array
    while (index < 10) {
        std::cout << "enter any arr[" << index << "] nums ";
        std::cin >> arr[index];
        index++;
    }

    // Search phase: look for a target value in the array
    int target;
    bool found = false;
    int searchIndex = 0;

    std::cout << "which nums u want seacher";
    std::cin >> target;

    while (searchIndex < 10) {
        if (arr[searchIndex] == target) {
            found = true;
            break;
        }
        searchIndex++;
    }

    if (!found) {
        std::cout << "element is not present";
    } else {
        std::cout << "element is present ";
    }

    return 0;
}

