// Helper macro to perform quicksort using a comparison function
// This is a placeholder for the actual GK_MKQSORT implementation
template<typename T, typename Compare>
void gk_quicksort(T* arr, size_t n, Compare comp) {
    // Placeholder implementation - in real code this would be replaced with GK_MKQSORT
    if (n <= 1) return;

    T pivot = arr[n/2];
    size_t i = 0, j = n - 1;

    while (i <= j) {
        while (comp(arr[i], pivot)) i++;
        while (comp(pivot, arr[j])) j--;

        if (i <= j) {
            T temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
            i++; j--;
        }
    }

    gk_quicksort(arr, j + 1, comp);
    gk_quicksort(arr + i, n - i, comp);
}

