// Overwrite the internal seed state with provided values and return previous state
unsigned short* seed48(unsigned short* newSeed)
{
    static unsigned short savedState[3];

    // Save current seed values before overwriting
    memcpy(savedState, __seed48, sizeof(savedState));

    // Update the global seed array with new values
    memcpy(__seed48, newSeed, sizeof(savedState));

    // Return the previously stored seed values
    return savedState;
}

#include "sdfg/codegen/dispatchers/if_else_dispatcher.h"
#include "sdfg/codegen/dispatchers/sequence_dispatcher.h"

namespace sdfg {
namespace codegen {

IfElseDispatcher::IfElseDispatcher(
    LanguageExtension& language_extension,
    StructuredSDFG& sdfg,
    analysis::AnalysisManager& analysis_manager,
    structured_control_flow::IfElse& node,
    InstrumentationPlan& instrumentation_plan,
    ArgCapturePlan& arg_capture_plan
)
    : NodeDispatcher(language_extension, sdfg, analysis_manager, node, instrumentation_plan, arg_capture_plan),
      condition_node_(node) {}

void IfElseDispatcher::dispatch_node(
    PrettyPrinter& main_stream,
    PrettyPrinter& globals_stream,
    CodeSnippetFactory& library_snippet_factory
) {
    // Iterate through each branch: first is 'if', rest are 'else if'
    size_t branch_index = 0;
    const size_t total_branches = condition_node_.size();

    while (branch_index < total_branches) {
        auto&& [seq_node, condition_expr] = condition_node_.at(branch_index);

        // Determine keyword based on position
        std::string keyword = (branch_index == 0) ? "if" : "else if";

        // Emit condition header
        main_stream << keyword << "(";
        main_stream << language_extension_.expression(condition_expr);
        main_stream << ")" << std::endl;

        // Open block and increase indentation
        main_stream << "{" << std::endl;
        main_stream.setIndent(main_stream.indent() + 4);

        // Dispatch child sequence
        SequenceDispatcher child_dispatcher{
            language_extension_, sdfg_, analysis_manager_, seq_node, instrumentation_plan_, arg_capture_plan_
        };
        child_dispatcher.dispatch(main_stream, globals_stream, library_snippet_factory);

        // Close block and restore indentation
        main_stream.setIndent(main_stream.indent() - 4);
        main_stream << "}" << std::endl;

        ++branch_index;
    }
}

} // namespace codegen
} // namespace sdfg

