// Helper function to process composition with optional output capture
static CompositorPlaneList executeComposition(DisplayListBuilder& inputBuilder,
                                              Ref<DisplayList>* resultRef = nullptr) {
    CompositorPlaneList layerStack;
    Compositor engine(ConsoleLogger::getLogger());
    auto processedList = engine.processDisplayList(*inputBuilder.displayList, layerStack);

    if (resultRef != nullptr) {
        *resultRef = processedList;
    }

    return layerStack;
}

// Test: No external surfaces means single drawable plane
TEST(Compositor, doesNothingWhenNoExternalSurfacesArePresent) {
    DisplayListBuilder builder(100, 100);
    builder.context(Vector(0, 0), 1.0, [&]() {
        builder.rectangle(Size(50, 50), 1.0);
        builder.context(Vector(25, 25), 1.0, [&]() { builder.rectangle(Size(10, 10), 1.0); });
        builder.context(Vector(35, 35), 1.0, [&]() { builder.rectangle(Size(50, 50), 1.0); });
        builder.rectangle(Size(25, 25), 1.0);
    });

    Ref<DisplayList> capturedList;
    auto layerStack = executeComposition(builder, &capturedList);

    ASSERT_EQ(static_cast<size_t>(1), layerStack.getPlanesCount());
    ASSERT_EQ(CompositorPlaneTypeDrawable, layerStack.getPlaneAtIndex(0).getType());
    ASSERT_TRUE(layerStack.getPlaneAtIndex(0).getExternalSurface() == nullptr);
    ASSERT_EQ(builder.displayList, capturedList);
}

