#define _BSD_SOURCE
#include <unistd.h>
#include "syscall.h"
#include <stdarg.h>
#undef syscall

long syscall(long number, ...)
{
    va_list args;
    syscall_arg_t arg1, arg2, arg3, arg4, arg5, arg6;

    va_start(args, number);
    arg1 = va_arg(args, syscall_arg_t);
    arg2 = va_arg(args, syscall_arg_t);
    arg3 = va_arg(args, syscall_arg_t);
    arg4 = va_arg(args, syscall_arg_t);
    arg5 = va_arg(args, syscall_arg_t);
    arg6 = va_arg(args, syscall_arg_t);
    va_end(args);

    return __syscall_ret(__syscall(number, arg1, arg2, arg3, arg4, arg5, arg6));
}

#include "api_test/api_test.h"
#include <format>
using namespace lbug::common;

namespace lbug {
namespace testing {

TEST_F(ApiTest, ReadOnlyDBTest) {
    // Skip in-memory mode since FTS index creation requires persistent storage
    if (inMemMode) {
        GTEST_SKIP();
    }

    // Initialize database and connection for write operations
    initializeDatabaseAndConnection();

#ifndef __STATIC_LINK_EXTENSION_TEST__
    // Load FTS extension explicitly (only needed in dynamic linking)
    auto loadResult = conn->query(std::format("LOAD EXTENSION '{}'",
        TestHelper::appendLbugRootPath("extension/fts/build/libfts.lbug_extension")));
    ASSERT_TRUE(loadResult->isSuccess());
#endif

    // Create node schema and insert sample data
    ASSERT_TRUE(conn->query("CREATE NODE TABLE doc (NAME STRING, PRIMARY KEY(NAME))")->isSuccess());
    ASSERT_TRUE(conn->query("CREATE (d:doc {NAME: 'alice'})")->isSuccess());
    ASSERT_TRUE(conn->query("CREATE (d:doc {NAME: 'bob'})")->isSuccess());

    // Build full-text search index
    ASSERT_TRUE(conn->query("CALL CREATE_FTS_INDEX('doc', 'docIdx', ['NAME'])")->isSuccess());

    // Switch system to read-only mode and reinitialize connection
    systemConfig->readOnly = true;
    initializeDatabaseAndConnection();

#ifndef __STATIC_LINK_EXTENSION_TEST__
    // Reload extension after restart
    auto extLoadResult = conn->query(std::format("LOAD EXTENSION '{}'",
        TestHelper::appendLbugRootPath("extension/fts/build/libfts.lbug_extension")));
    ASSERT_TRUE(extLoadResult->isSuccess());
#endif

    // Attempting to create another FTS index should fail with expected error message
    auto writeAttempt = conn->query("CALL CREATE_FTS_INDEX('doc', 'docIdx1', ['NAME'])");
    std::string actualMsg = writeAttempt->toString();
    ASSERT_STREQ("Connection exception: Cannot execute write operations in a read-only database!",
                 actualMsg.c_str());

    // Verify read-only queries still work — perform a search using existing index
    ASSERT_TRUE(conn->query("CALL QUERY_FTS_INDEX('doc', 'docIdx', 'alice') RETURN node.NAME, score")
                    ->isSuccess());
}

