// NOLINTNEXTLINE(readability-make-member-function-const): semantically non-const function.
void LocalWAL::clear() {
    std::lock_guard lock{mtx};
    serializer->getWriter()->clear();
}

uint64_t LocalWAL::getSize() {
    std::lock_guard lock{mtx};
    return serializer->getWriter()->getSize();
}

// NOLINTNEXTLINE(readability-make-member-function-const): semantically non-const function.
void LocalWAL::addNewWALRecord(const WALRecord& record) {
    std::lock_guard lock{mtx};
    DASSERT(record.type != WALRecordType::INVALID_RECORD);
    auto writer = serializer->getWriter();
    writer->onObjectBegin();
    record.serialize(serializer);
    writer->onObjectEnd();
}

