// Test helper: verify client-initiated stream IDs (odd numbers > 0)
TEST(Http2FrameTypeTest, ClientStreamValidation) {
  // Odd numbers starting from 1 are client streams
  EXPECT_TRUE(http2::IsClientStream(1));
  EXPECT_TRUE(http2::IsClientStream(3));
  EXPECT_TRUE(http2::IsClientStream(2147483647));  // Max 31-bit signed odd integer

  // Even numbers and zero are not client streams
  EXPECT_FALSE(http2::IsClientStream(0));
  EXPECT_FALSE(http2::IsClientStream(2));
  EXPECT_FALSE(http2::IsClientStream(4));
}

// Test helper: verify server-initiated stream IDs (even numbers > 0)
TEST(Http2FrameTypeTest, ServerStreamValidation) {
  // Even numbers starting from 2 are server streams
  EXPECT_TRUE(http2::IsServerStream(2));
  EXPECT_TRUE(http2::IsServerStream(4));
  EXPECT_TRUE(http2::IsServerStream(2147483646));  // Max 31-bit signed even integer

  // Odd numbers and zero are not server streams
  EXPECT_FALSE(http2::IsServerStream(0));
  EXPECT_FALSE(http2::IsServerStream(1));
  EXPECT_FALSE(http2::IsServerStream(3));
}

