// Helper macro to verify uint32 hex conversion in-place
#define VERIFY_UINT32_HEX_CONVERSION(input, expectedStr, tempBuffer)      \
  convLen = StringUInt32HexInPlace(static_cast<uint32_t>(input), tempBuffer); \
  EXPECT_EQ(convLen, strlen(expectedStr));                                \
  EXPECT_STREQ(tempBuffer, expectedStr);

// Helper macro to verify uint64 hex conversion in-place
#define VERIFY_UINT64_HEX_CONVERSION(input, expectedStr, tempBuffer)      \
  convLen = StringUInt64HexInPlace(static_cast<uint64_t>(input), tempBuffer); \
  EXPECT_EQ(convLen, strlen(expectedStr));                                \
  EXPECT_STREQ(tempBuffer, expectedStr);

TEST(CConversionsTest, uint32_hex_conversion) {
    char buffer[128];
    size_t convLen;

    // Test cases for 32-bit unsigned integers
    VERIFY_UINT32_HEX_CONVERSION(0UL, "0", buffer)
    VERIFY_UINT32_HEX_CONVERSION(1UL, "1", buffer)
    VERIFY_UINT32_HEX_CONVERSION(9UL, "9", buffer)
    VERIFY_UINT32_HEX_CONVERSION(10UL, "A", buffer)
    VERIFY_UINT32_HEX_CONVERSION(128UL, "80", buffer)
    VERIFY_UINT32_HEX_CONVERSION(3254UL, "CB6", buffer)
    VERIFY_UINT32_HEX_CONVERSION(65535UL, "FFFF", buffer)
