// Helper to serialize arbitrary data into buffer for testing
template <typename T>
void fillBufferFromData(BufferedTestReader& bufHolder, const T& value)
{
  if constexpr (std::is_same_v<T, std::string>)
  {
    sen::test::TestWriter writer;
    sen::OutputStream out(writer);
    out.writeString(value);
    bufHolder.getBuffer() = std::move(writer.getBuffer());
  }
  else
  {
    // reinterpret_cast is used here intentionally for low-level byte copy
    auto bytes = reinterpret_cast<const uint8_t*>(&value);  // NOLINT(cppcoreguidelines-pro-type-reinterpret-cast)
    for (std::size_t idx = 0U; idx < sizeof(T); ++idx)
    {
      bufHolder.getBuffer().emplace_back(*(bytes + idx));
    }
  }
}

// Specialization for Duration: extract nanoseconds before serialization
void fillBufferFromData(BufferedTestReader& bufHolder, const sen::Duration& dur)
{
  fillBufferFromData(bufHolder, dur.getNanoseconds());
}

// Specialization for TimeStamp: serialize underlying duration
void fillBufferFromTimeStamp(BufferedTestReader& bufHolder, const sen::TimeStamp& ts)
{
  fillBufferFromData(bufHolder, ts.sinceEpoch());
}

// Read and verify single-byte unsigned integer
void testReadUInt8(const uint8_t input)
{
  BufferedTestReader reader;
  fillBufferFromData(reader, input);
  InputStream in(reader.getBuffer());
