// Mock Upstream Implementation
class MockServerStream : public ServerUpstream {
public:
    static int next_upstream_serial;
    std::vector<uint64_t> active_connections;
    size_t last_tx_size = 0;
    TunnelAddress last_dst_addr;

    MockServerStream() : ServerUpstream(next_upstream_serial++) {}
    ~MockServerStream() override = default;
    MockServerStream(const MockServerStream &) = delete;
    MockServerStream &operator=(const MockServerStream &) = delete;
    MockServerStream(MockServerStream &&) noexcept = delete;
    MockServerStream &operator=(MockServerStream &&) noexcept = delete;

    void deinit() override {}
    bool open_session(std::optional<Millis>) override { return true; }
    void close_session() override {}

    uint64_t open_connection(const TunnelAddressPair *addr, int, std::string_view) override {
        auto id = vpn->upstream_conn_id_generator.get();
        active_connections.push_back(id);
        last_dst_addr = addr->dst;
        return id;
    }

    void close_connection(uint64_t id, bool, bool) override {
        active_connections.erase(
                std::remove(active_connections.begin(), active_connections.end(), id),
                active_connections.end());
        handler.func(handler.arg, SERVER_EVENT_CONNECTION_CLOSED, &id);
    }

    ssize_t send(uint64_t, const uint8_t *, size_t len) override {
        last_tx_size = len;
        return static_cast<ssize_t>(len);
    }

    void consume(uint64_t, size_t) override {}
    size_t available_to_send(uint64_t) override { return 1; }
    void update_flow_control(uint64_t, TcpFlowCtrlInfo) override {}
    void do_health_check() override {}
    void cancel_health_check() override {}
    [[nodiscard]] VpnConnectionStats get_connection_stats() const override { return {}; }
    void on_icmp_request(IcmpEchoRequestEvent &) override {}
};
int MockServerStream::next_upstream_serial = 0;

// Mock Listener Implementation
class MockClientListener : public ClientListener {
public:
    enum class ConnState {
        PENDING,
        ESTABLISHED,
    };

    struct ActiveConn {
        ConnState state = ConnState::PENDING;
        bool readable = false;
        std::optional<ClientConnectResult> result;
    };

    static size_t next_client_conn_index;
    std::unordered_map<size_t, ActiveConn> tracked_connections;

    MockClientListener() = default;
    ~MockClientListener() override = default;
    MockClientListener(const MockClientListener &) = delete;
    MockClientListener &operator=(const MockClientListener &) = delete;
    MockClientListener(MockClientListener &&) noexcept = delete;
    MockClientListener &operator=(MockClientListener &&) noexcept = delete;

    InitResult init(VpnClient *vpn, ClientHandler handler) override {
        return ClientListener::init(vpn, handler);
    }

    void deinit() override {}

    void complete_connect_request(uint64_t id, ClientConnectResult result) override {
        tracked_connections[id].state = ConnState::ESTABLISHED;
        tracked_connections[id].result = result;
    }

    void close_connection(uint64_t id, bool, bool) override {
        tracked_connections.erase(id);
        handler.func(handler.arg, CLIENT_EVENT_CONNECTION_CLOSED, &id);
    }

    ssize_t send(uint64_t, const uint8_t *, size_t len) override {
        return static_cast<ssize_t>(len);
    }

    void consume(uint64_t, size_t n) override {}

    TcpFlowCtrlInfo flow_control_info(uint64_t) override {
        return {DEFAULT_SEND_BUFFER_SIZE, DEFAULT_SEND_WINDOW_SIZE};
    }

    void turn_read(uint64_t id, bool on) override {
        if (tracked_connections.contains(id)) {
            tracked_connections[id].readable = on;
        }
    }

    int process_client_packets(VpnPackets) override { return 0; }
};
size_t MockClientListener::next_client_conn_index = BASE_CONN_ID;

