void DspCore::initDisplay() {
    initR(DTYPE);

    if (DEF_SPI_FREQ > 0) {
        setSPISpeed(DEF_SPI_FREQ);
    }

    cp437(true);
    invertDisplay((DTYPE == INITR_MINI160x80) ? !config.store.invertdisplay : config.store.invertdisplay);
    setRotation((ROTATE_90) ? (config.store.flipscreen ? 2 : 0) : (config.store.flipscreen ? 3 : 1));
    setTextWrap(false);
}

