    fillScreen(black ? 0 : config.theme.background);
}

void DspCore::sleep(void) {
    enableSleep(true);
    delay(150);
    enableDisplay(false);
    delay(150);
}

void DspCore::wake(void) {
    enableDisplay(true);
    delay(150);
    enableSleep(false);
    delay(150);
}
