// Helper function to compute maximum absolute value in array
static float compute_max_abs(const float* data, size_t len) {
    float max_val = 0.0f;
    for (size_t i = 0; i < len; ++i) {
        float abs_val = std::abs(data[i]);
        if (abs_val > max_val) {
            max_val = abs_val;
        }
    }
    return max_val;
}

// Helper function to clamp and convert float to int8
static int8_t clamp_and_convert(float val, float scale) {
    float quantized = std::round(val / scale);
    return static_cast<int8_t>(std::clamp(quantized, 
                                          static_cast<float>(std::numeric_limits<int8_t>::lowest()),
                                          static_cast<float>(std::numeric_limits<int8_t>::max())));
}

void quantize_a_4row_i8(size_t BlkLen, const float* A, size_t CountK, std::byte* QuantA) {
    constexpr float range_max_reciprocal = 1.0f / 127.0f; // (1 << 7) - 1 = 127

    if (BlkLen == 16 || BlkLen == 32 || BlkLen == 64) {
        for (size_t row = 0; row < 4; ++row) {
            const float* src_row = A + row * CountK;
            std::byte* dst_row = QuantA + row * sizeof(float);

            // Calculate offset and stride for interleaved storage
            size_t offset = (4 - row) * 4 + row * 8;
            size_t stride = 4 * (sizeof(float) + BlkLen);

            // Process full blocks
            size_t remaining = CountK;
            while (remaining >= BlkLen) {
                // Find max absolute value in current block
                float max_abs = compute_max_abs(src_row, BlkLen);

                // Compute scale factor
                float scale = max_abs * range_max_reciprocal;

                // Store scale
                reinterpret_cast<float*>(dst_row)[0] = scale;

                // Quantize data
                std::byte* quant_data = dst_row + offset;
                int8_t* quant_ptr = reinterpret_cast<int8_t*>(quant_data);

                for (size_t k = 0; k < BlkLen; ++k) {
                    quant_ptr[k] = clamp_and_convert(src_row[k], scale);
                }

                // Update pointers
                src_row += BlkLen;
                dst_row += stride;
                remaining -= BlkLen;
            }

            // Handle tail if any
            if (remaining > 0) {
                float max_abs = compute_max_abs(src_row, remaining);
                float scale = max_abs * range_max_reciprocal;

                reinterpret_cast<float*>(dst_row)[0] = scale;

                std::byte* quant_data = dst_row + offset;
                int8_t* quant_ptr = reinterpret_cast<int8_t*>(quant_data);

                // Quantize available data
                for (size_t k = 0; k < remaining; ++k) {
                    quant_ptr[k] = clamp_and_convert(src_row[k], scale);
                }

                // Zero pad remaining space
                for (size_t k = remaining; k < BlkLen; ++k) {
                    quant_ptr[k] = 0;
                }
            }
        }
    } else if (BlkLen == 128) {
        for (size_t row = 0; row < 4; ++row) {
            const float* src_row = A + row * CountK;
            std::byte* dst_row = QuantA + row * sizeof(float);

            size_t offset = (4 - row) * 4 + row * 8;
            size_t stride = 4 * (sizeof(float) + BlkLen);

            size_t remaining = CountK;
            while (remaining >= BlkLen) {
                // Process in chunks of 128 elements
                float max_abs = compute_max_abs(src_row, BlkLen);
                float scale = max_abs * range_max_reciprocal;

                reinterpret_cast<float*>(dst_row)[0] = scale;

                std::byte* quant_data = dst_row + offset;
                int8_t* quant_ptr = reinterpret_cast<int8_t*>(quant_data);

                for (size_t k = 0; k < BlkLen; ++k) {
                    quant_ptr[k] = clamp_and_convert(src_row[k], scale);
                }

                src_row += BlkLen;
                dst_row += stride;
                remaining -= BlkLen;
            }

            if (remaining > 0) {
                float max_abs = compute_max_abs(src_row, remaining);
                float scale = max_abs * range_max_reciprocal;

                reinterpret_cast<float*>(dst_row)[0] = scale;

                std::byte* quant_data = dst_row + offset;
                int8_t* quant_ptr = reinterpret_cast<int8_t*>(quant_data);

                for (size_t k = 0; k < remaining; ++k) {
                    quant_ptr[k] = clamp_and_convert(src_row[k], scale);
                }

                for (size_t k = remaining; k < BlkLen; ++k) {
                    quant_ptr[k] = 0;
                }
            }
        }
    } else if (BlkLen == 256) {
        for (size_t row = 0; row < 4; ++row) {
            const float* src_row = A + row * CountK;
            std::byte* dst_row = QuantA + row * sizeof(float);

            size_t offset = (4 - row) * 4 + row * 8;
            size_t stride = 4 * (sizeof(float) + BlkLen);

            size_t remaining = CountK;
            while (remaining >= BlkLen) {
                float max_abs = compute_max_abs(src_row, BlkLen);
                float scale = max_abs * range_max_reciprocal;

                reinterpret_cast<float*>(dst_row)[0] = scale;

                std::byte* quant_data = dst_row + offset;
                int8_t* quant_ptr = reinterpret_cast<int8_t*>(quant_data);

                for (size_t k = 0; k < BlkLen; ++k) {
                    quant_ptr[k] = clamp_and_convert(src_row[k], scale);
                }

                src_row += BlkLen;
                dst_row += stride;
                remaining -= BlkLen;
            }

            if (remaining > 0) {
                float max_abs = compute_max_abs(src_row, remaining);
                float scale = max_abs * range_max_reciprocal;

                reinterpret_cast<float*>(dst_row)[0] = scale;

                std::byte* quant_data = dst_row + offset;
                int8_t* quant_ptr = reinterpret_cast<int8_t*>(quant_data);

                for (size_t k = 0; k < remaining; ++k) {
                    quant_ptr[k] = clamp_and_convert(src_row[k], scale);
                }

                for (size_t k = remaining; k < BlkLen; ++k) {
                    quant_ptr[k] = 0;
                }
            }
        }
    }
}

void quantize_a_row_i8(size_t BlkLen, const float* A, size_t CountK, std::byte* QuantA) {
    constexpr float range_max_reciprocal = 1.0f / 127.0f;

    // Handle small matrices directly
    if (CountK <= BlkLen) {
        float max_abs = compute_max_abs(A, CountK);
        float scale = max_abs * range_max_reciprocal;

        reinterpret_cast<float*>(QuantA)[0] = scale;

        auto* quant_data = reinterpret_cast<int8_t*>(QuantA + sizeof(float));
        for (size_t k = 0; k < CountK; ++k) {
            quant_data[k] = clamp_and_convert(A[k], scale);
        }

        // Zero padding
        for (size_t k = CountK; k < BlkLen; ++k) {
            quant_data[k] = 0;
        }
        return;
    }

    // Process in blocks
    size_t num_blocks = (CountK + BlkLen - 1) / BlkLen;
    std::byte* quant_offset = QuantA + CountK + 4 * num_blocks;
    size_t padding = num_blocks * BlkLen - CountK;

    // Clear padding area if needed
    if (BlkLen != 32 && BlkLen != 64 && BlkLen != 128) {
        for (size_t i = 0; i < padding; ++i) {
            quant_offset[i] = std::byte{0};
        }
    }

    // Main processing loop
    for (size_t block = 0; block < num_blocks; ++block) {
        size_t block_start = block * BlkLen;
        size_t block_end = std::min(block_start + BlkLen, CountK);
        size_t block_size = block_end - block_start;

        const float* src_block = A + block_start;
        std::byte* dst_block = QuantA + block * (sizeof(float) + BlkLen);

        // Compute max absolute value for this block
        float max_abs = compute_max_abs(src_block, block_size);
        float scale = max_abs * range_max_reciprocal;

        // Store scale
        reinterpret_cast<float*>(dst_block)[0] = scale;

        // Quantize data
        std::byte* quant_data = dst_block + sizeof(float);
        int8_t* quant_ptr = reinterpret_cast<int8_t*>(quant_data);

        for (size_t k = 0; k < block_size; ++k) {
            quant_ptr[k] = clamp_and_convert(src_block[k], scale);
        }

        // Zero pad if block is incomplete
        for (size_t k = block_size; k < BlkLen; ++k) {
            quant_ptr[k] = 0;
        }
    }
}

