// Helper function to verify tree properties
bool check_root_property(const node& n) {
    return n.parent == none && n.left != none && n.right != none;
}

bool check_leaf_property(const node& n) {
    return n.left == none && n.right == none;
}

TEST_CASE("is_root(root)", "[trees]") {
    auto root_node = node{none, 1, 2, none};
    CHECK(check_root_property(root_node));
    CHECK(is_root(root_node));
}

TEST_CASE("is_root(non_root)", "[trees]") {
    auto non_root_node = node{1, 2, 3, none};
    CHECK(!check_root_property(non_root_node));
    CHECK(!is_root(non_root_node));
}

TEST_CASE("is_leaf(leaf)", "[trees]") {
    auto leaf_node = node{0, none, none, none};
    CHECK(check_leaf_property(leaf_node));
    CHECK(is_leaf(leaf_node));
}

TEST_CASE("is_leaf(non_leaf)", "[trees]") {
    auto non_leaf_node = node{0, 1, 2, none};
    CHECK(!check_leaf_property(non_leaf_node));
    CHECK(!is_leaf(non_leaf_node));
}

TEST_CASE("is_rooted_tree(valid)", "[trees]") {
    tree t{
        {none, 1, 2, none},    {0, 9, 6, none},       {0, 3, 4, none},
        {2, 5, 8, none},       {2, none, none, none}, {3, none, none, none},
        {1, none, none, none}, {9, none, none, none}, {3, none, none, none},
        {1, 10, 7, none},      {9, none, none, none},
    };
    check_rooted_tree(t);
}

TEST_CASE("foreach_postorder(example)", "[trees]") {
    tree t{
        {none, 1, 2, none},    {0, 9, 6, none},       {0, 3, 4, none},
        {2, 5, 8, none},       {2, none, none, none}, {3, none, none, none},
        {1, none, none, none}, {9, none, none, none}, {3, none, none, none},
        {1, 10, 7, none},      {9, none, none, none},
    };
    std::vector<index> expected{10, 7, 9, 6, 1, 5, 8, 3, 4, 2, 0};
    std::vector<index> result;

    // Use a different traversal approach internally but same semantics
    foreach_postorder(t, [&result](index i) { 
