typedef struct __attribute__((packed)) {
  char *name;
  char id;
} DeviceRecord;

DeviceRecord devices[4];

extern void avoid_opt(DeviceRecord *);

int main() {
    // Initialize and protect the first device record
    avoid_opt(&devices[0]);

    // Print all device IDs using a while loop instead of for-loop
    int index = 0;
    while (index < 4) {
        printf("id=%d\n", devices[index].id);
        index++;
    }

    // Non-deterministic integer input with constraints
    int position = nd_int();
    __CRAB_assume(position >= 0);
    __CRAB_assume(position < 4);

    // Verify bounds and value range of the selected device ID
    __CRAB_assert(devices[position].id >= 0);
    __CRAB_assert(devices[position].id <= 4);

    return 0;
}

