            { "NetworkPlayerMgrShutdown", Pointers.NetworkPlayerMgrShutdown, reinterpret_cast<void*>(Hooks::Info::NetworkPlayerMgrShutdown) }
        };

        Internal::HookDescriptor networkHooks[] = {
