            { "GetPoolType", Pointers.GetPoolType, reinterpret_cast<void*>(Hooks::Network::GetPoolType) },
            { "GetDLCHash", Pointers.GetDLCHash, reinterpret_cast<void*>(Hooks::Network::GetDLCHash) }
        };

        Internal::HookDescriptor spoofingHooks[] = {
            { "IsNodeInScope", Pointers.IsNodeInScope, reinterpret_cast<void*>(Hooks::Spoofing::IsNodeInScope) },
            { "ShouldUseNodeCache", Pointers.ShouldUseNodeCache, reinterpret_cast<void*>(Hooks::Spoofing::ShouldUseNodeCache) },
            { "WriteNetArrayData", Pointers.WriteNetArrayData, reinterpret_cast<void*>(Hooks::Spoofing::WriteNetArrayData) },
            { "WriteNodeData", Pointers.WriteNodeData, reinterpret_cast<void*>(Hooks::Spoofing::WriteNodeData) },
            { "WriteSyncTree", Pointers.WriteSyncTree, reinterpret_cast<void*>(Hooks::Spoofing::WriteSyncTree) }
        };

        Internal::HookDescriptor matchmakingHooks[] = {
            { "MatchmakingAdvertise", Pointers.MatchmakingAdvertise, reinterpret_cast<void*>(Hooks::Matchmaking::MatchmakingAdvertise) },
            { "MatchmakingSessionDetailSendResponse", Pointers.MatchmakingSessionDetailSendResponse, reinterpret_cast<void*>(Hooks::Matchmaking::MatchmakingSessionDetailSendResponse) },
            { "MatchmakingUnadvertise", Pointers.MatchmakingUnadvertise, reinterpret_cast<void*>(Hooks::Matchmaking::MatchmakingUnadvertise) },
            { "MatchmakingUpdate", Pointers.MatchmakingUpdate, reinterpret_cast<void*>(Hooks::Matchmaking::MatchmakingUpdate) }
        };

        Internal::HookDescriptor miscHooks[] = {
            { "AssistedAimShouldReleaseEntity", Pointers.AssistedAimShouldReleaseEntity, reinterpret_cast<void*>(Hooks::Misc::AssistedAimShouldReleaseEntity) }
        };

        // Register all hooks via helper
        Internal::RegisterBatch(m_HookRegistry, windowHooks);
        Internal::RegisterBatch(m_HookRegistry, swapChainHooks);
        Internal::RegisterBatch(m_HookRegistry, antiCheatHooks);
        Internal::RegisterBatch(m_HookRegistry, scriptHooks);
        Internal::RegisterBatch(m_HookRegistry, infoHooks);
        Internal::RegisterBatch(m_HookRegistry, networkHooks);
        Internal::RegisterBatch(m_HookRegistry, spoofingHooks);
        Internal::RegisterBatch(m_HookRegistry, matchmakingHooks);
        Internal::RegisterBatch(m_HookRegistry, miscHooks);
    }

    Hooking::~Hooking()
    {
        DestroyImpl();
    }

    bool Hooking::Init()
    {
        return GetInstance().InitImpl();
    }

    void Hooking::Destroy()
    {
        GetInstance().DestroyImpl();
        BytePatches::RestoreAll();
    }

    bool Hooking::InitImpl()
    {
        // First, apply queued MinHook changes (if any pending)
        m_MinHook.ApplyQueued();

        // Then enable all registered hooks
        for (auto& hook : m_HookRegistry.Hooks())
        {
            hook->Enable();
        }

        // Finalize MinHook state
        m_MinHook.ApplyQueued();
        return true;
    }

    void Hooking::DestroyImpl()
    {
        // Disable all active hooks first
        for (auto& hook : m_HookRegistry.Hooks())
        {
            hook->Disable();
        }

        // Apply MinHook cleanup
        m_MinHook.ApplyQueued();

        // Clear and release resources
        m_HookRegistry.Clear();
    }
}

#include "datetime.h"
#include <library/cpp/testing/unittest/registar.h>
#include <util/string/builder.h>

Y_UNIT_TEST_SUITE(TSimpleTMTest) {

    // Helper to format test location markers
    TString FormatLocation(const TString& testName, int lineNumber) {
        return TStringBuilder() << "test " << testName << " at line " << lineNumber;
    }

    // Append timestamp to marker string
    TString AttachTimestamp(const TString& baseMarker, time_t ts) {
        return TStringBuilder() << baseMarker << " (tstamp=" << ts << ")";
    }

    // Overload that combines both formatting steps
    TString FormatLocationWithTime(const TString& testName, int line, time_t ts) {
        return AttachTimestamp(FormatLocation(testName, line), ts);
    }

    // Compare struct tm and TSimpleTM fields for equality
    void ValidateTmFields(const TString& context,
                          const struct tm& expected,
                          const NDatetime::TSimpleTM& actual) {
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.Sec, expected.tm_sec, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.Min, expected.tm_min, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.Hour, expected.tm_hour, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.WDay, expected.tm_wday, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.MDay, expected.tm_mday, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.Mon, expected.tm_mon, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.YDay, expected.tm_yday, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.Year, expected.tm_year, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.IsDst, expected.tm_isdst, context);
#ifndef _win_
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.GMTOff, expected.tm_gmtoff, context);
#endif
    }

    // Comprehensive validation of TSimpleTM against expected components
    void ValidateSimpleTM(const TString& label,
                          const NDatetime::TSimpleTM& tms,
                          time_t timestamp,
                          ui32 year, ui32 month, ui32 day,
                          ui32 hour, ui32 minute, ui32 second) {
        TString fullLabel = AttachTimestamp(label, timestamp);

        struct tm reference;
        Zero(reference);
        GmTimeR(&timestamp, &reference);

        ValidateTmFields(fullLabel, reference, tms);

        // Round-trip check via AsStructTmUTC()
        struct tm reconstructed = tms.AsStructTmUTC();
        time_t roundTrip = TimeGM(&reconstructed);
        UNIT_ASSERT_VALUES_EQUAL_C(timestamp, roundTrip, fullLabel);
        UNIT_ASSERT_VALUES_EQUAL_C(timestamp, tms.AsTimeT(), fullLabel);

        // Field-level assertions
        UNIT_ASSERT_VALUES_EQUAL_C((int)tms.RealYear(), year, fullLabel);
        UNIT_ASSERT_VALUES_EQUAL_C((int)tms.RealMonth(), month, fullLabel);
        UNIT_ASSERT_VALUES_EQUAL_C((int)tms.MDay, day, fullLabel);
        UNIT_ASSERT_VALUES_EQUAL_C((int)tms.Hour, hour, fullLabel);
        UNIT_ASSERT_VALUES_EQUAL_C((int)tms.Min, minute, fullLabel);
        UNIT_ASSERT_VALUES_EQUAL_C((int)tms.Sec, second, fullLabel);
    }

    Y_UNIT_TEST(TestLeapYearLogic) {
        using namespace NDatetime;
        UNIT_ASSERT(LeapYearAD(2000));
        UNIT_ASSERT(LeapYearAD(2012));
        UNIT_ASSERT(!LeapYearAD(1999));
        UNIT_ASSERT(LeapYearAD(2004));
        UNIT_ASSERT(!LeapYearAD(1900));
    }

    Y_UNIT_TEST(TestDayOfYearConversion) {
        using namespace NDatetime;

        ui32 monthIndex;
        ui32 dayOfMonth;

        // Non-leap year tests
        for (ui32 yday = 0; yday < 365; ++yday) {
            YDayToMonthAndDay(yday, false, &monthIndex, &dayOfMonth);
            UNIT_ASSERT_VALUES_EQUAL(yday, YDayFromMonthAndDay(monthIndex, dayOfMonth, false));
        }

        // Leap year tests
        for (ui32 yday = 0; yday < 366; ++yday) {
            YDayToMonthAndDay(yday, true, &monthIndex, &dayOfMonth);
            UNIT_ASSERT_VALUES_EQUAL(yday, YDayFromMonthAndDay(monthIndex, dayOfMonth, true));
        }

        // Edge cases: invalid inputs should throw
        UNIT_ASSERT_EXCEPTION(YDayToMonthAndDay(365, false, &monthIndex, &dayOfMonth), yexception);
        UNIT_ASSERT_EXCEPTION(YDayToMonthAndDay(366, true, &monthIndex, &dayOfMonth), yexception);
    }

    Y_UNIT_TEST(SimpleTMFunctionality) {
        using namespace NDatetime;
        tzset();

        // Basic construction and conversion tests
        TSimpleTM::New(-1); // Should not crash

        UNIT_ASSERT_VALUES_EQUAL((ui32)0, (ui32)TSimpleTM::New(0));
        UNIT_ASSERT((ui32)TSimpleTM::New(0).IsUTC());

        time_t now = time(nullptr);

        // UTC-based tests
        {
            struct tm utcTm;
            Zero(utcTm);
            gmtime_r(&now, &utcTm);

            UNIT_ASSERT_VALUES_EQUAL_C((i64)now, (i64)TSimpleTM::New(now).AsTimeT(), ToString(now));
            UNIT_ASSERT_VALUES_EQUAL_C((i64)now, (i64)TSimpleTM::New(utcTm).AsTimeT(), ToString(now));

            ValidateTmFields(FormatLocationWithTime("UTC:from_time_t", __LINE__, now),
                             utcTm, TSimpleTM::New(now));
            ValidateTmFields(FormatLocationWithTime("UTC:from_tm", __LINE__, now),
                             utcTm, TSimpleTM::New(utcTm));

            UNIT_ASSERT(TSimpleTM::New(now).IsUTC());
            UNIT_ASSERT(TSimpleTM::New(utcTm).IsUTC());
        }

        // Local time tests
        {
            struct tm localTm;
            Zero(localTm);
            localtime_r(&now, &localTm);

            UNIT_ASSERT_VALUES_EQUAL((i64)now, (i64)TSimpleTM::NewLocal(now).AsTimeT());
            UNIT_ASSERT_VALUES_EQUAL((i64)now, (i64)TSimpleTM::New(localTm).AsTimeT());

            ValidateTmFields(FormatLocationWithTime("local:from_time_t", __LINE__, now),
                             localTm, TSimpleTM::NewLocal(now));
            ValidateTmFields(FormatLocationWithTime("local:from_tm", __LINE__, now),
                             localTm, TSimpleTM::New(localTm));
            ValidateTmFields(FormatLocationWithTime("local:regenerated", __LINE__, now),
                             localTm, TSimpleTM::New(localTm).RegenerateFields());
            ValidateTmFields(FormatLocationWithTime("local:set_real_date", __LINE__, now),
                             localTm,
                             TSimpleTM::NewLocal(now)
                                 .SetRealDate(localTm.tm_year + 1900,
                                              localTm.tm_mon + 1,
                                              localTm.tm_mday,
                                              localTm.tm_hour,
                                              localTm.tm_min,
                                              localTm.tm_sec,
                                              localTm.tm_isdst));
        }

        // Incremental modification tests
        {
            TSimpleTM dt = TSimpleTM::New(0);
            dt.SetRealDate(2012, 3, 30, 5, 6, 7);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1333083967, 2012, 3, 30, 5, 6, 7);

            dt.SetRealDate(2012, 3, 8, 5, 6, 7);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1331183167, 2012, 3, 8, 5, 6, 7);

            dt.SetRealDate(2010, 10, 4, 5, 6, 7);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1286168767, 2010, 10, 4, 5, 6, 7);

            dt.Add(TSimpleTM::F_MON);
            ValidateSimpleTM(FormatLocationWithTime("UTC:AddMonth", __LINE__),
                             dt, 1288847167, 2010, 11, 4, 5, 6, 7);

            dt.Add(TSimpleTM::F_DAY);
            ValidateSimpleTM(FormatLocationWithTime("UTC:AddDay", __LINE__),
                             dt, 1288933567, 2010, 11, 5, 5, 6, 7);

            dt.Add(TSimpleTM::F_YEAR);
            ValidateSimpleTM(FormatLocationWithTime("UTC:AddYear", __LINE__),
                             dt, 1320469567, 2011, 11, 5, 5, 6, 7);

            // Add 365 days manually
            for (ui32 i = 0; i < 365; ++i) {
                dt.Add(TSimpleTM::F_DAY);
            }
            ValidateSimpleTM(FormatLocationWithTime("UTC:365*AddDay", __LINE__),
                             dt, 1352005567, 2012, 11, 4, 5, 6, 7);

            dt.Add(TSimpleTM::F_MON, -10);
            ValidateSimpleTM(FormatLocationWithTime("UTC:AddMonth(-10)", __LINE__),
                             dt, 1325653567, 2012, 1, 4, 5, 6, 7);

            dt.Add(TSimpleTM::F_HOUR, -(24 * 4 + 6));
            ValidateSimpleTM(FormatLocationWithTime("UTC:AddHour(-102)", __LINE__),
                             dt, 1325286367, 2011, 12, 30, 23, 6, 7);
        }

        // Date-only initialization tests
        {
            TSimpleTM dt = TSimpleTM::New();
            dt.SetRealDate(2012, 2, 29);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1330473600, 2012, 2, 29, 0, 0, 0);

            dt.SetRealDate(2013, 12, 28);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1388188800, 2013, 12, 28, 0, 0, 0);

            dt.SetRealDate(2012, 10, 23);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1350950400, 2012, 10, 23, 0, 0, 0);

            dt.SetRealDate(2013, 3, 16);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1363392000, 2013, 3, 16, 0, 0, 0);

            dt.SetRealDate(2013, 2, 17);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1361059200, 2013, 2, 17, 0, 0, 0);

            dt.SetRealDate(2012, 12, 23);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1356220800, 2012, 12, 23, 0, 0, 0);

            dt.SetRealDate(2012, 5, 17);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1337212800, 2012, 5, 17, 0, 0, 0);

            dt.SetRealDate(2012, 6, 15);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1339718400, 2012, 6, 15, 0, 0, 0);

            dt.SetRealDate(2009, 3, 17);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1237248000, 2009, 3, 17, 0, 0, 0);

            dt.SetRealDate(2013, 8, 12);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1376265600, 2013, 8, 12, 0, 0, 0);

            dt.SetRealDate(2015, 12, 11, 10, 9, 8);
            ValidateSimpleTM(FormatLocationWithTime("UTC:SetRealDate", __LINE__),
                             dt, 1449828548, 2015, 12, 11, 10, 9, 8);
        }
    }
} // Y_UNIT_TEST_SUITE(TSimpleTMTest)

#include <iostream>
#include <string>
#include <vector>
#include "../include/parser.h"
