// Evaluate integer arithmetic expressions
void evaluate_integer_ops(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, std::string>> test_cases = {
        {"42", "42"},
        {"-15", "-15"},
        {"(+ 10 20)", "30"},
        {"(- 50 30)", "20"},
        {"(* 6 7)", "42"},
        {"(div 20 5)", "4"},
        {"(mod 17 5)", "2"},
        {"(abs -42)", "42"}
    };

    std::cout << "=== Integer Arithmetic Evaluation ===" << std::endl;
    for (const auto& entry : test_cases) {
        std::cout << "Input: " << entry.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> eval_result = parser->mkExpr(entry.first);
        assert(eval_result);
        std::string output = parser->toString(eval_result);
        std::cout << "  Output: " << output << std::endl;
        assert(output == entry.second && "integer result mismatch");
        std::cout << std::endl;
    }
}

// Validate real number arithmetic computations
void validate_real_ops(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, std::string>> scenarios = {
        {"3.14159", "3.14159"},
        {"-2.71828", "-2.71828"},
        {"(+ 3.5 2.7)", "6.2"},
        {"(- 10.5 4.2)", "6.3"},
        {"(* 2.5 4.0)", "10"},
        {"(/ 15.0 3.0)", "5"},
        {"(^ 2.0 3.0)", "8"},
        {"(sqrt 16.0)", "4"},
        {"(abs -9.81)", "9.81"}
    };

    std::cout << "=== Real Number Arithmetic Validation ===" << std::endl;
    for (const auto& scenario : scenarios) {
        std::cout << "Expression: " << scenario.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> computed = parser->mkExpr(scenario.first);
        assert(computed);
        std::string actual = parser->toString(computed);
        std::cout << "  Computed: " << actual << std::endl;
        assert(actual == scenario.second && "real arithmetic result mismatch");
        std::cout << std::endl;
    }
}

// Verify comparison operations on numeric values
void check_numeric_comparisons(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> trials = {
        {"(< 5 10)", true},
        {"(<= 7 7)", true},
        {"(> 15 5)", true},
        {"(>= 12 12)", true},
        {"(= 42 42)", true},
        {"(distinct 3 5 7)", true}
    };

    std::cout << "=== Numeric Comparison Verification ===" << std::endl;
    for (const auto& trial : trials) {
        std::cout << "Expression: " << trial.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> outcome = parser->mkExpr(trial.first);
        assert(outcome);
        std::cout << "  Outcome: " << parser->toString(outcome) << std::endl;
        assert(outcome->isTrue() == trial.second && "comparison evaluation incorrect");
        std::cout << std::endl;
    }
}

// Assess precision handling in floating-point calculations
void examine_precision_handling(SMTParser::ParserPtr& parser) {
    std::cout << "=== Precision Handling Assessment ===" << std::endl;

    // Default precision setting (128 bits)
    std::cout << "=== Using Default Precision (128 bits) ===" << std::endl;
    auto op1 = parser->mkExpr("(+ 3.5 2.7)");
    auto op2 = parser->mkExpr("(- 10.5 4.2)");
    assert(op1 && op2);
    std::cout << "Expression: (+ 3.5 2.7)" << std::endl;
    std::cout << "  Result: " << parser->toString(op1) << std::endl;
    assert(parser->toString(op1) == "6.2");
    std::cout << "Expression: (- 10.5 4.2)" << std::endl;
    std::cout << "  Result: " << parser->toString(op2) << std::endl;
    assert(parser->toString(op2) == "6.3");

    // Increase precision to 256 bits
    parser->setEvaluatePrecision(256);
    std::cout << "\n=== Enhanced Precision (256 bits) ===" << std::endl;
    auto op3 = parser->mkExpr("(+ 3.5 2.7)");
    auto op4 = parser->mkExpr("(- 10.5 4.2)");
    assert(op3 && op4);
    std::cout << "Expression: (+ 3.5 2.7)" << std::endl;
    std::cout << "  Result: " << parser->toString(op3) << std::endl;
    std::cout << "Expression: (- 10.5 4.2)" << std::endl;
    std::cout << "  Result: " << parser->toString(op4) << std::endl;
    assert(parser->toString(op3) == "6.2" && parser->toString(op4) == "6.3");

    // Switch to fixed-point mode (disable floating point)
    parser->setEvaluateUseFloating(false);
    std::cout << "\n=== Fixed-Point Mode (No Floating Point) ===" << std::endl;
    auto op5 = parser->mkExpr("(+ 3.5 2.7)");
    auto op6 = parser->mkExpr("(- 10.5 4.2)");
    assert(op5 && op6);
    std::cout << "Expression: (+ 3.5 2.7)" << std::endl;
    std::cout << "  Result: " << parser->toString(op5) << std::endl;
    std::cout << "Expression: (- 10.5 4.2)" << std::endl;
    std::cout << "  Result: " << parser->toString(op6) << std::endl;
    assert(parser->toString(op5) == "6.2" && parser->toString(op6) == "6.3");
}

int main() {
    std::cout << "======= Comprehensive Arithmetic Operations Test =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    evaluate_integer_ops(parser);
    validate_real_ops(parser);
    check_numeric_comparisons(parser);
    examine_precision_handling(parser);

    return 0;
}

