#include <iostream>
#include <vector>
#include <queue>
using namespace std;

class MedianCalculator {
public:
    // Compute running medians for the input array
    vector<double> getRunningMedians(const vector<int>& input) {
        vector<double> result;
        if (input.empty()) return result;

        // Max heap for lower half, min heap for upper half
        priority_queue<int> maxHeap;  // smaller half
        priority_queue<int, vector<int>, greater<int>> minHeap;  // larger half

        for (int num : input) {
            // Add number to appropriate heap
            if (maxHeap.empty() || num <= maxHeap.top()) {
                maxHeap.push(num);
            } else {
                minHeap.push(num);
            }

            // Rebalance heaps to maintain size difference <= 1
            if (maxHeap.size() > minHeap.size() + 1) {
                minHeap.push(maxHeap.top());
                maxHeap.pop();
            } else if (minHeap.size() > maxHeap.size()) {
                maxHeap.push(minHeap.top());
                minHeap.pop();
            }

            // Calculate median
            double median;
            if (maxHeap.size() == minHeap.size()) {
                median = (maxHeap.top() + minHeap.top()) / 2.0;
            } else {
                median = static_cast<double>(maxHeap.top());
            }
            result.push_back(median);
        }

        return result;
    }
};

int main() {
    MedianCalculator calculator;
    vector<int> test = {5, 2, 7, 3, 9};
    vector<double> medians = calculator.getRunningMedians(test);

    for (double m : medians) {
        cout << m << " ";
    }
    cout << endl;

    return 0;
}

#include "cleanup_functions.h"
#include <mutex>
using namespace sdb;
using namespace sdb::basics;

void CleanupFunctions::registerFunction(
  std::unique_ptr<CleanupFunctions::CleanupFunction> func) {
  std::lock_guard<std::mutex> guard{gFunctionsMutex};
  gCleanupFunctions.push_back(std::move(func));
}

void CleanupFunctions::run(int exitCode, void* userData) {
  std::lock_guard<std::mutex> guard{gFunctionsMutex};
  for (size_t i = 0; i < gCleanupFunctions.size(); ++i) {
    (*gCleanupFunctions[i])(exitCode, userData);
  }
  gCleanupFunctions.clear();
}

#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
#include "jemalloc/internal/prof_stats.h"

bool opt_prof_stats = false;
malloc_mutex_t prof_stats_mtx;

static prof_stats_t prof_stats_live[PROF_SC_NSIZES];
static prof_stats_t prof_stats_accum[PROF_SC_NSIZES];

static void
prof_stats_lock(tsd_t *tsd, szind_t ind) {
    assert(opt_prof && opt_prof_stats);
    assert(ind < SC_NSIZES);
    malloc_mutex_lock(tsd_tsdn(tsd), &prof_stats_mtx);
}

static void
prof_stats_unlock(tsd_t *tsd) {
    malloc_mutex_unlock(tsd_tsdn(tsd), &prof_stats_mtx);
}

void
prof_stats_add(tsd_t *tsd, szind_t ind, size_t size) {
    cassert(config_prof);
    prof_stats_lock(tsd, ind);

    prof_stats_live[ind].req_sum += size;
    prof_stats_live[ind].count += 1;
    prof_stats_accum[ind].req_sum += size;
    prof_stats_accum[ind].count += 1;

    prof_stats_unlock(tsd);
}

void
prof_stats_subtract(tsd_t *tsd, szind_t ind, size_t size) {
    cassert(config_prof);
    prof_stats_lock(tsd, ind);

    prof_stats_live[ind].req_sum -= size;
    prof_stats_live[ind].count -= 1;

    prof_stats_unlock(tsd);
}

void
prof_stats_copy_live(tsd_t *tsd, szind_t ind, prof_stats_t *out_stats) {
    cassert(config_prof);
    prof_stats_lock(tsd, ind);

    *out_stats = prof_stats_live[ind];

    prof_stats_unlock(tsd);
}

void
prof_stats_copy_accum(tsd_t *tsd, szind_t ind, prof_stats_t *out_stats) {
    cassert(config_prof);
    prof_stats_lock(tsd, ind);

    *out_stats = prof_stats_accum[ind];

    prof_stats_unlock(tsd);
}

