// Clone: underlay_message_test → refactored variable names and minor reordering
TEST(UnderlayMessageTest, message_operations) {
  UnderlayMessage msg;

  // Timestamp tests
  msg.timestamp(1024);
  int32_t& ts_ref = msg.timestamp();
  ts_ref = 256;
  EXPECT_EQ(256, msg.timestamp());

  // Sequence number tests
  msg.seq(1024);
  int32_t& seq_ref = msg.seq();
  seq_ref = 256;
  EXPECT_EQ(256, msg.seq());

  // Data string tests
  msg.data("data");
  std::string& data_ref = msg.data();
  data_ref = "data string";
  EXPECT_EQ(data_ref, msg.data());
  msg.data(std::forward<std::string>("data forward"));
  EXPECT_EQ("data forward", msg.data());

  // Datatype string tests
  msg.datatype("datatype");
  std::string& dtype_ref = msg.datatype();
  dtype_ref = "datatype string";
  EXPECT_EQ(dtype_ref, msg.datatype());
  msg.datatype("datatype assign");
  EXPECT_EQ("datatype assign", msg.datatype());
  msg.datatype(std::forward<std::string>("datatype forward"));
  EXPECT_EQ("datatype forward", msg.datatype());

  // Const access verification
  const UnderlayMessage const_msg(msg);
  std::string data_copy = const_msg.data();
  std::string dtype_copy = const_msg.datatype();
  EXPECT_EQ(256, const_msg.timestamp());
  EXPECT_EQ(256, const_msg.seq());
  EXPECT_EQ("data forward", const_msg.data());
  EXPECT_EQ("datatype forward", const_msg.datatype());

  // Copy assignment
  UnderlayMessage msg2;
  msg2 = msg;
  EXPECT_EQ(256, msg2.timestamp());
  EXPECT_EQ(256, msg2.seq());
  EXPECT_EQ("data forward", msg2.data());
  EXPECT_EQ("datatype forward", msg2.datatype());

  // Move assignment
  UnderlayMessage msg3;
  msg3 = std::forward<UnderlayMessage>(msg2);
  EXPECT_EQ(256, msg3.timestamp());
  EXPECT_EQ(256, msg3.seq());
  EXPECT_EQ("data forward", msg3.data());
  EXPECT_EQ("datatype forward", msg3.datatype());

  // Move construction
  UnderlayMessage msg4(std::move(msg3));
  EXPECT_EQ(256, msg4.timestamp());
  EXPECT_EQ(256, msg4.seq());
  EXPECT_EQ("data forward", msg4.data());
  EXPECT_EQ("datatype forward", msg4.datatype());

  // Final move construction from rvalue
  UnderlayMessage msg5(std::move(msg4));
  EXPECT_EQ(256, msg5.timestamp());
  EXPECT_EQ(256, msg5.seq());
  EXPECT_EQ("data forward", msg5.data());
  EXPECT_EQ("datatype forward", msg5.datatype());

  // After moves, original objects should be empty (as per typical move semantics)
  EXPECT_EQ("", msg4.data());
  EXPECT_EQ("", msg4.datatype());
}

