template<
  typename DerivedP,
  typename DerivedF
  >
IGL_INLINE void igl::copyleft::cgal::lexicographic_triangulation(
    const Eigen::PlainObjectBase<DerivedP>& P,
    Eigen::PlainObjectBase<DerivedF>& F)
{
  using Scalar = typename DerivedP::Scalar;
  igl::lexicographic_triangulation(P, 
      [](const Scalar& a, const Scalar& b, const Scalar& c) -> int {
