#include <iostream>

// Check if a number is prime
int main() {
    int number;
    std::cout << "enter any no" << std::endl;
    std::cin >> number;

    bool isPrime = true;
    int divisor = 2;

    // Handle edge cases: numbers less than 2 are not prime
    if (number < 2) {
        isPrime = false;
    } else {
        // Check divisors from 2 up to sqrt(number) (using number/2 as upper bound for simplicity)
        while (divisor <= number / 2) {
            if (number % divisor == 0) {
                isPrime = false;
                break;
            }
            divisor++;
        }
    }

    if (isPrime) {
        std::cout << "no is prime" << std::endl;
    } else {
        std::cout << "it is not prime" << std::endl;
    }

    return 0;
}

