}

// Test ufps::ensure with custom resource management (AutoRelease)
TEST(error, ensure_auto_release_variant)
{
    // Valid managed pointer
    ufps::AutoRelease<int*, nullptr> safe_ptr{new int{}, [](int* p) { delete p; }};
    EXPECT_NO_THROW(ufps::ensure(safe_ptr, "Resource present, operation allowed"));

    // Invalid managed pointer (null)
    ufps::AutoRelease<int*, nullptr> null_ptr{nullptr, nullptr};
    EXPECT_THROW(ufps::ensure(null_ptr, "Null resource, should fail"), ufps::Exception);
}

// Test ufps::ensure with std::unique_ptr
TEST(error, ensure_unique_ptr_variant)
{
    // Valid unique_ptr with value
    std::unique_ptr<int> valid_ptr = std::make_unique<int>(100);
    EXPECT_NO_THROW(ufps::ensure(valid_ptr, "Pointer holds value, proceed"));

    // Empty (null) unique_ptr
    std::unique_ptr<int> empty_ptr;
    EXPECT_THROW(ufps::ensure(empty_ptr, "Pointer is null, must throw"), ufps::Exception);
}

