// shoutouts to clibs' implementation of sha1: https://github.com/clibs/sha1

// Bit rotation macro for 32-bit values
#define rotateLeft(val, shift) (((val) << (shift)) | ((val) >> (32 - (shift))))

// Block processing macros
#define getBlock0(idx) m_workspace->data32[idx]
#define getBlock(idx) \
    (m_workspace->data32[(idx) & 15] = \
        rotateLeft( \
            m_workspace->data32[(idx) & 15] ^ \
            m_workspace->data32[(idx + 2) & 15] ^ \
            m_workspace->data32[(idx + 8) & 15] ^ \
            m_workspace->data32[(idx + 13) & 15], \
            1))

// SHA-1 round functions
#define ROUND1(a,b,c,d,e,idx) \
    (e) += ((b & (c ^ d)) ^ d) + getBlock0(idx) + 0x5A827999 + rotateLeft((a), 5); \
    (b) = rotateLeft((b), 30);

#define ROUND2(a,b,c,d,e,idx) \
    (e) += ((b & (c ^ d)) ^ d) + getBlock(idx) + 0x5A827999 + rotateLeft((a), 5); \
    (b) = rotateLeft((b), 30);

#define ROUND3(a,b,c,d,e,idx) \
    (e) += (b ^ c ^ d) + getBlock(idx) + 0x6ED9EBA1 + rotateLeft((a), 5); \
    (b) = rotateLeft((b), 30);

#define ROUND4(a,b,c,d,e,idx) \
    (e) += (((b | c) & d) | (b & c)) + getBlock(idx) + 0x8F1BBCDC + rotateLeft((a), 5); \
    (b) = rotateLeft((b), 30);

#define ROUND5(a,b,c,d,e,idx) \
    (e) += (b ^ c ^ d) + getBlock(idx) + 0xCA62C1D6 + rotateLeft((a), 5); \
    (b) = rotateLeft((b), 30);

void CSHA1::Transform(unsigned int *state, const unsigned char *input) {
    // Initialize working variables
    unsigned int wv_a = state[0];
    unsigned int wv_b = state[1];
    unsigned int wv_c = state[2];
    unsigned int wv_d = state[3];
    unsigned int wv_e = state[4];

    // Copy input buffer to workspace
    memcpy(m_workspace->data8, input, 64);

    // Process first 16 words with ROUND1
    ROUND1(wv_a, wv_b, wv_c, wv_d, wv_e, 0);
    ROUND1(wv_e, wv_a, wv_b, wv_c, wv_d, 1);
    ROUND1(wv_d, wv_e, wv_a, wv_b, wv_c, 2);
    ROUND1(wv_c, wv_d, wv_e, wv_a, wv_b, 3);
    ROUND1(wv_b, wv_c, wv_d, wv_e, wv_a, 4);
    ROUND1(wv_a, wv_b, wv_c, wv_d, wv_e, 5);
    ROUND1(wv_e, wv_a, wv_b, wv_c, wv_d, 6);
    ROUND1(wv_d, wv_e, wv_a, wv_b, wv_c, 7);
    ROUND1(wv_c, wv_d, wv_e, wv_a, wv_b, 8);
    ROUND1(wv_b, wv_c, wv_d, wv_e, wv_a, 9);
    ROUND1(wv_a, wv_b, wv_c, wv_d, wv_e, 10);
    ROUND1(wv_e, wv_a, wv_b, wv_c, wv_d, 11);
    ROUND1(wv_d, wv_e, wv_a, wv_b, wv_c, 12);
    ROUND1(wv_c, wv_d, wv_e, wv_a, wv_b, 13);
    ROUND1(wv_b, wv_c, wv_d, wv_e, wv_a, 14);
    ROUND1(wv_a, wv_b, wv_c, wv_d, wv_e, 15);

    // Process next 4 words with ROUND2
    ROUND2(wv_e, wv_a, wv_b, wv_c, wv_d, 16);
    ROUND2(wv_d, wv_e, wv_a, wv_b, wv_c, 17);
    ROUND2(wv_c, wv_d, wv_e, wv_a, wv_b, 18);
    ROUND2(wv_b, wv_c, wv_d, wv_e, wv_a, 19);

    // Process next 20 words with ROUND3
    ROUND3(wv_a, wv_b, wv_c, wv_d, wv_e, 20);
    ROUND3(wv_e, wv_a, wv_b, wv_c, wv_d, 21);
    ROUND3(wv_d, wv_e, wv_a, wv_b, wv_c, 22);
    ROUND3(wv_c, wv_d, wv_e, wv_a, wv_b, 23);
    ROUND3(wv_b, wv_c, wv_d, wv_e, wv_a, 24);
    ROUND3(wv_a, wv_b, wv_c, wv_d, wv_e, 25);
    ROUND3(wv_e, wv_a, wv_b, wv_c, wv_d, 26);
    ROUND3(wv_d, wv_e, wv_a, wv_b, wv_c, 27);
    ROUND3(wv_c, wv_d, wv_e, wv_a, wv_b, 28);
    ROUND3(wv_b, wv_c, wv_d, wv_e, wv_a, 29);
    ROUND3(wv_a, wv_b, wv_c, wv_d, wv_e, 30);
    ROUND3(wv_e, wv_a, wv_b, wv_c, wv_d, 31);
    ROUND3(wv_d, wv_e, wv_a, wv_b, wv_c, 32);
    ROUND3(wv_c, wv_d, wv_e, wv_a, wv_b, 33);
    ROUND3(wv_b, wv_c, wv_d, wv_e, wv_a, 34);
    ROUND3(wv_a, wv_b, wv_c, wv_d, wv_e, 35);
    ROUND3(wv_e, wv_a, wv_b, wv_c, wv_d, 36);
    ROUND3(wv_d, wv_e, wv_a, wv_b, wv_c, 37);
    ROUND3(wv_c, wv_d, wv_e, wv_a, wv_b, 38);
    ROUND3(wv_b, wv_c, wv_d, wv_e, wv_a, 39);

    // Process next 20 words with ROUND4
    ROUND4(wv_a, wv_b, wv_c, wv_d, wv_e, 40);
    ROUND4(wv_e, wv_a, wv_b, wv_c, wv_d, 41);
    ROUND4(wv_d, wv_e, wv_a, wv_b, wv_c, 42);
    ROUND4(wv_c, wv_d, wv_e, wv_a, wv_b, 43);
    ROUND4(wv_b, wv_c, wv_d, wv_e, wv_a, 44);
    ROUND4(wv_a, wv_b, wv_c, wv_d, wv_e, 45);
    ROUND4(wv_e, wv_a, wv_b, wv_c, wv_d, 46);
    ROUND4(wv_d, wv_e, wv_a, wv_b, wv_c, 47);
    ROUND4(wv_c, wv_d, wv_e, wv_a, wv_b, 48);
    ROUND4(wv_b, wv_c, wv_d, wv_e, wv_a, 49);
    ROUND4(wv_a, wv_b, wv_c, wv_d, wv_e, 50);
    ROUND4(wv_e, wv_a, wv_b, wv_c, wv_d, 51);
    ROUND4(wv_d, wv_e, wv_a, wv_b, wv_c, 52);
    ROUND4(wv_c, wv_d, wv_e, wv_a, wv_b, 53);
    ROUND4(wv_b, wv_c, wv_d, wv_e, wv_a, 54);
    ROUND4(wv_a, wv_b, wv_c, wv_d, wv_e, 55);
    ROUND4(wv_e, wv_a, wv_b, wv_c, wv_d, 56);
    ROUND4(wv_d, wv_e, wv_a, wv_b, wv_c, 57);
    ROUND4(wv_c, wv_d, wv_e, wv_a, wv_b, 58);
    ROUND4(wv_b, wv_c, wv_d, wv_e, wv_a, 59);

    // Process final 20 words with ROUND5
    ROUND5(wv_a, wv_b, wv_c, wv_d, wv_e, 60);
    ROUND5(wv_e, wv_a, wv_b, wv_c, wv_d, 61);
    ROUND5(wv_d, wv_e, wv_a, wv_b, wv_c, 62);
    ROUND5(wv_c, wv_d, wv_e, wv_a, wv_b, 63);
    ROUND5(wv_b, wv_c, wv_d, wv_e, wv_a, 64);
    ROUND5(wv_a, wv_b, wv_c, wv_d, wv_e, 65);
    ROUND5(wv_e, wv_a, wv_b, wv_c, wv_d, 66);
    ROUND5(wv_d, wv_e, wv_a, wv_b, wv_c, 67);
    ROUND5(wv_c, wv_d, wv_e, wv_a, wv_b, 68);
    ROUND5(wv_b, wv_c, wv_d, wv_e, wv_a, 69);
    ROUND5(wv_a, wv_b, wv_c, wv_d, wv_e, 70);
    ROUND5(wv_e, wv_a, wv_b, wv_c, wv_d, 71);
    ROUND5(wv_d, wv_e, wv_a, wv_b, wv_c, 72);
    ROUND5(wv_c, wv_d, wv_e, wv_a, wv_b, 73);
    ROUND5(wv_b, wv_c, wv_d, wv_e, wv_a, 74);
    ROUND5(wv_a, wv_b, wv_c, wv_d, wv_e, 75);
    ROUND5(wv_e, wv_a, wv_b, wv_c, wv_d, 76);
    ROUND5(wv_d, wv_e, wv_a, wv_b, wv_c, 77);
    ROUND5(wv_c, wv_d, wv_e, wv_a, wv_b, 78);
    ROUND5(wv_b, wv_c, wv_d, wv_e, wv_a, 79);

    // Accumulate results back into state
    state[0] += wv_a;
    state[1] += wv_b;
    state[2] += wv_c;
    state[3] += wv_d;
    state[4] += wv_e;
}

void CSHA1::Update(const unsigned char *data, unsigned int length) {
    unsigned int bufferIndex = (m_byteCount / 8) % 64;
    m_byteCount += length * 8;

    // Handle overflow in bit count
    if (m_byteCount < length * 8) {
        m_wordCount[0]++;
    }
    m_wordCount[0] += (length >> 29);
    m_wordCount[1] += (length >> 29);

    if ((bufferIndex + length) > 63) {
        unsigned int copySize = 64 - bufferIndex;
        memcpy(&m_buffer[bufferIndex], data, copySize);
        Transform(m_state, m_buffer);

        // Process complete 64-byte blocks
        for (; (copySize + 63) < length; copySize += 64) {
            Transform(m_state, &data[copySize]);
        }
        bufferIndex = 0;
    } else {
        copySize = 0;
    }

    // Copy remaining bytes
    if (length - copySize != 0) {
        memcpy(&m_buffer[bufferIndex], &data[copySize], length - copySize);
    }
}

const CSHA1::Digest &CSHA1::Final() {
    unsigned char paddingBytes[8];

    // Prepare padding with message length
    for (unsigned int i = 0; i < 8; i++) {
        paddingBytes[i] = static_cast<unsigned char>(
            (m_wordCount[(i >= 4) ? 0 : 1] >> ((3 - (i & 3)) * 8)) & 0xFF);
    }

    // Add padding byte 0x80
    Update(reinterpret_cast<const unsigned char*>("\x80"), 1);

    // Add zero padding until we reach 448 bits mod 512
    while ((m_byteCount & 504) != 448) {
        Update(reinterpret_cast<const unsigned char*>("\x00"), 1);
    }

    // Append original length
    Update(paddingBytes, 8);

    // Extract digest from state
    for (unsigned int i = 0; i < 20; i++) {
        m_digest.bytes[i] = static_cast<unsigned char>(
            (m_state[i >> 2] >> ((3 - (i & 3)) * 8)) & 0xFF);
    }

    // Clear sensitive data
    memset(m_buffer, 0, 64);
    memset(m_state, 0, 20);
    memset(m_wordCount, 0, 8);
    memset(paddingBytes, 0, 8);
    Transform(m_state, m_buffer);

    return m_digest;
}

void CSHA1::Digest::Copy(unsigned char *output) const { 
    memcpy(output, this, 20); 
}

void CSHA1::Digest::ReportHash(char *output, unsigned char format) const {
    char tempBuffer[24];
    unsigned int index;

    if (output) {
        if (format == 0) {  // Hexadecimal format
            sprintf(tempBuffer, "%02X", bytes[0]);
            strcpy(output, tempBuffer);
            for (index = 1; index < 20; index++) {
                sprintf(tempBuffer, "%02X", bytes[index]);
                strcat(output, tempBuffer);
            }
        } else if (format == 1) {  // Decimal format
            sprintf(tempBuffer, "%u", bytes[0]);
            strcpy(output, tempBuffer);
            for (index = 1; index < 20; index++) {
                sprintf(tempBuffer, " %u", bytes[index]);
                strcat(output, tempBuffer);
            }
        } else {
            strcpy(output, "Error: Unknown report type!");
        }
    }
}

BinStream &operator<<(BinStream &stream, const CSHA1::Digest &digest) {
    stream.Write(digest.bytes, 20);
    return stream;
}

BinStream &operator>>(BinStream &stream, CSHA1::Digest &digest) {
    stream.Read(digest.bytes, 20);
    return stream;
}

