TEST_CASE("enum/read-only-iteration", "verify iteration over read-only tables behaves correctly") {
    sol::state lua;
    lua.open_libraries(sol::lib::base);

    // Define test data for table and enum creation
    auto create_test_data = []() {
        return std::make_tuple("FIRST", 1, "SECOND", 2, "THIRD", 3, "NOT-FOURTH", 5);
    };

    // Create named table with test entries
    auto [k1, v1, k2, v2, k3, v3, k4, v4] = create_test_data();
    lua.create_named_table("Check", 
        std::make_pair(k1, v1), 
        std::make_pair(k2, v2), 
        std::make_pair(k3, v3), 
        std::make_pair(k4, v4));

    // Create enum with same key-value pairs
    lua.new_enum("Enum", 
        std::make_pair(k1, v1), 
        std::make_pair(k2, v2), 
        std::make_pair(k3, v3), 
        std::make_pair(k4, v4));

    SECTION("without global next function") {
        sol::optional<sol::error> maybe_result = lua.safe_script(
            "for k, v in pairs(Enum) do assert(Check[k] == v) end", 
            sol::script_pass_on_error);
        REQUIRE_FALSE(maybe_result.has_value());
    }

    SECTION("with global next function enabled") {
        lua.open_libraries(sol::lib::table);
        sol::optional<sol::error> maybe_result = lua.safe_script(
            "for k, v in pairs(Enum) do assert(Check[k] == v) end", 
            sol::script_pass_on_error);
        REQUIRE_FALSE(maybe_result.has_value());
    }
}

