            for (row_idx = 0; row_idx < matrix_size; ++row_idx) {
                if (diag_vals[row_idx] == 0.0) {
                    *info_ptr = row_idx + 1;
                    return;
                }
            }
            return;
        }
    } else if (*uplo_ptr == 'u' || *uplo_ptr == 'U') {
        // Upper triangular case
#if defined(TARGET_X64_INTEL_HASWELL)
        if (matrix_size >= 256 || matrix_size > K_MAX_STACK)
#elif defined(TARGET_X64_INTEL_SANDY_BRIDGE)
        if (matrix_size >= 64 || matrix_size > K_MAX_STACK)
#else
        if (matrix_size >= 12 || matrix_size > K_MAX_STACK)
#endif
        {
            // Large matrix: use dynamic allocation
            small_dim = (matrix_size + 127) / 128 * 128;
            sC_mem_size = blasfeo_memsize_dmat(small_dim, small_dim);
            total_mem_size = sC_mem_size;
            mem_block = malloc(total_mem_size + 64);
            blasfeo_align_64_byte(mem_block, &aligned_mem);
            blasfeo_create_dmat(matrix_size, matrix_size, &sC, aligned_mem);
            sdc = sC.cn;
            pc = sC.dA;

            row_idx = 0;
#if defined(TARGET_X64_INTEL_HASWELL) | defined(TARGET_ARMV8A_ARM_CORTEX_A53)
            for (; row_idx < matrix_size - 11; row_idx += 12) {
                for (col_idx = 0; col_idx < row_idx; col_idx += 4) {
                    kernel_dpack_tn_4_lib4(4, C_matrix + col_idx + (row_idx + 0) * leading_dim,
                        leading_dim, sC.pA + (row_idx + 0) * sdc + col_idx * block_size);
                    kernel_dpack_tn_4_lib4(4, C_matrix + col_idx + (row_idx + 4) * leading_dim,
                        leading_dim, sC.pA + (row_idx + 4) * sdc + col_idx * block_size);
                    kernel_dpack_tn_4_lib4(4, C_matrix + col_idx + (row_idx + 8) * leading_dim,
                        leading_dim, sC.pA + (row_idx + 8) * sdc + col_idx * block_size);
                    kernel_dtrsm_nt_rl_inv_12x4_lib4(
                        col_idx, sC.pA + row_idx * sdc, sdc,
                        sC.pA + col_idx * sdc, &one,
                        sC.pA + row_idx * sdc + col_idx * block_size, sdc,
                        sC.pA + row_idx * sdc + col_idx * block_size, sdc,
                        sC.pA + col_idx * sdc + col_idx * block_size, pc + col_idx);
                    kernel_dunpack_nt_4_lib4(4, sC.pA + (row_idx + 0) * sdc + col_idx * block_size,
                        C_matrix + col_idx + (row_idx + 0) * leading_dim, leading_dim);
                    kernel_dunpack_nt_4_lib4(4, sC.pA + (row_idx + 4) * sdc + col_idx * block_size,
                        C_matrix + col_idx + (row_idx + 4) * leading_dim, leading_dim);
                    kernel_dunpack_nt_4_lib4(4, sC.pA + (row_idx + 8) * sdc + col_idx * block_size,
                        C_matrix + col_idx + (row_idx + 8) * leading_dim, leading_dim);
                }
                kernel_dpack_tn_4_lib4(4, C_matrix + row_idx + (row_idx + 0) * leading_dim,
                    leading_dim, sC.pA + (row_idx + 0) * sdc + row_idx * block_size);
                kernel_dpack_tn_4_lib4(4, C_matrix + row_idx + (row_idx + 4) * leading_dim,
                    leading_dim, sC.pA + (row_idx + 4) * sdc + row_idx * block_size);
                kernel_dpack_tn_4_lib4(4, C_matrix + row_idx + (row_idx + 8) * leading_dim,
                    leading_dim, sC.pA + (row_idx + 8) * sdc + row_idx * block_size);
                kernel_dpotrf_nt_l_12x4_lib4(
                    row_idx, sC.pA + row_idx * sdc, sdc,
                    sC.pA + row_idx * sdc, sC.pA + row_idx * sdc + row_idx * block_size, sdc,
                    sC.pA + row_idx * sdc + row_idx * block_size, sdc, pc + row_idx);
                kernel_dunpack_nt_4_lib4(4, sC.pA + (row_idx + 0) * sdc + row_idx * block_size,
                    C_matrix + row_idx + (row_idx + 0) * leading_dim, leading_dim);
                kernel_dunpack_nt_4_lib4(4, sC.pA + (row_idx + 4) * sdc + row_idx * block_size,
                    C_matrix + row_idx + (row_idx + 4) * leading_dim, leading_dim);

