// Initialize the platform-specific HTTP client
bool SonyHttp::init()
{
    #ifdef __PS3__
        return sonyHttpClient_PS3.init();
    #elif defined __ORBIS__
        return sonyHttpClient_Orbis.init();
    #elif defined __PSVITA__
        return sonyHttpClient_Vita.init();
    #else
        return false;
    #endif
}

// Shutdown the platform-specific HTTP client
void SonyHttp::shutdown()
{
    #ifdef __PS3__
        sonyHttpClient_PS3.shutdown();
    #elif defined __ORBIS__
        sonyHttpClient_Orbis.shutdown();
    #elif defined __PSVITA__
        sonyHttpClient_Vita.shutdown();
    #endif
}

// Retrieve data from a given URL using the platform-specific implementation
