                entt::attribute{"name", "mip_count"},
                entt::attribute{"pretty_name", "Mip Count"},
                entt::attribute{"min", 2},
                entt::attribute{"max", 10},
            });
    }

    // Serialization: save bloom_pass::settings
    SAVE_INLINE(bloom_pass::settings)
    {
        auto& obj_ref = obj;
        try_save(ar, ser20::make_nvp("threshold", obj_ref.threshold));
        try_save(ar, ser20::make_nvp("soft_knee", obj_ref.soft_knee));
        try_save(ar, ser20::make_nvp("clamp", obj_ref.clamp));
        try_save(ar, ser20::make_nvp("intensity", obj_ref.intensity));
        try_save(ar, ser20::make_nvp("mip_count", obj_ref.mip_count));
    }

    SAVE_INSTANTIATE(bloom_pass::settings, ser20::oarchive_associative_t);
    SAVE_INSTANTIATE(bloom_pass::settings, ser20::oarchive_binary_t);

    // Serialization: load bloom_pass::settings
    LOAD_INLINE(bloom_pass::settings)
    {
        auto& obj_ref = obj;
        try_load(ar, ser20::make_nvp("threshold", obj_ref.threshold));
        try_load(ar, ser20::make_nvp("soft_knee", obj_ref.soft_knee));
        try_load(ar, ser20::make_nvp("clamp", obj_ref.clamp));
        try_load(ar, ser20::make_nvp("intensity", obj_ref.intensity));
        try_load(ar, ser20::make_nvp("mip_count", obj_ref.mip_count));
    }

    LOAD_INSTANTIATE(bloom_pass::settings, ser20::iarchive_associative_t);
    LOAD_INSTANTIATE(bloom_pass::settings, ser20::iarchive_binary_t);

    // Main component reflection: bloom_component
    REFLECT(bloom_component)
    {
        using comp_type = bloom_component;

        entt::meta_factory<comp_type>{}
            .type("bloom_component"_hs)
            .custom<entt::attributes>(entt::attributes{
