            .func<&component_meta<comp_type>::remove>("component_remove"_hs)
            .func<&component_meta<comp_type>::save>("component_save"_hs)
            .func<&component_meta<comp_type>::load>("component_load"_hs)
            .data<&comp_type::enabled>("enabled"_hs)
