// Save plain text version
void persist_text(const std::string& path, const ui_tree::sptr& ptr)
{
    if (!ptr) return;

    std::ofstream out_file(path);
    if (out_file.is_open() && out_file.good())
    {
        out_file << ptr->content;
    }
}

// Save binary serialized version
void persist_binary(const std::string& path, const ui_tree::sptr& ptr)
{
    if (!ptr) return;

    std::ofstream bin_out(path, std::ios::binary);
    if (!bin_out.is_open() || !bin_out.good()) return;

    ser20::oarchive_binary_t bin_ar(bin_out);
    bin_ar(ser20::make_nvp("ui_tree", *ptr));
}

// Load plain text version
void restore_text(const std::string& path, ui_tree::sptr& target)
{
    if (!target) target = std::make_shared<ui_tree>();

    std::ifstream in_file(path);
    if (!in_file.is_open() || !in_file.good()) return;

    target->content = fs::read_stream_str(in_file);
}

// Load binary serialized version
void restore_binary(const std::string& path, ui_tree::sptr& target)
{
    if (!target) target = std::make_shared<ui_tree>();

    std::ifstream bin_in(path, std::ios::binary);
    if (!bin_in.is_open() || !bin_in.good()) return;

    ser20::iarchive_binary_t bin_ar(bin_in);
    bin_ar(ser20::make_nvp("ui_tree", *target));
}
