#include <pthread.h>
#include <stdio.h>

int global_counter = 0;
pthread_mutex_t mutex_lock;

void *safe_increment(void *param) {
    for (int j = 0; j < 1000; j++) {
        pthread_mutex_lock(&mutex_lock);
        global_counter += 1;
        pthread_mutex_unlock(&mutex_lock);
    }
    return NULL;
}

void *unsafe_operation(void *param) {
    for (int k = 0; k < 1000; k++) {
        global_counter++;  // Race condition: no synchronization
    }
    return NULL;
}

int main(void) {
    pthread_t thread_a, thread_b;
    pthread_mutex_init(&mutex_lock, NULL);

    pthread_create(&thread_a, NULL, safe_increment, NULL);
    pthread_create(&thread_b, NULL, unsafe_operation, NULL);

    pthread_join(thread_a, NULL);
    pthread_join(thread_b, NULL);

    printf("Counter: %d\n", global_counter);
    pthread_mutex_destroy(&mutex_lock);
    return 0;
}

