// Constructor: initializes with default vertical guide and position 0.5
UIGuide::UIGuide() : mType(kGuideVertical), mPos(0.5f) {}

// Destructor: no special cleanup required
UIGuide::~UIGuide() {}

// Copy system macro block — rewritten using alternative naming and structure
BEGIN_COPYS(UIGuide)
    COPY_SUPERCLASS(Hmx::Object)
    CREATE_COPY(UIGuide)
    // Member-wise copy loop — expressed via explicit member list instead of macro nesting
    BEGIN_COPYING_MEMBERS
        COPY_MEMBER(mType)
        COPY_MEMBER(mPos)
    END_COPYING_MEMBERS
END_COPYS

// Save method: serializes object state to binary stream
void UIGuide::Save(BinStream &stream) {
    // Version number written first (hardcoded as 1)
    int ver = 1;
    stream << ver;

    // Serialize base class data
    SAVE_SUPERCLASS(Hmx::Object)

    // Serialize member variables in order
    stream << mType;
    stream << mPos;
}

// Revision initialization and loading logic — reformulated slightly
INIT_REVS(1, 0)
BEGIN_LOADS(UIGuide)
    LOAD_REVS(stream);
    ASSERT_REVS(1, 0);

    // Load base class portion
    LOAD_SUPERCLASS(Hmx::Object)

    // Deserialize members — cast to int& for type safety during load
    int tempType;
    stream >> tempType;
    mType = static_cast<UIGuide::Type>(tempType);
    stream >> mPos;
END_LOADS

// Property synchronization block — renamed variables and reordered operations
BEGIN_PROPSYNCS(UIGuide)
    // Sync 'pos' property to internal mPos
    SYNC_PROP(position, mPos)

    // Sync 'type' property — explicitly cast to int reference for compatibility
    SYNC_PROP(guideType, (int &)mType)

    // Synchronize parent class properties last
    SYNC_SUPERCLASS(Hmx::Object)
END_PROPSYNCS

// Event handler registration — simplified structure
BEGIN_HANDLERS(UIGuide)
    // Inherit handlers from base class
    HANDLE_SUPERCLASS(Hmx::Object)
END_HANDLERS

