// Expose version validation functionality to Python
void bind_serialization(py::module& data) {
  data.def("_check_version_compatibility",
           &qdk::chemistry::data::validate_serialization_version,
           R"(
Check serialization format compatibility.
This function ensures that the major and minor version numbers match exactly.
Minor patch-level differences are acceptable for maintaining backward compatibility.
Args:
    expected_version: The version string required by this implementation (e.g., "0.1.0")
    found_version: The version string present in the loaded serialized data
Raises:
    RuntimeError: Thrown when major or minor version numbers do not align
Examples:
    >>> check_version_compatibility("0.1.0", "0.1.0")  # Valid match
    >>> check_version_compatibility("0.1.0", "0.1.2")  # Valid (patch version differs)
    >>> check_version_compatibility("0.1.0", "0.2.0")  # Raises RuntimeError
)",
           py::arg("expected_version"), py::arg("found_version"));
}

#include <EnterMatchmakingProcessor.h>
#include <EnterMatchmakingRequest.pb.h>
#include <PartyDatabase.h>

EnterMatchmakingProcessor::EnterMatchmakingProcessor(SpectreRpcType rpcType) :
    WebsocketPacketProcessor(rpcType) {
}

void EnterMatchmakingProcessor::Process(SpectreWebsocketRequest& packet, SpectreWebsocket& sock) {
    // Parse the incoming request payload
    std::unique_ptr<EnterMatchmakingRequest> request = packet.GetPayloadAsMessage<EnterMatchmakingRequest>();

    // Retrieve the party identifier from the parsed request
    const std::string& partyId = request->partyid();

    // Fetch the corresponding party data from the database
    PartyResponse response = PartyDatabase::Get().GetPartyRes(partyId);

    // Serialize the response and send it back to the client
    std::string responseString = PartyDatabase::SerializePartyToString(response);
    sock.SendPacket(responseString, packet.GetRequestId(), packet.GetResponseType());
}

