RecordScoreJob::RecordScoreJob(
    Hmx::Object *callback, RecordScoreData &data, int songID, bool provideInstarank
)
    : RCJob("leaderboards/recordscore/", callback) {

    DataPoint pt;

    static Symbol song_id("song_id");
    static Symbol provide_instarank("provide_instarank");
    static Symbol xp("xp");

    char buffer[36];

    // Add score-related fields using formatted identifiers
    for (int idx = 0; idx < 1; ++idx) {
        Hx_snprintf(buffer, sizeof(buffer), "score%03d", idx);
        pt.AddPair(buffer, data.mStatus->mScore);

        Hx_snprintf(buffer, sizeof(buffer), "coop_score%03d", idx);
        pt.AddPair(buffer, data.mStatus->mCoopScore);

        Hx_snprintf(buffer, sizeof(buffer), "stars%03d", idx);
        pt.AddPair(buffer, data.mStatus->mStars);

        Hx_snprintf(buffer, sizeof(buffer), "no_flashcards%03d", idx);
        pt.AddPair(buffer, data.mStatus->mNoFlashcards != false);

        Hx_snprintf(buffer, sizeof(buffer), "diff%03d", idx);
        pt.AddPair(buffer, data.mStatus->mDifficulty);

        Hx_snprintf(buffer, sizeof(buffer), "pid%03d", idx);
        pt.AddPair(buffer, data.mProfile ? data.mProfile->GetOnlineID()->ToString() : "N/A");

        Hx_snprintf(buffer, sizeof(buffer), "xp%03d", idx);
        pt.AddPair(buffer, data.mProfile ? data.mProfile->GetMetagameRank()->RankNumber() : 0);

        Hx_snprintf(buffer, sizeof(buffer), "c_score%03d", idx);
        pt.AddPair(buffer, data.unkc);

        Hx_snprintf(buffer, sizeof(buffer), "cc_score%03d", idx);
        pt.AddPair(buffer, data.unk10);

        float calories_f1 = 0.0f;
        float calories_f2 = 0.0f;
        float calories_f3 = 0.0f;
        data.mProfile->GetFitnessStats(calories_f1, calories_f2, calories_f3);

        Hx_snprintf(buffer, sizeof(buffer), "calories%03d", idx);
        pt.AddPair(buffer, calories_f3);
    }

    // Attach metadata fields
    pt.AddPair(song_id, songID);
    pt.AddPair(provide_instarank, provideInstarank != false);

    SetDataPoint(pt);
}

