	constexpr FVector2D MediumIcon(16.0f, 16.0f);
	constexpr FVector2D LargeIcon(40.0f, 40.0f);
	constexpr FVector2D TinyIcon(8.0f, 8.0f);
	constexpr FVector2D ThumbSize(2.0f, 10.0f);

