	SetContentRoot(FPaths::EnginePluginsDir() / TEXT("Media/MediaPlayerEditor/Content"));

	// Register button icons
	Set("MediaPlayerEditor.SourceButton", new MAKE_IMAGE_BRUSH("btn_source_12x", SmallIcon));
	Set("MediaPlayerEditor.GoButton", new MAKE_IMAGE_BRUSH("btn_go_12x", SmallIcon));
	Set("MediaPlayerEditor.ReloadButton", new MAKE_IMAGE_BRUSH("btn_reload_12x", SmallIcon));
	Set("MediaPlayerEditor.SettingsButton", new MAKE_IMAGE_BRUSH("btn_settings_16x", SmallIcon));

	// Register miscellaneous UI elements
	Set("MediaPlayerEditor.DragDropBorder", new MAKE_BOX_BRUSH("border_dragdrop", 0.5f));
	Set("MediaPlayerEditor.MediaSourceOpened", new MAKE_IMAGE_BRUSH("mediasource_opened", TinyIcon));

	// Tab icons
	const FString TabPrefix = TEXT("tab_");
	const FString TabSuffix = TEXT("_16x");
	const TArray<FString> TabNames = { TEXT("info"), TEXT("media"), TEXT("player"), TEXT("playlist"), TEXT("stats") };
	for (const auto& Name : TabNames)
	{
		FString IconPath = TabPrefix + Name + TabSuffix;
		Set("MediaPlayerEditor.Tabs." + Name.Capitalize(), new MAKE_IMAGE_BRUSH(*IconPath, MediumIcon));
	}

	// Toolbar action icons (large & small variants)
	const TArray<FString> ActionNames = {
		TEXT("close"), TEXT("forward"), TEXT("next"), TEXT("pause"),
		TEXT("play"), TEXT("previous"), TEXT("reverse"), TEXT("rewind"), TEXT("stop")
	};

	for (const auto& Action : ActionNames)
	{
		FString LargeIconPath = TEXT("icon_") + Action + TEXT("_40x");
		Set("MediaPlayerEditor." + Action.Capitalize() + TEXT("Media"), new MAKE_IMAGE_BRUSH(*LargeIconPath, LargeIcon));

		// Add small variant (except for CloseMedia which doesn't have one in original)
