		.SetDisabledBarImage(FSlateColorBrush(FLinearColor::Gray))
		.SetNormalThumbImage(MAKE_IMAGE_BRUSH("scrubber", ThumbSize))
		.SetHoveredThumbImage(MAKE_IMAGE_BRUSH("scrubber", ThumbSize))
		.SetDisabledThumbImage(MAKE_IMAGE_BRUSH("scrubber", ThumbSize))
