TEST(GraphTest, VerticeSemantics) {
  // Default-constructed vertice should be dummy
  Vertice v1;
  EXPECT_TRUE(v1.IsDummy());

  // Copy constructor
  Vertice v2(v1);
  EXPECT_TRUE(v2.IsDummy());
  EXPECT_EQ(v2, v1);

  // Copy assignment
  Vertice v3 = v1;
  EXPECT_TRUE(v3.IsDummy());
  EXPECT_EQ(v3.GetKey(), v1.GetKey());

  // Self-assignment (no-op)
  v1 = v1;

  // Non-dummy vertice with value
  Vertice v4("v4");
  EXPECT_FALSE(v4.IsDummy());
  EXPECT_NE(v4, v1);
  EXPECT_NE(v4.GetKey(), v1.GetKey());
  EXPECT_EQ(v4.value(), "v4");
}

TEST(GraphTest, EdgeSemantics) {
  // Default edge is invalid
  Edge e1;
  EXPECT_FALSE(e1.IsValid());

  // Copy constructor
  Edge e2(e1);
  EXPECT_FALSE(e2.IsValid());
  EXPECT_EQ(e2, e1);
  EXPECT_EQ(e2.GetKey(), e1.GetKey());

  // Copy assignment
  Edge e3 = e1;
  EXPECT_FALSE(e3.IsValid());
  EXPECT_EQ(e3, e1);
  EXPECT_EQ(e3.GetKey(), e1.GetKey());

  // Self-assignment
  e1 = e1;

  // Assignment between edges
  Edge e4;
  e4 = e3;
  EXPECT_FALSE(e4.IsValid());
  EXPECT_EQ(e4, e3);
  EXPECT_EQ(e4.GetKey(), e3.GetKey());

  // Set and verify value
  const std::string val = "test_value";
  e1.set_value(val);
  EXPECT_EQ(e1.value(), val);
  EXPECT_FALSE(e1 == e2);  // e2 still default (invalid)

  e2.set_value(val);
  EXPECT_EQ(e1, e2);  // same value now

  // Set source/destination
  Vertice src_v("src_node");
  Vertice dst_v("dst_node");
  e1.set_src(src_v);
  e2.set_dst(dst_v);

  EXPECT_EQ(e1.src(), src_v);
  EXPECT_EQ(e2.dst(), dst_v);
  EXPECT_FALSE(e1 == e2);  // incomplete edges

  EXPECT_TRUE(e1.IsValid());
  EXPECT_TRUE(e2.IsValid());

  // Complete both edges to match
  e1.set_dst(dst_v);
  e2.set_src(src_v);
  EXPECT_EQ(e1, e2);
  EXPECT_EQ(e1.GetKey(), "test_value_dst_node");

  // Construct via constructor
  Edge e5(src_v, dst_v, val);
  EXPECT_EQ(e5, e1);
}

TEST(GraphTest, GraphOperations) {
  Graph g;

  // Initial state
  EXPECT_EQ(g.GetNumOfEdge(), 0);

  Vertice dummy;
  Vertice nodeA("A");
  Vertice nodeB("B");
  Vertice nodeC("C");
  Vertice nodeD("D");
  Vertice nodeE("E");

  // Insert empty edge → ignored
  Edge edgeAB;
  g.Insert(edgeAB);
  EXPECT_EQ(g.GetNumOfEdge(), 0);

  // Fill and insert valid edge
  edgeAB.set_src(nodeA);
  edgeAB.set_dst(nodeB);
  edgeAB.set_value("AB");
  g.Insert(edgeAB);
  EXPECT_EQ(g.GetNumOfEdge(), 1);

  // Duplicate insert → no change
  g.Insert(edgeAB);
  EXPECT_EQ(g.GetNumOfEdge(), 1);

  // Insert another edge via constructor
  Edge edgeCD(nodeC, nodeD, "CD");
  g.Insert(edgeCD);
  EXPECT_EQ(g.GetNumOfEdge(), 2);

  // Insert third edge
  Edge edgeCE(nodeC, nodeE, "CE");
  g.Insert(edgeCE);
  EXPECT_EQ(g.GetNumOfEdge(), 3);

  // Try inserting partial edges (should not increase count)
  Edge edgeAC;
  edgeAC.set_src(nodeA);
  edgeAC.set_dst(dummy);
  edgeAC.set_value("AC");
  g.Insert(edgeAC);
  EXPECT_EQ(g.GetNumOfEdge(), 3);

  edgeAC.set_src(dummy);
  edgeAC.set_dst(nodeC);
  g.Insert(edgeAC);
  EXPECT_EQ(g.GetNumOfEdge(), 4);

  Edge edgeBE;
  edgeBE.set_src(dummy);
  edgeBE.set_dst(nodeE);
  edgeBE.set_value("BE");
  g.Insert(edgeBE);
  EXPECT_EQ(g.GetNumOfEdge(), 4);

  edgeBE.set_dst(dummy);
  edgeBE.set_src(nodeB);
  g.Insert(edgeBE);
  EXPECT_EQ(g.GetNumOfEdge(), 5);

  // Direction checks
  EXPECT_EQ(g.GetDirectionOf(nodeA, nodeB), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeB, nodeA), DOWNSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeA, nodeC), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeC, nodeA), DOWNSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeB, nodeE), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeE, nodeB), DOWNSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeC, nodeD), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeD, nodeC), DOWNSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeC, nodeE), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeE, nodeC), DOWNSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeA, nodeE), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeE, nodeA), DOWNSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeA, nodeD), UPSTREAM);
  EXPECT_EQ(g.GetDirectionOf(nodeD, nodeA), DOWNSTREAM);

  // Unreachable pairs
  EXPECT_EQ(g.GetDirectionOf(nodeB, nodeD), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(nodeD, nodeB), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(nodeD, nodeE), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(nodeE, nodeD), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(dummy, dummy), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(nodeA, dummy), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(dummy, nodeA), UNREACHABLE);

  Vertice nodeF("F");
  EXPECT_EQ(g.GetDirectionOf(nodeA, nodeF), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(nodeF, nodeA), UNREACHABLE);

  // Deletion tests
  g.Delete(edgeBE);
  EXPECT_EQ(g.GetDirectionOf(nodeB, nodeE), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(nodeE, nodeB), UNREACHABLE);
  EXPECT_EQ(g.GetNumOfEdge(), 4);

  g.Delete(edgeBE);  // delete again — safe no-op
  g.Delete(edgeAC);
  EXPECT_EQ(g.GetNumOfEdge(), 3);
  EXPECT_EQ(g.GetDirectionOf(nodeA, nodeC), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(nodeD, nodeA), UNREACHABLE);

  g.Delete(edgeCD);
  EXPECT_EQ(g.GetNumOfEdge(), 2);
  EXPECT_EQ(g.GetDirectionOf(nodeC, nodeD), UNREACHABLE);
  EXPECT_EQ(g.GetDirectionOf(nodeD, nodeC), UNREACHABLE);

  g.Delete(edgeAB);
  EXPECT_EQ(g.GetNumOfEdge(), 1);

  g.Delete(edgeCE);
  EXPECT_EQ(g.GetNumOfEdge(), 0);

  // Delete non-existent or incomplete edges
  Vertice nodeQ("Q");
  Edge edgeQA;
  g.Delete(edgeQA);  // empty edge — safe

  edgeQA.set_src(nodeQ);
  edgeQA.set_dst(nodeA);
  edgeQA.set_value("QA");
  g.Delete(edgeQA);  // now complete — should delete if present
}
