    std::cout << "MaQa=M" << '\n';
    std::cout << "MbQb=M" << '\n';
    std::cout << "McQc=M" << '\n';

    // Success condition when pattern is fully matched
    std::cout << "MQ#=(return)1" << '\n';

    // Failure transitions for mismatched characters
    std::cout << "MaQb=F" << '\n';
    std::cout << "MaQc=F" << '\n';
    std::cout << "MbQa=F" << '\n';
    std::cout << "MbQc=F" << '\n';
    std::cout << "McQa=F" << '\n';
    std::cout << "McQb=F" << '\n';

    // Mismatch recovery rules
    std::cout << "aF=Fa" << '\n';
    std::cout << "bF=Fb" << '\n';
    std::cout << "cF=Fc" << '\n';
    std::cout << "MF=FM" << '\n';

    // Advance pointer after cleanup
    std::cout << "FM=P" << '\n';

    // Restore pattern from backup when starting new match attempt
    std::cout << "PaQ=PaR" << '\n';
    std::cout << "PbQ=PbR" << '\n';
    std::cout << "PcQ=PcR" << '\n';
    std::cout << "P#=P_R" << '\n';

    // Restore state processing
    std::cout << "Ra=R" << '\n';
    std::cout << "Rb=R" << '\n';
    std::cout << "Rc=R" << '\n';
    std::cout << "R#=T" << '\n';

    // Copy from backup tape
    std::cout << "TX=aT" << '\n';
    std::cout << "TY=bT" << '\n';
    std::cout << "TZ=cT" << '\n';

    // Finalize restoration
    std::cout << "aT=aQ" << '\n';
    std::cout << "bT=bQ" << '\n';
    std::cout << "cT=cQ" << '\n';
    std::cout << "T=Q" << '\n';

    // Termination condition when pattern scanning complete
    std::cout << "PQ=(return)0" << '\n';

    return 0;
}

#include <dolphin.h>
#include <dolphin/os.h>
#include "__os.h"

// Function declarations
void __OSSystemCallVectorStart(void);
void __OSSystemCallVectorEnd(void);

#ifdef __GEKKO__
static asm void SystemCallVector(void) {
entry __OSSystemCallVectorStart
    nofralloc
    mfspr r9, HID0
    ori r10, r9, 0x8
    mtspr HID0, r10
    isync
    sync
    mtspr HID0, r9
    rfi
entry __OSSystemCallVectorEnd
    nop
}
#endif

void __OSInitSystemCall(void) {
    // Compute the size of the system call vector
    u32 vectorSize = (u32)&__OSSystemCallVectorEnd - (u32)&__OSSystemCallVectorStart;

    // Map physical address 0xC00 to cached memory
    void* targetAddr = (void*)OSPhysicalToCached(0xC00);

    // Copy the vector code into place
    memcpy(targetAddr, &__OSSystemCallVectorStart, vectorSize);

    // Ensure data cache is flushed before invalidating instruction cache
    DCFlushRangeNoSync(targetAddr, 0x100);
    __sync();

    // Invalidate instruction cache for the copied region
    ICInvalidateRange(targetAddr, 0x100);
}

