void fatalf(const char* format, ...) {
    va_list args;
    fprintf(stderr, "runtime/cgo: ");
    va_start(args, format);
    vfprintf(stderr, format, args);
    va_end(args);
    fprintf(stderr, "\n");
    exit(EXIT_FAILURE);
}

