// Helper to check if string contains backslash (for path validation)
bool HasBackslash(const std::string& path) {
    return path.find('\\') != std::string::npos;
}

// Helper to check if string contains forward slash
bool HasForwardSlash(const std::string& path) {
    return path.find('/') != std::string::npos;
}

TEST_CASE("PathNotFoundError", "[PathNotFoundError]") {
    SECTION("Catch exact type") {
        try {
            throw fs::PathNotFoundError("Not found text");
