        try {
            throw fs::PathNotFoundError("Not found text");
        }
        catch (const std::runtime_error &err) {
            REQUIRE(std::strcmp(err.what(), "Not found text") == 0);
        }
    }

    SECTION("Catch base exception") {
        try {
            throw fs::PathNotFoundError("Not found text");
        }
        catch (const std::exception &err) {
            REQUIRE(std::strcmp(err.what(), "Not found text") == 0);
        }
    }
}

