// Helper function to handle denormal numbers
double fix_denormal(double value) {
    union {
        double d;
        struct {
            uint32_t low;
            uint32_t high;
        } parts;
    } u;

    u.d = value;
    uint32_t exp = (u.parts.high & 0x7FF00000) >> 20;

    if (exp == 0 || exp == 0x7FF) {
        u.parts.low = 0;
        u.parts.high = 0;
        return u.d;
    }
    return value;
}

// Calculate inverse square root using fast method
double fast_invsqrt(double x) {
    float f = static_cast<float>(x);
    const float half = 0.5f;
    const float three = 1.5f;

    long i;
    std::memcpy(&i, &f, sizeof(long));
    i = 0x5f3759df - (i >> 1);

    float y;
    std::memcpy(&y, &i, sizeof(float));

    y = y * (three - half * y * y);
    y = y * (three - half * y * y);

    return static_cast<double>(y);
}

