// Arithmetic operations
double nseel_asm_add(double a, double b) {
    return a + b;
}

double nseel_asm_add_op(double& dest, double src) {
    dest += src;
    return fix_denormal(dest);
}

double nseel_asm_add_op_fast(double& dest, double src) {
    dest += src;
    return dest;
}

