// Stack operations
class SimpleStack {
private:
    double* data;
    size_t capacity;
    size_t top;

public:
    SimpleStack() : capacity(1024), top(0) {
        data = new double[capacity];
    }

    ~SimpleStack() {
        delete[] data;
    }

    void push(double value) {
        if (top < capacity) {
            data[top++] = value;
        }
    }

    double pop() {
        if (top > 0) {
            return data[--top];
        }
        return 0.0;
    }

    double peek() {
        if (top > 0) {
            return data[top - 1];
        }
        return 0.0;
    }

    bool empty() const {
        return top == 0;
    }
};

// Global stack instance
SimpleStack global_stack;

void nseel_asm_stack_push(double value) {
    global_stack.push(value);
}

double nseel_asm_stack_pop() {
    return global_stack.pop();
}

double nseel_asm_stack_pop_fast() {
    return global_stack.pop();
}

int nseel_asm_stack_peek_int() {
    return static_cast<int>(global_stack.peek());
}

double nseel_asm_stack_peek() {
    return global_stack.peek();
}

double nseel_asm_stack_peek_top() {
    return global_stack.peek();
}

void nseel_asm_stack_exch(double& a, double& b) {
    double temp = a;
    a = b;
    b = temp;
}

