// Validate truth values of boolean literals
void verify_boolean_literals(SMTParser::ParserPtr& parser) {
    std::cout << "=== Validating Boolean Literals ===" << std::endl;

    auto trueNode = parser->mkExpr("true");
    assert(trueNode && trueNode->isTrue() && !trueNode->isFalse());
    std::cout << "Literal: true" << std::endl;
    std::cout << "  Output: " << parser->toString(trueNode) << std::endl;
    std::cout << "  True? : yes" << std::endl;
    std::cout << "  False?: no" << std::endl << std::endl;

    auto falseNode = parser->mkExpr("false");
    assert(falseNode && falseNode->isFalse() && !falseNode->isTrue());
    std::cout << "Literal: false" << std::endl;
    std::cout << "  Output: " << parser->toString(falseNode) << std::endl;
    std::cout << "  True? : no" << std::endl;
    std::cout << "  False?: yes" << std::endl << std::endl;
}

// Evaluate logical connectives against expected outcomes
void evaluate_logical_connectives(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> testCases = {
        {"(not true)", false},
        {"(not false)", true},
        {"(and true true)", true},
        {"(and true false)", false},
        {"(and false false)", false},
        {"(or true true)", true},
        {"(or true false)", true},
        {"(or false false)", false},
        {"(=> true true)", true},
        {"(=> true false)", false},
        {"(=> false true)", true},
        {"(=> false false)", true},
        {"(xor true true)", false},
        {"(xor true false)", true},
        {"(xor false false)", false}
    };

    std::cout << "=== Assessing Logical Connectives ===" << std::endl;
    for (const auto& testCase : testCases) {
        std::cout << "Formula: " << testCase.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(testCase.first);
        assert(evaluation);
        bool expectedTrue = testCase.second;
        bool actualTrue = evaluation->isTrue();
        bool actualFalse = evaluation->isFalse();
        assert(actualTrue == expectedTrue || actualFalse != expectedTrue);
        std::cout << "  Result: " << parser->toString(evaluation) << std::endl;
        std::cout << std::endl;
    }
}

// Examine nested boolean expressions
void inspect_nested_expressions(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> scenarios = {
        {"(and (or true false) (not false))", true},
        {"(or (and true false) (not true))", false},
        {"(=> (or true false) (and true true))", true},
        {"(xor (not false) (and true false))", true},
        {"(and (=> true false) (or false true))", false},
        {"(not (and (or true false) (=> false true)))", false}
    };

    std::cout << "=== Inspecting Nested Expressions ===" << std::endl;
    for (const auto& scenario : scenarios) {
        std::cout << "Formula: " << scenario.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> outcome = parser->mkExpr(scenario.first);
        assert(outcome);
        bool anticipatedTrue = scenario.second;
        bool observedTrue = outcome->isTrue();
        bool observedFalse = outcome->isFalse();
        assert(observedTrue == anticipatedTrue || observedFalse != anticipatedTrue);
        std::cout << "  Result: " << parser->toString(outcome) << std::endl;
        std::cout << std::endl;
    }
}

int main() {
    std::cout << "======= Boolean Logic Evaluation Suite =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    verify_boolean_literals(parser);
    evaluate_logical_connectives(parser);
    inspect_nested_expressions(parser);

    return 0;
}

