#include "bounding_box_diagonal.h"
#include "mat_max.h"
#include "mat_min.h"
#include <cmath>

// Compute the length of the diagonal of the axis-aligned bounding box of vertex set V
IGL_INLINE double igl::bounding_box_diagonal(
  const Eigen::MatrixXd & V)
{
  using namespace Eigen;

  VectorXd max_vals, min_vals;
  VectorXi max_indices, min_indices;

  // Find maximum and minimum values along each column (dimension)
  mat_max(V, 1, max_vals, max_indices);
  mat_min(V, 1, min_vals, min_indices);

  // Compute Euclidean norm of the difference vector (max - min)
  VectorXd diff = max_vals - min_vals;
  return std::sqrt((diff.array() * diff.array()).sum());
}

