namespace Karm::Base::Tests {
test$("ring-avoid-pop-back-underflow") {
    Ring<int> ring(5);

    // Fill the ring with values 0 through 4
    for (int i = 0; i < 5; ++i) {
        ring.pushBack(i);
    }

    // Verify initial head position
    expectEq$(ring._head, 0u);

    // Perform popBack operation
    ring.popBack();

    // After popping one element from back, head should wrap around to last index
    expectEq$(ring._head, 4u);

    return Ok();
}
} // namespace Karm::Base::Tests

