void RndShadowMap::Cleanup() {
    if (sLightCam) {
        delete sLightCam;
        sLightCam = nullptr;
    }
    if (sShadowTex) {
        delete sShadowTex;
        sShadowTex = nullptr;
    }
}

void RndShadowMap::Setup() {
    PhysMemTypeTracker memoryTracker("D3D(phys):Global");

    // Reinitialize light camera
    sLightCam = Hmx::Object::New<RndCam>();

    // Create shadow texture with specific parameters
    sShadowTex = Hmx::Object::New<RndTex>();
    sShadowTex->GenerateTexture(512, 512, 32, RndTex::kShadowMap, false);

    // Link camera to shadow texture
    sLightCam->AttachTarget(sShadowTex);
}

