class Solution {
public:
    int minimumOperations(vector<int>& nums) {
        int count = 0;
        for (int i = 0; i < nums.size(); ++i) {
            if (nums[i] % 3 != 0) {
                count++;
            }
        }
        return count;
    }
};

class Solution {
public:
    bool isStrictlyPalindromic(int n) {
        // Based on mathematical proof, no integer n > 4 can be 
        // palindromic in all bases from 2 to n-2
        // For n <= 4, the condition is vacuously false or undefined
        if (n <= 4) {
            return false;
        }

        // Check bases from 2 to n-2 (though this will never return true)
        for (int base = 2; base <= n - 2; ++base) {
            int temp = n;
            std::vector<int> digits;

            // Convert number to given base
            while (temp > 0) {
                digits.push_back(temp % base);
                temp /= base;
            }

            // Check if digits form a palindrome
            int left = 0;
            int right = digits.size() - 1;
            while (left < right) {
                if (digits[left] != digits[right]) {
                    return false;
                }
                left++;
                right--;
            }
        }

        return false;
    }
};

