#include <llvm/ObjectYAML/OffloadYAML.h>

namespace llvm {
namespace yaml {

// Enumerate ImageKind values using macro-based case registration
void ScalarEnumerationTraits<object::ImageKind>::enumeration(
    IO &IO, object::ImageKind &Val) {
#define CASE(X) IO.enumCase(Val, #X, object::X)
  CASE(IMG_None);
  CASE(IMG_Object);
  CASE(IMG_Bitcode);
  CASE(IMG_Cubin);
  CASE(IMG_Fatbinary);
  CASE(IMG_PTX);
  CASE(IMG_LAST);
#undef CASE
  IO.enumFallback<Hex16>(Val);
}

// Enumerate OffloadKind values similarly
void ScalarEnumerationTraits<object::OffloadKind>::enumeration(
    IO &IO, object::OffloadKind &Val) {
#define CASE(X) IO.enumCase(Val, #X, object::X)
  CASE(OFK_None);
  CASE(OFK_OpenMP);
  CASE(OFK_Cuda);
  CASE(OFK_HIP);
  CASE(OFK_LAST);
#undef CASE
  IO.enumFallback<Hex16>(Val);
}

// Mapping for OffloadYAML::Binary structure
void MappingTraits<OffloadYAML::Binary>::mapping(IO &IO,
                                                 OffloadYAML::Binary &Bin) {
  assert(!IO.getContext() && "Context already set");
  IO.setContext(&Bin);
  IO.mapTag("!Offload", true);
  IO.mapOptional("Version", Bin.Version);
  IO.mapOptional("Size", Bin.Size);
  IO.mapOptional("EntryOffset", Bin.EntryOffset);
  IO.mapOptional("EntrySize", Bin.EntrySize);
  IO.mapRequired("Members", Bin.Members);
  IO.setContext(nullptr);
}

// Mapping for StringEntry (key-value pair)
void MappingTraits<OffloadYAML::Binary::StringEntry>::mapping(
    IO &IO, OffloadYAML::Binary::StringEntry &Entry) {
  assert(IO.getContext() && "Context not initialized");
  IO.mapRequired("Key", Entry.Key);
  IO.mapRequired("Value", Entry.Value);
}

// Mapping for Member entry in binary offload image
void MappingTraits<OffloadYAML::Binary::Member>::mapping(
    IO &IO, OffloadYAML::Binary::Member &Member) {
  assert(IO.getContext() && "Context not initialized");
  IO.mapOptional("ImageKind", Member.ImageKind);
  IO.mapOptional("OffloadKind", Member.OffloadKind);
  IO.mapOptional("Flags", Member.Flags);
  IO.mapOptional("String", Member.StringEntries);
  IO.mapOptional("Content", Member.Content);
}

