#include <library/cpp/testing/gtest/gtest.h>
#include <library/cpp/yt/misc/compare.h>
#include <string>
#include <string_view>

namespace NYT {
namespace {

// Test for basic ternary comparison behavior including NaN handling
TEST(TCompareTest, BasicTernaryComparison) {
    EXPECT_EQ(TernaryCompare(123, 123), 0);
    EXPECT_EQ(TernaryCompare(10, 20), -1);
    EXPECT_EQ(TernaryCompare(20, 10), +1);

    // All NaN cases should return +1 in standard TernaryCompare
    EXPECT_EQ(TernaryCompare(std::nan("1"), std::nan("1")), +1);
    EXPECT_EQ(TernaryCompare(std::nan("1"), std::nan("2")), +1);
    EXPECT_EQ(TernaryCompare(std::nan("1"), 123.0), +1);
    EXPECT_EQ(TernaryCompare(123.0, std::nan("1")), +1);
}

// Test for NaN-safe ternary comparison
TEST(TCompareTest, NaNSafeComparison) {
    // Two NaNs should be considered equal (return 0)
    EXPECT_EQ(NaNSafeTernaryCompare(std::nan("1"), std::nan("1")), 0);
    EXPECT_EQ(NaNSafeTernaryCompare(std::nan("1"), std::nan("2")), 0);

    // NaN vs normal number: NaN is treated as greater than any normal value
    EXPECT_EQ(NaNSafeTernaryCompare(123.0, std::nan("1")), -1);
    EXPECT_EQ(NaNSafeTernaryCompare(std::nan("1"), 123.0), +1);
}

// Template test fixture for string-like types
template <class T>
class TStringCompareTest
    : public ::testing::Test
{ };

// Register the test suite with multiple string types
TYPED_TEST_SUITE_P(TStringCompareTest);

// Define the actual test logic
TYPED_TEST_P(TStringCompareTest, StringComparisons) {
    // Equal strings should compare as 0
    EXPECT_EQ(TernaryCompare(TypeParam("abc"), TypeParam("abc")), 0);

    // Lexicographic ordering tests
    EXPECT_EQ(TernaryCompare(TypeParam("x"), TypeParam("y")), -1);
    EXPECT_EQ(TernaryCompare(TypeParam("y"), TypeParam("x")), +1);
}

// Register the test cases for various string types
REGISTER_TYPED_TEST_SUITE_P(TStringCompareTest, StringComparisons);

// List of types to instantiate the test with
using TStringCompareTypes = ::testing::Types<
    TString,
    TStringBuf,
    std::string,
    std::string_view
>;

// Instantiate the typed test suite
INSTANTIATE_TYPED_TEST_SUITE_P(
    StringComparisons,
    TStringCompareTest,
    TStringCompareTypes);

