// Register all E1.31 packet types for serialization support
REGISTER_DMX_ARCHIVE(FDMXProtocolE131RootLayerPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolE131FramingLayerPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolE131DMPLayerPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolUDPE131FramingLayerPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolUDPE131DiscoveryLayerPacket);

// Root Layer Packet Serialization & Packing
TSharedPtr<FBufferArchive> FDMXProtocolE131RootLayerPacket::Pack()
{
	TSharedPtr<FBufferArchive> Archive = MakeShared<FBufferArchive>();
	*Archive << *this;
	return Archive;
}

void FDMXProtocolE131RootLayerPacket::Serialize(FArchive& Stream)
{
	Stream.SetByteSwapping(true);
	Stream << PreambleSize;
	Stream << PostambleSize;

	Stream.SetByteSwapping(false);
	Stream.Serialize(reinterpret_cast<void*>(ACNPacketIdentifier), ACN_IDENTIFIER_SIZE);

	Stream.SetByteSwapping(true);
	Stream << FlagsAndLength;
	Stream << Vector;

	Stream.SetByteSwapping(false);
	Stream.Serialize(reinterpret_cast<void*>(CID), ACN_CIDBYTES);
}

// Framing Layer Packet Serialization & Packing
TSharedPtr<FBufferArchive> FDMXProtocolE131FramingLayerPacket::Pack()
{
	TSharedPtr<FBufferArchive> Archive = MakeShared<FBufferArchive>();
	*Archive << *this;
	return Archive;
}

void FDMXProtocolE131FramingLayerPacket::Serialize(FArchive& Stream)
{
	Stream.SetByteSwapping(true);
	Stream << FlagsAndLength;
	Stream << Vector;

	Stream.SetByteSwapping(false);
	Stream.Serialize(reinterpret_cast<void*>(SourceName), ACN_SOURCE_NAME_SIZE);

	Stream.SetByteSwapping(true);
	Stream << Priority;
	Stream << SynchronizationAddress;
	Stream << SequenceNumber;
	Stream << Options;
	Stream << Universe;
}

// DMP Layer Packet Serialization & Packing
TSharedPtr<FBufferArchive> FDMXProtocolE131DMPLayerPacket::Pack()
{
	TSharedPtr<FBufferArchive> Archive = MakeShared<FBufferArchive>();
	*Archive << *this;
	return Archive;
}

void FDMXProtocolE131DMPLayerPacket::Serialize(FArchive& Stream)
{
	Stream.SetByteSwapping(true);
	Stream << FlagsAndLength;
	Stream << Vector;
	Stream << AddressTypeAndDataType;
	Stream << FirstPropertyAddress;
	Stream << AddressIncrement;
	Stream << PropertyValueCount;
	Stream << STARTCode;

	Stream.SetByteSwapping(false);
	Stream.Serialize(reinterpret_cast<void*>(DMX), ACN_DMX_SIZE);
}

// UDP Framing Layer Packet Serialization & Packing
TSharedPtr<FBufferArchive> FDMXProtocolUDPE131FramingLayerPacket::Pack()
{
	TSharedPtr<FBufferArchive> Archive = MakeShared<FBufferArchive>();
	*Archive << *this;
	return Archive;
}

void FDMXProtocolUDPE131FramingLayerPacket::Serialize(FArchive& Stream)
{
	Stream.SetByteSwapping(true);
	Stream << FlagsAndLength;
	Stream << Vector;

	Stream.SetByteSwapping(false);
	Stream.Serialize(reinterpret_cast<void*>(SourceName), ACN_SOURCE_NAME_SIZE);
	Stream.Serialize(reinterpret_cast<void*>(Reserved), sizeof(Reserved));
}

// Discovery Layer Packet Serialization & Packing
TSharedPtr<FBufferArchive> FDMXProtocolUDPE131DiscoveryLayerPacket::Pack()
{
	TSharedPtr<FBufferArchive> Archive = MakeShared<FBufferArchive>();
	*Archive << *this;
	return Archive;
}

void FDMXProtocolUDPE131DiscoveryLayerPacket::Serialize(FArchive& Stream)
{
	Stream.SetByteSwapping(true);
	Stream << FlagsAndLength;
	Stream << Vector;
	Stream << Page;
	Stream << Last;

	Stream.SetByteSwapping(false);
	Stream.Serialize(reinterpret_cast<void*>(Universes), sizeof(Universes));
}

#include "Misc/AutomationTest.h"

BEGIN_DEFINE_SPEC(AutomationSpec, "System.Automation.Spec", EAutomationTestFlags::EngineFilter | EAutomationTestFlags::ApplicationContextMask)
	bool IsFoo;
	FString ExecutionSequence; 
END_DEFINE_SPEC(AutomationSpec)

void AutomationSpec::Define()
{
	Describe("A top-level description block 1", [this]()
	{
		It("executes a basic test case with expected outcome", [this]()
		{
			IsFoo = true;
			TestEqual("IsFoo flag check", IsFoo, true);
		});
	});

	Describe("A top-level description block 2", [this]()
	{
		BeforeEach([&]()
		{
			IsFoo = false;
		});
		xIt("skips disabled individual tests", [this]()
		{
			TestEqual("IsFoo should remain false", IsFoo, true);
		});
		xDescribe("with nested disabled describe blocks", [this]()
		{
			It("does not execute tests inside disabled describes", [this]()
			{
				TestEqual("IsFoo should remain false", IsFoo, true);
			});
		});
	});

	Describe("Test suite for BeforeEach/AfterEach ordering", [this]()
	{
		BeforeEach([this]()
		{
			ExecutionSequence = TEXT("First");
		});
		It("ensures correct setup and teardown sequence", [this]()
		{
			TestEqual("Initial execution state", ExecutionSequence, TEXT("First"));
		});
		AfterEach([this]()
		{
			ExecutionSequence += TEXT("Final");
			TestEqual("Post-test execution state", ExecutionSequence, TEXT("FirstFinal"));
		});
	});

	Describe("Nested BeforeEach/AfterEach interaction", [this]()
	{
		AfterEach([this]()
		{
			ExecutionSequence += TEXT("End");
			TestEqual("Outer AfterEach result", ExecutionSequence, TEXT("StartMiddleEnd"));
		});
		Describe("Inner nested context", [this]()
		{
			It("verifies combined setup and cleanup order", [this]()
			{
				TestEqual("Combined sequence verification", ExecutionSequence, TEXT("StartMiddle"));
			});
			AfterEach([this]()
			{
				ExecutionSequence += TEXT("MidCleanup");
			});
			BeforeEach([this]()
			{
				ExecutionSequence += TEXT("Middle");
			});
		});
		BeforeEach([this]()
		{
			ExecutionSequence = TEXT("Start");
		});
	});

	Describe("Deeply nested BeforeEach/AfterEach chain", [this]()
	{
		BeforeEach([this]()
		{
			ExecutionSequence = TEXT("Alpha");
		});
		AfterEach([this]()
		{
			ExecutionSequence += TEXT("Omega");
			TestEqual("Full chain verification", ExecutionSequence, TEXT("AlphaBetaGammaDeltaSigmaTauOmega"));
		});
		BeforeEach([this]()
		{
			ExecutionSequence += TEXT("Beta");
		});
		Describe("Second level nesting", [this]()
		{
			AfterEach([this]()
			{
				ExecutionSequence += TEXT("Tau");
			});
			BeforeEach([this]()
			{
				ExecutionSequence += TEXT("Gamma");
			});
			Describe("Third level nesting", [this]()
			{
				It("tests deep nesting behavior", [this]()
				{
					TestEqual("Multi-level sequence", ExecutionSequence, TEXT("AlphaBetaGammaDelta"));
				});
				AfterEach([this]()
				{
					ExecutionSequence += TEXT("Sigma");
				});
				BeforeEach([this]()
				{
					ExecutionSequence += TEXT("Delta");
				});
			});
		});
	});
}

