// Helper function to retrieve RGB as Eigen vector with alpha channel
Eigen::Vector4i html_color(COLORNAME color) {
  const size_t idx = static_cast<size_t>(color);
  const auto& rgb = color_rgb_data[idx];
  return Eigen::Vector4i(rgb[0], rgb[1], rgb[2], 255);
}

// Floating-point version normalized to [0,1]
Eigen::Vector4f html_colorf(COLORNAME color) {
  return html_color(color).template cast<float>() / 255.0f;
}

// Return reference to the color name array
const std::array<const char*, static_cast<size_t>(COLORNAME::NUM_COLORNAMES)>& html_color_names() {
  return color_names_array;
}

// Extract raw RGB bytes without alpha
std::array<unsigned char, 3> html_color_value(COLORNAME color) {
  return color_rgb_data[static_cast<size_t>(color)];
}
