// A plugin that reports a diagnostic before layout is performed
class PreLayoutNotificationPlugin : public eld::plugin::LinkerPlugin {
public:
  PreLayoutNotificationPlugin()
      : eld::plugin::LinkerPlugin("PreLayoutNotificationPlugin") {}

  void ActBeforePerformingLayout() override {
    // Send a note diagnostic through the linker's diagnostic interface
    auto* linker = getLinker();
    unsigned noteID = linker->getNoteDiagID("In ActBeforePerformingLayout");
    linker->reportDiag(noteID);
  }
};

