TEST_CASE_MAP("load_factor", int, int) {
    auto m = map_t();

    // Initially, the load factor should be 0.0
    REQUIRE(static_cast<double>(m.load_factor()) == doctest::Approx(0.0));

    // Insert 10000 elements and verify load factor behavior
    for (int key = 0; key < 10000; ++key) {
        m.emplace(key, key);

        // After first insertion, load factor must be positive
        REQUIRE(m.load_factor() > 0.0F);

        // Load factor should not exceed the maximum allowed density (0.8)
        REQUIRE(m.load_factor() <= 0.8F);
    }
}

