#include "includes.h"
using spdlog::memory_buf_t;
using spdlog::details::to_string_view;

// Helper function to pad an integer to at least 'width' digits with leading zeros (or minus sign preserved)
template<typename T>
void pad_with_width(T n, int width, memory_buf_t &buf) {
    buf.clear();
    if (n < 0 && std::is_signed<T>::value) {
        buf.push_back('-');
        n = -n;
    }

    char temp[32];
    int idx = sizeof(temp) - 1;
    temp[idx] = '\0';

    do {
        temp[--idx] = static_cast<char>('0' + (n % 10));
        n /= 10;
    } while (n > 0);

    int remaining = width - (sizeof(temp) - 1 - idx);
    for (int i = 0; i < remaining; ++i) {
        buf.push_back('0');
    }

    while (temp[idx] != '\0') {
        buf.push_back(temp[idx++]);
    }
}

void test_pad2(int n, const char *expected) {
    memory_buf_t buf;
    pad_with_width(n, 2, buf);
    REQUIRE(to_string_view(buf) == expected);
}

void test_pad3(uint32_t n, const char *expected) {
    memory_buf_t buf;
    pad_with_width(n, 3, buf);
    REQUIRE(to_string_view(buf) == expected);
}

void test_pad6(std::size_t n, const char *expected) {
    memory_buf_t buf;
    pad_with_width(n, 6, buf);
    REQUIRE(to_string_view(buf) == expected);
}

void test_pad9(std::size_t n, const char *expected) {
    memory_buf_t buf;
    pad_with_width(n, 9, buf);
    REQUIRE(to_string_view(buf) == expected);
}

TEST_CASE("pad2", "[fmt_helper]") {
    test_pad2(0, "00");
    test_pad2(3, "03");
    test_pad2(10, "10");
    test_pad2(23, "23");
    test_pad2(99, "99");
    test_pad2(100, "100");
    test_pad2(123, "123");
    test_pad2(1234, "1234");
    test_pad2(-5, "-5");
}

