#include "chan.h"
#include "gmock/gmock.h"
#include "gtest/gtest.h"
#include <thread>

// Test channel operations: put, take, and close functionality
TEST(ChanTest, PutTakeClose) {
  dap::Chan<int> channel;

  // Launch a producer thread to send values
  std::thread producer([&] {
    channel.put(10);
    channel.put(20);
    channel.put(30);
    channel.close();
  });

  // Consume values in the main thread
  EXPECT_EQ(channel.take(), dap::optional<int>(10));
  EXPECT_EQ(channel.take(), dap::optional<int>(20));
  EXPECT_EQ(channel.take(), dap::optional<int>(30));
  EXPECT_EQ(channel.take(), dap::optional<int>());

  producer.join();
}

