template<typename Func, typename... Params>
ABSL_ATTRIBUTE_NOINLINE void invokeFunction(Func&& f, Params&&... args) {
    std::invoke(std::forward<Func>(f), std::forward<Params>(args)...);
}

template<typename TargetType, typename SourceCallable, typename... Args>
void runBenchmarkLoop(benchmark::State& state,
                      const SourceCallable& source,
                      Args&&... arguments) {
    for (auto _ : state) {
        invokeFunction<TargetType>(source, std::forward<Args>(arguments)...);
    }
}

