  void HybridRunAnywhereDeviceInfoSpec::loadHybridMethods() {
    // Initialize base class methods/properties first
    HybridObject::loadHybridMethods();

    // Register device info-specific hybrid methods
    registerHybrids(this, [](Prototype& proto) {
      // Device model information
      proto.registerHybridMethod("getDeviceModel", &HybridRunAnywhereDeviceInfoSpec::getDeviceModel);

      // OS version details
      proto.registerHybridMethod("getOSVersion", &HybridRunAnywhereDeviceInfoSpec::getOSVersion);

      // Platform identifier
      proto.registerHybridMethod("getPlatform", &HybridRunAnywhereDeviceInfoSpec::getPlatform);

      // Memory capacity info
      proto.registerHybridMethod("getTotalRAM", &HybridRunAnywhereDeviceInfoSpec::getTotalRAM);
      proto.registerHybridMethod("getAvailableRAM", &HybridRunAnywhereDeviceInfoSpec::getAvailableRAM);

      // CPU configuration
      proto.registerHybridMethod("getCPUCores", &HybridRunAnywhereDeviceInfoSpec::getCPUCores);

      // Hardware acceleration features
      proto.registerHybridMethod("hasGPU", &HybridRunAnywhereDeviceInfoSpec::hasGPU);
      proto.registerHybridMethod("hasNPU", &HybridRunAnywhereDeviceInfoSpec::hasNPU);

      // Chipset identification
      proto.registerHybridMethod("getChipName", &HybridRunAnywhereDeviceInfoSpec::getChipName);

      // Thermal management status
      proto.registerHybridMethod("getThermalState", &HybridRunAnywhereDeviceInfoSpec::getThermalState);

      // Battery state monitoring
      proto.registerHybridMethod("getBatteryLevel", &HybridRunAnywhereDeviceInfoSpec::getBatteryLevel);
      proto.registerHybridMethod("isCharging", &HybridRunAnywhereDeviceInfoSpec::isCharging);
      proto.registerHybridMethod("isLowPowerMode", &HybridRunAnywhereDeviceInfoSpec::isLowPowerMode);
    });
  }
