// Global render state instance with alternative initialization approach
RndRenderState TheRenderState;

// Helper function to set blend states using a unified approach
inline void ConfigureBlendStates(
    IDirect3DDevice9* device,
    int src, int dst, int srcA, int dstA
) {
    D3DDevice_SetRenderState_SrcBlend(device, src);
    D3DDevice_SetRenderState_DestBlend(device, dst);
    D3DDevice_SetRenderState_SrcBlendAlpha(device, srcA);
    D3DDevice_SetRenderState_DestBlendAlpha(device, dstA);
}

// Wrapper to handle boolean enable flags consistently
inline void ApplyEnableFlag(IDirect3DDevice9* dev, bool flag, D3DRENDERSTATETYPE state) {
    D3DDevice_SetRenderState_AlphaBlendEnable(dev, (u8)flag);
}

void RndRenderState::SetBlendEnable(bool enabled) {
    ApplyEnableFlag(TheDxRnd.Device(), enabled, D3DRS_ALPHABLENDENABLE);
}

void RndRenderState::SetBlendOp(BlendOp operation) {
    D3DDevice_SetRenderState_BlendOp(TheDxRnd.Device(), static_cast<int>(operation));
}

void RndRenderState::SetBlend(
    Blend source, Blend destination, 
    Blend sourceAlpha, Blend destAlpha
) {
    ConfigureBlendStates(
        TheDxRnd.Device(),
        static_cast<int>(source),
        static_cast<int>(destination),
        static_cast<int>(sourceAlpha),
        static_cast<int>(destAlpha)
    );
}

