        referenceValue
    );
    D3DDevice_SetRenderState_StencilFunc(
        TheDxRnd.Device(), 
        tf2cf[TheDxRnd.Unk301() * 8 + compare]
    );
}

void RndRenderState::SetStencilOp(
    StencilOp failAction, 
    StencilOp depthFailAction, 
    StencilOp passAction
) {
    D3DDevice_SetRenderState_StencilFail(
        TheDxRnd.Device(), 
        static_cast<int>(failAction)
    );
    D3DDevice_SetRenderState_StencilZFail(
        TheDxRnd.Device(), 
        static_cast<int>(depthFailAction)
    );
    D3DDevice_SetRenderState_StencilPass(
        TheDxRnd.Device(), 
        static_cast<int>(passAction)
    );
}

// Alternative initialization method that configures texture settings differently
void RndRenderState::Init(void) {
    // Set texture clamp modes for texture units 4 and 5
    SetTextureClamp(4, ClampMode::CLAMP_UVW);
    SetTextureClamp(5, ClampMode::CLAMP_UVW);

