namespace nb = nanobind;
using namespace mscclpp;

void register_proxy_interface(nb::module_& module) {
  // Register BaseProxyService class
  nb::class_<BaseProxyService>(module, "BaseProxyService")
      .def("start", &BaseProxyService::startProxy)
      .def("stop", &BaseProxyService::stopProxy);

  // Register ProxyService derived from BaseProxyService
  nb::class_<ProxyService, BaseProxyService>(module, "ProxyService")
      .def(nb::init<size_t>(), nb::arg("fifo_capacity") = DEFAULT_FIFO_SIZE)
      .def("start", &ProxyService::startProxy)
      .def("stop", &ProxyService::stopProxy)
      .def("construct_and_register_semaphore", &ProxyService::buildAndAddSemaphore, 
           nb::arg("communicator"), nb::arg("connection"))
      .def("register_semaphore", &ProxyService::addSemaphore, nb::arg("semaphore_obj"))
      .def("register_memory", &ProxyService::addMemory, nb::arg("memory_region"))
      .def("get_semaphore", &ProxyService::semaphore, nb::arg("index"))
      .def("get_base_channel", &ProxyService::baseProxyChannel, nb::arg("index"))
      .def("get_proxy_channel", &ProxyService::proxyChannel, 
           nb::arg("index"), nb::arg("destination"), nb::arg("source"));

  // Register BaseProxyChannel
  nb::class_<BaseProxyChannel>(module, "BaseProxyChannel")
      .def(nb::init<SemaphoreId, std::shared_ptr<Host2DeviceSemaphore>, std::shared_ptr<Proxy>>(),
           nb::arg("sem_id"), nb::arg("sync_sem"), nb::arg("proxy_obj"))
      .def("to_device", &BaseProxyChannel::deviceHandle);

  // Register BaseProxyChannel::DeviceHandle
  nb::class_<BaseProxyChannel::DeviceHandle>(module, "BaseProxyChannelDeviceHandle")
      .def(nb::init<>())
      .def_rw("semaphoreId_", &BaseProxyChannel::DeviceHandle::semaphoreId_)
      .def_rw("semaphore_", &BaseProxyChannel::DeviceHandle::semaphore_)
      .def_rw("fifo_buffer_", &BaseProxyChannel::DeviceHandle::fifo_)
      .def_prop_ro("as_bytes", [](const BaseProxyChannel::DeviceHandle& self) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&self), sizeof(self));
      });

  // Register ProxyChannel
  nb::class_<ProxyChannel>(module, "ProxyChannel")
      .def(nb::init<SemaphoreId, std::shared_ptr<Host2DeviceSemaphore>, std::shared_ptr<Proxy>, MemoryId, MemoryId>(),
           nb::arg("sem_id"), nb::arg("sync_sem"), nb::arg("proxy_obj"), nb::arg("dst_mem"), nb::arg("src_mem"))
      .def("to_device", &ProxyChannel::deviceHandle);

  // Register ProxyChannel::DeviceHandle
  nb::class_<ProxyChannel::DeviceHandle>(module, "ProxyChannelDeviceHandle")
      .def(nb::init<>())
      .def_rw("semaphoreId_", &ProxyChannel::DeviceHandle::semaphoreId_)
      .def_rw("semaphore_", &ProxyChannel::DeviceHandle::semaphore_)
      .def_rw("fifo_buffer_", &ProxyChannel::DeviceHandle::fifo_)
      .def_rw("source_mem_", &ProxyChannel::DeviceHandle::src_)
      .def_rw("dest_mem_", &ProxyChannel::DeviceHandle::dst_)
      .def_prop_ro("as_bytes", [](const ProxyChannel::DeviceHandle& self) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&self), sizeof(self));
      });
}

