DisableProxyPluginDialog::DisableProxyPluginDialog(
    MOBase::IPlugin* proxyPlugin, std::vector<MOBase::IPlugin*> const& required,
    QWidget* parent)
    : QDialog(parent), ui(new Ui::DisableProxyPluginDialog)
{
  ui->setupUi(this);

  // Construct the message with dynamic localization based on count
  QString const msgTemplate = QObject::tr("Disabling the '%1' plugin will prevent the "
                                          "following %2 plugin(s) from working:",
                                          "", required.size());
  ui->topLabel->setText(msgTemplate.arg(proxyPlugin->localizedName())
                        .arg(static_cast<int>(required.size())));

  // Connect buttons to dialog outcomes
  connect(ui->noBtn, &QPushButton::clicked, this, &QDialog::reject);
  connect(ui->yesBtn, &QPushButton::clicked, this, &QDialog::accept);

  // Configure table view settings
  ui->requiredPlugins->setSelectionMode(QAbstractItemView::NoSelection);
  ui->requiredPlugins->setRowCount(static_cast<int>(required.size()));

  // Populate the table with plugin info using index-based iteration
  int row = 0;
  for (auto const* plugin : required) {
    QTableWidgetItem* nameItem = new QTableWidgetItem(plugin->localizedName());
    QTableWidgetItem* descItem = new QTableWidgetItem(plugin->description());
    ui->requiredPlugins->setItem(row, 0, nameItem);
    ui->requiredPlugins->setItem(row, 1, descItem);
    ui->requiredPlugins->setRowHeight(row, 9);
    ++row;
  }

  // Hide vertical header and sort by first column
  ui->requiredPlugins->verticalHeader()->setVisible(false);
  ui->requiredPlugins->sortByColumn(0, Qt::AscendingOrder);
}

