bool ddsrt_prng_makeseed(struct ddsrt_prng_seed *seed)
{
    NTSTATUS status;
    // Initialize the seed key buffer to zero
    memset(seed->key, 0, sizeof(seed->key));

    // Attempt to generate random bytes using the system-preferred RNG
    status = BCryptGenRandom(NULL, (PUCHAR)seed->key, (ULONG)sizeof(seed->key), BCRYPT_USE_SYSTEM_PREFERRED_RNG);

    // Return true if the operation succeeded (status code is non-negative)
    return (status >= 0);
}

