// Helper functions for different operation modes
static void perform_nn_operation(char ta, char tb, int m, int n, int k, float alpha, float *A, int lda, float *B, int ldb, float beta, float *C, int ldc, float *D, int ldd);
static void perform_nt_operation(char ta, char tb, int m, int n, int k, float alpha, float *A, int lda, float *B, int ldb, float beta, float *C, int ldc, float *D, int ldd);
static void perform_tn_operation(char ta, char tb, int m, int n, int k, float alpha, float *A, int lda, float *B, int ldb, float beta, float *C, int ldc, float *D, int ldd);
static void perform_tt_operation(char ta, char tb, int m, int n, int k, float alpha, float *A, int lda, float *B, int ldb, float beta, float *C, int ldc, float *D, int ldd);

static void blasfeo_sgemm_internal(char ta, char tb, int m, int n, int k, float alpha, float *A, int lda, float *B, int ldb, float beta, float *C, int ldc, float *D, int ldd)
{
    if (m <= 0 || n <= 0)
        return;

    // Determine operation type based on transpose flags
    if (ta == 'n' || ta == 'N')
    {
        if (tb == 'n' || tb == 'N')
            perform_nn_operation(ta, tb, m, n, k, alpha, A, lda, B, ldb, beta, C, ldc, D, ldd);
        else if (tb == 't' || tb == 'T' || tb == 'c' || tb == 'C')
            perform_nt_operation(ta, tb, m, n, k, alpha, A, lda, B, ldb, beta, C, ldc, D, ldd);
        else
        {
            printf("\nBLASFEO: sgemm: wrong value for tb\n");
            return;
        }
    }
    else if (ta == 't' || ta == 'T' || ta == 'c' || ta == 'C')
    {
        if (tb == 'n' || tb == 'N')
            perform_tn_operation(ta, tb, m, n, k, alpha, A, lda, B, ldb, beta, C, ldc, D, ldd);
        else if (tb == 't' || tb == 'T' || tb == 'c' || tb == 'C')
            perform_tt_operation(ta, tb, m, n, k, alpha, A, lda, B, ldb, beta, C, ldc, D, ldd);
        else
        {
            printf("\nBLASFEO: sgemm: wrong value for tb\n");
            return;
        }
    }
    else
    {
        printf("\nBLASFEO: sgemm: wrong value for ta\n");
        return;
    }
}

