#include "style_sheet.hpp"
#include <filesystem/filesystem.h>
#include <fstream>
#include <serialization/associative_archive.h>
#include <serialization/binary_archive.h>

namespace unravel
{
    REFLECT(style_sheet)
    {
        // Register style_sheet with entt using alternative attribute setup
        auto& meta = entt::meta_factory<style_sheet>{}
            .type("style_sheet"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "style_sheet"},
                entt::attribute{"pretty_name", "Style Sheet"},
                entt::attribute{"category", "UI"},
            });

        // Bind content field with descriptive metadata
        meta.data<&style_sheet::content>("content"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "content"},
                entt::attribute{"pretty_name", "Content"},
                entt::attribute{"tooltip", "The CSS/RCSS content of the style sheet"},
                entt::attribute{"multiline", true},
                entt::attribute{"type", "code"},
                entt::attribute{"wrap", true},
            });
    }

    SAVE(style_sheet)
    {
        // Use lambda to wrap try_save for clarity and reuse
        auto serialize_content = [&](auto& archive) {
            archive(ser20::make_nvp("content", obj.content));
        };
        serialize_content(ar);
    }

    SAVE_INSTANTIATE(style_sheet, ser20::oarchive_associative_t);
    SAVE_INSTANTIATE(style_sheet, ser20::oarchive_binary_t);

    LOAD(style_sheet)
    {
        auto deserialize_content = [&](auto& archive) {
            archive(ser20::make_nvp("content", obj.content));
        };
        deserialize_content(ar);
    }

    LOAD_INSTANTIATE(style_sheet, ser20::iarchive_associative_t);
    LOAD_INSTANTIATE(style_sheet, ser20::iarchive_binary_t);

    void save_to_file(const std::string& absolute_path, const style_sheet::sptr& obj)
    {
        if (!obj || obj->content.empty()) return;

        std::ofstream file_stream{absolute_path};
        if (file_stream.is_open() && file_stream.good())
        {
            // Write character data directly from string buffer
            file_stream.write(obj->content.data(), obj->content.length());
        }
    }

    void save_to_file_bin(const std::string& absolute_path, const style_sheet::sptr& obj)
    {
        if (!obj) return;

        std::ofstream bin_stream{absolute_path, std::ios::binary};
        if (bin_stream.is_open() && bin_stream.good())
        {
            ser20::oarchive_binary_t archive{bin_stream};
            archive(ser20::make_nvp("style_sheet", *obj));
        }
    }

    void load_from_file(const std::string& absolute_path, style_sheet::sptr& obj)
    {
        if (!obj) obj = std::make_shared<style_sheet>();

        std::ifstream file_stream{absolute_path};
        if (file_stream.is_open() && file_stream.good())
        {
            // Read entire stream into string using helper
            obj->content = fs::read_stream_str(file_stream);
        }
    }

    void load_from_file_bin(const std::string& absolute_path, style_sheet::sptr& obj)
    {
        if (!obj) obj = std::make_shared<style_sheet>();

        std::ifstream bin_stream{absolute_path, std::ios::binary};
        if (bin_stream.is_open() && bin_stream.good())
        {
            ser20::iarchive_binary_t archive{bin_stream};
            archive(ser20::make_nvp("style_sheet", *obj));
        }
    }
} // namespace unravel

