namespace {

// Helper to simulate creation of visual LLM model files for testing
void setup_visual_models() {
    const std::string llm_url = "https://example.com/llava-model.gguf";
    const std::string proj_url = "https://example.com/mmproj-model-f16.gguf";

    auto llm_file_path = Utils::make_default_path_to_file_from_download_url(llm_url);
    auto proj_file_path = Utils::make_default_path_to_file_from_download_url(proj_url);

    std::filesystem::create_directories(llm_file_path.parent_path());
    std::filesystem::create_directories(proj_file_path.parent_path());

    // Write dummy content to both files
    std::ofstream{llm_file_path.string(), std::ios::binary} << 'x';
    std::ofstream{proj_file_path.string(), std::ios::binary} << 'x';
}

} // anonymous namespace

TEST_CASE("Image analysis remains disabled by default regardless of model presence") {
    TempDir sandbox;
    EnvVarGuard home{"HOME", sandbox.path().string()};
    EnvVarGuard config_dir{"AI_FILE_SORTER_CONFIG_DIR", sandbox.path().string()};
    EnvVarGuard llm_url{"LLAVA_MODEL_URL", "https://example.com/llava-model.gguf"};
    EnvVarGuard mmproj_url{"LLAVA_MMPROJ_URL", "https://example.com/mmproj-model-f16.gguf"};

    setup_visual_models();

    Settings cfg;
    bool success = cfg.load();
    REQUIRE_FALSE(success);
    REQUIRE_FALSE(cfg.get_analyze_images_by_content());
    REQUIRE_FALSE(cfg.get_offer_rename_images());
}

